Object.assign(window.TEM8_DICTIONARY, {"spontaneous":{"media":{"uk":"media/uk/spontaneous__gb_1.mp3","us":"media/us/spontaneous__us_1.mp3"},"oxford":{"phon":"spɒnˈteɪniəs","pos":"adjective","senses":[{"en":"not planned but done because you suddenly want to do it","cn":"自发的；非筹划安排的","ex":{"en":"a spontaneous offer of help","cn":"主动提出帮助"}},{"en":"often doing things without planning to, because you suddenly want to do them","cn":"常心血来潮的","ex":{"en":"Jo's a cheerful, spontaneous person, always ready for some fun.","cn":"乔是个乐呵呵的性情中人，总想着找些乐子。"}},{"en":"happening naturally, without being made to happen","cn":"自发的；自然的；自身造成的","lab":"specialist","ex":{"en":"spontaneous remission of the disease","cn":"疾病的自然缓解"}},{"en":"done naturally, without being forced, practised or organized in advance","cn":"自然的；非勉强的；无练习的；无事先安排的","ex":{"en":"a recording of spontaneous speech","cn":"一段即席讲话录音"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(行为)自然的，自发的","en":"Spontaneous acts are not planned or arranged, but are done because someone suddenly wants to do them.","ex":{"en":"Diana's house was crowded with happy people whose spontaneous outbursts of song were accompanied by lively music","cn":"戴安娜的家里挤满了兴奋的人们，他们伴着欢快的音乐不由自主地引吭高歌。"}},{"pos":"ADJ 形容词","cn":"自然的，自发的(指由于内部原因而非外界影响所引起的)","en":"A spontaneous event happens because of processes within something rather than being caused by things outside it.","ex":{"en":"I had another spontaneous miscarriage at around the 16th to 18th week.","cn":"我在大约第 16 至 18 孕周时又经历了一次自然流产。"}}]},"examples":[{"en":"a wonderfully spontaneous performance of the piece","cn":"对那支乐曲极其淳朴自然的演奏"},{"en":"We spontaneously started to dance.","cn":"我们情不自禁地跳起舞来。"}]},"spot":{"media":{"uk":"media/uk/spot__gb_1.mp3","us":"media/us/spot__us_1.mp3"},"oxford":{"phon":"spɒt","pos":"noun","senses":[{"en":"a small round area that has a different colour or feels different from the surface it is on","cn":"斑点","lab":"British English","sc":"small mark","ex":{"en":"Which has spots, the leopard or the tiger?","cn":"有斑点的是豹还是虎？"}},{"en":"a small mark or lump on a person’s skin, sometimes with a yellow head to it","cn":"（皮肤上的）丘疹，疱疹，粉刺；脓疱","g":"[usually plural]","lab":"British English","sc":"small mark","ex":{"en":"The baby's whole body was covered in small red spots.","cn":"当时这孩子浑身布满小红疙瘩。"}},{"en":"a small dirty mark on something","cn":"污迹；污渍；脏点","sc":"small mark","ex":{"en":"His jacket was covered with spots of mud.","cn":"他的上衣满是泥点。"}},{"en":"a particular area or place","cn":"地点；场所；处所","sc":"place","ex":{"en":"a quiet/secluded/lonely spot","cn":"宁静／僻静／偏僻的地方"}},{"en":"a small feature or part of somebody/something with a particular quality","cn":"（人或事物的）特别之处，特点","lab":"figurative","sc":"feature of somebody/something","ex":{"en":"He usually wears a hat to hide his bald spot.","cn":"他一般会戴个帽子来遮掩秃顶。"}},{"en":"a small amount of something","cn":"少量；一点","g":"[usually singular]","lab":"British English, informal，，","sc":"small amount","ex":{"en":"He's in a spot of trouble.","cn":"他遇到一点麻烦。"}},{"en":"a small amount of a liquid","cn":"几滴，少许（液体）","g":"[usually plural]","sc":"small amount","ex":{"en":"I felt a few spots of rain.","cn":"我感觉掉雨点了。"}},{"en":"a part of a television, radio, club or theatre show that is given to a particular person or type of entertainment","cn":"（电视、广播中或俱乐部、剧院演出中）某演员的固定节目，某类节目的固定栏目","sc":"part of show","ex":{"en":"a guest/solo spot","cn":"嘉宾节目；单人表演"}},{"en":"a position in a competition, event or team","cn":"排名位置","sc":"in competition","ex":{"en":"two teams battling for (the) top spot","cn":"争夺冠军的两个队"}},{"en":"a spotlight (= a light with a single, very bright beam that can be directed at a particular place or person, especially a performer on the stage)","cn":"吓呆了；呆若木鸡","lab":"informal","sc":"light"},{"en":"to see or notice a person or thing, especially suddenly or when it is not easy to do so","cn":"看见；看出；注意到；发现","ex":{"en":"Can you spot the difference between these two pictures?","cn":"你能不能看出这两幅画有什么不同？"},"pos":"verb"},{"en":"to give your opponent or the other team an advantage","cn":"（对比赛对手）让分，让子，让步","lab":"North American English, sport，，","ex":{"en":"We spotted the opposing team two goals.","cn":"我们让对手两个球。"},"pos":"verb"},{"en":"connected with a system of buying and selling things where goods are delivered and paid for immediately after sale","cn":"现货交易的；立即支付的","ex":{"en":"spot prices","cn":"现货价格"},"pos":"adjective"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"小圆点;斑点","en":"Spots are small, round, coloured areas on a surface.","ex":{"en":"The leaves have yellow areas on the top and underneath are powdery orange spots","cn":"叶子的表面有黄色斑块，背面则有桔色粉状圆点。"}},{"pos":"N-COUNT 可数名词","cn":"(皮肤上的)小肿块，斑点","en":"Spots on a person's skin are small lumps or marks.","ex":{"en":"Never squeeze blackheads, spots or pimples.","cn":"千万不要挤黑头、小肿块或粉刺。"}},{"pos":"N-COUNT 可数名词","cn":"(液体的)滴，点","en":"A spot of a liquid is a small amount of it.","ex":{"en":"Spots of rain had begun to fall","cn":"雨点开始落下来了。"}},{"pos":"QUANT 数量词","cn":"少量;少许","en":"If you have a spot of something, you have a small amount of it.","ex":{"en":"Mr Brooke is undoubtedly in a spot of bother","cn":"布鲁克先生肯定遇到了点小麻烦。"}},{"pos":"N-COUNT 可数名词","cn":"地点;处所","en":"You can refer to a particular place as a spot .","ex":{"en":"They stayed at several of the island's top tourist spots","cn":"他们在岛上最著名的几处旅游景点作了停留。"}},{"pos":"N-COUNT 可数名词","cn":"(电视、广播节目的)固定时段","en":"A spot in a television or radio show is a part of it that is regularly reserved for a particular performer or type of entertainment.","ex":{"en":"Unsuccessful at screen writing, he got a spot on a CNN film show.","cn":"写电影剧本未获成功后，他在美国有线新闻网的一档电影节目中争取到了一个固定时段。"}},{"pos":"VERB 动词","cn":"看到;发现;认出","en":"If you spot something or someone, you notice them.","ex":{"en":"Vicenzo failed to spot the error","cn":"维森佐未能发现该错误。"}},{"pos":"PHRASE 短语","cn":"在现场","en":"If you are on the spot, you are at the actual place where something is happening.","ex":{"en":"...areas where troops are on the spot and protecting civilians","cn":"有部队在现场保护平民的地区"}},{"pos":"PHRASE 短语","cn":"立即;当场","en":"If you do something on the spot, you do it immediately.","ex":{"en":"James was called to see the producer and got the job on the spot","cn":"詹姆斯被叫去见制片人，当场就得到了那份工作。"}},{"pos":"PHRASE 短语","cn":"使…陷入困境;使…为难","en":"If you put someone on the spot, you cause them to have to answer a difficult question or make a difficult decision.","ex":{"en":"He put me on the spot a bit because he invited me right in front of his mum and I didn't particularly want to go","cn":"他让我有点难堪，因为他当着他母亲的面邀请我，而我又不太想去。"}},{"pos":"PHRASE 短语","cn":"处于困境","en":"If you are in a tight spot, you are in a difficult situation.","ex":{"en":"In a tight spot there is no one I would sooner see than Frank.","cn":"有麻烦时，我会首先去找弗兰克。"}},{"pos":"","cn":"","en":"rooted to the spot→see: ; to have a soft spot for someone→see: ;"}]},"examples":[{"en":"He showed me the exact spot where he had asked her to marry him.","cn":"他把他当时向她求婚的确切地点指给我看。"},{"en":"An ambulance was on the spot within minutes.","cn":"几分钟之内，一辆救护车便赶到现场。"}]},"springy":{"media":{"uk":"media/uk/springy__gb_1.mp3","us":"media/us/springy__us_1.mp3"},"oxford":{"phon":"ˈsprɪŋi","pos":"adjective","senses":[{"en":"returning quickly to the original shape after being pushed, pulled, stretched, etc.","cn":"有弹性（或弹力）的","ex":{"en":"We walked across the springy grass.","cn":"我们走过松软的草地。"}},{"en":"full of energy and confidence","cn":"矫健的；有活力的","ex":{"en":"She's 73, but hasn't lost that youthful, springy step.","cn":"她 73 岁了，但走起路来依旧矫健轻捷。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"有弹性的;有弹力的","en":"If something is springy, it returns quickly to its original shape after you press it.","ex":{"en":"Steam for about 12 mins until the cake is risen and springy to touch in the centre.","cn":"蒸上 12 分钟左右，直到蛋糕膨起，中心摸起来很有弹性。"}}]},"examples":[{"en":"She's 73, but hasn't lost that youthful, springy step.","cn":"她 73 岁了，但走起路来依旧矫健轻捷。"},{"en":"We walked across the springy grass.","cn":"我们走过松软的草地。"}]},"space":{"media":{"uk":"media/uk/space__gb_1.mp3","us":"media/us/space__us_1.mp3"},"oxford":{"phon":"speɪs","pos":"noun","senses":[{"en":"the area outside the earth’s atmosphere where all the other planets and stars are","cn":"外层空间；太空","g":"[uncountable]","sc":"outside earth’s atmosphere","ex":{"en":"Valentina Tereshkova was the first woman in space.","cn":"瓦莲京娜•捷列什科娃是第一位进入太空的女性。"}},{"en":"an area or a place that is empty","cn":"空；空隙；空子；空当","g":"[countable]","sc":"empty area","ex":{"en":"an empty space","cn":"空地"}},{"en":"an amount of an area or of a place that is empty or that is available for use","cn":"（可利用的）空地，空间","g":"[uncountable]","sc":"empty area","ex":{"en":"We have 50 000 square metres of floor space.","cn":"我们拥有 50 000 平方米的建筑面积。"}},{"en":"a place, especially a room or a building, that can be used for a particular purpose","cn":"（某用途的）场所，场地","g":"[countable, uncountable]","sc":"empty area","ex":{"en":"The venue is a great space for music.","cn":"这地方是开音乐会的绝佳场所。"}},{"en":"the quality of being large and empty, allowing you to move freely","cn":"宽敞；空旷；开阔","g":"[uncountable]","sc":"empty area","ex":{"en":"The room has been furnished and decorated to give a feeling of space.","cn":"经过装潢和布置，这间屋子给人一种宽敞的感觉。"}},{"en":"a large area of land that has no buildings on it","cn":"（无建筑物的）大片空地，开阔地","g":"[countable, uncountable]","lab":"North American English","sc":"empty area","ex":{"en":"the wide open spaces of the Canadian prairies","cn":"加拿大一片片广袤的草原"}},{"en":"a period of time","cn":"一段时间；时间段","g":"[countable, usually singular]","sc":"period of time","ex":{"en":"Leave a space of two weeks between appointments.","cn":"每次约见要间隔两个星期。"}},{"en":"the part of a line, page or document that is empty","cn":"空白；空行；空格","g":"[uncountable, countable]","sc":"in writing/printing","ex":{"en":"Don't waste space by leaving a wide margin.","cn":"页边不要留太宽浪费版面。"}},{"en":"the freedom and the time to think or do what you want to","cn":"自我支配的自由；属于自己的空间","g":"[uncountable]","sc":"freedom","ex":{"en":"She was upset and needed space.","cn":"她心境不佳，需要一片自己的天地。"}},{"en":"the whole area in which all things exist and move","cn":"空间","g":"[uncountable]","sc":"where things exist/move","ex":{"en":"It is quite possible that space and time are finite.","cn":"很有可能空间和时间是有限的。"}},{"en":"an area of business in which a person or an organization operates","cn":"部门；领域；行业","g":"[uncountable]","lab":"informal, business，，","sc":"type of business","ex":{"en":"His investments have focused on the healthcare space.","cn":"他的投资聚焦于医疗服务领域。"}},{"en":"to arrange things so that they have regular spaces between them","cn":"以一定间隔排列","ex":{"en":"evenly spaced plants","cn":"间隔均匀的秧苗"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"空间;(空余的)地方","en":"You use space to refer to an area that is empty or available. The area can be any size. For example, you can refer to a large area outside as a large open space or to a small area between two objects as a small space .","ex":{"en":"Under the plan, bits of open space — fields, golf-course borders and small parks — will be preserved.","cn":"在这份规划里，一些开放空间——运动场、高尔夫球场边缘以及小公园——将得以保留。"}},{"pos":"N-VAR 可变名词","cn":"(活动或储藏用的)空间，场所，面积","en":"A particular kind of space is the area that is available for a particular activity or for putting a particular kind of thing in.","ex":{"en":"...the high cost of office space","cn":"办公场所的高额成本"}},{"pos":"N-UNCOUNT 不可数名词","cn":"开阔;空旷","en":"If a place gives a feeling of space, it gives an impression of being large and open.","ex":{"en":"Large paintings can enhance the feeling of space in small rooms","cn":"大型油画可以增加小房间的宽敞感。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"(思考问题、个人成长所需的)时间，余地，空间","en":"If you give someone space to think about something or to develop as a person, you allow them the time and freedom to do this.","ex":{"en":"You need space to think everything over","cn":"你需要时间把一切好好地考虑清楚。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"(文件中用于讨论某个话题的)版面，篇幅","en":"The amount of space for a topic to be discussed in a document is the number of pages available to discuss the topic.","ex":{"en":"We can't promise to publish a reply as space is limited.","cn":"由于版面有限，我们不能保证把回复登载出来。"}},{"pos":"N-SING 单数名词","cn":"一段(时间);期间","en":"A space of time is a period of time.","ex":{"en":"They've come a long way in a short space of time","cn":"他们在很短的时间之内就大老远地赶了过来。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"太空;外层空间","en":"Space is the area beyond the Earth's atmosphere, where the stars and planets are.","ex":{"en":"The six astronauts on board will spend ten days in space.","cn":"飞船上的6名宇航员将在太空度过 10 天。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"宇宙空间","en":"Space is the whole area within which everything exists.","ex":{"en":"She felt herself transcending time and space","cn":"她感到自己正在穿越时空。"}},{"pos":"VERB 动词","cn":"分隔;使有间隔","en":"If you space a series of things, you arrange them so that they are not all together but have gaps or intervals of time between them.","ex":{"en":"Women once again are having fewer children and spacing them further apart","cn":"女人再次减少了生孩子的数量，而且生育之间相隔的时间也更长了。"}},{"pos":"PHRASE 短语","cn":"直瞪瞪;茫然(直视)","en":"If you are staring into space, you are looking straight in front of you, without actually looking at anything in particular, for example because you are thinking or because you are feeling shocked.","ex":{"en":"He just sat in the dressing-room staring into space","cn":"他直愣愣地坐在化妆间里。"}},{"pos":"PHRASE 短语","cn":"废物;无用之人","en":"If you describe someone or something as a waste of space, you are indicating that you have a very low opinion of them.","ex":{"en":"Even Sarah treated him as if he were a waste of space","cn":"连萨拉对他都像是在对待一个废物。"}},{"pos":"PHRASE 短语","cn":"(新闻记者将进行后续报道时所说的话)请继续关注","en":"Journalists write 'Watch this space' in order to indicate in an informal way that they will be giving more information about something in the future.","ex":{"en":"Watch this space for details of our next event.","cn":"请继续关注我们对下一事件的详细报道。"}}]},"examples":[{"en":"The room has been furnished and decorated to give a feeling of space.","cn":"经过装潢和布置之后，这个房间给人一种宽敞的感觉。"},{"en":"There was not enough space to print all the letters we received.","cn":"版面有限，无法悉数刊载我们收到的所有来信。"}]},"spacious":{"media":{"uk":"media/uk/spacious__gb_1.mp3","us":"media/us/spacious__us_1.mp3"},"oxford":{"phon":"ˈspeɪʃəs","pos":"adjective","senses":[{"en":"large and with plenty of space for people to move around in","cn":"宽敞的","ex":{"en":"The hotel rooms are spacious and comfortable.","cn":"酒店客房宽敞舒适。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"广阔的;宽敞的","en":"A spacious room or other place is large in size or area, so that you can move around freely in it.","ex":{"en":"The house has a spacious kitchen and dining area.","cn":"这座房子有一个宽敞的厨房和用餐区。"}}]},"examples":[{"en":"White walls can give a feeling of spaciousness.","cn":"白墙能给人一种宽敞的感觉。"},{"en":"a spacious living area","cn":"宽敞的居住空间"}]},"specially":{"oxford":{"phon":"ˈspeʃəli","pos":"adverb","senses":[{"en":"for a particular purpose, person, etc.","cn":"专门地；特意","ex":{"en":"The ring was specially made for her.","cn":"这枚戒指是为她定做的。"}},{"en":"more than usual or more than other things","cn":"格外；特别；尤其","lab":"informal","ex":{"en":"It will be hard to work today—specially when it's so warm and sunny outside.","cn":"今天无心工作，尤其是外面这样风和日丽。"}}]},"collins":{"senses":[{"pos":"ADV 副词","cn":"专门地;特别地;特地","en":"If something has been done specially for a particular person or purpose, it has been done only for that person or purpose.","ex":{"en":"...a soap specially designed for those with sensitive skins","cn":"特别为皮肤敏感者设计的香皂"}},{"pos":"ADV 副词","cn":"特别地;超常地","en":"Specially is used to mean more than usually or more than other things.","ex":{"en":"Stay in bed extra late or get up specially early","cn":"起床过晚或过早。"}}]},"media":{"uk":"media/uk/specially__gb_1.mp3","us":"media/us/specially__us_1.mp3"},"examples":[{"en":"It will be hard to work today — specially when it's so warm and sunny outside.","cn":"今天无心工作，尤其是外面这样风和日丽。"},{"en":"I hate homework. Specially history.","cn":"我讨厌家庭作业，特别是历史。"}]},"spoken":{"media":{"uk":"media/uk/spoken__gb_2.mp3","us":"media/us/spoken__us_2.mp3"},"oxford":{"phon":"ˈspəʊkən","pos":"adjective","senses":[{"en":"involving speaking rather than writing; expressed in speech rather than in writing","cn":"口语的；口头的；以口头形式表达的","ex":{"en":"spoken English","cn":"英语口语"}},{"en":"speaking in the way mentioned","cn":"说话…的","ex":{"en":"a quietly spoken man","cn":"说话斯文的男人"}}]},"examples":[{"en":"There will be a test of both oral and written French.","cn":"将有一次法语口试和笔试。"},{"en":"the vocal organs (= the tongue, lips, etc.)","cn":"发声器官"}],"collins":{"senses":[{"pos":"","cn":"","en":"Spoken is the past participle of speak."}]}},"specific":{"media":{"uk":"media/uk/specific__gb_1.mp3","us":"media/us/specific__us_1.mp3"},"oxford":{"phon":"spəˈsɪfɪk","pos":"adjective","senses":[{"en":"connected with one particular thing only","cn":"特定的","g":"[usually before noun]","ex":{"en":"specific needs/requirements","cn":"特定的需要／要求"}},{"en":"detailed and exact","cn":"明确的；具体的","ex":{"en":"specific information/details/examples/questions","cn":"具体信息／细节／例子／问题"}},{"en":"existing only in one place or limited to one thing","cn":"特有的；独特的","lab":"formal","ex":{"en":"a belief that is specific to this part of Africa","cn":"非洲这一地区特有的一种观念"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(部位、问题、题目等)特定的，特别的","en":"You use specific to refer to a particular fixed area, problem, or subject.","ex":{"en":"Massage may help to increase blood flow to specific areas of the body","cn":"按摩有助于增加身体特定部位的血液流量。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（表达）明确的，确切的，具体的","en":"If someone is specific, they give a description that is precise and exact. You can also use specific to describe their description.","ex":{"en":"I asked him to be more specific","cn":"我要求他说得更具体些。"}},{"pos":"ADJ 形容词","cn":"特有的;独特的;只与…有关的","en":"Something that is specific to a particular thing is connected with that thing only.","ex":{"en":"Send your resume with a cover letter that is specific to that particular job.","cn":"寄出你的简历并附上一份针对那个特定工作岗位的附函。"}}]},"examples":[{"en":"‘I'd like your help tomorrow.’ ‘Can you be more specific (= tell me exactly what you want)? ’ “","cn":"我想让你明天来帮帮我。” “你能不能说得具体些？”"},{"en":"The money was collected for a specific purpose.","cn":"这笔钱是为一个特定用途而收的。"}]},"spat":{"oxford":{"phon":"spæt","pos":"noun","senses":[{"en":"a short argument about something unimportant","cn":"小争吵；小别扭；口角","lab":"informal"},{"en":"a piece of cloth that covers the ankle, worn in the past by men over the shoe and fastened with buttons at the side","cn":"（旧时男子用的）鞋罩","g":"[usually plural]"}]},"collins":{"senses":[{"pos":"","cn":"","en":"Spat is the past tense and past participle of spit ."},{"pos":"N-COUNT 可数名词","cn":"小争吵;口角;争执","en":"A spat between people, countries, or organizations is a disagreement between them.","ex":{"en":"...a spat between America and Germany over interest rates and currencies.","cn":"美国与德国在利率与货币方面的争端"}},{"pos":"N-PLURAL 复数名词","cn":"(昔时男子使用的)鞋罩","en":"Spats are specially shaped pieces of cloth or leather which button down one side and which were worn in former times by men over their ankles and part of their shoes."}]},"media":{"uk":"media/uk/spat__gb_1.mp3","us":"media/us/spat__us_1.mp3"},"examples":[{"en":"a marital spat","cn":"夫妻间的口角"}]},"spent":{"media":{"uk":"media/uk/spent__gb_2.mp3","us":"media/us/spent__us_2.mp3"},"oxford":{"phon":"spent","pos":"adjective","senses":[{"en":"that has been used, so that it cannot be used again","cn":"用过已废的；失效的","g":"[usually before noun]","ex":{"en":"spent matches","cn":"用过的火柴"}},{"en":"very tired","cn":"筋疲力尽的","lab":"formal","ex":{"en":"After the gruelling test, he felt totally spent.","cn":"紧张的考试过后，他感觉筋疲力尽了。"}}]},"collins":{"senses":[{"pos":"","cn":"","en":"Spent is the past tense and past participle of spend ."},{"pos":"ADJ 形容词","cn":"已用尽的;用过的","en":"Spent substances or containers have been used and cannot be used again.","ex":{"en":"Radioactive waste is simply spent fuel","cn":"放射性废物就是用后的燃料。"}}]},"examples":[{"en":"After the gruelling test, he felt totally spent.","cn":"紧张的考试过后，他感觉筋疲力尽了。"},{"en":"spent matches","cn":"用过的火柴"}]},"spoon":{"oxford":{"phon":"spuːn","pos":"noun","senses":[{"en":"a tool that has a handle with a shallow bowl at the end, used for mixing, serving and eating food","cn":"勺；匙；调羹","ex":{"en":"a plastic/metal spoon","cn":"塑料勺；金属勺"}},{"en":"the amount that a spoon can hold","cn":"一勺（的量）","ex":{"en":"two spoons of sugar","cn":"两勺糖"}},{"en":"to lift and move food with a spoon","cn":"用勺舀","ex":{"en":"She spooned the sauce over the chicken pieces.","cn":"她用勺把沙司浇到鸡块上。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"调羹;匙；小勺子","en":"A spoon is an object used for eating, stirring, and serving food. One end of it is shaped like a shallow bowl and it has a long handle.","ex":{"en":"He stirred his coffee with a spoon.","cn":"他用一把小勺搅着自己的咖啡。"}},{"pos":"N-COUNT 可数名词","cn":"一匙之量","en":"You can refer to an amount of food resting on a spoon as a spoon of food.","ex":{"en":"...tea with two spoons of sugar.","cn":"放了两匙糖的茶"}},{"pos":"VERB 动词","cn":"用匙舀取","en":"If you spoon food into something, you put it there with a spoon.","ex":{"en":"He spooned instant coffee into two of the mugs","cn":"他舀了几勺速溶咖啡放进两个杯子中。"}},{"pos":"PHRASE 短语","cn":"出生于富贵人家","en":"If you think that someone has a lot of advantages because they have a rich or influential family, you can say that they have been born with a silver spoon in their mouth .","ex":{"en":"She was born with a silver spoon in her mouth and everything has been done for her.","cn":"她出生于富贵人家，什么事都已为她安排得好好的。"}}]},"media":{"uk":"media/uk/spoon__gb_1.mp3","us":"media/us/spoon__us_1.mp3","img":["media/ldoce/img/cutlery.jpg"]},"examples":[{"en":"She spooned the sauce over the chicken pieces.","cn":"她用勺把沙司浇到鸡块上。"},{"en":"a soup spoon","cn":"汤匙"}]},"spanish":{"media":{"uk":"media/uk/spanish__gb_1.mp3","us":"media/us/spanish_1_us_1.mp3"},"oxford":{"phon":"ˈspænɪʃ","pos":"adjective","senses":[{"en":"from or connected with Spain","cn":"西班牙的"},{"en":"the language of Spain, Mexico and most countries in Central and South America","cn":"西班牙语","pos":"noun"}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"西班牙的;西班牙人的;西班牙语(或文化)的","en":"Spanish means belonging or relating to Spain, or to its people, language, or culture.","ex":{"en":"...a Spanish sherry.","cn":"西班牙雪利酒"}},{"pos":"N-UNCOUNT 不可数名词","cn":"西班牙语","en":"Spanish is the main language spoken in Spain, and in many countries in South and Central America."},{"pos":"N-PLURAL 复数名词","cn":"西班牙人","en":"The Spanish are the people who come from Spain."}]}},"spoiling":{"oxford":{"phon":"spɔɪl","pos":"verb","senses":[{"en":"to change sth good into sth bad, unpleasant, useless, etc.","cn":"破坏；搞坏；糟蹋；毁掉"},{"en":"to give a child everything that they ask for and not enough discipline in a way that has a bad effect on their character and behaviour","cn":"溺爱；娇惯；宠坏"}]}},"special":{"media":{"uk":"media/uk/special__gb_1.mp3","us":"media/us/special__us_1.mp3"},"oxford":{"phon":"ˈspeʃl","pos":"adjective","senses":[{"en":"not ordinary or usual; different from what is normal","cn":"特殊的；特别的；不寻常的；不一般的","g":"[usually before noun]","ex":{"en":"The school will only allow this in special circumstances.","cn":"学校只有在特殊情况下才会同意这种事。"}},{"en":"more important than others; deserving or getting more attention than usual","cn":"重要的；格外看重的；特别关照的","ex":{"en":"What are your special interests?","cn":"你有哪些主要的爱好？"}},{"en":"organized or intended for a particular purpose","cn":"特设的；有专门目的的；起专门作用的","ex":{"en":"British special forces were employed on stealth operations.","cn":"英国特种部队受雇参加了秘密行动。"}},{"en":"used by or intended for one particular person or group of people","cn":"专用的；专门针对…的；特有的","ex":{"en":"She has a special way of smiling.","cn":"她微笑的样子有些特别。"}},{"en":"better or more than usual","cn":"更好的；格外的","g":"[only before noun]","ex":{"en":"As an only child she got special attention.","cn":"她是个独生女，所以备受关爱。"}},{"en":"something that is not usually available but is provided for a particular purpose or on one occasion","cn":"特别活动（或节目等）；特制产品","ex":{"en":"an election-night special on television","cn":"选举之夜电视特别节目"},"pos":"noun"},{"en":"a price for a particular product in a shop or restaurant that is lower than usual","cn":"特价","lab":"informal, especially North American English，，","ex":{"en":"There's a special on coffee this week.","cn":"本周咖啡特价。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"特别的;非同寻常的","en":"Someone or something that is special is better or more important than other people or things.","ex":{"en":"You're very special to me, darling","cn":"亲爱的，你对我来说很重要。"}},{"pos":"ADJ 形容词","cn":"特殊的；异常的","en":"Special means different from normal.","ex":{"en":"In special cases, a husband can deduct the travel expenses of his wife who accompanies him on a business trip","cn":"在特殊情况下，丈夫可以扣除陪同出差的妻子的旅费。"}},{"pos":"ADJ 形容词","cn":"特派的;有特殊用途的","en":"You use special to describe someone who is officially appointed or who has a particular position specially created for them.","ex":{"en":"Due to his wife's illness, he returned to the State Department as special adviser to the President","cn":"由于妻子生病，他回到了国务院，出任总统的特别顾问。"}},{"pos":"ADJ 形容词","cn":"(为残疾人或有心理障碍者)特设的，专门的","en":"Special institutions are for people who have serious physical or mental problems.","ex":{"en":"Police are still searching for a convicted rapist, who escaped from Broadmoor special hospital yesterday.","cn":"警方仍然在搜寻昨天从布罗德莫尔专科医院逃跑的一名强奸犯。"}},{"pos":"ADJ 形容词","cn":"特有的;独具特色的","en":"You use special to describe something that relates to one particular person, group, or place.","ex":{"en":"Every anxious person will have his or her own special problems or fears.","cn":"每一个焦虑的人都会有自己的问题或者担心。"}},{"pos":"N-COUNT 可数名词","cn":"特产;特色菜;特别节目","en":"A special is a product, programme, or meal which is not normally available, or which is made for a particular purpose.","ex":{"en":"...complaints about the BBC's Hallowe'en special, 'Ghostwatch'","cn":"对英国广播公司的万圣节特别节目《幽灵观察》的投诉"}}]},"examples":[{"en":"The menu changes regularly and there are daily specials to choose from.","cn":"菜谱定期更换，而且每天都有特色菜供选择。"},{"en":"The school will only allow this in special circumstances.","cn":"学校只有在特殊情况下才会同意这种事。"}]},"spy":{"oxford":{"phon":"spaɪ","pos":"noun","senses":[{"en":"a person who tries to get secret information about another country, organization or person, especially somebody who is employed by a government or the police","cn":"间谍；密探","ex":{"en":"He was denounced as a foreign spy.","cn":"有人告发他是外国间谍。"}},{"en":"to collect secret information about another country, organization or person","cn":"从事间谍活动；搜集情报","g":"[intransitive]","ex":{"en":"He spied for his government for more than ten years.","cn":"他做过十多年的政府间谍。"},"pos":"verb"},{"en":"to suddenly see or notice somebody/something","cn":"突然看见；发现","g":"[transitive]","lab":"literary or formal","ex":{"en":"In the distance we spied the Pacific for the first time.","cn":"在远处，我们突然第一次看到了太平洋。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"间谍","en":"A spy is a person whose job is to find out secret information about another country or organization.","ex":{"en":"He was jailed for five years as an alleged British spy","cn":"他被指控为英国间谍，入狱关押了 5 年。"}},{"pos":"ADJ 形容词","cn":"(卫星、飞机)执行间谍任务的","en":"A spy satellite or spy plane obtains secret information about another country by taking photographs from the sky."},{"pos":"VERB 动词","cn":"从事间谍活动;充当间谍","en":"Someone who spies for a country or organization tries to find out secret information about another country or organization.","ex":{"en":"The agent spied for East Germany for more than twenty years","cn":"该特工人员为东德做了 20 多年的间谍。"}},{"pos":"VERB 动词","cn":"秘密监视","en":"If you spy on someone, you watch them secretly.","ex":{"en":"That day he spied on her while pretending to work on the shrubs","cn":"那天，他假装在修剪灌木，秘密对她进行监视。"}},{"pos":"VERB 动词","cn":"看见;发现","en":"If you spy someone or something, you notice them.","ex":{"en":"He was walking down the street when he spied an old friend.","cn":"他正沿街走着，突然看见了一位老朋友。"}}]},"media":{"uk":"media/uk/spy__gb_1.mp3","us":"media/us/spy__us_1.mp3"},"examples":[{"en":"In the distance we spied the Pacific for the first time.","cn":"在远处，我们突然第一次看到了太平洋。"},{"en":"Video spy cameras are being used in public places.","cn":"隐蔽的摄像机在监视着公共场所。"}]},"spoons":{"oxford":{"phon":"spuːn","pos":"noun","senses":[{"en":"a tool that has a handle with a shallow bowl at the end, used for stirring, serving and eating food","cn":"勺；匙；调羹"},{"en":"to lift and move food with a spoon","cn":"用勺舀"}]}},"speaker":{"media":{"uk":"media/uk/speaker__gb_1.mp3","us":"media/us/speaker__us_1.mp3"},"oxford":{"phon":"ˈspiːkə(r)","pos":"noun","senses":[{"en":"a person who gives a talk or makes a speech","cn":"发言者；演讲者","ex":{"en":"He was a guest speaker at the conference.","cn":"他是会议的特邀演讲人。"}},{"en":"a person who speaks a particular language","cn":"讲（某种语言）的人","ex":{"en":"English speakers","cn":"讲英语的人"}},{"en":"a person who is or was speaking","cn":"说话者","ex":{"en":"I looked around to see who the speaker was.","cn":"我四下环顾看说话的是谁。"}},{"en":"the part of a radio, computer or piece of musical equipment that the sound comes out of","cn":"扬声器；喇叭","ex":{"en":"The car had a powerful sound system with four speakers.","cn":"这辆车配有四喇叭大功率音响系统。"}},{"en":"the title of the person whose job is to control the discussions in a parliament","cn":"（议会的）议长","ex":{"en":"the Speaker of the House of Commons/Representatives","cn":"英国下议院／美国众议院议长"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"发言人;演讲者;演说家","en":"A speaker at a meeting, conference, or other gathering is a person who is making a speech or giving a talk.","ex":{"en":"Among the speakers at the gathering was Treasury Secretary Nicholas Brady","cn":"与会的发言人中有财政部长尼古拉斯·布莱迪。"}},{"pos":"N-COUNT 可数名词","cn":"讲某种语言的人","en":"A speaker of a particular language is a person who speaks it, especially one who speaks it as their first language.","ex":{"en":"...in the Ukraine, where a fifth of the population are Russian speakers","cn":"在乌克兰，有五分之一人口说俄语"}},{"pos":"N-PROPER; N-VOC 专有名词；称呼名词","cn":"(议会或立法机构的)议长","en":"In the parliament or legislature of many countries, the Speaker is the person who is in charge of meetings.","ex":{"en":"For twenty minutes, the Speaker tried to keep order.","cn":"20 分钟的时间里，议长一直在竭力维持秩序。"}},{"pos":"N-COUNT 可数名词","cn":"说话人","en":"A speaker is a person who is speaking.","ex":{"en":"From a simple gesture or the speaker's tone of voice, the Japanese listener gleans the whole meaning.","cn":"仅从一个简单的手势或者说话人的语气里，日本人就能够领悟到所有的意思。"}},{"pos":"N-COUNT 可数名词","cn":"扬声器;喇叭","en":"A speaker is a piece of electrical equipment, for example part of a radio or set of equipment for playing CDs or tapes, through which sound comes out.","ex":{"en":"For a good stereo effect, the speakers should not be too wide apart.","cn":"为了达到理想的立体声效果，扬声器之间的距离不能太远。"}}]},"examples":[{"en":"Myra is a dear, but she's also a terrible gossip.","cn":"迈拉是很可爱，但也是个讨厌的长舌妇。"},{"en":"The ideal candidate will be an effective communicator.","cn":"理想的候选人定要是善于沟通的人。"}]},"spread":{"media":{"uk":"media/uk/spread__gb_1.mp3","us":"media/us/spread__us_1.mp3"},"oxford":{"phon":"spred","pos":"verb","senses":[{"en":"to affect or make something affect, be known by, or be used by more and more people","cn":"传播；散布；（使）流传","g":"[intransitive, transitive]","sc":"among people","ex":{"en":"The news had spread and was causing great excitement.","cn":"消息传开了，大家兴奋不已。"}},{"en":"to cover, or to make something cover, a larger and larger area","cn":"（使）蔓延，扩散，散开","g":"[intransitive, transitive]","sc":"cover large area","ex":{"en":"There is no evidence that the cancer has spread.","cn":"没有证据表明癌已扩散。"}},{"en":"to cause somebody/something to be in a number of different places","cn":"使分散；使分布","g":"[transitive]","sc":"cover large area","ex":{"en":"Seeds and pollen are spread by the wind.","cn":"种子和花粉是随风传播的。"}},{"en":"to cover a large area","cn":"延伸；伸展；扩张","g":"[intransitive]","sc":"cover large area","ex":{"en":"The valley spread out beneath us.","cn":"山谷在我们下方延伸。"}},{"en":"to put a layer of a substance onto the surface of something; to be able to be put onto a surface","cn":"涂；敷","g":"[transitive, intransitive]","sc":"soft layer","ex":{"en":"They spread manure in both spring and autumn.","cn":"他们在春秋两季都要施肥。"}},{"en":"to open something that has been folded so that it covers a larger area than before","cn":"展开；打开","g":"[transitive]","sc":"open/arrange","ex":{"en":"The bird spread its wings.","cn":"鸟展开翅膀。"}},{"en":"to arrange objects so that they cover a large area and can be seen easily","cn":"摊开；使散开","g":"[transitive]","sc":"open/arrange","ex":{"en":"Papers had been spread out on the desk.","cn":"各种报纸摊在书桌上。"}},{"en":"to place the thumb and a finger of one hand on the screen of an electronic device such as a mobile phone or small computer and move them apart to make the image on the screen larger, as though it is closer","cn":"（在手机等电子设备的屏幕上）滑开两指以放大图文","g":"[transitive]","sc":"open/arrange","ex":{"en":"Re-size the text by using the pinch and spread gestures on the screen.","cn":"用两指在屏幕上开合滑动，以缩放文字。"}},{"en":"to move your arms, legs, fingers, etc. far apart from each other","cn":"张开；伸开","g":"[transitive]","sc":"arms/legs","ex":{"en":"She spread her arms and the child ran towards her.","cn":"她张开双臂，孩子向她跑来。"}},{"en":"to separate something into parts and divide them between different times or different people","cn":"分（若干次）进行；由（若干人）分摊","g":"[transitive]","sc":"divide/share","ex":{"en":"Why not pay monthly and spread the cost of your car insurance?","cn":"你为什么不把汽车保险费按月分期支付呢？"}},{"en":"an increase in the amount or number of something that there is, or in the area that is affected by something","cn":"传播；散布；扩展；蔓延","g":"[uncountable]","sc":"increase","ex":{"en":"measures to halt the spread of the disease","cn":"阻止疾病传播的措施"},"pos":"noun"},{"en":"a range or variety of things or people","cn":"广泛；多样","g":"[countable, usually singular]","sc":"range/variety","ex":{"en":"a broad spread of opinions","cn":"各种各样的意见"},"pos":"noun"},{"en":"a soft food that you put on bread","cn":"抹在面包上的东西","g":"[countable, uncountable]","sc":"on bread","ex":{"en":"Use a low-fat spread instead of butter.","cn":"不要抹黄油，抹点低脂肪的东西吧。"},"pos":"noun"},{"en":"the area that something exists in or happens in","cn":"涉及区域；活动范围","g":"[countable, usually singular]","sc":"area covered","ex":{"en":"The company has a good geographical spread of hotels in this country.","cn":"该公司在这个国家开设的饭店地理分布相当广。"},"pos":"noun"},{"en":"how wide something is or the area that something covers","cn":"宽度；面积；翼展","g":"[countable, usually singular]","sc":"area covered","ex":{"en":"The bird's wings have a spread of nearly a metre.","cn":"这只鸟翼展近一米。"},"pos":"noun"},{"en":"an article or advertisement in a newspaper or magazine, especially one that covers two opposite pages","cn":"（尤指横贯两版的）文章，广告","g":"[countable]","sc":"in newspaper/magazine","ex":{"en":"The story continued with a double-page spread on the inside pages.","cn":"这篇报道在报纸的内页有横贯两版的后续部分。"},"pos":"noun"},{"en":"a large meal, especially one that is prepared for a special occasion","cn":"丰盛的餐食","g":"[countable]","lab":"informal","sc":"meal","ex":{"en":"They had laid on a huge spread for the party.","cn":"他们为聚会安排了丰盛的食物。"},"pos":"noun"},{"en":"an area of land or water","cn":"区域；一大片","g":"[countable, usually singular]","lab":"North American English","sc":"of land/water","ex":{"en":"a vast spread of water","cn":"浩瀚的水域"},"pos":"noun"},{"en":"the difference between two rates or prices","cn":"（两种价格或比率的）差额，差幅","g":"[uncountable]","sc":"finance","pos":"noun"},{"en":"an attractive cover put on top of all the sheets and covers on a bed","cn":"床罩","g":"[countable]","lab":"North American English","sc":"on bed","pos":"noun"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"摊开;铺开","en":"If you spread something somewhere, you open it out or arrange it over a place or surface, so that all of it can be seen or used easily.","ex":{"en":"She spread a towel on the sand and lay on it","cn":"她在沙滩上铺了一条毛巾，躺在上面。"}},{"pos":"VERB 动词","cn":"伸出，张开,叉开(手臂、双手、手指、双腿等)","en":"If you spread your arms, hands, fingers, or legs, you stretch them out until they are far apart.","ex":{"en":"Sitting on the floor, spread your legs as far as they will go without overstretching","cn":"坐在地板上，在不要拉伤的前提下将双腿尽量分开。"}},{"pos":"VERB 动词","cn":"涂;抹;敷","en":"If you spread a substance on a surface or spread the surface with the substance, you put a thin layer of the substance over the surface.","ex":{"en":"Spread the mixture in the cake tin and bake for 30 minutes","cn":"将混合物抹在蛋糕烤盘里，烘烤 30 分钟。"}},{"pos":"N-MASS 物质名词","cn":"涂抹在面包上的酱","en":"Spread is a soft food which is put on bread.","ex":{"en":"...a wholemeal salad roll with low fat spread.","cn":"涂有低脂酱的全麦色拉面包卷"}},{"pos":"V-ERG 及物/不及物动词","cn":"(使)传播;(使)散布;(使)扩散","en":"If something spreads or is spread by people, it gradually reaches or affects a larger and larger area or more and more people.","ex":{"en":"The industrial revolution which started a couple of hundred years ago in Europe is now spreading across the world.","cn":"两百多年前始于欧洲的工业革命目前正在向全世界传播。"}},{"pos":"V-ERG 及物/不及物动词","cn":"(使)扩散;(使)散开;(使)蔓延","en":"If something such as a liquid, gas, or smoke spreads or is spread, it moves outwards in all directions so that it covers a larger area.","ex":{"en":"Fire spread rapidly after a chemical truck exploded","cn":"一辆装有化学品的卡车爆炸后，火势迅速蔓延。"}},{"pos":"VERB 动词","cn":"将…分散(在一段时间内);分期做","en":"If you spread something over a period of time, it takes place regularly or continuously over that period, rather than happening at one time.","ex":{"en":"There seems to be little difference whether you eat all your calorie allowance in one go, or spread it over the day","cn":"不管你是一次性摄入全天的卡路里限量，还是在一天内分次摄入，结果好像没有多大差别。"}},{"pos":"VERB 动词","cn":"分摊;均摊","en":"If you spread something such as wealth or work, you distribute it evenly or equally.","ex":{"en":"...policies that spread the state's wealth more evenly","cn":"更加平均地分配国家财富的政策"}},{"pos":"N-SING 单数名词","cn":"(想法、兴趣等的)广泛，多样","en":"A spread of ideas, interests, or other things is a wide variety of them.","ex":{"en":"A topic-based approach can be hard to assess in primary schools with a typical spread of ability","cn":"因为学生的能力通常差异很大，基于话题的教学方法在小学里评估起来可能很难。"}},{"pos":"N-COUNT 可数名词","cn":"(尤指为某一特殊场合准备的)丰盛饭菜，盛宴","en":"A spread is a large meal, especially one that has been prepared for a special occasion."},{"pos":"N-COUNT 可数名词","cn":"(书籍、杂志、报纸中)横贯两版的篇幅","en":"A spread is two pages of a book, magazine, or newspaper that are opposite each other when you open it at a particular place.","ex":{"en":"There was a double-page spread of a dinner for 46 people.","cn":"有一张横贯两版的、由 46 人参加的宴席的照片。"}},{"pos":"N-SING 单数名词","cn":"(股票的)价差","en":"Spread is used to refer to the difference between the price that a seller wants someone to pay for a particular stock or share and the price that the buyer is willing to pay.","ex":{"en":"Market makers earn their livings from the spread between buying and selling prices.","cn":"做市商靠赚取买卖价差生存。"}},{"pos":"","cn":"","en":"to spread your wings→see: ;"},{"pos":"","cn":"","en":"相关词组：spread out"}]},"examples":[{"en":"The company has a good geographical spread of hotels in this country.","cn":"该公司在这个国家开设的饭店地理分布相当广。"},{"en":"The story continued with a double-page spread on the inside pages.","cn":"这篇报道在报纸的内页有横贯两版的后续部分。"}]},"spice":{"media":{"img":["media/pic/spices_comp.jpg","media/thumb/staranise.jpg","media/ldoce/img/spice_bottles.jpg"],"uk":"media/uk/spice__gb_1.mp3","us":"media/us/spice__us_1.mp3"},"oxford":{"phon":"spaɪs","pos":"noun","senses":[{"en":"one of the various types of powder or seed that come from plants and are used in cooking. Spices have a strong taste and smell.","cn":"（调味）香料","g":"[countable, uncountable]","ex":{"en":"common spices such as ginger and cinnamon","cn":"姜和肉桂等常见香料"}},{"en":"extra interest or excitement","cn":"额外的趣味（或刺激等）","g":"[uncountable]","ex":{"en":"We need an exciting trip to add some spice to our lives.","cn":"我们需要一次新奇的旅行来调剂一下生活。"}},{"en":"a powerful illegal synthetic (= artificial) drug that some people smoke for the physical and mental effects that it has on them","cn":"合成大麻素","g":"[uncountable]","ex":{"en":"Six men overdosed on the synthetic drug known as spice.","cn":"六名男子过量服用了一种名为香料的合成药物。"}},{"en":"to add spice to food in order to give it more taste","cn":"在…中加香料","ex":{"en":"highly spiced dishes","cn":"高度香料的菜肴"},"pos":"verb"},{"en":"to add interest or excitement to something","cn":"给…增添趣味；使…变得刺激","ex":{"en":"He exaggerated the details to spice up the story.","cn":"他添油加醋，使故事更有趣味。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-MASS 物质名词","cn":"香料，佐料，调料，调味品(如肉桂、姜、辣椒粉等)","en":"A spice is a part of a plant, or a powder made from that part, which you put in food to give it flavour. Cinnamon, ginger, and paprika are spices.","ex":{"en":"...herbs and spices.","cn":"香草和香料"}},{"pos":"VERB 动词","cn":"使活泼生动;给…增添趣味","en":"If you spice something that you say or do, you add excitement or interest to it.","ex":{"en":"They spiced their conversations and discussions with intrigue.","cn":"他们的谈话和讨论透着些许的神秘。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"给生活增添情趣的事","en":"Spice is something which makes life more exciting.","ex":{"en":"Variety is the spice of life!","cn":"多样化使生活更有情趣！"}},{"pos":"","cn":"","en":"相关词组：spice up"}]},"examples":[{"en":"We need an exciting trip to add some spice to our lives.","cn":"我们需要一次新奇的旅行来调剂一下生活。"},{"en":"He exaggerated the details to spice up the story.","cn":"他添油加醋，使故事更有趣味。"}]},"speedboat":{"oxford":{"phon":"ˈspiːdbəʊt","pos":"noun","senses":[{"en":"a boat with a motor that can travel very fast","cn":"快艇"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"快艇","en":"A speedboat is a boat that can go very fast because it has a powerful engine."}]},"media":{"img":["media/ldoce/img/speedboat.jpg","media/pic/boats_comp.jpg"],"uk":"media/uk/speedboat__gb_1.mp3","us":"media/us/speedboat__us_1.mp3"}},"sparkling":{"oxford":{"phon":"ˈspɑːklɪŋ","pos":"adjective","senses":[{"en":"shining and flashing with light","cn":"闪烁的；闪耀的","lab":"less frequent, informal，，","ex":{"en":"the calm and sparkling waters of the lake","cn":"平静的波光粼粼的湖水"}},{"en":"containing bubbles of gas","cn":"有气泡的","ex":{"en":"a sparkling wine","cn":"汽酒"}},{"en":"interesting and funny","cn":"妙趣横生的","ex":{"en":"a sparkling conversation/personality","cn":"妙趣横生的谈话；风趣的人"}},{"en":"excellent; of very good quality","cn":"极佳的；卓越的；上乘的","ex":{"en":"The champion was in sparkling form.","cn":"夺冠者状态极佳。"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"(饮料)起泡的","en":"Sparkling drinks are slightly fizzy.","ex":{"en":"...a glass of sparkling wine.","cn":"一杯葡萄汽酒"}},{"pos":"ADJ 形容词","cn":"(公司业绩)斐然的，辉煌的","en":"If a company is described as having sparkling figures or sparkling results, it has performed very well and made a lot of money.","ex":{"en":"Top retailer Marks & Spencer has romped in with another set of sparkling results.","cn":"零售巨头玛莎百货再次凭借一系列耀眼的成绩轻松胜出。"}}]},"media":{"uk":"media/uk/sparkling__gb_1.mp3","us":"media/us/sparkling__us_1.mp3","img":["media/ldoce/img/ldoce_318.png"]},"examples":[{"en":"the calm and sparkling waters of the lake","cn":"平静的波光粼粼的湖水"},{"en":"The champion was in sparkling form.","cn":"夺冠者状态极佳。"}]},"spell":{"oxford":{"phon":"spel","pos":"verb","senses":[{"en":"to say or write the letters of a word in the correct order","cn":"用字母拼；拼写","g":"[transitive]","ex":{"en":"How do you spell your surname?","cn":"你的姓怎么拼？"}},{"en":"to form words correctly from individual letters","cn":"拼出，会拼（单词）","g":"[intransitive]","ex":{"en":"I've never been able to spell.","cn":"我一直不会拼写。"}},{"en":"to form words when they are put together in a particular order","cn":"拼作；拼成","g":"[transitive]","ex":{"en":"C—A—T spells ‘cat’.","cn":"C–A–T 拼作 cat。"}},{"en":"to have something, usually something bad, as a result; to mean something, usually something bad","cn":"招致，意味着（通常指坏事）","g":"[transitive]","ex":{"en":"The crop failure spelt disaster for many farmers.","cn":"对许多农民来说，庄稼歉收就意味着灾难。"}},{"en":"to replace for a short time somebody who is doing a particular activity so that they can rest","cn":"（短时间）替换，顶替","g":"[transitive]","lab":"North American English, informal，，","ex":{"en":"Carter will be here in an hour to spell you.","cn":"卡特一小时后过来替换你。"}},{"en":"a short period of time during which something lasts","cn":"（持续的）一段时间","g":"[countable]","ex":{"en":"We had a spell of warm weather in April.","cn":"4月份我们度过了一段温暖的日子。"},"pos":"noun"},{"en":"a period of time doing something or working somewhere","cn":"（干某事或在某处工作的）一段时间","g":"[countable]","ex":{"en":"She had a spell as a singer before becoming an actress.","cn":"在当演员以前她唱过一阵子歌。"},"pos":"noun"},{"en":"words that are thought to have magic power or to make a piece of magic work; a piece of magic that happens when somebody says these magic words","cn":"咒语；符咒；魔法","g":"[countable]","ex":{"en":"a magic spell","cn":"魔咒"},"pos":"noun"},{"en":"a quality that a person or thing has that makes them so attractive or interesting that they have a strong influence on you","cn":"魅力；魔力","g":"[singular]","ex":{"en":"I completely fell under her spell.","cn":"我完全给她迷住了。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"拼写;拼读","en":"When you spell a word, you write or speak each letter in the word in the correct order.","ex":{"en":"He gave his name and then helpfully spelt it","cn":"他说出自己的名字，然后又热心地将它拼了出来。"}},{"pos":"VERB 动词","cn":"(会)拼写(单词)","en":"Someone who can spell knows the correct order of letters in words.","ex":{"en":"It's shocking how students can't spell these days","cn":"当今的学生们拼写上差得令人吃惊。"}},{"pos":"VERB 动词","cn":"意味着，招致(常常是不愉快的结果)","en":"If something spells a particular result, often an unpleasant one, it suggests that this will be the result.","ex":{"en":"If the irrigation plan goes ahead, it could spell disaster for the birds","cn":"如果灌溉计划开始实施，它可能会给鸟类带来灾难。"}},{"pos":"N-COUNT 可数名词","cn":"(某种活动、天气等的)一段短暂时间，一阵","en":"A spell of a particular type of weather or a particular activity is a short period of time during which this type of weather or activity occurs.","ex":{"en":"There has been a long spell of dry weather","cn":"很长一段时间里天气一直很干燥。"}},{"pos":"N-COUNT 可数名词","cn":"魔法;妖术","en":"A spell is a situation in which events are controlled by a magical power.","ex":{"en":"They say she died after a witch cast a spell on her.","cn":"他们说她是被一个女巫施了魔法后死的。"}},{"pos":"PHRASE 短语","cn":"吸引;迷住","en":"If something or someone casts their spell on you or casts a spell on you, you are fascinated or charmed by them.","ex":{"en":"For many years sundials have cast their spell over scientists and mathematicians","cn":"多年来，日晷一直吸引着科学家和数学家们。"}},{"pos":"PHRASE 短语","cn":"被…迷住","en":"If you are under someone's spell, you are so fascinated by them that you cannot think about anything else.","ex":{"en":"Even sensible Frank had fallen under her spell.","cn":"甚至连一向理智的弗兰克都被她迷住了。"}},{"pos":"","cn":"","en":"相关词组：spell out"}]},"media":{"uk":"media/uk/spell__gb_1.mp3","us":"media/us/spell__us_1.mp3"},"examples":[{"en":"I thought her name was Catherine, but it's Kathryn spelt with a ‘K’.","cn":"我原以为她叫 Catherine，其实是 Kathryn，以 K 开头。"},{"en":"The crop failure spelt disaster for many farmers.","cn":"对许多农民来说，庄稼歉收就意味着灾难。"}]},"sporting":{"oxford":{"phon":"ˈspɔːtɪŋ","pos":"adjective","senses":[{"en":"connected with sports","cn":"体育运动的","g":"[only before noun]","lab":"North American English","ex":{"en":"a major sporting event","cn":"一项重要的体育赛事"}},{"en":"fair and generous in your treatment of other people, especially in a game or sport","cn":"风格高的；有良好体育风尚的","lab":"especially British English","ex":{"en":"The game was played in a very sporting spirit.","cn":"这场比赛充满了体育精神。"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"与体育运动有关的;体育运动用的","en":"Sporting means relating to sports or used for sports.","ex":{"en":"...major sporting events, such as Wimbledon and the World Cup finals.","cn":"主要的体育赛事，如温布尔登网球赛及世界杯决赛"}},{"pos":"PHRASE 短语","cn":"极大的可能","en":"If you have a sporting chance of doing something, it is quite likely that you will do that thing.","ex":{"en":"There was a sporting chance they would meet, but not necessarily at the party.","cn":"他们很有可能会见面，但不一定在聚会上。"}}]},"media":{"uk":"media/uk/sporting__gb_1.mp3","us":"media/us/sporting__us_1.mp3"},"examples":[{"en":"His main sporting interests are golf and tennis.","cn":"他在体育方面主要爱好高尔夫球和网球。"},{"en":"He sportingly agreed to play the point again.","cn":"他风格高，同意那一分重打。"}]},"spiritual":{"media":{"uk":"media/uk/spiritual__gb_1.mp3","us":"media/us/spiritual__us_1.mp3"},"oxford":{"phon":"ˈspɪrɪtʃuəl","pos":"adjective","senses":[{"en":"connected with the human spirit, rather than the body or physical things","cn":"精神的；心灵的","ex":{"en":"a spiritual experience","cn":"心灵体验"}},{"en":"connected with religion","cn":"宗教的","ex":{"en":"a spiritual leader","cn":"宗教领袖"}},{"en":"a religious song of the type created by black Christians in the southern states of the US","cn":"灵歌（宗教歌曲，最初为美国黑人奴隶所唱）","pos":"noun"}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"精神(上)的;心灵(上)的","en":"Spiritual means relating to people's thoughts and beliefs, rather than to their bodies and physical surroundings.","ex":{"en":"She lived entirely by spiritual values, in a world of poetry and imagination.","cn":"她追求精神上的满足，完全生活在一个诗歌和想象的世界里。"}},{"pos":"ADJ 形容词","cn":"宗教(上)的；宗教信仰(上)的","en":"Spiritual means relating to people's religious beliefs.","ex":{"en":"The spiritual leader of Ireland's 3.7 million Catholics","cn":"爱尔兰 370 万天主教徒的宗教领袖"}},{"pos":"N-COUNT 可数名词","cn":"灵歌(原为美国黑奴所唱的一种宗教歌曲)","en":"A spiritual is a religious song of the type originally sung by black slaves in America."},{"pos":"PHRASE 短语","cn":"精神家园;精神故乡","en":"Your spiritual home is the place where you feel that you belong, usually because your ideas or attitudes are the same as those of the people who live there."}]},"examples":[{"en":"a lack of spiritual values in the modern world","cn":"现代世界精神价值的缺失"},{"en":"We're concerned about your spiritual welfare.","cn":"我们担心你的心理健康。"}]},"spices":{"oxford":{"phon":"spaɪs","pos":"noun","senses":[{"en":"one of the various types of powder or seed that come from plants and are used in cooking. Spices have a strong taste and smell （","cn":"调味）香料"},{"en":"extra interest or excitement","cn":"额外的趣味（或刺激等）"}]},"media":{"img":["media/pic/spices_comp.jpg","media/thumb/staranise.jpg"],"uk":"media/uk/spice__gb_1.mp3","us":"media/us/spice__us_1.mp3"}},"spatial":{"media":{"uk":"media/uk/spatial__gb_1.mp3","us":"media/us/spatial__us_1.mp3"},"oxford":{"phon":"ˈspeɪʃl","pos":"adjective","senses":[{"en":"relating to space and the position, size, shape, etc. of things in it","cn":"空间的","ex":{"en":"changes taking place in the spatial distribution of the population","cn":"人口的地域分布所发生的变化"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"空间的;与空间有关的","en":"Spatial is used to describe things relating to areas.","ex":{"en":"...the spatial distribution of black employment and population in South Africa.","cn":"南非黑人就业与人口的空间分布"}},{"pos":"ADJ 形容词","cn":"(能力)理解立体空间的","en":"Your spatial ability is your ability to see and understand the relationships between shapes, spaces, and areas.","ex":{"en":"His manual dexterity and fine spatial skills were wasted on routine tasks.","cn":"他灵巧的动手能力和杰出的空间识别能力都浪费在日常事务上了。"}}]},"examples":[{"en":"changes taking place in the spatial distribution of the population","cn":"人口的地域分布所发生的变化"},{"en":"the development of a child's spatial awareness (= the ability to judge the positions and sizes of objects)","cn":"孩子空间意识的形成"}]},"spiral":{"oxford":{"phon":"ˈspaɪrəl","pos":"noun","senses":[{"en":"a shape or design, consisting of a continuous curved line that winds around a central point, with each curve further away from the centre","cn":"螺旋形；螺旋式","ex":{"en":"The birds circled in a slow spiral above the house.","cn":"鸟儿在房子上空缓缓盘旋。"}},{"en":"a continuous harmful increase or decrease in something, that gradually gets faster and faster","cn":"逐渐加速上升（或下降）","ex":{"en":"How can we halt the destructive spiral of violence in the inner cities?","cn":"我们怎样才能遏止内城区日益严重的破坏性暴力行为？"}},{"en":"moving in a continuous curve that winds around a central point","cn":"螺旋形的；螺旋式的","ex":{"en":"A snail's shell is spiral in form.","cn":"蜗牛壳呈螺旋形。"},"pos":"adjective"},{"en":"to move in continuous circles, going upwards or downwards","cn":"螺旋式上升（或下降）；盘旋上升（或下降）","g":"[intransitive]","ex":{"en":"Smoke spiralled into the sky.","cn":"烟雾盘旋升上天空。"},"pos":"verb"},{"en":"to increase rapidly","cn":"急剧增长","g":"[intransitive]","ex":{"en":"the spiralling cost of healthcare","cn":"急剧上涨的医疗费用"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"螺旋(形)","en":"A spiral is a shape which winds round and round, with each curve above or outside the previous one.","ex":{"en":"...a spiral staircase.","cn":"螺旋形楼梯"}},{"pos":"V-ERG 及物/不及物动词","cn":"(使)盘旋着生长(或移动)","en":"If something spirals or is spiralled somewhere, it grows or moves in a spiral curve.","ex":{"en":"Vines spiraled upward toward the roof","cn":"藤蔓盘旋着朝屋顶方向生长。"}},{"pos":"VERB 动词","cn":"(数量、水平)急遽增长","en":"If an amount or level spirals, it rises quickly and at an increasing rate.","ex":{"en":"Production costs began to spiral.","cn":"生产成本开始急遽上升。"}},{"pos":"VERB 动词","cn":"(数量、水平)急遽变化","en":"If an amount or level spirals downwards, it falls quickly and at an increasing rate.","ex":{"en":"House prices will continue to spiral downwards.","cn":"房价将继续暴跌。"}}]},"media":{"uk":"media/uk/spiral__gb_1.mp3","us":"media/us/spiral__us_1.mp3"},"examples":[{"en":"measures to control the inflationary spiral","cn":"控制日益恶化的通货膨胀的措施"},{"en":"The birds circled in a slow spiral above the house.","cn":"鸟儿在房子上空缓缓盘旋。"}]},"spoke":{"media":{"uk":"media/uk/spoke__gb_2.mp3","us":"media/us/spoke__us_2.mp3","img":["media/ldoce/img/mountain_bike.jpg"]},"oxford":{"phon":"spəʊk","pos":"noun","senses":[{"en":"one of the thin bars or long, straight pieces of metal that connect the centre of a wheel to its outer edge, for example on a bicycle","cn":"辐条；轮辐"}]},"collins":{"senses":[{"pos":"","cn":"","en":"Spoke is the past tense of speak ."},{"pos":"N-COUNT 可数名词","cn":"(车轮的)辐条","en":"The spokes of a wheel are the bars that connect the outer ring to the centre."}]}},"sport":{"media":{"img":["media/pic/sports_comp.jpg","media/thumb/basketball.jpg"],"uk":"media/uk/sport__gb_1.mp3","us":"media/us/sport__us_1.mp3"},"oxford":{"phon":"spɔːt","pos":"noun","senses":[{"en":"activity that you do for pleasure and that needs physical effort or skill, usually done in a special area and according to fixed rules","cn":"体育运动","g":"[uncountable]","lab":"British English","ex":{"en":"There are excellent facilities for sport and recreation.","cn":"有完善的体育娱乐设施。"}},{"en":"a particular form of sport","cn":"（某项）体育运动","g":"[countable]","ex":{"en":"What's your favourite sport?","cn":"你最喜欢哪一项体育运动？"}},{"en":"used as a friendly way of addressing somebody, especially a man","cn":"（用作友好称呼，尤指对男子）朋友，老兄，哥们儿","g":"[countable]","lab":"Australian English, New Zealand English, informal，，，，","ex":{"en":"How are you doing, sport?","cn":"你好哇，哥儿们！"}},{"en":"pleasure or fun","cn":"乐趣；消遣；玩笑","g":"[uncountable]","lab":"old-fashioned","ex":{"en":"The comments were only made in sport.","cn":"那些话只不过是开个玩笑。"}},{"en":"a plant or an animal that is clearly and definitely different from its usual type","cn":"芽变；突变；变种","g":"[countable]","lab":"biology"},{"en":"to have or wear something in a proud way","cn":"得意地穿戴；夸示；故意显示","g":"[transitive]","ex":{"en":"to sport a beard","cn":"故意蓄着大胡子"},"pos":"verb"},{"en":"to play in a happy and lively way","cn":"开心活泼地玩；嬉戏","g":"[intransitive]","lab":"literary","pos":"verb"}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"体育运动;运动","en":"Sports are games such as football and basketball and other competitive leisure activities which need physical effort and skill.","ex":{"en":"I'd say football is my favourite sport","cn":"我最喜欢的运动要数足球了。"}},{"pos":"N-COUNT 可数名词","cn":"开朗大度的人","en":"If you say that someone is a sport or a good sport, you mean that they cope with a difficult situation or teasing in a cheerful way.","ex":{"en":"He was accused of having no sense of humor, of not being a good sport.","cn":"他被指责缺乏幽默感，不够大度。"}},{"pos":"VERB 动词","cn":"引人注目地穿戴;炫耀","en":"If you say that someone sports something such as a distinctive item of clothing, you mean that they wear it without any shyness.","ex":{"en":"He sported a collarless jacket with pleated black panels","cn":"他穿着一件带有黑色褶子饰条的无领上衣。"}}]},"examples":[{"en":"She was sporting a T-shirt with the company's logo on it.","cn":"她穿了一件带有公司徽标的 T 恤衫，很是炫耀。"},{"en":"What's your favourite sport?","cn":"你最喜欢哪一项体育运动？"}]},"spotlight":{"oxford":{"phon":"ˈspɒtlaɪt","pos":"noun","senses":[{"en":"a light with a single, very bright beam that can be directed at a particular place or person, especially a performer on the stage","cn":"聚光灯","g":"[countable]","lab":"informal","ex":{"en":"The room was lit by spotlights.","cn":"房间被聚光灯照亮。"}},{"en":"the area of light that is made by a spotlight","cn":"聚光灯照亮的地方；聚光灯照明圈","g":"[uncountable]","ex":{"en":"She stood alone on stage in the spotlight.","cn":"她独自站在舞台的聚光灯下。"}},{"en":"attention from newspapers, television and the public","cn":"媒体和公众的注意","g":"[uncountable]","ex":{"en":"Unemployment is once again in the spotlight.","cn":"失业问题再次受到人们的关注。"}},{"en":"to shine a spotlight on somebody/something","cn":"用聚光灯照","ex":{"en":"a spotlit stage","cn":"聚光灯照亮的舞台"},"pos":"verb"},{"en":"to give special attention to a problem, situation, etc. so that people notice it","cn":"特别关注，突出报道（以使公众注意）","ex":{"en":"The programme spotlights financial problems in the health service.","cn":"节目突出报道了公共医疗机构的财政问题。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"聚光灯","en":"A spotlight is a powerful light, for example in a theatre, which can be directed so that it lights up a small area."},{"pos":"VERB 动词","cn":"使受关注;使突出醒目","en":"If something spotlights a particular problem or situation, it makes people notice it and think about it.","ex":{"en":"The budget crisis also spotlighted a weakening American economy.","cn":"预算危机也突显了正在衰退的美国经济。"}},{"pos":"PHRASE 短语","cn":"成为公众关注的焦点;受到瞩目","en":"Someone or something that is in the spotlight is getting a great deal of public attention.","ex":{"en":"Webb is back in the spotlight.","cn":"韦布又重新成为焦点。"}},{"pos":"PHRASE 短语","cn":"备受(媒体和公众的)关注","en":"If someone or something comes under the spotlight, they are thoroughly examined, especially by journalists and the public.","ex":{"en":"The economy will come under the spotlight today at the conference of the Trades Union Congress.","cn":"经济将会成为今天工会代表大会会议上的焦点。"}}]},"media":{"img":["media/pic/lamps_livingroom_comp.jpg","media/thumb/spotlight.jpg"],"uk":"media/uk/spotlight__gb_1.mp3","us":"media/us/spotlight__us_1.mp3"},"examples":[{"en":"The report has turned the spotlight on the startling rise in street crime.","cn":"报道使人们将关注的目光投向街头犯罪激增的问题。"},{"en":"The issue will come under the spotlight when parliament reassembles.","cn":"等议会重开的时候，这个问题将成为焦点。"}]},"speeds":{"oxford":{"phon":"spiːd","pos":"noun","senses":[{"en":"the rate at which sb/sth moves or travels （","cn":"运动的）速度，速率"},{"en":"the rate at which sth happens or is done （","cn":"发生或进行的）速度；进度"}]},"media":{"uk":"media/uk/speed__gb_1.mp3","us":"media/us/speed__us_1.mp3"}},"specialty":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"专业;专长","en":"Someone's specialty is a particular type of work that they do most or do best, or a subject that they know a lot about.","ex":{"en":"His specialty is international law","cn":"他的专业是国际法。"}},{"pos":"N-COUNT 可数名词","cn":"(某个地方的)特色食品，特产","en":"A specialty of a particular place is a special food or product that is always very good there.","ex":{"en":"...seafood, paella, empanadas and other specialties.","cn":"海鲜、西班牙肉菜饭、南美肉馅卷饼和其他特色食品"}}]},"media":{"uk":"media/uk/specialty__gb_1.mp3","us":"media/us/specialty__us_1.mp3"},"examples":[{"en":"Doctors training for General Practice must complete programmes in a number of specialties, including Paediatrics.","cn":"接受全科培训的医生必须修完包括儿科学在内的多门专业课程。"},{"en":"Her specialty is taxation law.","cn":"她的专长是税法。"}],"oxford":{"phon":"ˈspeʃəlti","pos":"noun","senses":[{"en":"a type of food or product that a restaurant or place is famous for because it is so good","cn":"特产；特色菜","ex":{"en":"regional specialties","cn":"地方特产"}},{"en":"an area of work or study that somebody gives most of their attention to and knows a lot about; something that somebody is good at","cn":"专业；专长","ex":{"en":"Her specialty is taxation law.","cn":"她的专长是税法。"}}]}},"spokesman":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"男发言人","en":"A spokesman is a male spokesperson.","ex":{"en":"A UN spokesman said that the mission will carry 20 tons of relief supplies.","cn":"联合国的一名男发言人说，该代表团将携带 20 吨救济物资。"}}]},"media":{"uk":"media/ldoce/hwd/bre/e/spokesman0205.mp3","us":"media/ldoce/hwd/ame/4/laadspokesman.mp3"},"examples":[{"en":"a spokesman for the victims’ families","cn":"受害者家属发言人"},{"en":"a White House spokesman","cn":"白宫发言人"}],"oxford":{"phon":"ˈspəʊksmən","pos":"noun","senses":[{"en":"a person who speaks for a group or an organization","cn":"发言人","lab":"British English","ex":{"en":"a police spokesman","cn":"警方发言人"}}]}},"spare":{"media":{"uk":"media/uk/spare__gb_1.mp3","us":"media/us/spare__us_1.mp3"},"oxford":{"phon":"speə(r)","pos":"adjective","senses":[{"en":"available to do what you want with rather than work","cn":"空闲的；空余的","sc":"time","ex":{"en":"He's studying music in his spare time.","cn":"他在空闲时间学音乐。"}},{"en":"that is not being used or is not needed at the present time","cn":"不用的；闲置的","g":"[usually before noun]","sc":"not used/needed","ex":{"en":"We've got a spare bedroom, if you'd like to stay.","cn":"要是愿意你就住下，我们空着一间卧室。"}},{"en":"kept in case you need to replace the one you usually use; extra","cn":"备用的；外加的","g":"[only before noun]","sc":"extra","ex":{"en":"a spare key/tyre","cn":"备用钥匙／轮胎"}},{"en":"thin, and usually quite tall","cn":"瘦的；瘦高的","sc":"person"},{"en":"to make something such as time or money available to somebody or for something, especially when it requires an effort for you to do this","cn":"抽出；拨出；留出；匀出","sc":"time/money/room/thought, etc.","ex":{"en":"I'd love to have a break, but I can't spare the time just now.","cn":"我是想休息一下，可眼下找不出时间。"},"pos":"verb"},{"en":"to save somebody/yourself from having to go through an unpleasant experience","cn":"省得；免去","sc":"save somebody pain/trouble","ex":{"en":"He wanted to spare his mother any anxiety.","cn":"他不想让母亲有丝毫的担忧。"},"pos":"verb"},{"en":"to allow somebody/something to escape harm, damage or death, especially when others do not escape it","cn":"饶恕；赦免；放过；使逃脱","lab":"formal","sc":"not harm/damage","ex":{"en":"They killed the men but spared the children.","cn":"他们杀死了大人，但放过了孩子。"},"pos":"verb"},{"en":"to do everything possible to achieve something or to do something well without trying to limit the time or money involved","cn":"不吝惜（时间、金钱）","sc":"no effort/expense, etc.","ex":{"en":"He spared no effort to make her happy again.","cn":"为使她重新快乐起来，他想尽了办法。"},"pos":"verb"},{"en":"to work as hard as possible","cn":"不遗余力","sc":"work hard","pos":"verb"},{"en":"an extra thing that you keep in case you need to replace the one you usually use (used especially about a tyre of a car)","cn":"备用品；备用轮胎","ex":{"en":"to get the spare out of the boot/trunk","cn":"从汽车行李箱中取出备用轮胎"},"pos":"noun"},{"en":"spare parts (= new parts that you buy to replace old or broken parts of a car, machine, etc.)","cn":"备用零件","g":"[plural]","lab":"especially British English","ex":{"en":"It can be difficult to get spares for some older makes of car.","cn":"有些旧型号汽车可能不好买配件。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"备用的;预备的","en":"You use spare to describe something that is the same as things that you are already using, but that you do not need yet and are keeping ready in case another one is needed.","ex":{"en":"If possible keep a spare pair of glasses accessible in case your main pair is broken or lost","cn":"如果有可能的话，最好准备一副备用眼镜，以防常用的那副眼镜打碎或者丢失。"}},{"pos":"ADJ 形容词","cn":"剩下的;多余的;空闲的","en":"You use spare to describe something that is not being used by anyone, and is therefore available for someone to use.","ex":{"en":"They don't have a lot of spare cash","cn":"他们没有多少闲钱。"}},{"pos":"VERB 动词","cn":"剩余，剩下(时间、金钱或空间)","en":"If you have something such as time, money, or space to spare, you have some extra time, money, or space that you have not used or which you do not need.","ex":{"en":"You got here with ninety seconds to spare","cn":"你到这里的时候还剩 90 秒钟时间。"}},{"pos":"VERB 动词","cn":"抽出，拨出(金钱或其他资源)","en":"If you spare time or another resource for a particular purpose, you make it available for that purpose.","ex":{"en":"She said that she could only spare 35 minutes for our meeting","cn":"她说她只能抽出 35 分钟时间参加我们的会议。"}},{"pos":"VERB 动词","cn":"使免遭伤害;使幸免","en":"If a person or a place is spared, they are not harmed, even though other people or places have been.","ex":{"en":"We have lost everything, but thank God, our lives have been spared","cn":"我们已经失去了一切，不过谢天谢地，总算是保住了性命。"}},{"pos":"VERB 动词","cn":"不让…难堪(或难过)","en":"If you spare someone an unpleasant experience, you prevent them from suffering it.","ex":{"en":"I wanted to spare Frances the embarrassment of discussing this subject","cn":"讨论这个话题太尴尬，我不想让弗朗西斯难堪。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"瘦削的","en":"Someone who is described as spare is tall and not at all fat.","ex":{"en":"She was thin and spare, with a sharply intelligent face.","cn":"她又高又瘦，一副精明过人的模样。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"简单的;不加修饰的;简朴的","en":"Something such as a room that is spare is very plain with no unnecessary features.","ex":{"en":"Inside, the two small rooms were spare and neat, stripped bare of ornaments.","cn":"进去以后是两个简单而整洁的小房间，朴实无华，没有什么装饰。"}},{"pos":"PHRASE 短语","cn":"不遗余力/不惜工本","en":"If you spare no effort in doing something, you do it as well as possible, without worrying about the amount of work involved. If you spare no expense in doing it, you do it as well as possible, without trying to save money.","ex":{"en":"The government is determined to spare no effort in investigating this case thoroughly","cn":"政府决定不遗余力地彻底调查这个案子。"}},{"pos":"PHRASE 短语","cn":"可怜一下(不幸的人)","en":"If you spare a thought for an unfortunate person, you make an effort to think sympathetically about them and their bad luck.","ex":{"en":"Spare a thought for the nation's shopkeepers — consumer sales slid again in May","cn":"可怜一下这个国家的店老板吧—— 5 月份消费品的销售量又下滑了。"}},{"pos":"","cn":"","en":"to spare someone's blushes→see: ;"}]},"examples":[{"en":"Hong Kong was spared a direct hit, but the storm still brought heavy rains and powerful winds.","cn":"香港虽然未遭正面吹袭，但风暴还是带来了大雨和强风。"},{"en":"Could you spare one of your staff to help us out?","cn":"你能不能从你手下抽一个人过来帮帮我们？"}]},"spelling":{"oxford":{"phon":"ˈspelɪŋ","pos":"noun","senses":[{"en":"the act of forming words correctly from individual letters; the ability to do this","cn":"拼写；拼写能力","g":"[uncountable]","ex":{"en":"the differences between British and American spelling","cn":"英式英语和美式英语在拼写方面的区别"}},{"en":"the way that a particular word is written","cn":"拼法","g":"[countable]","ex":{"en":"a list of difficult spellings","cn":"难拼单词表"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"拼法;拼写;拼读","en":"A spelling is the correct order of the letters in a word.","ex":{"en":"In most languages adjectives have slightly different spellings for masculine and feminine","cn":"在多数语言中，形容词的阳性和阴性的拼法略为不同。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"正确拼写单词的能力;拼写","en":"Spelling is the ability to spell words in the correct way. It is also an attempt to spell a word in the correct way.","ex":{"en":"His spelling is very bad","cn":"他的拼写能力很差。"}}]},"media":{"uk":"media/uk/spelling__gb_1.mp3","us":"media/us/spelling__us_1.mp3"},"examples":[{"en":"the differences between British and American spelling","cn":"英式英语和美式英语在拼写方面的区别"},{"en":"My spelling is terrible.","cn":"我的拼写很糟糕。"}]},"specifically":{"media":{"uk":"media/uk/specifically__gb_1.mp3","us":"media/us/specifically__us_1.mp3"},"oxford":{"phon":"spəˈsɪfɪkli","pos":"adverb","senses":[{"en":"connected with or intended for one particular thing only","cn":"特意；专门地","ex":{"en":"liquid vitamins specifically designed for children","cn":"专为儿童设计的液态维生素"}},{"en":"in a detailed and exact way","cn":"明确地；具体地","ex":{"en":"She had specifically asked him to keep her updated on the investigation.","cn":"她明确要求他及时告知调查的最新进展。"}},{"en":"used when you want to add more detailed and exact information","cn":"具体来说；确切地说","ex":{"en":"The newspaper, or more specifically, the editor, was taken to court for publishing the photographs.","cn":"那家报纸，更确切地说是那家报纸的编辑，因刊登那些照片而遭起诉。"}}]},"collins":{"senses":[{"pos":"ADV 副词","cn":"特别地;特意地;专门地","en":"You use specifically to emphasize that something is given special attention and considered separately from other things of the same kind.","ex":{"en":"...the first nursing home designed specifically for people with AIDS","cn":"首家专为艾滋病人设计的疗养院"}},{"pos":"ADV 副词","cn":"确切地说","en":"You use specifically to add something more precise or exact to what you have already said.","ex":{"en":"Death frightens me, specifically my own death.","cn":"死亡让我感到恐惧，确切地说，是我自己的死亡。"}},{"pos":"ADV 副词","cn":"局限性地","en":"You use specifically to indicate that something has a restricted nature, as opposed to being more general in nature.","ex":{"en":"...a specifically female audience","cn":"只由女性组成的听众"}},{"pos":"ADV 副词","cn":"准确地;确切地","en":"If you state or describe something specifically, you state or describe it precisely and clearly.","ex":{"en":"I asked her to repeat specifically the words that Patti had used","cn":"我让她原原本本地重复一下帕蒂的措辞。"}}]},"examples":[{"en":"The newspaper, or more specifically, the editor, was taken to court for publishing the photographs.","cn":"那家报纸，更确切地说是那家报纸的编辑，因刊登那些照片而遭起诉。"},{"en":"I specifically told you not to go near the water!","cn":"我明确告诉过你不要靠近水边！"}]},"spur":{"media":{"uk":"media/uk/spur__gb_1.mp3","us":"media/us/spur__us_1.mp3"},"oxford":{"phon":"spɜː(r)","pos":"noun","senses":[{"en":"a sharp pointed object that riders sometimes wear on the heels of their boots and use to encourage their horse to go faster","cn":"马刺；靴刺","ex":{"en":"He dug his spurs into the horse’s sides.","cn":"他用马刺刺进马的两侧。"}},{"en":"a fact or an event that makes you want to do something better or more quickly","cn":"鞭策；激励；刺激；鼓舞","g":"[usually singular]","ex":{"en":"His speech was a powerful spur to action.","cn":"他的讲话很有鼓动力。"}},{"en":"an area of high ground that sticks out from a mountain or hill","cn":"山嘴；尖坡；支脉"},{"en":"a road or a railway track that leads from the main road or line","cn":"（公路或铁路的）支线，岔线"},{"en":"to encourage somebody to do something or to encourage them to try harder to achieve something","cn":"鞭策；激励；刺激；鼓舞","ex":{"en":"Her difficult childhood spurred her on to succeed.","cn":"她艰辛的童年激励她取得成功。"},"pos":"verb"},{"en":"to make something happen faster or sooner","cn":"促进，加速，刺激（某事发生）","ex":{"en":"The agreement is essential to spurring economic growth around the world.","cn":"这项协议对于促进世界经济的增长是至关重要的。"},"pos":"verb"},{"en":"to encourage a horse to go faster, especially by pushing the spurs on your boots into its side","cn":"策（马）前进；（尤指用马刺）策（马）加速","ex":{"en":"As he shouted his order he spurred the horse forward suddenly.","cn":"他一声令下，猛地策马前行。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"鼓励;激励","en":"If one thing spurs you to do another, it encourages you to do it.","ex":{"en":"It's the money that spurs these fishermen to risk a long ocean journey in their flimsy boats","cn":"是金钱驱使这些渔民驾着破旧小船冒险出海远航。"}},{"pos":"VERB 动词","cn":"促进;加速;推动","en":"If something spurs a change or event, it makes it happen faster or sooner.","ex":{"en":"The administration may put more emphasis on spurring economic growth","cn":"政府可能会更加重视推动经济增长。"}},{"pos":"N-COUNT 可数名词","cn":"刺激;激励;推动力","en":"Something that acts as a spur to something else encourages a person or organization to do that thing or makes it happen more quickly.","ex":{"en":"...a belief in competition as a spur to efficiency","cn":"认为竞争会促进效率的信念"}},{"pos":"N-COUNT 可数名词","cn":"马刺;靴刺","en":"Spurs are small metal wheels with sharp points that are attached to the heels of a rider's boots. The rider uses them to make their horse go faster."},{"pos":"N-COUNT 可数名词","cn":"山嘴;尖坡","en":"The spur of a hill or mountain is a piece of ground which sticks out from its side."},{"pos":"PHRASE 短语","cn":"一时冲动;心血来潮","en":"If you do something on the spur of the moment, you do it suddenly, without planning it beforehand.","ex":{"en":"They admitted they had taken a vehicle on the spur of the moment","cn":"他们承认是一时冲动偷走了一辆车。"}},{"pos":"PHRASE 短语","cn":"获得地位;赢得名望","en":"If you win your spurs or earn your spurs, you achieve a particular status by proving that you can do something skilfully.","ex":{"en":"Young conductors earn their spurs in a small orchestra or opera house.","cn":"年轻的指挥家们在小乐队或小歌剧院里崭露头角。"}}]},"examples":[{"en":"The agreement is essential to spurring economic growth around the world.","cn":"这项协议对于促进世界经济的增长是至关重要的。"},{"en":"The band has been spurred on by the success of their last single.","cn":"最近一张单曲唱片的成功使乐队受到鼓舞。"}]},"spoilt":{"oxford":{"phon":"spɔɪlt","pos":"adjective","senses":[{"en":"rude and badly behaved because they are given everything they ask for and not enough discipline","cn":"宠坏的；娇惯坏的","ex":{"en":"a spoiled brat","cn":"娇惯坏的淘气鬼"}}]},"media":{"uk":"media/uk/spoilt__gb_2.mp3","us":"media/us/spoilt__us_2.mp3"},"examples":[{"en":"He's spoilt rotten (= a lot).","cn":"他给惯得一点样子都没有了。"},{"en":"a spoiled brat","cn":"娇惯坏的淘气鬼"}],"collins":{"senses":[{"pos":"","cn":"","en":"Spoilt is a past participle and past tense of spoil."}]}},"specialized":{"media":{"uk":"media/uk/specialized__gb_1.mp3","us":"media/us/specialized__us_1.mp3"},"oxford":{"phon":"ˈspeʃəlaɪzd","pos":"adjective","senses":[{"en":"designed or developed for a particular purpose or area of knowledge","cn":"专用的；专业的；专门的","ex":{"en":"specialized equipment","cn":"专用设备"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"专业化的;专门的;特殊的","en":"Someone or something that is specialized is trained or developed for a particular purpose or area of knowledge.","ex":{"en":"Cocaine addicts get specialized support from knowledgeable staff.","cn":"对可卡因上瘾的人从那些懂相关知识的工作人员那里得到了专业化的帮助。"}}]},"examples":[{"en":"specialized equipment","cn":"专用设备"},{"en":"specialized skills","cn":"专门技能"}]},"spirit":{"media":{"uk":"media/uk/spirit__gb_1.mp3","us":"media/us/spirit__us_1.mp3"},"oxford":{"phon":"ˈspɪrɪt","pos":"noun","senses":[{"en":"the part of a person that includes their mind, feelings and character rather than their body","cn":"精神；心灵","g":"[uncountable, countable]","sc":"mind/feelings/character","ex":{"en":"You are underestimating the power of the human spirit to overcome difficulties.","cn":"你低估了人类克服困难的精神力量。"}},{"en":"a person’s feelings or state of mind","cn":"情绪；心境","g":"[plural]","sc":"mind/feelings/character","ex":{"en":"to be in high/low spirits","cn":"情绪高涨／低落"}},{"en":"a person of the type mentioned","cn":"（某种类型的）人","g":"[countable]","sc":"mind/feelings/character","ex":{"en":"a brave spirit","cn":"勇敢的人"}},{"en":"courage, energy or determination","cn":"勇气；活力；意志","g":"[uncountable]","sc":"courage/energy","ex":{"en":"Peter had a good game and showed his true spirit.","cn":"彼得打出了一场精彩的比赛，展现了他真正的精神。"}},{"en":"feelings of support towards a group, team or society","cn":"（对团体、队伍、社会的）忠心，忠诚","g":"[uncountable, singular]","sc":"feelings of support","ex":{"en":"There's not much community spirit around here.","cn":"这里集体精神比较薄弱。"}},{"en":"the typical or most important quality or mood of something","cn":"本质；精髓；基本精神","g":"[singular]","sc":"typical quality","ex":{"en":"The exhibition captures the spirit of the age/times.","cn":"这场展览抓住了时代精神。"}},{"en":"a state of mind or mood; an attitude","cn":"心态；态度","g":"[singular]","sc":"attitude","ex":{"en":"We approached the situation in the wrong spirit.","cn":"我们以前对待局势的心态不对。"}},{"en":"the real or intended meaning or purpose of something","cn":"真实意义；实质","g":"[uncountable]","sc":"real meaning","ex":{"en":"Obey the spirit, not the letter (= the narrow meaning of the words) of the law.","cn":"要依照法律的精神实质，而不是字面意思。"}},{"en":"the soul thought of as separate from the body and believed to live on after death; a ghost","cn":"灵魂；鬼魂；幽灵","g":"[countable]","sc":"soul","ex":{"en":"He is dead, but his spirit lives on.","cn":"他死了，但他的灵魂将永存。"}},{"en":"an imaginary creature with magic powers, for example, a fairy or an elf","cn":"仙子；小精灵；小妖精","g":"[countable]","lab":"old-fashioned","sc":"imaginary creature"},{"en":"a strong alcoholic drink","cn":"烈酒","g":"[countable, usually plural]","lab":"especially British English","sc":"alcohol","ex":{"en":"I don't drink whisky or brandy or any other spirits.","cn":"我不喝威士忌和白兰地，也不喝其他烈性酒。"}},{"en":"a special type of alcohol used in industry or medicine","cn":"工业酒精；医用酒精","g":"[uncountable]","sc":"alcohol"},{"en":"to take somebody/something away in a quick, secret or mysterious way","cn":"偷偷带走；让人不可思议地弄走","ex":{"en":"After the concert, the band was spirited away before their fans could get near them.","cn":"音乐会结束后，乐队没等歌迷靠近就神秘地消失了。"},"pos":"verb"},{"en":"the second Mars Rover vehicle which landed on the planet Mars in 2004 and sent pictures of the surface of the planet back to NASA","cn":"勇气号火星探测器","pos":""}]},"collins":{"senses":[{"pos":"N-SING 单数名词","cn":"精神;心灵","en":"Your spirit is the part of you that is not physical and that consists of your character and feelings.","ex":{"en":"The human spirit is virtually indestructible","cn":"人的精神实际上是不可摧毁的。"}},{"pos":"N-COUNT 可数名词","cn":"灵魂","en":"A person's spirit is the non-physical part of them that is believed to remain alive after their death.","ex":{"en":"His spirit has left him and all that remains is the shell of his body.","cn":"他已灵魂出窍，剩下的只是他的躯壳。"}},{"pos":"N-COUNT 可数名词","cn":"鬼魂;幽灵","en":"A spirit is a ghost or supernatural being.","ex":{"en":"...protection against evil spirits.","cn":"避邪"}},{"pos":"N-UNCOUNT 不可数名词","cn":"勇气;意志","en":"Spirit is the courage and determination that helps people to survive in difficult times and to keep their way of life and their beliefs.","ex":{"en":"She was a very brave girl and everyone who knew her admired her spirit.","cn":"她是个非常勇敢的女孩，认识她的人都敬佩她的勇气。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"生命力;精力;活力","en":"Spirit is the liveliness and energy that someone shows in what they do.","ex":{"en":"They played with spirit.","cn":"他们打得生龙活虎。"}},{"pos":"N-SING 单数名词","cn":"(对待事物的)态度","en":"The spirit in which you do something is the attitude you have when you are doing it.","ex":{"en":"Their problem can only be solved in a spirit of compromise","cn":"他们的问题只能通过妥协来解决。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"(团体成员对团体的)忠诚度","en":"A particular kind of spirit is the feeling of loyalty to a group that is shared by the people who belong to the group.","ex":{"en":"There is a great sense of team spirit among the British Olympic squad","cn":"在英国的奥运代表团中有一种强烈的团队精神。"}},{"pos":"N-SING 单数名词","cn":"精神(指某一群体特有的思想、信念、目标)","en":"A particular kind of spirit is the set of ideas, beliefs, and aims that are held by a group of people.","ex":{"en":"...the real spirit of the Labour movement.","cn":"劳工运动的精髓"}},{"pos":"N-SING 单数名词","cn":"(法律、协议等的)原意,实质，精神","en":"The spirit of something such as a law or an agreement is the way that it was intended to be interpreted or applied.","ex":{"en":"The requirement for work permits violates the spirit of the 1950 treaty.","cn":"对工作许可证的要求违反了 1950 年条约的精神。"}},{"pos":"N-COUNT 可数名词","cn":"(具有特定品质的)人","en":"You can refer to a person as a particular kind of spirit if they show a certain characteristic or if they show a lot of enthusiasm in what they are doing.","ex":{"en":"I like to think of myself as a free spirit","cn":"我愿意把自己看成是个无拘无束的人。"}},{"pos":"N-PLURAL 复数名词","cn":"情绪;心情;兴致","en":"Your spirits are your feelings at a particular time, especially feelings of happiness or unhappiness.","ex":{"en":"At supper, everyone was in high spirits","cn":"晚餐时，每个人都兴致勃勃。"}},{"pos":"VERB 动词","cn":"把…迅速而秘密地带走","en":"If someone or something is spirited away, or if they are spirited out of somewhere, they are taken from a place quickly and secretly without anyone noticing.","ex":{"en":"He was spirited away and probably murdered","cn":"他被秘密带走，可能被杀害了。"}},{"pos":"N-PLURAL 复数名词","cn":"(威士忌、杜松子酒等)烈性酒","en":"Spirits are strong alcoholic drinks such as whisky and gin."},{"pos":"N-UNCOUNT 不可数名词","cn":"(用作燃料、清洗等用途的)酒精","en":"Spirit or spirits is an alcoholic liquid that is used as a fuel, for cleaning things, or for other purposes. There are many kinds of spirit."},{"pos":"PHRASE 短语","cn":"热情地参加","en":"If you enter into the spirit of something, you take part in it in an enthusiastic way."},{"pos":"PHRASE 短语","cn":"精神上(在某地或和某人在一起，但实际上本人并不在场)","en":"If you say you are somewhere in spirit or with someone in spirit, you mean that although you are not with them, you feel as though you are with them because you are thinking about them a lot.","ex":{"en":"In spirit I was with you here.","cn":"我在精神上支持你。"}},{"pos":"PHRASE 短语","cn":"本质上","en":"You use in spirit when you are talking about someone's true nature.","ex":{"en":"They seemed close in spirit to those first independent-minded Turkish women who took professions","cn":"她们在本质上似乎和那些最早出去工作的具有独立思想的土耳其女性很相似。"}},{"pos":"PHRASE 短语","cn":"时代精神","en":"The spirit of the age or the spirit of the times is the set of ideas, beliefs, and aims that is typical of people in a particular period in history."}]},"examples":[{"en":"After the concert, the band was spirited away before their fans could get near them.","cn":"音乐会结束后，乐队没等歌迷靠近就神秘地消失了。"},{"en":"My spirits sank at the prospect of starting all over again.","cn":"想到一切都得从头再来，我的情绪一下子低落了。"}]},"spout":{"oxford":{"phon":"spaʊt","pos":"noun","senses":[{"en":"a pipe or tube on a container through which you can pour liquid out","cn":"（容器的）嘴","ex":{"en":"the spout of a teapot","cn":"茶壶嘴"}},{"en":"a stream of liquid coming out of somewhere with great force","cn":"（喷出的）水柱，液体柱"},{"en":"to send out something, especially a liquid, in a stream with great force; to come out of something in this way","cn":"喷出；喷射","g":"[transitive, intransitive]","ex":{"en":"The wound was still spouting blood.","cn":"伤口还在喷血。"},"pos":"verb"},{"en":"to send out a stream of water from a hole in its head","cn":"喷水","g":"[intransitive]","pos":"verb"},{"en":"to speak a lot about something; to repeat something in a boring or annoying way","cn":"滔滔不绝地说；喋喋不休地说","g":"[intransitive, transitive]","lab":"informal, disapproving，，","ex":{"en":"He's always spouting off about being a vegetarian.","cn":"他老把自己吃素挂在嘴边。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"V-ERG 及物/不及物动词","cn":"喷出;涌出","en":"If something spouts liquid or fire, or if liquid or fire spout out of something, it comes out very quickly with a lot of force.","ex":{"en":"He replaced the boiler when the last one began to spout flames","cn":"原来的锅炉开始往外喷火苗后他便换了个新的。"}},{"pos":"N-COUNT 可数名词","cn":"(迅速喷出的)液流，水柱","en":"A spout of liquid is a long stream of it which is coming out of something very forcefully."},{"pos":"VERB 动词","cn":"喋喋不休地说;夸夸其谈","en":"If you say that a person spouts something, you disapprove of them because they say something which you do not agree with or which you think they do not honestly feel.","ex":{"en":"He used his column to spout ill-informed criticism of the Scots rugby team.","cn":"他根本不了解苏格兰橄榄球队，却在自己的专栏上对其大加抨击。"}},{"pos":"N-COUNT 可数名词","cn":"容器嘴;喷嘴;喷口","en":"A spout is a long, hollow part of a container through which liquids can be poured out easily."},{"pos":"PHRASE 短语","cn":"错误的;出问题的","en":"If you say that something is up the spout, you mean that it is wrong or it is no longer working.","ex":{"en":"If you only take a sample then all the statistics are up the spout.","cn":"如果你只采集了一个样本，那么所有的数据就有问题了。"}}]},"media":{"uk":"media/uk/spout__gb_1.mp3","us":"media/us/spout__us_1.mp3","img":["media/ldoce/img/spout.jpg"]},"examples":[{"en":"Well, that's my holiday plans gone up the spout!","cn":"唉，我的休假计划全泡汤了！"},{"en":"Clear water spouted from the fountains.","cn":"清澈的水从喷泉中喷射出来。"}]},"speedily":{"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"moving or able to move quickly","cn":""},{"en":"moving fast or doing something in a short time","cn":""}]},"examples":[{"en":"a speedy recovery from injury","cn":"","src":"ld"}],"media":{"uk":"media/uk/speedily__gb_1.mp3","us":"media/us/speedily__us_1.mp3"},"oxford":{"phon":"ˈspiːdəli","pos":"adverb","senses":[{"en":"quickly; without delay","cn":"迅速的；尽快的","ex":{"en":"All enquiries will be dealt with as speedily as possible.","cn":"所有询问都将从速处理。"}}]}},"specialists":{"oxford":{"phon":"ˈspeʃəlɪst","pos":"noun","senses":[{"en":"a person who is an expert in a particular area of work or study","cn":"专家"},{"en":"a doctor who has specialized in a particular area of medicine","cn":"专科医生"}]}},"spade":{"media":{"img":["media/pic/tools_garden_comp.jpg","media/thumb/spade.jpg"],"uk":"media/uk/spade__gb_1.mp3","us":"media/us/spade__us_1.mp3"},"oxford":{"phon":"speɪd","pos":"noun","senses":[{"en":"a garden tool with a broad metal part and a long handle, used for digging","cn":"锹；铲","g":"[countable]","lab":"British English","ex":{"en":"Turn the soil over with a spade.","cn":"用锹把地翻一遍。"}},{"en":"one of the four suits (= sets) in a pack of cards. The cards have a black design with shapes like pointed leaves with short stems.","cn":"（扑克牌的）黑桃","g":"[plural, uncountable]","ex":{"en":"the five/queen/ace of spades","cn":"黑桃五／王后／A"}},{"en":"one card from the suit called spades","cn":"黑桃牌","g":"[countable]","ex":{"en":"You must play a spade if you have one.","cn":"你如果有黑桃牌，就必须打出来。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"铲;锹","en":"A spade is a tool used for digging, with a flat metal blade and a long handle.","ex":{"en":"... a garden spade","cn":"园艺铲"}},{"pos":"N-UNCOUNT-COLL 不可数集合名词","cn":"(纸牌中的)黑桃","en":"Spades is one of the four suits in a pack of playing cards. Each card in the suit is marked with one or more black symbols: .","ex":{"en":"...the ace of spades.","cn":"黑桃 A"}},{"pos":"PHRASE 短语","cn":"有啥说啥;直言不讳","en":"If you say that someone calls a spade a spade, you mean that they speak clearly and directly about things, even embarrassing or unpleasant things.","ex":{"en":"I'm not at all secretive, and I'm pretty good at calling a spade a spade.","cn":"我不会遮遮掩掩，我喜欢直言不讳。"}}]},"examples":[{"en":"( BrE ) The children took their buckets and spades to the beach.","cn":"孩子们带上自己的桶和铲子到海滩去了。"},{"en":"He'd got his revenge now, and in spades.","cn":"现在他报了仇，毫不留情地报了仇。"}]},"sparsely":{"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"a small number of people, things, places etc","cn":""},{"en":"a few people, things, places etc, especially when they are part of a much bigger number","cn":""}]},"examples":[{"en":"his sparse brown hair","cn":"","src":"ld"},{"en":"rural areas with sparse populations","cn":"","src":"ld"}],"media":{"uk":"media/uk/sparsely__gb_1.mp3","us":"media/us/sparsely__us_1.mp3"},"oxford":{"phon":"ˈspɑːsli","pos":"adverb","senses":[{"en":"with only small amounts or numbers of something, often spread over a large area","cn":"稀少的；稀疏的；零落的","ex":{"en":"a sparsely populated area","cn":"人口稀少的地区"}}]}},"splendid":{"media":{"uk":"media/uk/splendid__gb_1.mp3","us":"media/us/splendid__us_1.mp3"},"oxford":{"phon":"ˈsplendɪd","pos":"adjective","senses":[{"en":"very impressive; very beautiful","cn":"壮丽的；雄伟的；豪华的；华丽的","ex":{"en":"splendid scenery","cn":"壮丽的风景"}},{"en":"excellent; very good","cn":"极佳的；非常好的","lab":"old-fashioned","ex":{"en":"What a splendid idea!","cn":"这主意妙极了！"}},{"en":"used to show that you approve of something, or are pleased","cn":"（表示赞许或满意）好极了，痛快","ex":{"en":"You're both coming? Splendid!","cn":"你们俩都要来？太好了！"},"pos":"exclamation"}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"极好的;绝妙的;出色的","en":"If you say that something is splendid, you mean that it is very good.","ex":{"en":"The book includes a wealth of splendid photographs","cn":"该书中有大量精彩的照片。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(建筑、艺术作品)壮丽的，华丽的，美妙的","en":"If you describe a building or work of art as splendid, you mean that it is beautiful, impressive, and extremely well made.","ex":{"en":"...a splendid Victorian mansion.","cn":"华丽的维多利亚式宅第"}},{"pos":"EXCLAM 感叹语","cn":"好极了(表示赞同)","en":"You can say 'splendid' in a conversation to indicate that you approve of a particular situation or something that someone has said.","ex":{"en":"'I was thinking I might do a lemon cream sauce and baked potatoes.' 'Splendid!' Midge applauded.","cn":"“我在考虑做一道浇柠檬奶油汁的烤马铃薯。”“好极了！”米基表示赞同。"}}]},"examples":[{"en":"The hotel stands in splendid isolation , surrounded by moorland.","cn":"那旅馆岿然独立，周围是一片荒原。"},{"en":"We've all had a splendid time.","cn":"我们大家都玩得很开心。"}]},"spacing":{"oxford":{"phon":"ˈspeɪsɪŋ","pos":"noun","senses":[{"en":"the amount of space that is left between things, especially between the words or lines printed on a page","cn":"（空间）间隔；（尤指）字距，行距","ex":{"en":"single/double spacing (= with one or two lines left between lines of type)","cn":"单倍／双倍行距"}},{"en":"the amount of time that is left between things happening","cn":"（时间）间隔","ex":{"en":"In music, the spacing of intervals is vital.","cn":"在音乐中，音程间隔长度至关重要。"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"字距;行距","en":"Spacing refers to the way that typing or printing is arranged on a page, especially in relation to the amount of space that is left between words or lines.","ex":{"en":"Please type or write clearly in double spacing on one side of A4 paper only.","cn":"请用A4纸、以双倍行距单面打印或誊抄，字迹务必清晰。"}}]},"media":{"uk":"media/uk/spacing__gb_1.mp3","us":"media/us/spacing__us_1.mp3"},"examples":[{"en":"single/double spacing (= with one or two lines left between lines of type)","cn":"单倍/双倍行距"}]},"sprang":{"collins":{"senses":[{"pos":"","cn":"","en":"Sprang is the past tense of spring."}]},"media":{"uk":"media/uk/sprang__gb_1.mp3","us":"media/us/sprang__us_1.mp3"}},"species":{"media":{"uk":"media/uk/species__gb_1.mp3","us":"media/us/species__us_1.mp3"},"oxford":{"phon":"ˈspiːʃiːz","pos":"noun","senses":[{"en":"a group into which animals, plants, etc. that are able to have sex with each other and produce healthy young are divided, smaller than a genus and identified by a Latin name","cn":"种，物种（分类上小于属）","ex":{"en":"a conservation area for endangered species","cn":"濒危物种保护区"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(动植物的)物种，种","en":"A species is a class of plants or animals whose members have the same main characteristics and are able to breed with each other.","ex":{"en":"Pandas are an endangered species","cn":"熊猫是濒危物种。"}}]},"examples":[{"en":"a conservation area for endangered species","cn":"濒危物种保护区"},{"en":"There are many species of dog(s).","cn":"狗有许多种。"}]},"spoiled":{"oxford":{"phon":"spɔɪl","pos":"verb","senses":[{"en":"to change sth good into sth bad, unpleasant, useless, etc.","cn":"破坏；搞坏；糟蹋；毁掉"},{"en":"to give a child everything that they ask for and not enough discipline in a way that has a bad effect on their character and behaviour","cn":"溺爱；娇惯；宠坏"}]},"media":{"uk":"media/ldoce/hwd/bre/b/brelasdespoiled.mp3","us":"media/ldoce/hwd/ame/d/laadspoiled.mp3"},"examples":[{"en":"Ben was a spoilt brat (= a spoiled and unpleasant child ) .","cn":"本是个被宠坏的小恶魔。"},{"en":"Their children were spoiled rotten (= very spoiled ) .","cn":"他们的孩子完全被宠坏了。"}]},"spouting":{"oxford":{"phon":"spaʊt","pos":"noun","senses":[{"en":"a pipe or tube on a container, that you can pour liquid out through （","cn":"容器的）嘴"},{"en":"a stream of liquid coming out of somewhere with great force （","cn":"喷出的）水柱，液体柱"}]}},"spying":{"oxford":{"phon":"spaɪ","pos":"noun","senses":[{"en":"a person who tries to get secret information about another country, organization or person, especially sb who is employed by a government or the police","cn":"间谍；密探"},{"en":"to collect secret information about another country, organization or person","cn":"从事间谍活动；搜集情报"}]},"media":{"uk":"media/ldoce/hwd/bre/8/spy_n0205.mp3","us":"media/ldoce/hwd/ame/b/spy1.mp3"},"examples":[{"en":"He was charged with spying on British military bases.","cn":""},{"en":"He confessed to spying for North Korea.","cn":""}]},"speed":{"media":{"uk":"media/uk/speed__gb_1.mp3","us":"media/us/speed__us_1.mp3"},"oxford":{"phon":"spiːd","pos":"noun","senses":[{"en":"the rate at which somebody/something moves or travels","cn":"（运动的）速度，速率","g":"[countable, uncountable]","sc":"rate of movement/action","ex":{"en":"at high/low/full/top speed","cn":"以高速／低速／全速／最高速"}},{"en":"the rate at which something happens or is done","cn":"（发生或进行的）速度；进度","g":"[countable, uncountable]","sc":"rate of movement/action","ex":{"en":"the processing speed of the computer","cn":"计算机的处理速度"}},{"en":"the quality of being quick or rapid","cn":"快；迅速","g":"[uncountable]","lab":"formal","sc":"rate of movement/action","ex":{"en":"The Kenyan runner put on a sudden burst of speed over the last 50 metres.","cn":"肯尼亚选手在最后 50 米突然加速。"}},{"en":"a measurement of how sensitive film for cameras, etc. is to light","cn":"感光度","g":"[countable]","sc":"in photography"},{"en":"the time taken by a camera shutter to open and close","cn":"快门速度","g":"[countable]","sc":"in photography"},{"en":"a gear on a bicycle, in a car, etc.","cn":"排挡；速","g":"[countable]","sc":"on bicycle/car","ex":{"en":"a four-speed gearbox","cn":"四挡变速箱"}},{"en":"an illegal amphetamine drug that is taken to give feelings of excitement and energy","cn":"苯丙胺，安非他明（一种兴奋剂）","g":"[uncountable]","lab":"informal","sc":"drug"},{"en":"to move along quickly","cn":"快速前行","g":"[intransitive]","sc":"move/happen quickly","ex":{"en":"They sped off to get help.","cn":"他们飞奔出去找人帮忙。"},"pos":"verb"},{"en":"to take somebody/something somewhere very quickly, especially in a vehicle","cn":"快速运送","g":"[transitive]","lab":"formal","sc":"move/happen quickly","ex":{"en":"The cab speeded them into the centre of the city.","cn":"出租汽车载着他们迅速驶往市中心。"},"pos":"verb"},{"en":"to make something happen more quickly","cn":"加速；促进","g":"[transitive]","lab":"formal","sc":"move/happen quickly","ex":{"en":"The drugs will speed her recovery.","cn":"这些药会加速她的康复。"},"pos":"verb"},{"en":"to drive faster than the speed that is legally allowed","cn":"超速驾驶；超速行驶","g":"[intransitive]","sc":"drive too fast","ex":{"en":"The police caught him speeding.","cn":"警察发现他超速行驶。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"(运动、运行的)速度，速率","en":"The speed of something is the rate at which it moves or travels.","ex":{"en":"He drove off at high speed","cn":"他驱车飞驰而去。"}},{"pos":"N-COUNT 可数名词","cn":"(某事发生或进展的)速度，进度","en":"The speed of something is the rate at which it happens or is done.","ex":{"en":"In the late 1850s the speed of technological change quickened","cn":"19 世纪 50 年代末期，技术变革的速度加快了。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"(指运动、运行的)高速，快速","en":"Speed is very fast movement or travel.","ex":{"en":"Speed is the essential ingredient of all athletics","cn":"速度是所有田径运动项目的关键要素。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"(指某事发生或进展时的)高速，快速","en":"Speed is a very fast rate at which something happens or is done.","ex":{"en":"I was amazed at his speed of working.","cn":"他办事之麻利让我深感叹服。"}},{"pos":"VERB 动词","cn":"(尤指坐车)快速行进","en":"If you speed somewhere, you move or travel there quickly, usually in a vehicle.","ex":{"en":"Trains will speed through the Channel Tunnel at 186mph","cn":"火车将以每小时 186 英里的速度快速穿过海峡隧道。"}},{"pos":"VERB 动词","cn":"(驾车者)超速行驶","en":"Someone who is speeding is driving a vehicle faster than the legal speed limit.","ex":{"en":"This man was not qualified to drive and was speeding.","cn":"这名男子没有驾驶资格，并且违章超速行驶。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"安非他明(一种兴奋剂)","en":"Speed is an illegal drug such as amphetamine which some people take to increase their energy and excitement."},{"pos":"","cn":"","en":"to pick up speed→see: ;"},{"pos":"PHRASE 短语","cn":"掌握最新情况的","en":"If you are up to speed, you have all the most recent information that you need about something.","ex":{"en":"A day has been set aside to bring all councillors up to speed on the proposal","cn":"已经确定了一个日子，届时将向所有的市政委员汇报有关该建议的最新进展情况。"}},{"pos":"","cn":"","en":"相关词组：speed up"}]},"examples":[{"en":"a speed of 50 mph/80 kph","cn":"每小时 50 英里/ 80 公里的速度"},{"en":"This course is designed so that students can progress at their own speed.","cn":"这门课的设计思路是让学生自己掌握进度。"}]},"spending":{"media":{"uk":"media/uk/spending__gb_1.mp3","us":"media/us/spending__us_1.mp3"},"oxford":{"phon":"ˈspendɪŋ","pos":"noun","senses":[{"en":"the amount of money that is spent by a government, an organization or a person","cn":"（政府、机构或个人的）开支，支出，花销","ex":{"en":"to increase/cut/reduce spending","cn":"增加／减少开支"}}]},"examples":[{"en":"to increase public spending","cn":"增加公共开支"}]},"spells":{"oxford":{"phon":"spel","pos":"verb","senses":[{"en":"to say or write the letters of a word in the correct order","cn":"用字母拼；拼写"},{"en":"to form words correctly from individual letters","cn":"拼出，会拼（单词）"}]}},"spinning":{"oxford":{"phon":"ˈspɪnɪŋ","pos":"noun","senses":[{"en":"the art or the process of twisting wool, etc. to make thread","cn":"纺线（手艺）；纺纱（手艺）","ex":{"en":"cotton spinning","cn":"棉纺"}},{"en":"a type of exercise performed on an exercise bike, usually in a class","cn":"Spinning 动感单车"}]},"media":{"uk":"media/uk/spinning__gb_1.mp3","us":"media/us/spinning__us_1.mp3"}},"split":{"oxford":{"phon":"splɪt","pos":"verb","senses":[{"en":"to divide, or to make something divide, into two or more parts","cn":"分开，使分开（成为几个部分）","g":"[transitive, intransitive]","sc":"divide","ex":{"en":"He was a member of the team that split the atom in 1932.","cn":"他是 1932 年原子裂变团队的成员。"}},{"en":"to divide something into two or more parts and share it between different people, activities, etc.","cn":"分担；分摊；分享","g":"[transitive]","sc":"divide","ex":{"en":"She split the money she won with her brother.","cn":"她把得到的钱与弟弟分了。"}},{"en":"to divide, or to make a group of people divide, into smaller groups that have very different opinions","cn":"分裂，使分裂（成不同的派别）","g":"[intransitive, transitive]","sc":"divide","ex":{"en":"The committee split over government subsidies.","cn":"在政府补贴的问题上，委员会出现了相互对立的意见。"}},{"en":"to tear, or to make something tear, along a straight line","cn":"（使）撕裂","g":"[intransitive, transitive]","sc":"tear","ex":{"en":"Her dress had split along the seam.","cn":"她的连衣裙顺着接缝裂开了。"}},{"en":"to cut somebody’s skin and make it bleed","cn":"划破；割破；碰破","g":"[transitive]","sc":"cut","ex":{"en":"She split her head open on the cupboard door.","cn":"她碰到碗橱门上把头碰破了。"}},{"en":"to leave somebody and stop having a relationship with them","cn":"（和某人）断绝关系，分手；离开（某人）","g":"[intransitive]","lab":"informal","sc":"end relationship","ex":{"en":"The singer split with his wife last June.","cn":"那歌手去年六月和妻子分手了。"}},{"en":"to leave a place quickly","cn":"（迅速）离开，走","g":"[intransitive]","lab":"old-fashioned, informal，，","sc":"leave","ex":{"en":"Let's split!","cn":"咱们快走吧！"}},{"en":"an argument or disagreement that divides a group of people or makes somebody separate from somebody else","cn":"分歧；分裂；分离","g":"[countable]","sc":"disagreement","ex":{"en":"Ten years after their acrimonious split, the band has reformed.","cn":"闹翻 10 年之后，这个乐队重组了。"},"pos":"noun"},{"en":"a long opening made when something tears","cn":"裂缝；裂口","g":"[countable]","sc":"tear/hole","ex":{"en":"A blockage in the artery caused the split.","cn":"动脉堵塞导致了动脉破裂。"},"pos":"noun"},{"en":"a division between two or more things; one of the parts that something is divided into","cn":"划分；分别；份额","g":"[singular]","sc":"division","ex":{"en":"He demanded a 50–50 split in the profits.","cn":"他要求利润对半分成。"},"pos":"noun"},{"en":"a position in which you stretch your legs flat across the floor in opposite directions with the rest of your body sitting straight up","cn":"劈叉","g":"[plural]","lab":"US English also","sc":"body position","ex":{"en":"a gymnast doing the splits","cn":"做劈叉的体操运动员"},"pos":"noun"}]},"collins":{"senses":[{"pos":"V-ERG 及物/不及物动词","cn":"（使）断裂;（使）裂开;分割","en":"If something splits or if you split it, it is divided into two or more parts.","ex":{"en":"In a severe gale the ship split in two","cn":"在一次大风中，船断成了两截。"}},{"pos":"V-ERG 及物/不及物动词","cn":"（使）(团体)意见不合；（使）分裂","en":"If an organization splits or is split, one group of members disagrees strongly with the other members, and may form a group of their own.","ex":{"en":"Yet it is feared the Republican leadership could split over the agreement","cn":"但有人担心，共和党的领导层可能会在该协议上出现意见分歧。"}},{"pos":"N-COUNT 可数名词","cn":"(团体中的)意见分歧","en":"A split in an organization is a disagreement between its members.","ex":{"en":"They accused both radicals and conservatives of trying to provoke a split in the party.","cn":"他们指责激进派和保守派都在试图挑起党内分歧。"}},{"pos":"N-SING 单数名词","cn":"区分；不同","en":"A split between two things is a division or difference between them.","ex":{"en":"...a split between what is thought and what is felt.","cn":"所想到的和感受到的之间的不同"}},{"pos":"V-ERG 及物/不及物动词","cn":"(使)(木头、衣服)开裂，出现裂缝;撕开","en":"If something such as wood or a piece of clothing splits or is split, a long crack or tear appears in it.","ex":{"en":"The seat of his short grey trousers split","cn":"他的灰色短裤的臀部开裂了。"}},{"pos":"N-COUNT 可数名词","cn":"裂缝;裂口","en":"A split is a long crack or tear.","ex":{"en":"The plastic-covered seat has a few small splits around the corners.","cn":"塑料面椅子的四角上有几道小裂缝。"}},{"pos":"VERB 动词","cn":"分担;分享;分得","en":"If two or more people split something, they share it between them.","ex":{"en":"I would rather pay for a meal than watch nine friends pick over and split a bill","cn":"我宁可掏钱请客，也不愿看到9位朋友算来算去分摊账单。"}},{"pos":"","cn":"","en":"相关词组：split off split up"}]},"media":{"uk":"media/uk/split__gb_1.mp3","us":"media/us/split__us_1.mp3"},"examples":[{"en":"His time is split between the London and Paris offices.","cn":"他一半时间在伦敦的办事处，一半时间在巴黎的办事处。"},{"en":"The committee split over government subsidies.","cn":"在政府补贴的问题上，委员会出现了相互对立的意见。"}]},"spins":{"oxford":{"phon":"spɪn","pos":"verb","senses":[{"en":"to turn round and round quickly; to make sth do this （","cn":"使）快速旋转"},{"en":"to turn round quickly once; to make sb do this （","cn":"使）急转身，猛转回头，急转弯"}]},"media":{"uk":"media/uk/spin__gb_1.mp3","us":"media/us/spin__us_1.mp3"}},"sperm":{"oxford":{"phon":"spɜːm","pos":"noun","senses":[{"en":"a cell that is produced by the sex organs of a male and that can combine with a female egg to produce young","cn":"精子","g":"[countable]","ex":{"en":"He has a low sperm count (= very few live male cells).","cn":"他的精液精子计数低。"}},{"en":"the liquid that is produced by the male sex organs that contains these cells","cn":"精液","g":"[uncountable]"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"精子","en":"A sperm is a cell which is produced in the sex organs of a male animal and can enter a female animal's egg and fertilize it.","ex":{"en":"Conception occurs when a single sperm fuses with an egg","cn":"当一个精子和一个卵子结合时受孕就发生了。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"精液","en":"Sperm is used to refer to the liquid that contains sperm when it is produced.","ex":{"en":"...a sperm donor.","cn":"精液捐献者"}}]},"media":{"uk":"media/uk/sperm__gb_1.mp3","us":"media/us/sperm__us_1.mp3"},"examples":[{"en":"He has a low sperm count (= very few live male cells).","cn":"他的精液精子计数低。"}]},"spectacle":{"oxford":{"phon":"ˈspektəkl","pos":"noun","senses":[{"en":"two lenses in a frame that rests on the nose and ears. People wear spectacles in order to be able to see better or to protect their eyes from bright light.","cn":"眼镜","g":"[plural]","lab":"formal","ex":{"en":"a pair of spectacles","cn":"一副眼镜"}},{"en":"a performance or an event that is very impressive and exciting to look at","cn":"精彩的表演；壮观的场面","g":"[countable, uncountable]","ex":{"en":"The carnival parade was a magnificent spectacle.","cn":"狂欢节游行场面热烈，蔚为大观。"}},{"en":"a sight or view that is very impressive to look at","cn":"壮观的景象","g":"[countable]","ex":{"en":"The sunset was a stunning spectacle.","cn":"夕阳西斜，异常壮观。"}},{"en":"an unusual or surprising sight or situation that attracts a lot of attention","cn":"奇特的现象；出人意外的情况","g":"[singular]","ex":{"en":"I remember the sad spectacle of her standing in her wedding dress, covered in mud.","cn":"我记得她穿着婚纱、满身泥污站在那儿的凄惨样。"}}]},"collins":{"senses":[{"pos":"N-PLURAL 复数名词","cn":"眼镜","en":"Glasses are sometimes referred to as spectacles .","ex":{"en":"He looked at me over the tops of his spectacles.","cn":"他从眼镜框的上方看了看我。"}},{"pos":"N-COUNT 可数名词","cn":"奇异的景象;有趣的场面","en":"A spectacle is a strange or interesting sight.","ex":{"en":"It was a spectacle not to be missed.","cn":"这是个不容错过的奇观。"}},{"pos":"N-VAR 可变名词","cn":"盛大的演出;壮观的场面","en":"A spectacle is a grand and impressive event or performance.","ex":{"en":"94,000 people turned up for the spectacle.","cn":"94,000 人参加了这一盛大活动。"}},{"pos":"","cn":"","en":"rose-coloured spectacles→see: ;"}]},"media":{"uk":"media/uk/spectacle__gb_1.mp3","us":"media/us/spectacle__us_1.mp3","img":["media/ldoce/img/glasses.jpg"]},"examples":[{"en":"I remember the sad spectacle of her standing in her wedding dress, covered in mud.","cn":"我记得她穿着婚纱、满身泥污站在那儿的凄惨样。"},{"en":"The carnival parade was a magnificent spectacle.","cn":"狂欢节游行场面热烈，蔚为大观。"}]},"speak":{"media":{"uk":"media/uk/speak__gb_1.mp3","us":"media/us/speak__us_1.mp3"},"oxford":{"phon":"spiːk","pos":"verb","senses":[{"en":"to talk to somebody about something; to have a conversation with somebody","cn":"谈；谈话；交谈","g":"[intransitive]","lab":"especially North American English","sc":"have conversation","ex":{"en":"The President refused to speak to reporters.","cn":"总统拒绝同记者讲话。"}},{"en":"to use your voice to say something","cn":"说话；讲话","g":"[intransitive]","sc":"use voice","ex":{"en":"The illness left him unable to speak.","cn":"生病后他不能说话了。"}},{"en":"to be able to use a particular language","cn":"会说，会讲（某种语言）","g":"[transitive]","sc":"a language","ex":{"en":"to speak several languages","cn":"会讲几种语言"}},{"en":"to use a particular language to express yourself","cn":"用（某种语言）说话","g":"[transitive, intransitive]","sc":"a language","ex":{"en":"What language is it they're speaking?","cn":"他们讲的是什么语？"}},{"en":"speaking the language mentioned","cn":"讲…语的","sc":"-speaking","ex":{"en":"French-speaking Canada","cn":"加拿大法语区"}},{"en":"to mention or describe something/somebody","cn":"提起；讲述","g":"[intransitive]","sc":"mention/describe","ex":{"en":"She still speaks about him with great affection.","cn":"说起他来她依旧一往情深。"}},{"en":"to make a speech to an audience","cn":"发言；演说；演讲","g":"[intransitive]","sc":"make speech","ex":{"en":"Hundreds of people came to hear her speak.","cn":"数百人前来听她演讲。"}},{"en":"to say or state something","cn":"说；讲述","g":"[transitive]","sc":"say/state","ex":{"en":"She was clearly speaking the truth.","cn":"她讲的显然是实情。"}},{"en":"the language used by a particular group of people, especially when it is difficult for other people to understand or they find it annoying","cn":"（尤指令他人费解或厌烦的）圈中行话，用语","ex":{"en":"Visitors to websites don't want to read marketing-speak.","cn":"网页浏览者不想看推销语言。"},"pos":"combining form"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"说话;讲话","en":"When you speak, you use your voice in order to say something.","ex":{"en":"He tried to speak, but for once, his voice had left him","cn":"他想说话，却一时语塞。"}},{"pos":"VERB 动词","cn":"发言；演说","en":"When someone speaks to a group of people, they make a speech.","ex":{"en":"When speaking to the seminar Mr Franklin spoke of his experience, gained on a recent visit to Trinidad","cn":"在研讨会上发言的时候，富兰克林先生谈到了他最近游览特立尼达的经历。"}},{"pos":"VERB 动词","cn":"代表…讲话;充当…的代言人","en":"If you speak for a group of people, you make their views and demands known, or represent them.","ex":{"en":"He said it was the job of the Church to speak for the underprivileged","cn":"他说，为贫困群体说话是教会的义务。"}},{"pos":"VERB 动词","cn":"(会)讲，说(外语)","en":"If you speak a foreign language, you know the language and are able to have a conversation in it.","ex":{"en":"He doesn't speak English","cn":"他不会讲英语。"}},{"pos":"VERB 动词","cn":"(在文中)谈起，提到","en":"People sometimes mention something that has been written by saying what the author speaks of .","ex":{"en":"In the book she speaks of his “social ineptitude” and says he verbally abused her","cn":"她在书中提到他“缺乏社交技能”，并且说他曾经对她出言不逊。"}},{"pos":"V-RECIP 相互动词","cn":"(吵架之后)不说话，不搭理","en":"If two people are not speaking, they no longer talk to each other because they have quarrelled.","ex":{"en":"He is not speaking to his mother because of her friendship with his ex-wife","cn":"因为母亲和前妻仍旧保持着友好的关系，他便不再和母亲说话。"}},{"pos":"VERB 动词","cn":"表明;显示","en":"If you say that something speaks to you of a quality, experience, or feeling, you mean that it is evidence of it or expresses it.","ex":{"en":"His behaviour spoke of an early maturity","cn":"他的举止流露出早熟的痕迹。"}},{"pos":"VERB 动词","cn":"不言而喻","en":"If you say that something speaks for itself, you mean that its meaning or quality is so obvious that it does not need explaining or pointing out.","ex":{"en":"...the figures speak for themselves — low order books, bleak prospects at home and a worsening outlook for exports","cn":"这些数字本身就说明了问题——订单订购量低，国内销售前景惨淡，出口形势日趋恶化。"}},{"pos":"CONVENTION 惯用语","cn":"你说的只是你的看法;这只是你的高见","en":"If you say 'Speak for yourself' when someone has said something, you mean that what they have said is only their opinion or applies only to them.","ex":{"en":"'We're not blaming you,' Kate said. 'Speak for yourself,' Boris muttered.","cn":"“我们没有怪你，”凯特说。“也就是你这么想，”鲍里斯嘟囔道。"}},{"pos":"PHRASE 短语","cn":"已被预订;早已订购;已经许给别人","en":"If a person or thing is spoken for or has been spoken for, someone has claimed them or asked for them, so no-one else can have them.","ex":{"en":"She'd probably drop some comment about her 'fiancé' into the conversation so that he'd think she was already spoken for","cn":"她可能会在谈话的时候不着痕迹地对她的“未婚夫”作些评论，这样他便会认为她已经名花有主了。"}},{"pos":"PHRASE 短语","cn":"行动胜于言语","en":"If you say that actions speak louder than words, you mean that people's actions show their real attitudes, rather than what they say. This expression is sometimes used to advise a person to do something positive."},{"pos":"PHRASE 短语","cn":"（没什么）值得一提","en":"Nothing to speak of means 'hardly anything' or 'only unimportant things'.","ex":{"en":"They have no weaponry to speak of","cn":"他们没有什么武器值得炫耀。"}},{"pos":"PHRASE 短语","cn":"更不用说","en":"You can use not to speak of when adding something which your previous statement also applies to, or applies to even more than other things.","ex":{"en":"This move caused consternation among universities and the government, not to speak of the students affected.","cn":"这个举措在大学和政府里造成了恐慌，更不用说受到影响的学生们了。"}},{"pos":"PHRASE 短语","cn":"说…的好话/坏话；称赞/批评","en":"If you speak well of someone or speak highly of someone, you say good things about them. If you speak ill of someone, you criticize them.","ex":{"en":"Both spoke highly of the Russian president","cn":"双方均盛赞俄罗斯总统。"}},{"pos":"PHRASE 短语","cn":"可以说;可谓","en":"You use so to speak to draw attention to the fact that you are describing or referring to something in a way that may be amusing or unusual rather than completely accurate.","ex":{"en":"I ought not to tell you but I will, since you're in the family, so to speak","cn":"我本来不该告诉你的，但我还是要这么做，因为好歹你是家里的一员。"}},{"pos":"PHRASE 短语","cn":"见面交谈的；相识的","en":"If you are on speaking terms with someone, you are quite friendly with them and often talk to them.","ex":{"en":"For a long time her mother and her grandmother had hardly been on speaking terms.","cn":"很久以来，她的母亲和外婆两人之间几乎不怎么说话。"}},{"pos":"","cn":"","en":"to speak your mind→see: ; to speak volumes→see: ;"},{"pos":"","cn":"","en":"相关词组：speak out speak up"}]},"examples":[{"en":"They were all very similar. All cut from the same cloth, so to speak.","cn":"他们都十分相像。可以说就跟一块布上剪下来似的。"},{"en":"Speaking of travelling, (= referring back to a subject just mentioned) are you going anywhere exciting this year?","cn":"说到旅游，你今年要去什么好玩的地方吗？"}]},"spectacular":{"media":{"uk":"media/uk/spectacular__gb_1.mp3","us":"media/us/spectacular__us_1.mp3"},"oxford":{"phon":"spekˈtækjələ(r)","pos":"adjective","senses":[{"en":"very impressive","cn":"壮观的；壮丽的；令人惊叹的","ex":{"en":"The coastal road has spectacular scenery.","cn":"滨海大道景色壮丽。"}},{"en":"an impressive show or performance","cn":"壮观的场面；精彩的表演","ex":{"en":"a Christmas TV spectacular","cn":"精彩的圣诞节电视节目"},"pos":"noun"}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"引人注目的;惊人的;壮观的","en":"Something that is spectacular is very impressive or dramatic.","ex":{"en":"...spectacular views of the Sugar Loaf Mountain","cn":"甜面包山的壮观景色"}},{"pos":"N-COUNT 可数名词","cn":"壮观的表演;盛大的演出","en":"A spectacular is a show or performance which is very grand and impressive.","ex":{"en":"...a television spectacular.","cn":"一场电视盛宴"}}]},"examples":[{"en":"It was a spectacular achievement on their part.","cn":"这是他们取得的一项了不起的成就。"},{"en":"Messi scored a spectacular goal.","cn":"梅西攻进了一个精彩入球。"}]},"spin":{"media":{"uk":"media/uk/spin__gb_1.mp3","us":"media/us/spin__us_1.mp3"},"oxford":{"phon":"spɪn","pos":"verb","senses":[{"en":"to turn round and round quickly; to make something do this","cn":"（使）快速旋转","g":"[intransitive, transitive]","sc":"turn round quickly","ex":{"en":"The plane was spinning out of control.","cn":"飞机失去控制，进入尾旋状态。"}},{"en":"to turn round quickly once; to make somebody do this","cn":"（使）急转身，猛转回头，急转弯","g":"[intransitive, transitive]","sc":"turn round quickly","ex":{"en":"He spun around to face her.","cn":"他猛地回过身来，面对着她。"}},{"en":"to make thread from wool, cotton, silk, etc. by twisting it","cn":"纺（线）；纺（纱）","g":"[intransitive, transitive]","sc":"make thread","ex":{"en":"She sat by the window spinning.","cn":"她坐在窗前纺线。"}},{"en":"to produce thread from its body to make a web or cocoon","cn":"吐（丝）；作（茧）；结（网）","g":"[transitive]","sc":"of spider/silkworm","ex":{"en":"a spider spinning a web","cn":"结网的蜘蛛"}},{"en":"to drive or travel quickly","cn":"驾车飞驰；疾驰","g":"[intransitive]","sc":"drive/travel quickly","ex":{"en":"They went spinning along the roads on their bikes.","cn":"他们骑自行车沿公路疾驰。"}},{"en":"to remove the water from clothes that have just been washed, in a spin dryer","cn":"（用旋转式脱水机）甩干衣服","g":"[transitive]","sc":"dry clothes"},{"en":"to present information or a situation in a particular way, especially one that makes you or your ideas seem good","cn":"有倾向性地陈述；（尤指）以有利于自己的口吻描述","g":"[transitive]","sc":"present information","ex":{"en":"An aide was already spinning the senator's defeat as ‘almost as good as an outright win’.","cn":"一名助手已经开始将那位参议员的失败描述成“几乎是大获全胜”。"}},{"en":"a very fast turning movement","cn":"高速旋转","g":"[countable, uncountable]","sc":"fast turning movement","ex":{"en":"Only in the last 50 years have we had clocks accurate enough to measure changes in the earth's spin.","cn":"直到最近 50 年，我们才有了足够精确的时钟来测量地球自转的变化。"},"pos":"noun"},{"en":"if an aircraft goes into a spin, it falls and turns round rapidly","cn":"（飞机的）尾旋，螺旋式下坠","g":"[countable, usually singular]","lab":"figurative","sc":"fast turning movement","ex":{"en":"He had to stop the helicopter from going into a spin.","cn":"他必须制止直升机旋冲下降。"},"pos":"noun"},{"en":"a short ride in a car for pleasure","cn":"兜风","g":"[countable]","lab":"informal, becoming old-fashioned，，","sc":"in car","ex":{"en":"Let's go for a spin.","cn":"咱们兜风去吧。"},"pos":"noun"},{"en":"the way you make a ball turn very fast when you throw it or hit it","cn":"旋转","g":"[uncountable]","sc":"in tennis/cricket","ex":{"en":"She puts a lot of spin on the ball.","cn":"她打出的球旋转得很厉害。"},"pos":"noun"},{"en":"a way of presenting information or a situation in a particular way, especially one that makes you or your ideas seem good","cn":"（尤指有利于自己的）导向性陈述","g":"[singular, uncountable]","lab":"informal","sc":"on information","ex":{"en":"Politicians put their own spin on the economic situation.","cn":"政治家们对经济形势各执一词。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"V-ERG 及物/不及物动词","cn":"(使)旋转","en":"If something spins or if you spin it, it turns quickly around a central point.","ex":{"en":"The latest discs, used for small portable computers, spin 3600 times a minute","cn":"用在小型便携式计算机上的最新光盘转速为每分钟 3,600 转。"}},{"pos":"VERB 动词","cn":"(用甩干机或洗衣机)甩干（衣服），给…脱水","en":"When you spin washing, it is turned round and round quickly in a spin drier or a washing machine to get the water out.","ex":{"en":"Just spin the washing and it's nearly dry.","cn":"只需要将洗好的衣物脱水，它就差不多干了。"}},{"pos":"VERB 动词","cn":"(因醉酒、生病或兴奋而)头晕","en":"If your head is spinning, you feel unsteady or confused, for example because you are drunk, ill, or excited.","ex":{"en":"My head was spinning from the wine","cn":"我喝了葡萄酒后晕乎乎的。"}},{"pos":"N-SING 单数名词","cn":"带倾向性的解释(或说法)","en":"If someone puts a certain spin on an event or situation, they interpret it and try to present it in a particular way.","ex":{"en":"He interpreted the vote as support for the constitution and that is the spin his supporters are putting on the results today.","cn":"他把这次投票解释为对宪法的支持，这也是他的支持者对今天的投票结果所作的解释。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"(政治上的)倾向性报道","en":"In politics, spin is the way in which political parties try to present everything they do in a positive way to the public and the media.","ex":{"en":"The public is sick of spin and tired of promises. It's time for politicians to act.","cn":"公众厌烦了那些有倾向性的报道和种种许诺。该是用政绩说话的时候了。"}},{"pos":"N-SING 单数名词","cn":"(乘车)兜风","en":"If you go for a spin or take a car for a spin, you make a short journey in a car just to enjoy yourself."},{"pos":"VERB 动词","cn":"杜撰;虚构;编造","en":"If someone spins a story, they give you an account of something that is untrue or only partly true.","ex":{"en":"He was surprised, and annoyed that she had spun a story which was too good to be condemned as a simple lie.","cn":"他很惊讶，也很生气，因为她编的故事太真实了，甚至不能被斥为一个简单的谎言。"}},{"pos":"VERB 动词","cn":"纺纱;纺线","en":"When people spin, they make thread by twisting together pieces of a fibre such as wool or cotton using a device or machine.","ex":{"en":"Michelle will also spin a customer's wool fleece to specification at a cost of $2.25 an ounce.","cn":"米歇尔也会按顾客的要求为其纺羊毛呢，每盎司收费 2.25 美元。"}},{"pos":"N-SING 单数名词","cn":"(飞机的)螺旋式急遽下坠，向下旋冲","en":"If a plane goes into a spin, it falls very rapidly towards the ground in a spiral movement."},{"pos":"N-UNCOUNT 不可数名词","cn":"(网球或板球运动中球的）快速旋转，旋转运动","en":"In a game such as tennis or cricket, if you put spin on a ball, you deliberately make it spin rapidly when you hit it or throw it."},{"pos":"PHRASE 短语","cn":"感到惊慌失措","en":"If you say that someone is in a spin or in a flat spin, you mean that they are confused and unable to act sensibly because of something that has happened.","ex":{"en":"Poor Jane was in rather a spin about the party.","cn":"可怜的简对这次聚会真有些不知所措。"}},{"pos":"","cn":"","en":"相关词组：spin off spin out"}]},"examples":[{"en":"An aide was already spinning the senator's defeat as ‘almost as good as an outright win’.","cn":"一名助手已经开始将那位参议员的失败描述成“几乎是大获全胜”。"},{"en":"The transportation operation will be spun off into a separate company.","cn":"运输部门将脱离出来组建为一家独立公司。"}]},"specialties":{"media":{"uk":"media/uk/specialty__gb_1.mp3","us":"media/us/specialty__us_1.mp3"}},"spotted":{"media":{"uk":"media/uk/spotted__gb_1.mp3","us":"media/us/spotted__us_1.mp3"},"oxford":{"phon":"ˈspɒtɪd","pos":"adjective","senses":[{"en":"having a regular pattern of small dots (= small round marks) on it","cn":"有圆点的","ex":{"en":"a black and white spotted dress","cn":"黑白点相间的连衣裙"}},{"en":"having marks on it, sometimes in a pattern","cn":"有斑点的","ex":{"en":"a leopard’s spotted coat","cn":"豹的花斑皮毛"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"带圆点的；有斑点的","en":"Something that is spotted has a pattern of spots on it.","ex":{"en":"...hand-painted spotted cups and saucers in green and blue","cn":"带有手绘圆点的绿色和蓝色茶杯和茶托"}}]},"examples":[{"en":"a black and white spotted dress","cn":"黑白点相间的连衣裙"},{"en":"a leopard's spotted coat","cn":"豹的花斑皮毛"}]},"spoils":{"oxford":{"phon":"spɔɪl","pos":"verb","senses":[{"en":"to change sth good into sth bad, unpleasant, useless, etc.","cn":"破坏；搞坏；糟蹋；毁掉"},{"en":"to give a child everything that they ask for and not enough discipline in a way that has a bad effect on their character and behaviour","cn":"溺爱；娇惯；宠坏"}]}},"spectacles":{"oxford":{"phon":"ˈspektəkl","pos":"noun","senses":[{"en":"a performance or an event that is very impressive and exciting to look at","cn":"精彩的表演；壮观的场面"},{"en":"a sight or view that is very impressive to look at","cn":"壮观的景象"}]}},"spring":{"media":{"img":["media/ldoce/img/spring.jpg","media/pic/spring.jpg"],"uk":"media/uk/spring__gb_1.mp3","us":"media/us/spring__us_1.mp3"},"oxford":{"phon":"sprɪŋ","pos":"noun","senses":[{"en":"the season between winter and summer when plants begin to grow","cn":"春天；春季","g":"[uncountable, countable]","sc":"season","ex":{"en":"The following spring, the three artists travelled to California.","cn":"接下来的春天，这三位艺术家旅行到了加州。"}},{"en":"a place where water comes naturally to the surface from under the ground","cn":"泉","g":"[countable]","sc":"water","ex":{"en":"a mountain spring","cn":"山泉"}},{"en":"a twisted piece of wire that can be pushed, pressed or pulled but which always returns to its original shape or position afterwards","cn":"弹簧；发条","g":"[countable]","sc":"wire","ex":{"en":"bed springs","cn":"床垫弹簧"}},{"en":"the ability of a spring to return to its original position","cn":"弹性；弹力","g":"[uncountable]","sc":"wire","ex":{"en":"The mattress has lost its spring.","cn":"那个床垫失去弹性了。"}},{"en":"a cheerful, lively quality","cn":"活力；朝气","g":"[uncountable, singular]","sc":"cheerful quality","ex":{"en":"She walked along with a spring in her step.","cn":"她迈着轻快的步伐向前走去。"}},{"en":"a quick sudden jump upwards or forwards","cn":"跳；跃","g":"[countable]","sc":"sudden jump","ex":{"en":"With a spring, the cat leapt on to the table.","cn":"猫一跃跳上桌子。"}},{"en":"to move suddenly and with one quick movement in a particular direction","cn":"跳；跃；蹦","g":"[intransitive]","lab":"figurative","sc":"jump/move suddenly","ex":{"en":"The cat crouched ready to spring.","cn":"那猫弓起背准备跳。"},"pos":"verb"},{"en":"to move suddenly and violently","cn":"突然猛烈地移动","g":"[intransitive]","sc":"jump/move suddenly","ex":{"en":"The branch sprang back and hit him in the face.","cn":"树枝弹回来打在他脸上。"},"pos":"verb"},{"en":"to do something, ask something or say something that somebody is not expecting","cn":"突如其来地做；冷不防地问；突然说","g":"[transitive]","sc":"surprise","ex":{"en":"She sprang a surprise by winning the tournament.","cn":"这次比赛她获得冠军，爆了个大冷门。"},"pos":"verb"},{"en":"to appear or come somewhere suddenly","cn":"突然出现（或来到）","g":"[intransitive]","sc":"appear suddenly","ex":{"en":"Tears sprang to her eyes.","cn":"她眼里一下子涌出了泪水。"},"pos":"verb"},{"en":"to help a prisoner to escape","cn":"帮助…逃跑（或越狱）；营救","g":"[transitive]","lab":"informal","sc":"free prisoner","ex":{"en":"Plans to spring the hostages have failed.","cn":"营救人质的计划失败了。"},"pos":"verb"}]},"examples":[{"en":"I'm sorry to spring it on you , but I've been offered another job.","cn":"我很抱歉这样突然告诉您，我另有工作了。"},{"en":"The idea for the novel sprang from a trip to India.","cn":"写这部小说的想法源于一次去印度的旅行。"}]},"speeding":{"media":{"uk":"media/uk/speeding__gb_1.mp3","us":"media/us/speeding__us_1.mp3"},"oxford":{"phon":"ˈspiːdɪŋ","pos":"noun","senses":[{"en":"the traffic offence of driving faster than the legal limit","cn":"超速驾驶；超速行驶","lab":"British English","ex":{"en":"Max was fined £300 for speeding.","cn":"马克斯因超速被罚款 300 英镑。"}}]},"examples":[{"en":"She got stopped for speeding.","cn":"她因超速被拦下。"},{"en":"a speeding ticket","cn":"超速驾驶罚单"}]},"sponge":{"oxford":{"phon":"spʌndʒ","pos":"noun","senses":[{"en":"a piece of artificial or natural material that is soft and light and full of holes and can hold water easily, used for washing or cleaning","cn":"（天然或人造、擦洗物品用的）海绵块","g":"[countable]","lab":"figurative","ex":{"en":"a bath sponge (= to wash your body with in the bath)","cn":"浴用海绵"}},{"en":"artificial sponge used for filling furniture, cushions, etc.","cn":"（用以填充家具、垫子等的）人造海绵","g":"[uncountable]"},{"en":"a simple sea creature with a light body full of holes, from which natural sponge is obtained","cn":"海绵动物","g":"[countable]"},{"en":"a light cake or hot dessert made from eggs, sugar and flour, with or without fat","cn":"海绵蛋糕；松蛋糕","g":"[countable, uncountable]","lab":"British English","ex":{"en":"a chocolate sponge","cn":"巧克力海绵蛋糕"}},{"en":"to wash somebody/yourself/something with a wet cloth or sponge","cn":"用湿布（或海绵）擦；揩拭","g":"[transitive]","ex":{"en":"She sponged his hot face.","cn":"她用湿毛巾擦了擦他那滚烫的脸。"},"pos":"verb"},{"en":"to remove something using a wet cloth or sponge","cn":"用湿布（或海绵）擦掉；揩去","g":"[transitive]","ex":{"en":"We tried to sponge the blood off my shirt.","cn":"我们试着把我衬衫上的血迹擦掉。"},"pos":"verb"},{"en":"to get money, food, etc. regularly from other people without doing anything for them or offering to pay","cn":"白要；白吃；揩油；蹭（饭等）","g":"[intransitive]","lab":"informal, disapproving，，","ex":{"en":"He spent his life sponging off his relatives.","cn":"他靠在众亲属那儿蹭吃蹭喝过了一辈子。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"海绵;人造海绵","en":"Sponge is a very light soft substance with lots of little holes in it, which can be either artificial or natural. It is used to clean things or as a soft layer.","ex":{"en":"...a sponge mattress.","cn":"海绵床垫"}},{"pos":"N-COUNT 可数名词","cn":"海绵(一种海洋动物，体圆而柔软)","en":"A sponge is a sea animal with a soft round body made of natural sponge."},{"pos":"N-COUNT 可数名词","cn":"(洗澡或清洁用的)海绵块","en":"A sponge is a piece of sponge that you use for washing yourself or for cleaning things.","ex":{"en":"He wiped off the table with a sponge.","cn":"他用一块海绵擦桌子。"}},{"pos":"VERB 动词","cn":"用湿海绵擦拭","en":"If you sponge something, you clean it by wiping it with a wet sponge.","ex":{"en":"Fill a bowl with water and gently sponge your face and body.","cn":"在一只盆里放上水，轻轻地用蘸湿的海绵擦拭你的面部及身体。"}},{"pos":"N-VAR 可变名词","cn":"海绵蛋糕;松软布丁","en":"A sponge is a light cake or pudding made from flour, eggs, sugar, and sometimes fat.","ex":{"en":"It makes a superb filling for cakes and sponges.","cn":"它非常适合做蛋糕和软布丁的馅儿。"}},{"pos":"VERB 动词","cn":"揩…的油;靠…养活","en":"If you say that someone sponges off other people or sponges on them, you mean that they regularly get money from other people when they should be trying to support themselves.","ex":{"en":"He should just get an honest job and stop sponging off the rest of us!","cn":"他应该找一份正当的工作，不要再揩我们这些人的油了！"}}]},"media":{"img":["media/ldoce/img/sponge.jpg","media/pic/toiletries_bathroom_comp.jpg"],"uk":"media/uk/sponge__gb_1.mp3","us":"media/us/sponge__us_1.mp3"},"examples":[{"en":"Take your jacket off and I'll sponge it down with water.","cn":"把你的夹克脱下来，我要用海绵蘸上水把它擦一擦。"},{"en":"( figurative ) His mind was like a sponge, ready to absorb anything.","cn":"他的脑子跟海绵似的，什么都能吸收。"}]},"spa":{"oxford":{"phon":"spɑː","pos":"noun","senses":[{"en":"a place where water with minerals in it, which is considered to be good for your health, comes up naturally out of the ground; the name given to a town that has such a place and where there are, or were, places where people could drink the water","cn":"矿泉疗养地；矿泉城","ex":{"en":"Leamington Spa","cn":"利明顿矿泉城"}},{"en":"a place where people can relax and receive health and beauty treatments, with, for example steam baths and exercise equipment","cn":"休闲健身中心（提供休闲、健身、美容等服务，如蒸汽浴和运动设施）","ex":{"en":"a superb spa, which includes sauna, Turkish bath and fitness rooms","cn":"内设桑拿浴室、土耳其浴室和健身房的一流休闲健身中心"}},{"en":"a large bath with a pump that moves the water around, giving a pleasant feeling to your body","cn":"杰酷士按摩浴缸","lab":"especially North American English"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"温泉疗养地;矿泉疗养地","en":"A spa is a place where water with minerals in it comes out of the ground. People drink the water or go in it in order to improve their health.","ex":{"en":"...Fiuggi, a spa town famous for its water.","cn":"菲乌吉——一个以水质绝佳而闻名的温泉疗养城市"}},{"pos":"N-COUNT 可数名词","cn":"温泉疗养院;温泉疗养中心","en":"A health spa is a kind of hotel where people go to do exercise and have special treatments in order to improve their health."}]},"media":{"uk":"media/uk/spa__gb_1.mp3","us":"media/us/spa__us_1.mp3"},"examples":[{"en":"a superb health spa which includes sauna, Turkish bath and fitness rooms","cn":"内设桑拿浴室、蒸汽浴室和健身房的第一流的休闲健身中心"},{"en":"Leamington Spa","cn":"利明顿矿泉城"}]},"spines":{"oxford":{"phon":"spaɪn","pos":"noun","senses":[{"en":"the row of small bones that are connected together down the middle of the back","cn":"脊柱；脊椎"},{"en":"any of the sharp pointed parts like needles on some plants and animals （","cn":"植物的）刺；（动物的）刺毛"}]}},"specialist":{"oxford":{"phon":"ˈspeʃəlɪst","pos":"noun","senses":[{"en":"a person who is an expert in a particular area of work or study","cn":"专家","ex":{"en":"a specialist in Japanese history","cn":"日本史专家"}},{"en":"a doctor who has specialized in a particular area of medicine","cn":"专科医生","ex":{"en":"You need to see a specialist.","cn":"你需要去看专科医生。"}},{"en":"having or involving expert knowledge of a particular area of work, study or medicine","cn":"专家的；专业人员的","ex":{"en":"specialist knowledge/training/skills","cn":"专业知识／培训／技能"},"pos":"adjective"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"专家","en":"A specialist is a person who has a particular skill or knows a lot about a particular subject.","ex":{"en":"If you are housebound, you can arrange for a home visit from a specialist adviser","cn":"如果你出不了门，可以预约专家顾问上门就诊。"}}]},"media":{"uk":"media/uk/specialist__gb_1.mp3","us":"media/us/specialist__us_1.mp3"},"examples":[{"en":"You need some specialist advice.","cn":"你需要咨询专业人士。"},{"en":"a cancer specialist","cn":"癌症专科医生"}]},"spin-off":{"oxford":{"phon":"ˈspɪn ɒf","pos":"noun","senses":[{"en":"an unexpected but useful result of an activity that is designed to produce something else","cn":"（意外但有用的）副产品，派生物","ex":{"en":"commercial spin-offs from medical research","cn":"医学研究引出的有商业价值的副产品"}},{"en":"a book, a film, a television programme, or an object that is based on a book, film or television series that has been very successful","cn":"（根据成功的书、电影或电视剧制作的）衍生作品，周边产品","ex":{"en":"The TV comedy series is a spin-off of the original movie.","cn":"这部喜剧连续剧是电影原作的衍生剧。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"副产品;派生产品","en":"A spin-off is an unexpected but useful or valuable result of an activity that was designed to achieve something else.","ex":{"en":"The company put out a report on commercial spin-offs from its research.","cn":"公司公布了一份有关其研究活动所产生的商业副产品的报告。"}},{"pos":"N-COUNT 可数名词","cn":"(受欢迎的书籍、电影、电视连续剧等的)派生产品","en":"A spin-off is a book, film, or television series that comes after and is related to a successful book, film, or television series."}]},"media":{"uk":"media/uk/spin_off_1_gb_1.mp3","us":"media/us/spin_off_1_us_1.mp3"},"examples":[{"en":"The TV comedy series is a spin-off of the original movie.","cn":"这部电视喜剧连续剧是电影原作的副产品。"},{"en":"spin-off merchandise from the latest Disney movie","cn":"根据最新的迪斯尼影片开发的商品"}]},"spoil":{"oxford":{"phon":"spɔɪl","pos":"verb","senses":[{"en":"to change something good into something bad, unpleasant, etc.","cn":"破坏；糟蹋；毁掉","g":"[transitive]","ex":{"en":"Our camping trip was spoilt by bad weather.","cn":"天气不好，破坏了我们的露营旅行。"}},{"en":"to give a child everything that they ask for and not enough discipline in a way that has a bad effect on their character and behaviour","cn":"溺爱；娇惯；宠坏","g":"[transitive]","ex":{"en":"She spoils those kids of hers.","cn":"那几个孩子被她宠坏了。"}},{"en":"to make somebody/yourself happy by doing something special","cn":"善待；格外关照","g":"[transitive]","ex":{"en":"Why not spoil yourself with a weekend in a top hotel?","cn":"为什么不到顶级饭店度个周末，让自己享受享受呢？"}},{"en":"to become bad so that it can no longer be eaten","cn":"变坏；变质；腐败","g":"[intransitive]"},{"en":"to mark a ballot paper in a way that is not correct so the vote does not count, especially as a form of protest","cn":"错填（选票），使作废（尤指作为抗议）","g":"[transitive]","ex":{"en":"The group called on its supporters to spoil their ballot papers.","cn":"该组织呼吁其支持者毁掉他们的选票。"}},{"en":"goods taken from a place by thieves or by an army that has won a battle or war","cn":"赃物；战利品；掠夺物","g":"[plural]","lab":"formal or literary","ex":{"en":"the spoils of war","cn":"战利品"},"pos":"noun"},{"en":"the profits or advantages that somebody gets from being successful","cn":"成功所带来的好处；权力地位的连带利益","g":"[plural]","ex":{"en":"the spoils of high office","cn":"身居高位的连带利益"},"pos":"noun"},{"en":"waste material that is brought up when a hole is dug, etc.","cn":"（开掘等时挖出的）弃土，废石方","g":"[uncountable]","lab":"specialist","pos":"noun"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"弄糟;损坏;破坏","en":"If you spoil something, you prevent it from being successful or satisfactory.","ex":{"en":"It's important not to let mistakes spoil your life","cn":"重要的是不要让错误毁了你的生活。"}},{"pos":"VERB 动词","cn":"溺爱，宠坏(孩子)","en":"If you spoil children, you give them everything they want or ask for. This is considered to have a bad effect on a child's character.","ex":{"en":"Grandparents are often tempted to spoil their grandchildren whenever they come to visit.","cn":"祖父母每次来访都往往禁不住要娇惯孙辈。"}},{"pos":"VERB 动词","cn":"犒赏（自己或他人）","en":"If you spoil yourself or spoil another person, you give yourself or them something nice as a treat or do something special for them.","ex":{"en":"Spoil yourself with a new perfume this summer","cn":"今年夏天买瓶新香水慰劳一下自己吧。"}},{"pos":"V-ERG 及物/不及物动词","cn":"（使）(食物)变坏;(使)腐坏","en":"If food spoils or if it is spoilt, it is no longer fit to be eaten.","ex":{"en":"We all know that fats spoil by becoming rancid","cn":"我们都知道油脂变质后会发臭。"}},{"pos":"VERB 动词","cn":"(因在其上写违法的内容而)使(选票)无效","en":"If someone spoils their vote, they write something illegal on their voting paper, usually as a protest about the election, and their vote is not accepted.","ex":{"en":"They had broadcast calls for voters to spoil their ballot papers","cn":"他们通过广播呼吁选民们投无效选票。"}},{"pos":"N-PLURAL 复数名词","cn":"战利品;因成功获得的好处","en":"The spoils of something are things that people get as a result of winning a battle or of doing something successfully.","ex":{"en":"True to military tradition, the victors are now treating themselves to the spoils of war","cn":"按照军事惯例，胜者正在分享战利品。"}},{"pos":"PHRASE 短语","cn":"可供选择的东西众多","en":"If you say that someone is spoilt for choice or spoiled for choice, you mean that they have a great many things of the same type to choose from.","ex":{"en":"At lunchtime, MPs are spoilt for choice in 26 restaurants and bars.","cn":"到了午餐时间，议员们有 26 家之多的餐厅和酒吧可供选择。"}},{"pos":"","cn":"","en":"相关词组：spoil for"}]},"media":{"uk":"media/uk/spoil__gb_1.mp3","us":"media/us/spoil__us_1.mp3"},"examples":[{"en":"Why not spoil yourself with a weekend in a top hotel?","cn":"为什么不到顶级饭店度个周末，让自己享受享受呢？"},{"en":"Our camping trip was spoilt by bad weather.","cn":"天气不好，破坏了我们的露营旅行。"}]},"specimen":{"media":{"uk":"media/uk/specimen__gb_1.mp3","us":"media/us/specimen__us_1.mp3"},"oxford":{"phon":"ˈspesɪmən","pos":"noun","senses":[{"en":"a small amount of something that shows what the rest of it is like","cn":"样品；样本；标本","ex":{"en":"Astronauts have brought back specimens of rock from the moon.","cn":"宇航员从月球带回了岩石标本。"}},{"en":"a single example of something, especially an animal or a plant","cn":"（尤指动植物的）单一实例","lab":"humorous","ex":{"en":"The aquarium has some interesting specimens of unusual tropical fish.","cn":"水族馆里有一些罕见的热带鱼，很有意思。"}},{"en":"a small quantity of blood, urine, etc. that is taken from somebody and tested by a doctor","cn":"（化验的）抽样，血样，尿样","ex":{"en":"to provide/take a specimen","cn":"提供血样；采血样"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(动植物的)标本","en":"A specimen is a single plant or animal which is an example of a particular species or type and is examined by scientists.","ex":{"en":"200,000 specimens of fungus are kept at the Komarov Botanical Institute.","cn":"有 20 万份菌类标本被保存在科马罗夫植物研究所。"}},{"pos":"N-COUNT 可数名词","cn":"样品;样本","en":"A specimen of something is an example of it which gives an idea of what the whole of it is like.","ex":{"en":"Job applicants have to submit a specimen of handwriting.","cn":"求职者必须要提交一份笔迹样本。"}},{"pos":"N-COUNT 可数名词","cn":"(供检验用的尿、血液等体液的)抽样，样本","en":"A specimen is a small quantity of someone's urine, blood, or other body fluid which is examined in a medical laboratory, in order to find out if they are ill or if they have been drinking alcohol or taking drugs.","ex":{"en":"He refused to provide a specimen","cn":"他拒绝提供血样。"}},{"pos":"N-COUNT 可数名词","cn":"具有…特性的人；…的典型","en":"You can use specimen to refer to someone who has a quality of a particular kind.","ex":{"en":"What a poor specimen that child is!","cn":"那孩子真不幸！"}}]},"examples":[{"en":"The aquarium has some interesting specimens of unusual tropical fish.","cn":"水族馆里有一些罕见的热带鱼，很有意思。"},{"en":"Astronauts have brought back specimens of rock from the moon.","cn":"宇航员从月球带回了岩石标本。"}]},"spend":{"media":{"uk":"media/uk/spend__gb_1.mp3","us":"media/us/spend__us_1.mp3"},"oxford":{"phon":"spend","pos":"verb","senses":[{"en":"to give money to pay for goods, services, etc.","cn":"用，花（钱）","g":"[transitive, intransitive]","ex":{"en":"I've spent all my money already.","cn":"我已经把我的钱全都花完了。"}},{"en":"to use time for a particular purpose; to pass time","cn":"花（时间）；度过","g":"[transitive]","ex":{"en":"We spent the day at the beach.","cn":"我们在海滩上待了一天。"}},{"en":"to use energy, effort, etc., especially until it has all been used","cn":"花费，消耗，用尽（精力等）","g":"[transitive, often passive]","ex":{"en":"She spends too much effort on things that don't matter.","cn":"她在一些无关紧要的事情上花费精力太多。"}},{"en":"the amount of money spent for a particular purpose or over a particular length of time","cn":"（为某目的或某段时间内的）花销，花费，开销","ex":{"en":"The average spend at the cafe is £10 a head.","cn":"在咖啡馆的人均消费是 10 英镑。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"花(钱);用(钱)","en":"When you spend money, you pay money for things that you want.","ex":{"en":"By the end of the holiday I had spent all my money","cn":"到假期结束时，我已经花光了自己所有的钱。"}},{"pos":"VERB 动词","cn":"花费(时间或精力)","en":"If you spend time or energy doing something, you use your time or effort doing it.","ex":{"en":"Engineers spend much time and energy developing brilliant solutions","cn":"工程师们花费很多时间和精力来开发完美的解决方案。"}},{"pos":"VERB 动词","cn":"(在某处)度过(一段时间)","en":"If you spend a period of time in a place, you stay there for a period of time.","ex":{"en":"We spent the night in a hotel.","cn":"我们在一家旅馆过夜。"}},{"pos":"N-COUNT 可数名词","cn":"开支;费用","en":"The spend on a particular thing is the amount of money that is spent on it, or will be spent.","ex":{"en":"...the marketing and advertising spend.","cn":"营销和广告开支"}},{"pos":"","cn":"","en":"to spend a penny→see: ;"}]},"examples":[{"en":"She spends too much effort on things that don't matter.","cn":"她在一些无关紧要的事情上花费精力太多。"},{"en":"She spent £100 on a new dress.","cn":"她花 100 英镑买了一条新连衣裙。"}]},"spinner":{"media":{"uk":"media/uk/spinner__gb_1.mp3","us":"media/us/spinner__us_1.mp3","img":["media/ldoce/img/spinner.jpg"]},"oxford":{"phon":"ˈspɪnə(r)","pos":"noun","senses":[{"en":"a bowler who uses spin when throwing the ball","cn":"投旋转球的投球手"},{"en":"a person who spins wool into thread","cn":"纺线者；纺纱工"},{"en":"a device that turns round and round, used on a fishing line to attract fish","cn":"（钓鱼用的）旋式诱饵，旋转亮片"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"投旋转球的板球投手","en":"A spinner is a cricketer who makes the ball spin when he or she bowls it so that it changes direction when it hits the ground or the bat."},{"pos":"N-COUNT 可数名词","cn":"纺纱者;纺纱工","en":"A spinner is a person who makes thread by spinning."}]}},"speech":{"media":{"uk":"media/uk/speech__gb_1.mp3","us":"media/us/speech__us_1.mp3"},"oxford":{"phon":"spiːtʃ","pos":"noun","senses":[{"en":"a formal talk that a person gives to an audience","cn":"演说；讲话；发言","g":"[countable]","ex":{"en":"Several people made speeches at the wedding.","cn":"有几个人在婚礼上讲了话。"}},{"en":"the language used when speaking; the fact of speaking rather than writing","cn":"口语；口头","g":"[uncountable]","ex":{"en":"This expression is used mainly in speech, not in writing.","cn":"这种表达主要用于口语，而不是书面语。"}},{"en":"the ability to speak","cn":"说话的能力","g":"[uncountable]","ex":{"en":"I seemed to have lost the power of speech.","cn":"我好像话都说不出来了。"}},{"en":"the way in which a particular person speaks","cn":"说话方式","g":"[uncountable]","ex":{"en":"Her speech was slurred—she was clearly drunk.","cn":"她说话含混不清，显然是喝醉了。"}},{"en":"a group of lines that an actor speaks in a play in the theatre","cn":"（戏剧中的）台词","g":"[countable]","ex":{"en":"She has the longest speech in the play.","cn":"在这部剧中，她的台词最长。"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"说话能力;说话;言语","en":"Speech is the ability to speak or the act of speaking.","ex":{"en":"...the development of speech in children","cn":"儿童言语能力的发展"}},{"pos":"N-SING 单数名词","cn":"说话方式;言谈","en":"Your speech is the way in which you speak.","ex":{"en":"His speech became increasingly thick and nasal","cn":"他说话的声音变得越来越粗，鼻音越来越重。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"口语，言语(与书面语相对而言)","en":"Speech is spoken language.","ex":{"en":"He could imitate in speech or writing most of those he admired.","cn":"他能模仿大多数自己崇拜的偶像的讲话和写作风格。"}},{"pos":"N-COUNT 可数名词","cn":"演说;演讲;讲话;致辞","en":"A speech is a formal talk which someone gives to an audience.","ex":{"en":"She is due to make a speech on the economy next week","cn":"她将在下周作一个关于经济的演讲。"}},{"pos":"N-COUNT 可数名词","cn":"(演员的)台词","en":"A speech is a group of lines spoken by a character in a play.","ex":{"en":"...the hilarious speech from Alan Bennett's 'Forty Years On'.","cn":"艾伦·贝内特的《弹指四十年》中的一段非常有趣的台词"}}]},"examples":[{"en":"This expression is used mainly in speech, not in writing.","cn":"这种表达主要用于口语，而不是书面语。"},{"en":"She gave an interesting talk on her visit to China.","cn":"她做了个关于她在中国访问的有趣报告。"}]},"spellcheck":{"oxford":{"phon":"ˈspeltʃek","pos":"verb","senses":[{"en":"to use a computer program to check your writing to see if your spelling is correct","cn":"（用计算机程序）检查拼写"},{"en":"a check of the spelling in a file or text using a spellchecker","cn":"拼写检查","ex":{"en":"I do/run a spellcheck after I've typed the posts.","cn":"输入帖子后，我会进行/运行拼写检查。"},"pos":"noun"},{"en":"a computer program that checks your writing to see if your spelling is correct","cn":"（计算机中的）拼写检查程序","pos":"noun"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"用拼写检查程序检查","en":"If you spellcheck something you have written on a computer, you use a special program to check whether you have made any spelling mistakes.","ex":{"en":"This model allows you to spellcheck over 100,000 different words.","cn":"用这个型号可以检查逾 10 万个词的拼写。"}},{"pos":"N-COUNT 可数名词","cn":"拼写检查","en":"If you run a spellcheck over something you have written on a computer, you use a special program to check whether you have made any spelling mistakes."}]},"media":{"uk":"media/uk/spellcheck__gb_1.mp3","us":"media/us/spellcheck__us_1.mp3"}},"spouse":{"media":{"uk":"media/uk/spouse__gb_1.mp3","us":"media/us/spouse__us_1.mp3"},"oxford":{"phon":"spaʊs","pos":"noun","senses":[{"en":"a husband or wife","cn":"配偶","ex":{"en":"Fill in your spouse’s name here.","cn":"在这儿填上配偶的姓名。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"配偶","en":"Someone's spouse is the person they are married to."}]},"examples":[{"en":"( formal ) spousal consent","cn":"配偶的同意"},{"en":"spousal abuse","cn":"虐待配偶"}]},"spelt":{"collins":{"senses":[{"pos":"","cn":"","en":"Spelt is a past tense and past participle form of spell ."}]},"media":{"uk":"media/uk/spelt__gb_1.mp3","us":"media/us/spelt__us_1.mp3"},"oxford":{"phon":"spelt","pos":"noun","senses":[{"en":"a type of grain that used to be grown widely but is now eaten mainly as a health food","cn":"斯佩耳特小麦","ex":{"en":"Like wheat, spelt also contains gluten.","cn":"与小麦一样，斯佩尔特小麦也含有麸质。"}}]}},"spine":{"oxford":{"phon":"spaɪn","pos":"noun","senses":[{"en":"the row of small bones that are connected together down the middle of the back","cn":"脊柱；脊椎","ex":{"en":"A shiver went down my spine.","cn":"我感到毛骨悚然。"}},{"en":"the central feature of something or the main source of its strength","cn":"主要特点；力量源泉","ex":{"en":"These speeches form the spine of his election campaign.","cn":"这些讲话成为他竞选活动的纲领。"}},{"en":"strength of character","cn":"骨气；志气","ex":{"en":"Their protests stiffened the spines of party activists.","cn":"他们的抗议坚定了该党积极分子的信念。"}},{"en":"any of the sharp, pointed parts like needles on some plants and animals","cn":"（植物或动物的）刺","ex":{"en":"Porcupines use their spines to protect themselves.","cn":"豪猪用身上的棘刺来自卫。"}},{"en":"the narrow part of the cover of a book that the pages are joined to","cn":"书脊"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"脊椎;脊柱","en":"Your spine is the row of bones down your back."},{"pos":"N-COUNT 可数名词","cn":"书脊","en":"The spine of a book is the narrow stiff part which the pages and covers are attached to."},{"pos":"N-COUNT 可数名词","cn":"(动物身体上的)棘状突起;(植物上的)棘，刺，针","en":"Spines are also long, sharp points on an animal's body or on a plant."}]},"media":{"uk":"media/uk/spine__gb_1.mp3","us":"media/us/spine__us_1.mp3","img":["media/ldoce/img/skeleton.jpg"]},"examples":[{"en":"Porcupines use their spines to protect themselves.","cn":"豪猪用身上的刺毛来自卫。"},{"en":"cactus spines","cn":"仙人掌的刺"}]},"spray":{"media":{"uk":"media/uk/spray__gb_1.mp3","us":"media/us/spray__us_1.mp3"},"oxford":{"phon":"spreɪ","pos":"noun","senses":[{"en":"very small drops of a liquid that are sent through the air, for example by the wind","cn":"浪花；水花；飞沫","g":"[uncountable, countable]","lab":"figurative","ex":{"en":"The advertisement showed a group of horsemen on the beach, galloping through the sea spray.","cn":"广告中一群骑兵在海滩上驰骋在浪花中。"}},{"en":"a substance that is forced out of a container such as an aerosol, in very small drops","cn":"喷剂；喷雾的液体","g":"[uncountable, countable]","ex":{"en":"a can of insect spray (= used to kill insects)","cn":"一罐喷雾杀虫剂"}},{"en":"a device or container, for example an aerosol, that you use to apply liquid in fine drops","cn":"喷雾器","g":"[countable]","ex":{"en":"a throat spray","cn":"喉头喷雾器"}},{"en":"an act of applying liquid to something in very small drops","cn":"喷雾；液体的喷洒","g":"[countable]","ex":{"en":"I gave the plants a quick spray.","cn":"我给这些花草略微喷了喷水。"}},{"en":"a small branch of a tree or plant, with its leaves and flowers or berries, that you use for decoration","cn":"（用作装饰的）小树枝，小花枝","g":"[countable]"},{"en":"an attractive arrangement of flowers or jewellery, that you wear","cn":"（戴在身上的）一簇花，枝状饰物","g":"[countable]","ex":{"en":"a spray of orchids","cn":"一簇兰花"}},{"en":"to cover somebody/something with very small drops of a liquid that are forced out of a container or sent through the air","cn":"喷；喷洒；向…喷洒","g":"[transitive, intransitive]","ex":{"en":"Spray the conditioner onto your wet hair.","cn":"往你的湿头发上喷些护发素。"},"pos":"verb"},{"en":"to cover somebody/something with a lot of small things with a lot of force","cn":"向…扫射（或抛洒）；往…上撒","g":"[transitive, intransitive]","ex":{"en":"The gunman sprayed the building with bullets.","cn":"持枪歹徒向那座房子扫射。"},"pos":"verb"},{"en":"to leave small amounts of urine to mark its own area","cn":"撒尿（以示领地占有）","g":"[intransitive]","pos":"verb"}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"水花;飞沫","en":"Spray is a lot of small drops of water which are being thrown into the air.","ex":{"en":"The moon was casting a rainbow through the spray from the waterfall","cn":"月亮在瀑布溅起的水雾上照出了一道彩虹。"}},{"pos":"N-MASS 物质名词","cn":"喷剂","en":"A spray is a liquid kept under pressure in a can or other container, which you can force out in very small drops.","ex":{"en":"...hair spray.","cn":"喷发胶"}},{"pos":"V-ERG 及物/不及物动词","cn":"喷,喷洒（液体）","en":"If you spray a liquid somewhere or if it sprays somewhere, drops of the liquid cover a place or shower someone.","ex":{"en":"A sprayer hooked to a tractor can spray five gallons onto ten acres","cn":"用拖拉机牵引的喷雾器可以将 5 加仑药水喷洒在 10 英亩田地上。"}},{"pos":"V-ERG 及物/不及物动词","cn":"（使）飞溅;(使)飞散","en":"If a lot of small things spray somewhere or if something sprays them, they are scattered somewhere with a lot of force.","ex":{"en":"A shower of mustard seeds sprayed into the air and fell into the grass","cn":"许多芥子撒向空中，然后落进了草丛里。"}},{"pos":"VERB 动词","cn":"大量射出，扫射（子弹)","en":"If someone sprays bullets somewhere, they fire a lot of bullets at a group of people or things.","ex":{"en":"He ran to the top of the building spraying bullets into shoppers below","cn":"他跑到楼顶上，向下面的购物人群开枪扫射。"}},{"pos":"VERB 动词","cn":"在…上喷涂料(或油漆)","en":"If something is sprayed, it is painted using paint kept under pressure in a container.","ex":{"en":"The bare metal was sprayed with several coats of primer.","cn":"裸露的金属上被喷上了几层底漆。"}},{"pos":"VERB 动词","cn":"喷农药","en":"When someone sprays against insects, they cover plants or crops with a chemical which prevents insects feeding on them.","ex":{"en":"He doesn't spray against pests or diseases","cn":"他并不喷药防虫祛病。"}},{"pos":"N-COUNT 可数名词","cn":"(尤指用于植被的)喷水器，喷雾器","en":"A spray is a piece of equipment for spraying water or another liquid, especially over growing plants."},{"pos":"N-COUNT 可数名词","cn":"(一根枝条上的)花簇(或叶片)","en":"A spray of flowers or leaves is a number of flowers or leaves on one stem or branch.","ex":{"en":"...a small spray of freesias.","cn":"一小簇小苍兰"}}]},"examples":[{"en":"I gave the plants a quick spray.","cn":"我给这些花草略微喷了喷水。"},{"en":"Spray the conditioner onto your wet hair.","cn":"往你的湿头发上喷些护发素。"}]},"splits":{"oxford":{"phon":"splɪt","pos":"verb","senses":[{"en":"to divide, or to make a group of people divide, into smaller groups that have very different opinions","cn":"分裂，使分裂（成不同的派别）"},{"en":"to divide, or to make sth divide, into two or more parts","cn":"分开，使分开（成为几个部分）"}]}},"specs":{"collins":{"senses":[{"pos":"","cn":"","en":"→see: ;"}]},"media":{"uk":"media/uk/specs__gb_1.mp3","us":"media/us/specs__us_1.mp3"},"oxford":{"phon":"speks","pos":"noun","senses":[{"en":"two lenses in a frame that rests on the nose and ears. People wear glasses in order to be able to see better or to protect their eyes from bright light.","cn":"眼镜","g":"[plural]","lab":"especially British English, informal，，","ex":{"en":"I need a new pair of specs.","cn":"我需要一副新眼镜。"}},{"en":"a detailed description of something, especially the design and materials needed to produce something","cn":"规格","g":"[countable]","lab":"North American English"}]}},"spies":{"oxford":{"phon":"spaɪ","pos":"noun","senses":[{"en":"a person who tries to get secret information about another country, organization or person, especially sb who is employed by a government or the police","cn":"间谍；密探"},{"en":"to collect secret information about another country, organization or person","cn":"从事间谍活动；搜集情报"}]},"media":{"uk":"media/uk/spies__gb_1.mp3","us":"media/us/spies__us_1.mp3"}},"speakers":{"oxford":{"phon":"ˈspiːkə(r)","pos":"noun","senses":[{"en":"a person who gives a talk or makes a speech","cn":"发言者；演讲者"},{"en":"a person who is or was speaking","cn":"说话者"}]},"media":{"img":["media/ldoce/img/speakers.jpg"]}},"specifications":{"oxford":{"phon":"ˌspesɪfɪˈkeɪʃn","pos":"noun","senses":[{"en":"a detailed description of how sth is, or should be, designed or made","cn":"规格；规范；明细单；说明书"}]}},"speculates":{"oxford":{"phon":"ˈspekjuleɪt","pos":"verb","senses":[{"en":"to form an opinion about sth without knowing all the details or facts","cn":"推测；猜测；推断"},{"en":"to buy goods, property, shares, etc., hoping to make a profit when you sell them, but with the risk of losing money","cn":"投机；做投机买卖"}]}},"spawned":{"oxford":{"phon":"spɔːn","pos":"verb","senses":[{"en":"to lay eggs","cn":"产卵"},{"en":"( often disapproving ) to cause sth to develop or be produced","cn":"引发；引起；导致；造成"}]}},"spirits":{"oxford":{"phon":"ˈspɪrɪt","pos":"noun","senses":[{"en":"the part of a person that includes their mind, feelings and character rather than their body","cn":"精神；心灵"},{"en":"a person's feelings or state of mind","cn":"情绪；心境"}]}},"spiced":{"oxford":{"phon":"spaɪs","pos":"noun","senses":[{"en":"one of the various types of powder or seed that come from plants and are used in cooking. Spices have a strong taste and smell （","cn":"调味）香料"},{"en":"extra interest or excitement","cn":"额外的趣味（或刺激等）"}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"加了香料的;加了佐料的","en":"Food that is spiced has had spices or other strong-tasting foods added to it.","ex":{"en":"Every dish was served heavily spiced.","cn":"端上来的每道菜都加了很多佐料。"}}]}},"splashing":{"oxford":{"phon":"splæʃ","pos":"verb","senses":[{"en":"to fall noisily onto a surface","cn":"泼洒；哗啦哗啦地溅；劈里啪啦地落"},{"en":"to make sb/sth wet by making water, mud, etc. fall on them/it","cn":"把（水、泥等）泼在 … 上，溅在 … 上；朝 … 上泼（或溅）"}]}},"sports":{"oxford":{"phon":"spɔːt","pos":"noun","senses":[{"en":"activity that you do for pleasure and that needs physical effort or skill, usually done in a special area and according to fixed rules","cn":"体育运动"},{"en":"a particular form of sport （","cn":"某项）体育运动"}]},"media":{"img":["media/pic/sports_comp.jpg"]}},"spared":{"oxford":{"phon":"speə(r)","pos":"adjective","senses":[{"en":"that is not being used or is not needed at the present time","cn":"不用的；闲置的"},{"en":"kept in case you need to replace the one you usually use; extra","cn":"备用的；外加的"}]}},"spends":{"oxford":{"phon":"spend","pos":"verb","senses":[{"en":"to give money to pay for goods, services, etc.","cn":"用，花（钱）"},{"en":"to use time for a particular purpose; to pass time","cn":"花（时间）；度过"}]}},"speculating":{"oxford":{"phon":"ˈspekjuleɪt","pos":"verb","senses":[{"en":"to form an opinion about sth without knowing all the details or facts","cn":"推测；猜测；推断"},{"en":"to buy goods, property, shares, etc., hoping to make a profit when you sell them, but with the risk of losing money","cn":"投机；做投机买卖"}]}},"spayed":{"oxford":{"phon":"speɪ","pos":"verb","senses":[{"en":"( technical","cn":"术语 ) to remove the ovaries of a female animal, to prevent it from breeding 切除雌兽的卵巢；劁（雌兽）"}]}},"spots":{"oxford":{"phon":"spɒt","pos":"noun","senses":[{"en":"a small round area that has a different colour or feels different from the surface it is on","cn":"斑点"},{"en":"a small dirty mark on sth","cn":"污迹；污渍；脏点"}]}},"sparkled":{"oxford":{"phon":"ˈspɑːkl","pos":"verb","senses":[{"en":"to shine brightly with small flashes of light","cn":"闪烁；闪耀"},{"en":"to be full of life, enthusiasm or humour","cn":"生气勃勃；热情奔放；神采飞扬"}]}},"speaks":{"oxford":{"phon":"spiːk","pos":"verb","senses":[{"en":"to talk to sb about sth; to have a conversation with sb","cn":"谈；谈话；交谈"},{"en":"to use your voice to say sth","cn":"说话；讲话"}]}},"sparked":{"oxford":{"phon":"spɑːk","pos":"noun","senses":[{"en":"a very small burning piece of material that is produced by sth that is burning or by hitting two hard substances together","cn":"火花；火星"},{"en":"a small flash of light produced by an electric current","cn":"电火花"}]}},"spreads":{"oxford":{"phon":"spred","pos":"verb","senses":[{"en":"to open sth that has been folded so that it covers a larger area than before","cn":"展开；打开"},{"en":"to arrange objects so that they cover a large area and can be seen easily","cn":"摊开；使散开"}]}},"speeches":{"oxford":{"phon":"spiːtʃ","pos":"noun","senses":[{"en":"a formal talk that a person gives to an audience","cn":"演说；讲话；发言"},{"en":"the ability to speak","cn":"说话的能力"}]}},"speaking":{"oxford":{"phon":"spiːk","pos":"verb","senses":[{"en":"to talk to sb about sth; to have a conversation with sb","cn":"谈；谈话；交谈"},{"en":"to use your voice to say sth","cn":"说话；讲话"}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"发表讲话;演讲","en":"Speaking is the activity of giving speeches and talks.","ex":{"en":"It would also train women union members in public speaking and decision-making","cn":"它还将培养工会的女性成员公开演讲和决策的能力。"}},{"pos":"PREP-PHRASE 短语介词","cn":"(表示说话者身份)作为…来说","en":"You can say 'speaking as a parent' or 'speaking as a teacher', for example, to indicate that the opinion you are giving is based on your experience as a parent or as a teacher.","ex":{"en":"Well, speaking as a journalist I'm dismayed by the amount of pressure there is for pictures of combat.","cn":"嗯，作为一名新闻记者，拍摄战争场面的巨大压力让我深感不安。"}},{"pos":"PREP-PHRASE 短语介词","cn":"(接过话头引入新话题)说到…，谈到…","en":"You can say speaking of something that has just been mentioned as a way of introducing a new topic which has some connection with that thing.","ex":{"en":"There's plenty of time to drop hints for Christmas presents! And speaking of presents, we have 100 exclusive fragrance collections to give away.","cn":"还有足够的时间去暗示自己想要的圣诞礼物！说到礼物，我们有 100 份限量版香水要赠送。"}},{"pos":"PHRASE 短语","cn":"一般说来/从技术角度说来","en":"You use speaking in expressions such as generally speaking and technically speaking to indicate which things or which particular aspect of something you are talking about.","ex":{"en":"Generally speaking there was no resistance to the idea","cn":"一般说来，没有人会反对这个观点。"}}]}},"spilled":{"oxford":{"phon":"spɪl","pos":"verb","senses":[{"en":"to flow over the edge of a container by accident; to make liquid do this （","cn":"使）洒出，泼出，溢出"},{"en":"to come out of a place in large numbers and spread out","cn":"涌出；蜂拥而出"}]}},"spooks":{"oxford":{"phon":"spuːk","pos":"noun","senses":[{"en":"a ghost","cn":"鬼"},{"en":"( especially NAmE ) a spy","cn":"间谍；特工"}]}},"spaces":{"oxford":{"phon":"speɪs","pos":"noun","senses":[{"en":"an amount of an area or of a place that is empty or that is available for use （","cn":"可利用的）空地，空间"},{"en":"an area or a place that is empty","cn":"空；空隙；空子；空当"}]}},"spreading":{"oxford":{"phon":"spred","pos":"verb","senses":[{"en":"to open sth that has been folded so that it covers a larger area than before","cn":"展开；打开"},{"en":"to arrange objects so that they cover a large area and can be seen easily","cn":"摊开；使散开"}]}},"spooky":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"阴森可怖的;闹鬼似的","en":"A place that is spooky has a frightening atmosphere, and makes you feel that there are ghosts around.","ex":{"en":"The whole place has a slightly spooky atmosphere.","cn":"整个地方的气氛有点阴森可怖。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"making you feel frightened","cn":""},{"en":"frightening. Scary is less formal than frightening and is very common in everyday English","cn":""},{"en":"frightening, especially because violence, cruelty, or danger is involved","cn":""}]},"collocations":{"phrases":["VERBS be, feel, look, sound | become, get It got a bit spooky when James started telling ghost stories.","ADV. dead, decidedly, really, very | a bit, pretty, quite, rather, slightly"]},"media":{"uk":"media/ldoce/hwd/bre/4/spooky0205.mp3","us":"media/ldoce/hwd/ame/c/spooky.mp3"},"examples":[{"en":"I was just thinking about her when she phoned. Spooky!","cn":"我正在想她，她就来电话了。你说怪不怪！"},{"en":"a spooky old house","cn":"阴森森的老房子"}],"oxford":{"phon":"ˈspuːki","pos":"adjective","senses":[{"en":"strange and frightening","cn":"怪异吓人的；阴森可怖的","ex":{"en":"a spooky old house","cn":"阴森森的老房子"}}]}},"spindle":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(机器的)轴，心轴","en":"A spindle is a rod in a machine, around which another part of the machine turns."},{"pos":"N-COUNT 可数名词","cn":"(手纺用的)绕线杆","en":"A spindle is a pointed rod which you use when you are spinning wool by hand. You twist the wool with the spindle to make it into a thread."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a part of a machine shaped like a stick, around which something turns 〔","cn":"机器的〕轴，心轴"},{"en":"a round pointed stick used for twisting the thread when you are spinning wool","cn":"纺锤﹔纱锭"}]},"vocab":{"pos":"n","senses":[{"en":"A spindle is a narrow wooden rod that's used when spinning wool. If your aunt has a spinning wheel for making yarn from the wool of her sheep, it must have a spindle on it for twisting the fibers."}]},"media":{"uk":"media/ldoce/hwd/bre/f/ld41spindle.mp3","us":"media/ldoce/hwd/ame/e/spindle.mp3"},"oxford":{"phon":"ˈspɪndl","pos":"noun","senses":[{"en":"a long straight part that turns in a machine, or that another part of the machine turns around","cn":"轴；心轴；指轴"},{"en":"a thin pointed piece of wood used for spinning wool into thread by hand","cn":"（手纺用的）绕线杆，纺锤"}]}},"splash":{"collins":{"senses":[{"pos":"VERB 动词","cn":"在水中嬉戏；戏水","en":"If you splash about or splash around in water, you hit or disturb the water in a noisy way, causing some of it to fly up into the air.","ex":{"en":"A lot of people were in the water, swimming or simply splashing about","cn":"水里有很多人在游泳或只是在戏水玩耍。"}},{"pos":"V-ERG 及物/不及物动词","cn":"(使)溅泼;(使)飞溅;(使)洒落","en":"If you splash a liquid somewhere or if it splashes, it hits someone or something and scatters in a lot of small drops.","ex":{"en":"He closed his eyes tight, and splashed the water on his face","cn":"他紧闭双眼，将水泼在自己脸上。"}},{"pos":"N-SING 单数名词","cn":"溅泼声;扑通声","en":"A splash is the sound made when something hits water or falls into it.","ex":{"en":"There was a splash and something fell clumsily into the water.","cn":"扑通一声，有东西重重地掉进了水里。"}},{"pos":"N-COUNT 可数名词","cn":"洒泼上去的一点儿;添加进去的少量","en":"A splash of a liquid is a small quantity of it that falls on something or is added to something.","ex":{"en":"Wallcoverings and floors should be able to withstand steam and splashes","cn":"墙面材料和地板都应该能耐热汽且防水。"}},{"pos":"N-COUNT 可数名词","cn":"(与周围颜色形成强烈对照的)一片鲜艳颜色","en":"A splash of colour is an area of a bright colour which contrasts strongly with the colours around it.","ex":{"en":"Anne has left the walls white, but added splashes of colour with the tablecloth and the paintings.","cn":"安妮让墙壁维持白色，但用桌布及油画进行了色彩点缀。"}},{"pos":"VERB 动词","cn":"(报刊)以醒目方式刊登","en":"If a magazine or newspaper splashes a story, it prints it in such a way that it is very noticeable.","ex":{"en":"The newspapers splashed the story all over their front pages","cn":"各家报纸都以整个头版醒目地刊登了这一报道。"}},{"pos":"PHRASE 短语","cn":"引人注目;引起轰动","en":"If you make a splash, you become noticed or become popular because of something that you have done.","ex":{"en":"Now she's made a splash in the American television show 'Civil Wars'.","cn":"现在她已经凭借美国电视剧《内战》而一炮走红。"}},{"pos":"","cn":"","en":"相关词组：splash out"}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to make a liquid or other substance flow out of or into a container by holding it at an angle","cn":""},{"en":"to pour a liquid onto food in small drops or in a small stream – often used in cooking instructions","cn":""},{"en":"to pour something out of a container by turning it upside down","cn":""}]},"vocab":{"pos":"1 v n 2 v 3 n 4 n","senses":[{"en":"A splash is a tiny amount of a liquid. You might, for example, prefer your coffee with just a splash of cream."}]},"collocations":{"phrases":["ADJ. big, huge | small | loud | soft","VERB + SPLASH make (often figurative) She intended to make a big splash with her wedding. | hear","PREP. with a ~ She jumped into the pool with a splash. 2 area of colour/light","ADJ. bold, bright a bold splash of red","VERB + SPLASH add, lend Window boxes of tulips added a splash of colour to the street.","PHRASES a splash of colour/light"]},"media":{"uk":"media/ldoce/hwd/bre/c/brelasdesplash.mp3","us":"media/ldoce/hwd/ame/6/splash1.mp3"},"examples":[{"en":"People were having fun in the pool, swimming or just splashing around.","cn":"人们在游泳池里或者游泳，或者只是拍打戏水，开心地玩着。"},{"en":"The kids were splashing through the puddles.","cn":"孩子们哗啦哗啦地溅着水花从水坑里蹚过。"}],"oxford":{"phon":"splæʃ","pos":"verb","senses":[{"en":"to fall noisily onto a surface","cn":"泼洒；哗啦哗啦地溅；噼里啪啦地落","g":"[intransitive]","ex":{"en":"Water splashed onto the floor.","cn":"水哗的一声泼洒在地板上。"}},{"en":"to make somebody/something wet by making water, mud, etc. fall on them/it","cn":"把（水、泥等）泼在…上，溅在…上；朝…上泼（或溅）","g":"[transitive]","ex":{"en":"He splashed cold water on his face.","cn":"他把冷水往脸上泼。"}},{"en":"to move through water making drops fly everywhere","cn":"（在水中）溅着水花行走，拍打着水游","g":"[intransitive]","ex":{"en":"The kids were splashing through the puddles.","cn":"孩子们哗啦哗啦地溅着水花从水坑里蹚过。"}},{"en":"to decorate something with areas of bright colour, not in a regular pattern","cn":"用（泼洒色斑）装饰","g":"[transitive]","ex":{"en":"The walls were splashed with patches of blue and purple.","cn":"墙壁上随意泼了大块的蓝色和紫色。"}},{"en":"the sound of something hitting liquid or of liquid hitting something","cn":"落水声；溅泼声","g":"[countable]","ex":{"en":"We heard the splash when she fell into the pool.","cn":"她掉进游泳池时我们听见扑通的一声。"},"pos":"noun"},{"en":"a small amount of liquid that falls onto something; the mark that this makes","cn":"溅上的液体；溅洒后留下的污渍","g":"[countable]","ex":{"en":"splashes of water on the floor","cn":"洒在地板上的一摊摊水"},"pos":"noun"},{"en":"a small area of bright colour or light that contrasts with the colours around it","cn":"色块；光斑","g":"[countable]","ex":{"en":"These flowers will give a splash of colour throughout the summer.","cn":"这些花会给整个夏天增添一片亮丽的色彩。"},"pos":"noun"},{"en":"a small amount of liquid that you add to a drink","cn":"掺入饮料的少量液体","g":"[singular]","lab":"informal","ex":{"en":"coffee with just a splash of milk","cn":"只加了少量牛奶的咖啡"},"pos":"noun"},{"en":"an article in a newspaper, etc. that is intended to attract a lot of attention","cn":"（报章等旨在招徕读者的）重点文章","g":"[singular]","ex":{"en":"Their engagement was the front-page splash in all the papers.","cn":"他们的订婚成为所有报纸的头版头条。"},"pos":"noun"}]}},"spit":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"唾液，唾沫(常指唾沫星子)","en":"Spit is the watery liquid produced in your mouth. You usually use spit to refer to an amount of it that has been forced out of someone's mouth."},{"pos":"VERB 动词","cn":"吐唾沫(常表示憎恨或轻蔑)","en":"If someone spits, they force an amount of liquid out of their mouth, often to show hatred or contempt.","ex":{"en":"The gang thought of hitting him too, but decided just to spit","cn":"那伙人也想过要揍他，但最后只是啐了他一口。"}},{"pos":"VERB 动词","cn":"吐出(少量液体或食物)","en":"If you spit liquid or food somewhere, you force a small amount of it out of your mouth.","ex":{"en":"Spit out that gum and pay attention","cn":"把那块口香糖吐出来，注意听。"}},{"pos":"VERB 动词","cn":"(机器) 噼啪作响;(煮着的食物)毕剥作响","en":"If something such as a machine or food that is cooking spits, it sends out small amounts of something, making a series of short, sharp noises.","ex":{"en":"The engine spat and banged.","cn":"发动机发出劈啪声，接着是砰的一声响。"}},{"pos":"VERB 动词","cn":"(咬牙切齿地)愤愤说出","en":"If someone spits an insult or comment, they say it in an angry or hostile way.","ex":{"en":"'Wait a damn minute,' Mindy spat. 'Nobody said anything about staying overnight.'","cn":"“该死的，等一下”，明迪愤愤地说道，“谁也没说过要过夜。”"}},{"pos":"VERB 动词","cn":"下毛毛细雨","en":"If it is spitting, it is raining very lightly.","ex":{"en":"It will stop in a minute — it's only spitting.","cn":"雨很快就会停的——这只不过是毛毛雨。"}},{"pos":"N-COUNT 可数名词","cn":"烤肉叉;扦子","en":"A spit is a long rod which is pushed through a piece of meat and hung over an open fire to cook the meat.","ex":{"en":"She roasted the meat on a spit.","cn":"她用烤肉叉子烤肉。"}},{"pos":"N-COUNT 可数名词","cn":"岬角;海岬","en":"A spit of land is a long, flat, narrow piece of land that sticks out into the sea."},{"pos":"PHRASE 短语","cn":"离…非常近","en":"If one place is within spitting distance of another, they are very close to each other.","ex":{"en":"...a restaurant within spitting distance of the Tower of London.","cn":"离伦敦塔非常近的一个餐馆"}},{"pos":"PHRASE 短语","cn":"极像…的人;和…一模一样的人","en":"If you say that one person is the spitting image of another, you mean that they look very similar.","ex":{"en":"Nina looks the spitting image of Sissy Spacek.","cn":"尼娜看起来像极了茜茜·斯帕赛克。"}},{"pos":"","cn":"","en":"相关词组：spit out"}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"say this when you are annoyed or angry because someone has not told you something","cn":""},{"en":"to force a small amount of saliva (= the liquid in your mouth ) out of your mouth","cn":"吐口水﹐吐唾沫"},{"en":"to force something out of your mouth","cn":"吐﹐唾"}]},"media":{"uk":"media/ldoce/hwd/bre/0/ld41spit.mp3","us":"media/ldoce/hwd/ame/1/spit1.mp3"},"examples":[{"en":"He was dragged out of the court, spitting abuse at the judge and jury.","cn":"他被拖出法庭，嘴里还不停地骂着法官和陪审团。"},{"en":"She spat in his face and went out.","cn":"她朝他脸上啐了一口，然后走了出去。"}],"oxford":{"phon":"spɪt","pos":"verb","senses":[{"en":"to force liquid, food, etc. out of your mouth","cn":"吐，唾（唾沫、食物等）","g":"[transitive]","sc":"from mouth","ex":{"en":"She took a mouthful of food and then suddenly spat it out.","cn":"她吃了一口食物，突然又吐了出来。"}},{"en":"to force saliva (= the liquid that is produced in the mouth) out of your mouth, often as a sign of anger or lack of respect","cn":"啐唾沫（常表示愤怒或鄙视）","g":"[intransitive]","sc":"from mouth","ex":{"en":"He coughed and spat.","cn":"他咳嗽一声，吐了口痰。"}},{"en":"to say something in an angry or aggressive way","cn":"怒斥","g":"[transitive]","sc":"say something angrily","ex":{"en":"‘You liar!’ she spat.","cn":"“你撒谎！”她怒叱道。"}},{"en":"to make a short angry sound","cn":"（发怒时）发呼噜呼噜声","g":"[intransitive]","sc":"of an animal","ex":{"en":"Snakes spit and hiss when they are cornered.","cn":"蛇陷入绝境时会发出咝咝呼呼的声音。"}},{"en":"to make a noise and throw out fat, sparks, etc.","cn":"咝咝地冒油；噼啪作响；爆出火花","g":"[intransitive]","sc":"of something cooking/burning","ex":{"en":"sausages spitting in the frying pan","cn":"在煎锅里咝咝冒油的香肠"}},{"en":"when it is spitting, it is raining lightly","cn":"下小雨","g":"[intransitive]","lab":"informal","sc":"rain"},{"en":"the liquid that is produced in your mouth","cn":"唾液；唾沫","g":"[uncountable]","sc":"in/from mouth","pos":"noun"},{"en":"the act of spitting liquid or food out of your mouth","cn":"啐唾沫；吐痰；吐食物","g":"[countable, usually singular]","sc":"in/from mouth","pos":"noun"},{"en":"a long, thin piece of land that sticks out into the sea, a lake, etc.","cn":"岬；沙嘴","g":"[countable]","sc":"piece of land","ex":{"en":"a spit of land between Lake Macquarie and the ocean","cn":"麦觉理湖和海洋之间的一小片陆地"},"pos":"noun"},{"en":"a long, thin, straight piece of metal that you put through meat to hold and turn it while you cook it over a fire","cn":"烤肉扦","g":"[countable]","sc":"for cooking meat","ex":{"en":"chickens roasting on a spit","cn":"烤鸡"},"pos":"noun"}]}},"spiteful":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"怀有恶意的;怀恨在心的","en":"Someone who is spiteful does cruel things to hurt people they dislike.","ex":{"en":"He could be spiteful.","cn":"他可能怀有恶意。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"treating people in a way that makes them unhappy or upset. Unkind sounds rather formal. In everyday English, people usually say mean or nasty","cn":""},{"en":"unkind","cn":""},{"en":"deliberately unkind, and seeming to enjoy making people unhappy","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"When you're spiteful , you act in a mean way, with a desire to hurt someone. If your little brother was driving you crazy, you could calmly ignore him — or you could give him a spiteful pinch."}]},"media":{"uk":"media/ldoce/hwd/bre/e/spiteful0205.mp3","us":"media/ldoce/hwd/ame/d/spiteful.mp3"},"examples":[{"en":"‘I don't need you,’ she said spitefully. “","cn":"我不需要你。”她故意气他地说。"},{"en":"‘I don't need you,’ she said spitefully.","cn":""}],"oxford":{"phon":"ˈspaɪtfl","pos":"adjective","senses":[{"en":"behaving in an unkind way in order to hurt or upset somebody","cn":"恶意的；居心不良的；故意使人苦恼的","ex":{"en":"a spiteful child","cn":"一个惹人烦的孩子"}}]}},"sprinkling":{"collins":{"senses":[{"pos":"N-SING 单数名词","cn":"(尤指分布在较大面积上的)少量，少许","en":"A sprinkling of something is a small quantity or amount of it, especially if it is spread over a large area.","ex":{"en":"...a light sprinkling of snow","cn":"薄薄的一层雪"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"water that falls from the sky in small drops","cn":""},{"en":"if it rains , water falls from the sky in the form of small drops","cn":""},{"en":"use this to say that rain is falling now","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/7/ld41sprinkling.mp3","us":"media/ldoce/hwd/ame/b/sprinkling.mp3"},"examples":[{"en":"Most were men, but there was also a sprinkling of young women.","cn":"多数是男人，不过也有为数不多的年轻妇女。"},{"en":"Add a sprinkling of pepper.","cn":"加一点胡椒粉。"}],"oxford":{"phon":"ˈsprɪŋklɪŋ","pos":"noun","senses":[{"en":"a small amount of a substance that is dropped somewhere, or a number of things or people that are spread or included somewhere","cn":"少量（落、撒或包含的某种物质）；少数（分散在或包括在某处的人）","ex":{"en":"Add a sprinkling of pepper.","cn":"加一点胡椒粉。"}}]}},"sprig":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(尤指烹饪或装饰用的)带叶小枝","en":"A sprig is a small stem with leaves on it which has been picked from a bush or plant, especially so that it can be used in cooking or as a decoration."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a small stem or part of a branch with leaves or flowers on it","cn":"带叶[花]的小枝"}]},"media":{"uk":"media/ldoce/hwd/bre/7/sprig0205.mp3","us":"media/ldoce/hwd/ame/9/sprig.mp3"},"examples":[{"en":"a sprig of parsley/holly/heather","cn":"一小枝欧芹/冬青/帚石楠"},{"en":"a sprig of parsley","cn":"一小枝欧芹"}],"oxford":{"phon":"sprɪɡ","pos":"noun","senses":[{"en":"a small stem with leaves on it from a plant or bush, used in cooking or as a decoration","cn":"（烹饪或装饰用）带叶小枝","ex":{"en":"a sprig of parsley/holly/heather","cn":"一小枝欧芹／冬青／帚石楠"}}]}},"spank":{"collins":{"senses":[{"pos":"VERB 动词","cn":"用手打(小孩的)屁股","en":"If someone spanks a child, they punish them by hitting them on the bottom several times with their hand.","ex":{"en":"When I used to do that when I was a kid, my mom would spank me.","cn":"我还是个孩子的时候常常干那种事，每次妈妈总是打我的屁股。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to hit someone quickly and hard with your hand, a stick etc","cn":""},{"en":"to hit someone deliberately many times, especially very hard","cn":""},{"en":"to hit someone with your hand or a weapon. Strike is more formal than hit and is mainly used in written English","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/0/spank0205.mp3","us":"media/ldoce/hwd/ame/9/spank1.mp3"},"oxford":{"phon":"spæŋk","pos":"noun","senses":[{"en":"a hit given several times on the bottom as a punishment, especially to a child","cn":"打（小孩的）屁股"},{"en":"to hit somebody, especially a child, several times on their bottom as a punishment","cn":"打（小孩的）屁股","ex":{"en":"I used to get beaten and spanked a lot when I was a kid.","cn":"我小时候经常挨打、打屁股。"},"pos":"verb"}]}},"spoilage":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"(通常指食物)腐败，变质，变坏","en":"When spoilage occurs, something, usually food, decays or is harmed, so that it is no longer fit to be used."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"waste resulting from something being spoiled","cn":"损坏物﹐报废物﹐废品"}]},"media":{"uk":"media/ldoce/hwd/bre/8/ld41spoilage.mp3","us":"media/ldoce/hwd/ame/b/laadspoilage.mp3"},"oxford":{"phon":"ˈspɔɪlɪdʒ","pos":"noun","senses":[{"en":"the decay (= the process of being destroyed) of food which means that it can no longer be used","cn":"（食物的）变质，腐败"}]}},"sputter":{"collins":{"senses":[{"pos":"VERB 动词","cn":"(发动机)发出噼啪声;(火焰)发出毕剥声","en":"If something such as an engine or a flame sputters, it works or burns in an uneven way and makes a series of soft popping sounds.","ex":{"en":"The truck sputtered and stopped","cn":"卡车噼啪响了几声停下了。"}},{"pos":"VERB 动词","cn":"(过程、行动或事态)缓慢不稳地进行，慢慢结束","en":"If a process, action, or state of affairs sputters, it progresses slowly and unevenly or starts to end.","ex":{"en":"The economy is already sputtering, with low or no growth","cn":"经济发展速度已经放慢，增长率很低，或者根本没有增长。"}},{"pos":"VERB 动词","cn":"(尤指因生气、震惊或激动)结结巴巴地说话，语无伦次地说话","en":"If you sputter, you speak with difficulty and make short sounds, especially because you are angry, shocked, or excited.","ex":{"en":"Stunned, I sputtered, 'What do you mean?'","cn":"我大吃一惊，结结巴巴地问道：“你是什么意思？”"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"if something such as an engine or a fire sputters, it makes short soft uneven noises like very small explosions","cn":"发出噼噼啪啪声﹐毕毕剥剥作响"},{"en":"to talk quickly in short confused phrases, especially because you are angry or shocked","cn":"急促而慌乱地说﹐语无伦次地说〔尤因气愤或震惊〕"}]},"media":{"uk":"media/ldoce/hwd/bre/b/sputter0205.mp3","us":"media/ldoce/hwd/ame/e/sputter.mp3"},"examples":[{"en":"‘W-What?’ sputtered Anna. “","cn":"什 … 什么？”安娜气急败坏地说。"},{"en":"sputtering fireworks","cn":"劈啪作响的烟火"}],"oxford":{"phon":"ˈspʌtə(r)","pos":"verb","senses":[{"en":"if an engine, a lamp or a fire sputters, it makes a series of short explosive sounds","cn":"（发动机、灯或火）发出噼啪声","g":"[intransitive]","ex":{"en":"Suddenly the car sputtered and stopped.","cn":"突然，车子吱呀一声停了下来。"}},{"en":"to speak quickly and with difficulty, making soft spitting sounds, because you are angry or shocked","cn":"气急败坏地说；急促而语无伦次地说","g":"[transitive]","ex":{"en":"‘W-What?’ sputtered Anna.","cn":"“什…什么？”安娜气急败坏地说。"}}]}},"specify":{"collins":{"senses":[{"pos":"VERB 动词","cn":"明确说明;具体指定","en":"If you specify something, you give information about what is required or should happen in a certain situation.","ex":{"en":"They specified a spacious entrance hall","cn":"他们专门指定要一个宽敞的大门厅。"}},{"pos":"VERB 动词","cn":"具体说明（或规定）","en":"If you specify what should happen or be done, you explain it in an exact and detailed way.","ex":{"en":"Each recipe specifies the size of egg to be used","cn":"每种菜谱都具体规定了所用鸡蛋的大小。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"a detailed description, explanation, picture etc contains a lot of details","cn":""},{"en":"if you discuss or consider something in detail , you discuss or consider all the details","cn":""},{"en":"carefully produced and full of details","cn":""}]},"vocab":{"pos":"v","senses":[{"en":"To explicitly name something or state a particular detail, you specify that thing. So, when you have a craving for dessert and you send someone to the store to buy ice cream, you may want to specify a flavor."}]},"collocations":{"phrases":["ADV. clearly | fully | carefully | exactly, precisely She did not specify precisely how many people were involved in the incident. | explici","VERB + SPECIFY allow sb to | require sb to | be used to | be possible to It should be possible to specify the range of values of x which wou"]},"media":{"uk":"media/ldoce/hwd/bre/f/specify0205.mp3","us":"media/ldoce/hwd/ame/b/specify.mp3"},"examples":[{"en":"The regulations specify that calculators may not be used in the examination.","cn":"考试规则明确规定考试时不得使用计算器。"},{"en":"Remember to specify your size when ordering clothes.","cn":"订购服装时记着要详细说明你要的号码。"}],"oxford":{"phon":"ˈspesɪfaɪ","pos":"verb","senses":[{"en":"to state something, especially by giving an exact measurement, time, exact instructions, etc.","cn":"具体说明；明确规定；详述；详列","ex":{"en":"Remember to specify your size when ordering clothes.","cn":"订购衣服时记着要注明你的尺码。"}}]}},"spaghetti":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"意大利式细面条","en":"Spaghetti is a type of pasta. It looks like long pieces of string and is usually served with a sauce."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a type of pasta in very long thin pieces, that is cooked in boiling water","cn":"意大利粉﹐意大利面条"}]},"vocab":{"pos":"n","senses":[{"en":"Spaghetti is long, thin pasta. Spaghetti with meatballs in marinara sauce is an Italian restaurant classic."}]},"collocations":{"phrases":["ADJ. wholemeal","QUANT. strand","VERB + SPAGHETTI eat, have | cook | drain, strain Drain the spaghetti well.","SPAGHETTI + NOUN sauce •"]},"media":{"img":["media/ldoce/img/spaghetti.jpg"],"uk":"media/ldoce/hwd/bre/a/spaghetti0205.mp3","us":"media/ldoce/hwd/ame/d/spaghetti.mp3"},"oxford":{"phon":"spəˈɡeti","pos":"noun","senses":[{"en":"pasta in the shape of long thin pieces that look like string when they are cooked","cn":"意大利细面条","ex":{"en":"Drain the spaghetti well.","cn":"把意大利面中的水沥干。"}}]}},"spousal":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"婚姻的","en":"Spousal rights and duties are ones which you gain if you are married."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the man/woman you are married to","cn":""},{"en":"the person you live with and have a sexual relationship with. Partner is often used when people are not married, or when you do not know if they are married. It is also used when talking about same-sex couples","cn":""},{"en":"the man/woman you are engaged to","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/3/spouse0205.mp3","us":"media/ldoce/hwd/ame/4/spouse.mp3"},"examples":[{"en":"( formal ) spousal consent","cn":"配偶的同意"},{"en":"spousal abuse","cn":"虐待配偶"}],"oxford":{"phon":"ˈspaʊzl","pos":"adjective","senses":[{"en":"connected with a husband or wife; of or from a husband or wife","cn":"配偶的；夫或妻的","ex":{"en":"spousal consent","cn":"配偶的同意"}}]}},"speedy":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"快的;迅速的","en":"A speedy process, event, or action happens or is done very quickly.","ex":{"en":"We wish Bill a speedy recovery","cn":"我们祝愿比尔快快康复。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"moving or able to move quickly","cn":""},{"en":"moving fast or doing something in a short time","cn":""},{"en":"designed to travel or operate very quickly","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"Speedy means super fast! If you're a speedy driver, you keep your foot on the gas pedal and zip by all the slowpokes. Speedy is also the nickname for a cartoon who is “the fastest mouse in Mexico.”"}]},"media":{"uk":"media/ldoce/hwd/bre/6/speedy0205.mp3","us":"media/ldoce/hwd/ame/0/speedy.mp3"},"examples":[{"en":"All enquiries will be dealt with as speedily as possible.","cn":"所有询问都将从速处理。"},{"en":"We wish you a speedy recovery (= from an illness or injury).","cn":"我们祝愿你早日康复。"}],"oxford":{"phon":"ˈspiːdi","pos":"adjective","senses":[{"en":"happening or done quickly or without delay","cn":"迅速的；尽快的","ex":{"en":"We wish you a speedy recovery (= from an illness or injury).","cn":"我们祝愿你早日康复。"}},{"en":"moving or working very quickly","cn":"快速的；高速的","ex":{"en":"speedy computers","cn":"高速计算机"}}]}},"spillover":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"伴随的结果(或影响)","en":"A spillover is a situation or feeling that starts in one place but then begins to happen or have an effect somewhere else.","ex":{"en":"Some jobs are quite likely to have a negative spillover into family life","cn":"有些工作很可能会对家庭生活产生不良影响。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the effect that one situation or problem has on another situation 〔","cn":"某一情况或问题所造成的〕影响﹐结果"}]},"media":{"uk":"media/ldoce/hwd/bre/c/ld41spillover.mp3","us":"media/ldoce/hwd/ame/a/laadspillover.mp3"},"examples":[{"en":"A second room was needed for the spillover of staff and reporters.","cn":"还需要一个房间给没有安置的员工和记者。"},{"en":"Not all of the violence in Miami was spillover from the trial.","cn":"迈阿密的暴力事件并非全是那次审判引起的。"}],"oxford":{"phon":"ˈspɪləʊvə(r)","pos":"noun","senses":[{"en":"something that is too large or too much for the place where it starts, and spreads to other places","cn":"容纳不下的部分；溢出部分","ex":{"en":"A second room was needed for the spillover of staff and reporters.","cn":"还需要一个房间给没有安置的员工和记者。"}},{"en":"the results or the effects of something that have spread to other situations or places","cn":"影响","ex":{"en":"The developments in the town will create spillovers for neighbouring regions.","cn":"该镇的发展将为周边地区带来溢出效应。"}}]}},"spectrum":{"collins":{"senses":[{"pos":"N-SING 单数名词","cn":"光谱","en":"The spectrum is the range of different colours which is produced when light passes through a glass prism or through a drop of water. A rainbow shows the colours in the spectrum."},{"pos":"N-COUNT 可数名词","cn":"系列;范围","en":"A spectrum is a range of a particular type of thing.","ex":{"en":"She'd seen his moods range across the emotional spectrum","cn":"她见识过他的情绪波动会有多大。"}},{"pos":"N-COUNT 可数名词","cn":"波谱(如光波波谱、无线电波波谱等)","en":"A spectrum is a range of light waves or radio waves within particular frequencies.","ex":{"en":"Vast amounts of energy, from X-rays right through the spectrum down to radio waves, are escaping into space","cn":"大量的能量，从 X 光直到无线电电波，都正被泄露到太空中去。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a set of many different things of the same general type that are available in the same place for the same use","cn":""},{"en":"a complete range of different types of things or people, especially when those at one end of the range are the opposite of those at the other end","cn":""},{"en":"a number of different things of the same kind that are available for you to choose or use","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"A spectrum is a broad range of similar things or qualities. Like the wide spectrum of political beliefs in this country, ranging anywhere from super conservative to uber-liberal and everything in between."}]},"collocations":{"phrases":["ADJ. visible Beyond the red end of the visible light spectrum is infrared. | continuous a continuous spectrum of light waves | colour, elect","SPECTRUM + NOUN analysis","PHRASES the colours of the spectrum Other species can perceive colours of the spectrum that are invisible to us. | the &hellip; band/end/par","ADJ. complete, full The courses cover the full spectrum of levels. | broad, wide | narrow | entire, whole | political, social","VERB + SPECTRUM cover","PREP. across the ~ There was consensus across the political spectrum. | ~ of a wide spectrum of interests","PHRASES at one/the other end of the spectrum, both/opposite ends of the spectrum The two speakers were chosen to represent opposite ends of "]},"media":{"uk":"media/ldoce/hwd/bre/5/spectrum0205.mp3","us":"media/ldoce/hwd/ame/f/spectrum.mp3"},"examples":[{"en":"We shall hear views from across the political spectrum.","cn":"我们要听取各个政治派别的看法。"},{"en":"A spectrum is formed by a ray of light passing through a prism.","cn":"一束光通过棱镜就会形成光谱。"}],"oxford":{"phon":"ˈspektrəm","pos":"noun","senses":[{"en":"a band of coloured lights in order of their wavelengths, as seen in a rainbow and into which light may be separated","cn":"谱；光谱","ex":{"en":"A spectrum is formed by a ray of light passing through a prism.","cn":"一束光通过棱镜就会形成光谱。"}},{"en":"a range of sound waves or several other types of wave","cn":"声谱；波谱；频谱","ex":{"en":"the electromagnetic/radio/sound spectrum","cn":"电磁波谱；射频频谱；声谱"}},{"en":"a complete or wide range of related qualities, ideas, etc.","cn":"范围；各层次；系列；幅度","g":"[usually singular]","ex":{"en":"a broad spectrum of interests","cn":"广泛的兴趣"}}]}},"spacesuit":{"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a special protective suit that people wear in space, that covers the whole body and provides a supply of air","cn":"航天服﹐宇航服"}]},"media":{"uk":"media/ldoce/hwd/bre/f/ld41spacesuit.mp3","us":"media/ldoce/hwd/ame/f/spacesuit.mp3"},"oxford":{"phon":"ˈspeɪssuːt","pos":"noun","senses":[{"en":"a special suit that covers the whole body and has a supply of air, allowing somebody to survive and move around in space","cn":"航天服；宇航服"}]}},"spasmodic":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"间歇的;一阵阵的","en":"Something that is spasmodic happens suddenly, for short periods of time, and at irregular intervals.","ex":{"en":"He managed to stifle the spasmodic sobs of panic rising in his throat","cn":"他惊慌得差一点哭了起来，不过还是竭力地克制住了。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"happening for short irregular periods, not continuously","cn":"间歇的﹐一阵阵的﹐断断续续的"},{"en":"of or relating to a muscle spasm","cn":"痉挛性的﹐抽搐的"}]},"vocab":{"pos":"adj","senses":[{"en":"Something that is spasmodic is experiencing a fit, a loss of muscular control. If you are spazzing out, you are spasmodic ."}]},"media":{"uk":"media/ldoce/hwd/bre/d/spasmodic0205.mp3","us":"media/ldoce/hwd/ame/8/spasmodic.mp3"},"examples":[{"en":"There was spasmodic fighting in the area yesterday.","cn":"昨天，那一地区发生过零星的战斗。"},{"en":"spasmodic movements","cn":"痉挛性动作"}],"oxford":{"phon":"spæzˈmɒdɪk","pos":"adjective","senses":[{"en":"happening suddenly for short periods of time; not regular or continuous","cn":"一阵阵的；阵发性的；断断续续的","ex":{"en":"a spasmodic interest in politics","cn":"对政治的间歇性兴趣"}},{"en":"caused by your muscles becoming tight in a way that you cannot control","cn":"痉挛（性）的","lab":"specialist","ex":{"en":"spasmodic movements","cn":"痉挛性动作"}}]}},"spicy":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(食物)加了很多香料的，辛辣的","en":"Spicy food is strongly flavoured with spices.","ex":{"en":"Thai food is hot and spicy.","cn":"泰国菜味道辛辣浓烈。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"having a very good taste","cn":""},{"en":"having a very bad taste","cn":""},{"en":"tasting full of sugar","cn":""}]},"collocations":{"phrases":["VERBS be, smell, taste The soup tasted mildly spicy.","ADV. really, very | lightly, mildly, quite, slightly | deliciously a deliciously spicy flavour"]},"media":{"uk":"media/ldoce/hwd/bre/7/spicy0205.mp3","us":"media/ldoce/hwd/ame/0/spicy.mp3"},"examples":[{"en":"a spicy tomato sauce","cn":"辣番茄酱"}],"oxford":{"phon":"ˈspaɪsi","pos":"adjective","senses":[{"en":"having a strong taste because spices have been added to it","cn":"加有香料的；用香料调味的","ex":{"en":"I don't like spicy food.","cn":"我不喜欢味道重的食物。"}},{"en":"exciting and making you feel slightly shocked","cn":"刺激的；耸人听闻的","lab":"informal","ex":{"en":"spicy stories about the sex lives of the stars","cn":"关于明星性生活的辛辣故事"}}]}},"spurt":{"collins":{"senses":[{"pos":"V-ERG 及物/不及物动词","cn":"(使)喷射;(使)喷发","en":"When liquid or fire spurts from somewhere, or when something spurts liquid or fire, it comes out quickly in a thin, powerful stream.","ex":{"en":"They spurted blood all over me. I nearly passed out","cn":"他们的血喷了我一身。我几乎昏了过去。"}},{"pos":"N-COUNT 可数名词","cn":"(喷射出的)一股","en":"A spurt of liquid is a stream of it which comes out of something very forcefully.","ex":{"en":"A spurt of diesel came from one valve and none from the other.","cn":"一股柴油从一个阀门中喷射出来，另一个阀门中则没有喷出任何东西。"}},{"pos":"N-COUNT 可数名词","cn":"(行动、努力、感情的)迸发","en":"A spurt of activity, effort, or emotion is a sudden, brief period of intense activity, effort, or emotion.","ex":{"en":"At adolescence, muscles go through a growth spurt","cn":"在青春期，肌肉会迅猛发育。"}},{"pos":"VERB 动词","cn":"突然加速前进;冲刺","en":"If someone or something spurts somewhere, they suddenly increase their speed for a short while in order to get there.","ex":{"en":"The back wheels spun and the van spurted up the last few feet.","cn":"后轮突然转动起来，货车加速冲过了最后几英尺距离。"}},{"pos":"PHRASE 短语","cn":"时有时无;一阵一阵地","en":"If something happens in spurts, there are periods of activity followed by periods in which it does not happen.","ex":{"en":"The deals came in spurts: three in 1977, none in 1978, three more in 1979.","cn":"交易时有时无：1977 年有 3 笔，1978 年没有，1979 年又有 3 笔。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"if liquid flows, it moves in a steady continuous stream","cn":""},{"en":"to flow – used when saying that something flows in a particular direction","cn":""},{"en":"to flow out of something","cn":""}]},"collocations":{"phrases":["ADJ. sudden | great A great spurt of blood came out of the wound. | brief, little | final | growth","VERB + SPURT put on She put on a spurt to get to the station in time. | feel He felt a spurt of resentment against his brother.","PREP. with a ~ With one final spurt, he reached the top of the hill. | ~ in a spurt in capital spending | ~ of"]},"media":{"uk":"media/ldoce/hwd/bre/f/spurt_n0205.mp3","us":"media/ldoce/hwd/ame/6/spurt1.mp3"},"examples":[{"en":"You'd better put on a spurt (= hurry up) if you want to finish that work today.","cn":"你要是想今天完成那项工作，最好狠加一把劲。"},{"en":"The volcano spurted clouds of steam and ash high into the air.","cn":"火山把团团热气和灰尘喷向高空。"}],"oxford":{"phon":"spɜːt","pos":"verb","senses":[{"en":"to burst out or pour out suddenly; to produce sudden, powerful streams of liquid or flames","cn":"喷出；冒出","g":"[intransitive, transitive]","ex":{"en":"Blood was spurting from her nose.","cn":"血从她鼻子里汩汩流出来。"}},{"en":"to increase your speed for a short time to get somewhere faster","cn":"（短暂地）加速前进；冲刺","g":"[intransitive]","ex":{"en":"She spurted past me to get to the line first.","cn":"她冲刺超过我，率先抵达终点线。"}},{"en":"an amount of liquid or flames that comes out of somewhere with great force","cn":"涌出的液体；喷出的火舌","ex":{"en":"a great spurt of blood","cn":"一大股急速喷出的血"},"pos":"noun"},{"en":"a sudden increase in speed, effort, activity or emotion for a short period of time","cn":"（速度、干劲、活动或感情的）短时间激增，迸发","ex":{"en":"You'd better put on a spurt (= hurry up) if you want to finish that work today.","cn":"你要是想今天完成那项工作，最好狠加一把劲。"},"pos":"noun"}]}},"spender":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"花钱者；花钱…的人","en":"If a person or organization is a big spender or a compulsive spender, for example, they spend a lot of money or are unable to stop themselves spending money.","ex":{"en":"The Swiss are Europe's biggest spenders on food","cn":"瑞士人是欧洲人中在食品上开销最大的人群。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"spending more money than you can afford on expensive things that you do not really need","cn":""},{"en":"someone who spends money carelessly even when they know that they do cannot afford to","cn":""},{"en":"a rich person who spends a lot of money, especially in order to impress other people","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/b/ld41spender.mp3","us":"media/ldoce/hwd/ame/f/spender.mp3"},"examples":[{"en":"a big spender (= who spends a lot of money)","cn":"花钱大手大脚的人"},{"en":"The new casino hopes to attract big spenders (= people who spend a lot of money ) .","cn":"这家新开的赌场希望能够吸引大豪客前来。"}],"oxford":{"phon":"ˈspendə(r)","pos":"noun","senses":[{"en":"a person who spends money in the particular way mentioned","cn":"花钱…的人","ex":{"en":"a big spender (= who spends a lot of money)","cn":"花钱大手大脚的人"}}]}},"spam":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"斯帕姆午餐肉","en":"Spam is a cooked meat product made from pork and ham."},{"pos":"VERB 动词","cn":"向…群发垃圾邮件","en":"In computing, to spam people or organizations means to send unwanted e-mails to a large number of them, usually as advertising.","ex":{"en":"...programs that let you spam the newspapers.","cn":"使您能够向各家报纸群发垃圾邮件的程序"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to send the same message to many different people using email or the Internet, usually as a way of advertising something – used to show disapproval 〔","cn":"在网上〕滥发（垃圾电子邮件）〔含贬义〕"},{"en":"an advertisement","cn":""},{"en":"an advertisement","cn":""}]},"vocab":{"pos":"n v","senses":[{"en":"There are few things more annoying than an email in-box full of spam . Spam is unwanted Internet advertising that's sent to a huge number of people at a time."}]},"media":{"uk":"media/ldoce/hwd/bre/8/spam_v0205.mp3","us":"media/ldoce/hwd/ame/a/spam.mp3"},"examples":[{"en":"You can filter out spam with special software.","cn":"你可以使用专门的软件过滤掉垃圾电子邮件。"}],"oxford":{"phon":"spæm","pos":"noun","senses":[{"en":"advertising material sent by email to people who have not asked for it; advertising material on the internet that is not wanted","cn":"滥发的电邮；垃圾电邮","lab":"informal, disapproving，，","ex":{"en":"to send/block spam","cn":"发送／拦截垃圾电邮"}},{"en":"cooked meat that has been cut up in very small pieces that are pressed together in a container, usually sold in cans and served cold in slices","cn":"世棒午餐肉"},{"en":"to send the same message to large numbers of internet users who have not requested the information","cn":"滥发（电子信息）；发垃圾邮件","ex":{"en":"Some companies will keep spamming you until you change your email address.","cn":"有些公司会不停地给你发垃圾电邮，直到你换了电邮地址。"},"pos":"verb"}]}},"spruce":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"云杉;花旗松","en":"A spruce is a kind of evergreen tree.","ex":{"en":"Trees such as spruce, pine and oak have been planted.","cn":"种植了云杉、松树和橡树等树木。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(人)整洁漂亮的","en":"Someone who is spruce is very neat and smart in appearance.","ex":{"en":"Chris was looking spruce in his stiff-collared black shirt and new short hair cut.","cn":"克里斯穿着硬领黑衫，新理了短发，看起来整洁帅气。"}},{"pos":"","cn":"","en":"相关词组：spruce up"}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a tree that grows in northern countries and has short leaves shaped like needles","cn":"云杉"},{"en":"to clean yourself with soap and water","cn":""},{"en":"to wash your hands and face","cn":""}]},"vocab":{"pos":"1 n 2 adj v","senses":[{"en":"Spruce is a verb that means you pay special attention to your personal appearance, especially your grooming and clothing. If you want to spruce up for a wedding, you'll need to rent a tuxedo and do something with your hair."}]},"media":{"uk":"media/ldoce/hwd/bre/e/spruce_n0205.mp3","us":"media/ldoce/hwd/ame/8/spruce1.mp3"},"examples":[{"en":"The city is sprucing up its museums and galleries.","cn":"这座城市正在美化自己的博物馆和美术馆。"},{"en":"She spruced up for the interview.","cn":"她为参加面试打扮了一番。"}],"oxford":{"phon":"spruːs","pos":"noun","senses":[{"en":"an evergreen forest tree with leaves like needles","cn":"云杉","g":"[countable, uncountable]"},{"en":"the soft wood of the spruce, used, for example, in making paper","cn":"云杉木","g":"[uncountable]"},{"en":"neat and clean in appearance","cn":"整洁的","pos":"adjective"}]}},"spermatozoon":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"精子","en":"A spermatozoon is a sperm."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a sperm","cn":"精子"}]},"media":{"uk":"media/ldoce/hwd/bre/e/spermatozoon0205.mp3","us":"media/ldoce/hwd/ame/a/laadspermatozoon.mp3"},"oxford":{"phon":"ˌspɜːmətəˈzəʊən","pos":"noun","senses":[{"en":"a sperm","cn":"精子"}]}},"sporadic":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"间断发生的;零星的","en":"Sporadic occurrences of something happen at irregular intervals.","ex":{"en":"...a year of sporadic fighting over northern France","cn":"法国北部发生零星战斗的一年"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"sometimes, but not very often and not regularly","cn":""},{"en":"if you do something on and off or off and on during a long period, you do it for short periods but not regularly","cn":""},{"en":"repeatedly starting and stopping, but not regularly and never for more than a short time","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"Sporadic is an adjective that you can use to refer to something that happens or appears often, but not constantly or regularly. The mailman comes every day but the plumber visits are sporadic ––he comes as needed."}]},"media":{"uk":"media/ldoce/hwd/bre/2/sporadic0205.mp3","us":"media/ldoce/hwd/ame/6/sporadic.mp3"},"examples":[{"en":"sporadic fighting/gunfire/violence, etc.","cn":"零星的战斗、一阵一阵的炮火、间或发生的暴力事件等"},{"en":"Fighting continued sporadically for two months.","cn":"战斗断断续续地进行了两个月。"}],"oxford":{"phon":"spəˈrædɪk","pos":"adjective","senses":[{"en":"happening only occasionally or at intervals that are not regular","cn":"偶尔发生的；间或出现的；阵发性的；断断续续的","ex":{"en":"sporadic fighting/gunfire/violence","cn":"零星的战斗；阵阵炮火；间或发生的暴力事件"}}]}},"speculator":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"投机者;投机商","en":"A speculator is a person who speculates financially."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone who buys goods, property, share s in a company etc, hoping that they will make a large profit when they sell them","cn":"投机者"}]},"media":{"uk":"media/ldoce/hwd/bre/0/ld41speculator.mp3","us":"media/ldoce/hwd/ame/0/ld41speculator.mp3"},"examples":[{"en":"property speculators","cn":"房地产投机商"},{"en":"a New York property speculator","cn":"纽约的一名房地产投机者"}],"oxford":{"phon":"ˈspekjuleɪtə(r)","pos":"noun","senses":[{"en":"a person who buys and sells goods or shares in a company in the hope of making a profit","cn":"投机商；投机倒把者","ex":{"en":"property speculators","cn":"房地产投机商"}}]}},"splenetic":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"脾气坏的;易怒的","en":"If you describe someone as splenetic, you mean that they easily become very angry about things.","ex":{"en":"...retired military men with splenetic opinions.","cn":"满腹怨言的退伍军人"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"bad-tempered and often angry","cn":"脾气坏的﹐易怒的"}]},"media":{"uk":"media/ldoce/hwd/bre/0/ld41splenetic.mp3","us":"media/ldoce/hwd/ame/a/splenetic.mp3"},"oxford":{"phon":"spləˈnetɪk","pos":"adjective","senses":[{"en":"often annoyed and angry","cn":"易怒的"}]}},"spokeswoman":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"女发言人","en":"A spokeswoman is a female spokesperson.","ex":{"en":"A United Nations spokeswoman in New York said the request would be considered.","cn":"联合国的一名女发言人在纽约说，该要求会得到考虑。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone who has been chosen to represent an organization or country","cn":""},{"en":"a person who officially gives the opinions of an organization, company, government etc","cn":""},{"en":"a word meaning spokesman or spokeswoman , used especially when you do not want to say whether the person is a man or a woman","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/6/spokeswoman0205.mp3","us":"media/ldoce/hwd/ame/4/laadspokeswoman.mp3"},"oxford":{"phon":"ˈspəʊkswʊmən","pos":"noun","senses":[{"en":"a woman who speaks for a group or an organization","cn":"女发言人","lab":"British English","ex":{"en":"a government spokeswoman","cn":"政府发言人"}}]}},"spectral":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"鬼怪(似)的;幽灵(似)的","en":"If you describe someone or something as spectral, you mean that they look like a ghost.","ex":{"en":"She is compelling, spectral, fascinating, an unforgettably unique performer.","cn":"她极具吸引力，清幽如鬼魅，令人着迷，令人难忘，是个独具特色的演员。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"relating to or like a spectre","cn":"鬼魂的﹔幽灵般的"},{"en":"relating to or made by a spectrum","cn":"光谱的﹔由光谱做的"}]},"vocab":{"pos":"1 adj 2 adj","senses":[{"en":"When something is spectral , it has a ghostlike quality; it seems to vanish or disappear. You may have heard of ghosts referred to as \"specters\": that means that they're spectral ."}]},"media":{"uk":"media/ldoce/hwd/bre/8/ld41spectral.mp3","us":"media/ldoce/hwd/ame/2/spectral.mp3"},"examples":[{"en":"spectral bands","cn":"光谱带"}],"oxford":{"phon":"ˈspektrəl","pos":"adjective","senses":[{"en":"like a ghost; connected with a ghost","cn":"鬼一般的；幽灵似的；鬼的；幽灵的","lab":"literary","ex":{"en":"a spectral figure","cn":"鬼影"}},{"en":"connected with a spectrum","cn":"谱的；光谱的；频谱的","lab":"specialist","ex":{"en":"spectral bands","cn":"光谱带"}}]}},"spreadsheet":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"电子制表程序(主要用于制定财务计划)","en":"A spreadsheet is a computer program that is used for displaying and dealing with numbers. Spreadsheets are used mainly for financial planning."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a computer program that can show and calculate financial information","cn":"电子表格程序〔一种能显示和计算财务数据的计算机程序〕"},{"en":"a document that contains rows and column s of numbers that can be used to calculate something","cn":"电子表格﹐试算表"}]},"media":{"uk":"media/ldoce/hwd/bre/2/spreadsheet0205.mp3","us":"media/ldoce/hwd/ame/b/spreadsheet.mp3"},"oxford":{"phon":"ˈspredʃiːt","pos":"noun","senses":[{"en":"a computer program that is used, for example, when doing financial or project planning. You enter data in rows and columns and the program calculates costs, etc. from it. The individual documents are also called spreadsheets.","cn":"（计算机）电子表格程序，电子表格","ex":{"en":"I created a spreadsheet to calculate my expenses.","cn":"我创建了一份电子表格来计算支出。"}}]}},"splotch":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(尤指某种液体的)大块污渍，大斑块","en":"A splotch is a large uneven mark or stain, especially one that has been caused by a liquid."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a splodge","cn":"斑块﹐污渍"}]},"media":{"uk":"media/ldoce/hwd/bre/8/splotch0205.mp3","us":"media/ldoce/hwd/ame/5/splotch.mp3"}},"spaceman":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"太空人(主要为儿童用语)","en":"A spaceman is a male astronaut; used mainly by children."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a man who travels into space","cn":"宇航员﹐航天员"},{"en":"someone in stories who visits the Earth from another world 〔","cn":"小说中的〕外星人"}]},"media":{"uk":"media/ldoce/hwd/bre/4/ld41spaceman.mp3","us":"media/ldoce/hwd/ame/1/spaceman.mp3"},"oxford":{"phon":"ˈspeɪsmæn","pos":"noun","senses":[{"en":"a man who travels into space; an astronaut","cn":"宇航员；航天员","lab":"informal"},{"en":"(in stories) a creature that visits the earth from another planet","cn":"（小说中的）外星人"}]}},"spiv":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(无固定职业而)靠诈骗过日子的人;黑市商人","en":"A spiv is a man who does not have a regular job and who makes money by business deals which are usually illegal."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a man who gets money from small dishonest business deals","cn":"靠诈骗过日子的人"}]},"media":{"uk":"media/ldoce/hwd/bre/6/ld41spiv.mp3","us":"media/ldoce/hwd/ame/6/ld41spiv.mp3"},"oxford":{"phon":"spɪv","pos":"noun","senses":[{"en":"a man who makes his money by being dishonest in business, especially one who dresses in a way that makes people believe he is rich and successful","cn":"衣冠楚楚的奸商"}]}},"spec":{"collins":{"senses":[{"pos":"N-PLURAL 复数名词","cn":"眼镜","en":"Someone's specs are their glasses.","ex":{"en":"...a young businessman in his specs and suit.","cn":"一个戴眼镜、穿西装的年轻商务人士"}},{"pos":"N-COUNT 可数名词","cn":"(尤指机器、车辆的)规格，配置","en":"The spec for something, especially a machine or vehicle, is its design and the features included in it.","ex":{"en":"The standard spec includes stainless steel holding tanks.","cn":"标准配置里包含了不锈钢储液罐。"}},{"pos":"PHRASE 短语","cn":"碰运气","en":"If you do something on spec, you do it hoping to get something that you want, but without being asked or without being certain to get it.","ex":{"en":"When searching for a job Adrian favours networking and writing letters on spec.","cn":"找工作的时候，阿德里安喜欢通过上网和写信去碰运气。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a detailed instruction about how a building, car, piece of equipment etc should be made 〔","cn":"制造房子﹑汽车﹑设备等的〕规格说明"},{"en":"if you do something on spec, you do it without being sure that you will get what you are hoping for","cn":"碰运气"},{"en":"glasses that help you see","cn":"眼镜"}]},"media":{"uk":"media/ldoce/hwd/bre/0/ld41spec.mp3","us":"media/ldoce/hwd/ame/e/spec.mp3"},"examples":[{"en":"We want the machine manufactured to our own spec.","cn":"我们要求这台机器按我们自己的规格来制造。"},{"en":"The camera is well specced at the price.","cn":"就价钱来说，这台照相机的配置很不错。"}],"oxford":{"phon":"spek","pos":"noun","senses":[{"en":"a detailed description of something, especially the design and materials needed to produce something","cn":"规格","ex":{"en":"We want the machine manufactured to our own spec.","cn":"我们要求这台机器按我们自己的规格来制造。"}},{"en":"to design and make something to a particular standard","cn":"按特定标准设计并制造","ex":{"en":"The camera is well specced for the price.","cn":"就价钱来说，这台照相机的配置很不错。"},"pos":"verb"}]}},"sprawl":{"collins":{"senses":[{"pos":"VERB 动词","cn":"(懒洋洋地)伸开四肢坐着(或躺着)","en":"If you sprawl somewhere, you sit or lie down with your legs and arms spread out in a careless way.","ex":{"en":"She sprawled on the bed as he had left her, not even moving to cover herself up","cn":"他离开她后她就摊手摊脚地躺在床上，甚至都懒得往身上盖点儿东西。"}},{"pos":"VERB 动词","cn":"扩展;延伸","en":"If you say that a place sprawls, you mean that it covers a large area of land.","ex":{"en":"The State Recreation Area sprawls over 900 acres on the southern tip of Key Biscayne","cn":"州立休闲区在比斯坎岛南端，占地 900 多英亩。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"(城市的)杂乱无章地扩展的地区","en":"You can use sprawl to refer to an area where a city has grown outwards in an uncontrolled way.","ex":{"en":"The whole urban sprawl of Ankara contains over 2.6m people.","cn":"安卡拉整个肆意扩展的城区容纳了 260 多万人口。"}},{"pos":"VERB 动词","cn":"肆意扩展;杂乱无章地延伸","en":"If something sprawls, its structure is disorganized or it lacks direction.","ex":{"en":"Boylan plays with language, letting the prose sprawl about before tightening it suddenly to great effect","cn":"博伊兰随心所欲地驾驭着语言，先是任文章自由铺展，然后猛地收住，产生了绝好的效果。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to put yourself in a flat position on a surface such as a bed, especially in order to relax or to go to sleep","cn":""},{"en":"to put yourself in a flat position on a surface","cn":""},{"en":"to lie with your body and legs straight so that you can relax","cn":""}]},"vocab":{"pos":"v n","senses":[{"en":"When you sprawl, you spread out in an ungainly way, like when you're lying down comfortably on the sofa with your legs and arms flung out around you."}]},"collocations":{"phrases":["ADV. untidily | out He was sprawled out on the sofa.","PREP. across, in, on, over She sprawled untidily in an armchair.","PHRASES lie/sit sprawled She lay sprawled across the bed. | send sb sprawling The blow sent him sprawling."]},"media":{"img":["media/ldoce/img/ldoce_311.png"],"uk":"media/ldoce/hwd/bre/4/sprawl_v0205.mp3","us":"media/ldoce/hwd/ame/e/sprawl1.mp3"},"examples":[{"en":"He was sprawling in an armchair in front of the TV.","cn":"他伸开手脚坐在电视机前的一张扶手椅上。"},{"en":"Something hit her and sent her sprawling to the ground.","cn":"不知什么东西击中了她，把她打趴在地上。"}],"oxford":{"phon":"sprɔːl","pos":"verb","senses":[{"en":"to sit, lie or fall with your arms and legs spread out in a relaxed or careless way","cn":"伸开四肢坐（或躺）；手脚伸开摔倒","g":"[intransitive]","ex":{"en":"He was sprawling in an armchair in front of the TV.","cn":"他伸开手脚坐在电视机前的一张扶手椅上。"}},{"en":"to spread in an untidy way; to cover a large area","cn":"蔓延；杂乱无序地拓展","g":"[intransitive]","ex":{"en":"The town sprawled along the side of the lake.","cn":"小镇顺着湖的边缘扩展。"}},{"en":"a large area covered with buildings that spreads from the city into the countryside in an ugly way","cn":"（城市）杂乱无序拓展的地区","ex":{"en":"attempts to control the fast-growing urban sprawl","cn":"为控制城市过快过乱的拓展所作的努力"},"pos":"noun"}]}},"spool":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"线轴;(录音带、胶卷的)卷轴","en":"A spool is a round object onto which thread, tape, or film can be wound, especially before it is put into a machine."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"an object shaped like a wheel that you wind thread, wire etc around 〔","cn":"线﹑电线等的〕线轴"}]},"media":{"img":["media/ldoce/img/spool.jpg"],"uk":"media/ldoce/hwd/bre/7/spool0205.mp3","us":"media/ldoce/hwd/ame/f/spool1.mp3"},"examples":[{"en":"a spool of thread","cn":"一轴线"}],"oxford":{"phon":"spuːl","pos":"noun","senses":[{"en":"a round object around which you wind such things as thread, wire or film; a reel together with the film, wire, thread, etc. that is wound around it","cn":"卷轴；卷盘；卷筒；一卷胶卷（或金属丝、线等）","ex":{"en":"a spool of thread","cn":"一轴线"}},{"en":"to wind something onto or off a spool","cn":"把…绕到线轴上（或从线轴上绕下来）","g":"[transitive]","pos":"verb"},{"en":"to move data and store it for a short time, for example on a disk, especially before it is printed","cn":"假脱机（尤指打印前出现的操作情况）","g":"[transitive, intransitive]","lab":"computing","pos":"verb"}]}},"spunky":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"勇敢的;有胆量的","en":"A spunky person shows courage.","ex":{"en":"...a spunky girl","cn":"勇敢的女孩"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"having a lot of courage, energy, or determination","cn":"勇敢坚定的﹔干劲十足的"}]},"vocab":{"pos":"adj","senses":[{"en":"A spunky person is someone who's high spirited and brave. The hero of a fairy tale is often described as spunky ."}]},"media":{"uk":"media/ldoce/hwd/bre/f/ld41spunky.mp3","us":"media/ldoce/hwd/ame/f/ld41spunky.mp3"},"examples":[{"en":"She is bright, tough and spunky.","cn":"她聪明、顽强而且干劲十足。"},{"en":"a top babe with a spunky boyfriend","cn":"有个性感男友的绝色女子"}],"oxford":{"phon":"ˈspʌŋki","pos":"adjective","senses":[{"en":"brave and determined; full of enthusiasm","cn":"勇敢坚定的；劲头十足的","ex":{"en":"She is bright, tough and spunky.","cn":"她聪明、顽强而且干劲十足。"}},{"en":"sexually attractive","cn":"性感的","lab":"Australian English, informal，，","ex":{"en":"a top babe with a spunky boyfriend","cn":"有个性感男友的绝色女子"}}]}},"sparse":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"稀少的;稀疏的","en":"Something that is sparse is small in number or amount and spread out over an area.","ex":{"en":"Many slopes are rock fields with sparse vegetation","cn":"许多山坡都是石头地，植被稀疏。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"a small number of people, things, places etc","cn":""},{"en":"a few people, things, places etc, especially when they are part of a much bigger number","cn":""},{"en":"a smaller number than you expected or wanted","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"Something that’s sparse is thin, not dense. If you’re looking for the perfect place to build a tree house, a sparse forest is probably not your best bet."}]},"media":{"uk":"media/ldoce/hwd/bre/4/sparse0205.mp3","us":"media/ldoce/hwd/ame/b/sparse.mp3"},"examples":[{"en":"Vegetation becomes sparse higher up the mountains.","cn":"山上越高的地方植物越稀少。"},{"en":"the sparse population of the islands","cn":"那些岛上零星的人口"}],"oxford":{"phon":"spɑːs","pos":"adjective","senses":[{"en":"only present in small amounts or numbers and often spread over a large area","cn":"稀少的；稀疏的；零落的","ex":{"en":"the sparse population of the islands","cn":"那些岛上零星的人口"}}]}},"sportsman":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"男运动员","en":"A sportsman is a man who takes part in sports."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone who takes part in a game or competition","cn":""},{"en":"someone who is competing, especially against a lot of people, in a particular game or competition","cn":""},{"en":"someone who takes part in a competition or game","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/b/sportsman0205.mp3","us":"media/ldoce/hwd/ame/2/sportsman.mp3"},"examples":[{"en":"He’s a very keen sportsman .","cn":"他是个非常喜爱运动的人。"},{"en":"a talented all-round sportsman","cn":"一名有天赋的全能运动员"}],"oxford":{"phon":"ˈspɔːtsmən","pos":"noun","senses":[{"en":"a man who plays a lot of sport, especially as a professional","cn":"运动员；体育运动爱好者；（尤指）职业运动员","lab":"British English","ex":{"en":"He is one of this country's top professional sportsmen.","cn":"他是该国顶级职业运动员之一。"}}]}},"spiky":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"有尖顶的；成锥形的","en":"Something that is spiky has one or more sharp points.","ex":{"en":"Her short spiky hair is damp with sweat.","cn":"她的刺头被汗打湿了。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"having a very thin edge or point that can cut things easily","cn":""},{"en":"having an irregular edge with a lot of sharp points","cn":""},{"en":"having a lot of thin sharp points","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/7/ld41spiky.mp3","us":"media/ldoce/hwd/ame/b/spiky.mp3","img":["media/thumb/spiky.jpg"]},"examples":[{"en":"spiky plants, such as cacti","cn":"带刺的植物，如仙人掌"},{"en":"short black spiky hair","cn":"一根根竖起的黑色短发"}],"oxford":{"phon":"ˈspaɪki","pos":"adjective","senses":[{"en":"having sharp points","cn":"有尖刺的","ex":{"en":"spiky plants, such as cacti","cn":"带刺的植物，如仙人掌"}},{"en":"sticking straight up from the head","cn":"刺猬式的","ex":{"en":"He had spiky hair, strong opinions and a wacky sense of humour.","cn":"他头发短硬，思想激进，开玩笑时显得疯疯癫癫的。"}},{"en":"easily annoyed or offended","cn":"易怒的；爱生气的","lab":"British English"}]}},"sprinter":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"短跑运动员;短程竞赛选手","en":"A sprinter is a person who takes part in short, fast races."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone who runs in fast races over short distances","cn":"短跑运动员"}]},"media":{"uk":"media/ldoce/hwd/bre/f/sprinter0205.mp3","us":"media/ldoce/hwd/ame/7/laadsprinter.mp3"},"oxford":{"phon":"ˈsprɪntə(r)","pos":"noun","senses":[{"en":"a person who runs, swims, etc. very fast over a short distance in a race","cn":"短跑比赛；短距离速度竞赛","ex":{"en":"Olympic sprinters","cn":"奥运会短跑运动员"}}]}},"sprout":{"collins":{"senses":[{"pos":"VERB 动词","cn":"(植物、蔬菜、种子)发芽，抽芽，长芽","en":"When plants, vegetables, or seeds sprout, they produce new shoots or leaves.","ex":{"en":"It only takes a few days for beans to sprout.","cn":"豆子只要几天就能发芽。"}},{"pos":"VERB 动词","cn":"(叶子、芽或植株)生长","en":"When leaves, shoots, or plants sprout somewhere, they grow there.","ex":{"en":"Leaf-shoots were beginning to sprout on the hawthorn","cn":"山楂树上开始长出叶芽。"}},{"pos":"VERB 动词","cn":"使生长","en":"If a garden or other area of land sprouts plants, they start to grow there.","ex":{"en":"...the garden, which had had time to sprout a shocking collection of weeds.","cn":"久而久之便野草丛生的花园"}},{"pos":"VERB 动词","cn":"(出于食用目的)使(豆子、种子等)发芽","en":"If you sprout beans or seeds, you make them grow small shoots before eating them. You usually do this by soaking them in water.","ex":{"en":"When you sprout seeds their nutritional content increases","cn":"让种子发芽后，其营养含量会提高。"}},{"pos":"V-ERG 及物/不及物动词","cn":"(毛发等)生长，长出","en":"If something such as hair sprouts from a person or animal, or if they sprout it, it grows on them.","ex":{"en":"She is very old now, with little, round, wire-rimmed glasses and whiskers sprouting from her chin","cn":"她现在很老了，戴着圆圆的金属架小眼镜，下巴上还长出了胡须。"}},{"pos":"V-ERG 及物/不及物动词","cn":"大量涌现;迅猛发展","en":"If a large number of things have appeared or developed somewhere, you can say that they have sprouted there or that the place has sprouted them.","ex":{"en":"More than a million satellite dishes have sprouted on homes across the country","cn":"100 多万个卫星接收器迅速出现在了全国各地的家庭用户中。"}},{"pos":"N-COUNT 可数名词","cn":"抱子甘蓝;球芽甘蓝","en":"Sprouts are vegetables that look like tiny cabbages. They are also called brussels sprouts ."},{"pos":"N-COUNT 可数名词","cn":"新芽;子苗;嫩枝","en":"Sprouts are new shoots on plants.","ex":{"en":"After eleven days of growth the number of sprouts was counted.","cn":"经过11天的生长后，对新芽的数量进行了计数。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"if vegetables, seeds, or plants sprout, they start to grow, producing shoot s , bud s , or leaves","cn":"发芽﹐抽芽﹔开始长出〔叶子〕"},{"en":"to appear suddenly in large numbers","cn":"突然大量出现﹐大量冒出"},{"en":"if something such as hair sprouts or if you sprout it, it starts to grow 〔","cn":"头发等〕开始长出﹔〔某人〕开始长〔毛发等〕"}]},"vocab":{"pos":"v n","senses":[{"en":"A sprout is a small growth on a plant — a little new bud. Other things can sprout too: kids are constantly sprouting (growing)."}]},"media":{"uk":"media/ldoce/hwd/bre/5/sprout_n0205.mp3","us":"media/ldoce/hwd/ame/2/sprout1.mp3"},"examples":[{"en":"The town has sprouted shopping malls, discos and nightclubs in recent years.","cn":"最近几年，城里涌现出不少购物中心、迪斯科舞厅和夜总会。"},{"en":"Tim has sprouted a beard since we last saw him.","cn":"我们上次见到蒂姆以后，蒂姆长出了胡子。"}],"oxford":{"phon":"spraʊt","pos":"verb","senses":[{"en":"to produce new leaves or buds; to start to grow","cn":"发芽；抽芽；抽条；生长","g":"[intransitive]","ex":{"en":"new leaves sprouting from the trees","cn":"树上长出的新叶"}},{"en":"to appear; to develop something, especially in large numbers","cn":"出现；（使）涌现出","g":"[intransitive, transitive]","ex":{"en":"Hundreds of mushrooms had sprouted up overnight.","cn":"一夜之间长出来好几百朵蘑菇。"}},{"en":"to start to grow something; to start to grow on somebody/something","cn":"长出（某物）；（某物）长出","g":"[transitive, intransitive]","ex":{"en":"Tim has sprouted a beard since we last saw him.","cn":"我们上次见到蒂姆以后，蒂姆长出了胡子。"}},{"en":"a small round green vegetable like a very small cabbage","cn":"汤菜；抱子甘蓝","pos":"noun"},{"en":"a new part growing on a plant","cn":"苗；新芽；嫩枝","pos":"noun"}]}},"spelunker":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"洞穴探险爱好者","en":"A spelunker is someone who goes into underground caves and tunnels as a leisure activity."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the sport of walking and climbing in cave s","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"A spelunker is an explorer of caves. If you hope to one day be a spelunker , you probably have a love of dark, damp spaces and headlamps."}]},"media":{"uk":"media/ldoce/hwd/bre/f/ld41spelunking.mp3","us":"media/ldoce/hwd/ame/f/ld41spelunking.mp3"},"oxford":{"phon":"spəˈlʌŋkə(r)","pos":"noun","senses":[{"en":"a person who goes into caves under the ground as a sport or hobby","cn":"探察洞穴者（以此为体育运动或业余爱好）"}]}},"splay":{"collins":{"senses":[{"pos":"V-ERG 及物/不及物动词","cn":"(使)(物体的多个末端)向外张开","en":"If things splay or are splayed, their ends are spread out away from each other.","ex":{"en":"He splayed his fingers across his face","cn":"他张开手指蒙住了脸。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to spread apart widely, or to make things do this, especially parts of the body （","cn":"使）张开﹐展开〔尤指身体部位〕"}]},"media":{"uk":"media/ldoce/hwd/bre/b/splay0205.mp3","us":"media/ldoce/hwd/ame/d/splay.mp3"},"examples":[{"en":"His long fingers splayed across her back.","cn":"他把长长的手指叉开贴在她背上。"},{"en":"She lay on the bed, her arms and legs splayed out.","cn":"她四肢摊开躺在床上。"}],"oxford":{"phon":"spleɪ","pos":"verb","senses":[{"en":"to make fingers, legs, etc. become further apart from each other or spread out; to be spread out wide apart","cn":"使（手指、腿等）叉开；使分开；张开；展开","ex":{"en":"She lay on the bed, her arms and legs splayed out.","cn":"她四肢摊开躺在床上。"}}]}},"spearmint":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"留兰香，绿薄荷(尤用作食物增甜剂)","en":"Spearmint is a plant whose leaves have a strong smell and taste. It is often used for flavouring foods, especially sweets."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a fresh mint taste, often used in sweets","cn":"留兰香（味）"},{"en":"a type of mint plant","cn":"留兰香（植物）"}]},"media":{"uk":"media/ldoce/hwd/bre/3/spearmint0205.mp3","us":"media/ldoce/hwd/ame/2/spearmint.mp3"},"examples":[{"en":"spearmint chewing gum","cn":"留兰香口香糖"}],"oxford":{"phon":"ˈspɪəmɪnt","pos":"noun","senses":[{"en":"a type of mint used especially in making sweets and toothpaste","cn":"留兰香；绿薄荷","ex":{"en":"spearmint chewing gum","cn":"留兰香口香糖"}}]}},"spoonful":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"一匙之量","en":"You can refer to an amount of food resting on a spoon as a spoonful of food.","ex":{"en":"He took a spoonful of the stew and ate it.","cn":"他舀了一匙炖菜吃了。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the amount that a spoon will hold","cn":"一匙之量﹐一满匙"}]},"media":{"uk":"media/ldoce/hwd/bre/7/spoonful0205.mp3","us":"media/ldoce/hwd/ame/f/spoonful.mp3"},"examples":[{"en":"two spoonfuls of sugar","cn":"两勺糖"},{"en":"Two spoonfuls of sugar, please.","cn":"请放两匙糖。"}],"oxford":{"phon":"ˈspuːnfʊl","pos":"noun","senses":[{"en":"the amount that a spoon can hold","cn":"一勺（的量）","ex":{"en":"two spoonfuls of sugar","cn":"两勺糖"}}]}},"spasm":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"痉挛;抽搐","en":"A spasm is a sudden tightening of your muscles, which you cannot control.","ex":{"en":"A muscular spasm in the coronary artery can cause a heart attack","cn":"冠状动脉的肌肉痉挛可能导致心脏病。"}},{"pos":"N-COUNT 可数名词","cn":"(剧痛或不愉快情感的)阵发，迸发","en":"A spasm is a sudden strong pain or unpleasant emotion which lasts for a short period of time.","ex":{"en":"A spasm of pain brought his thoughts back to the present","cn":"一阵剧痛把他的思绪拉回到了现在。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the feeling you have when part of your body hurts","cn":""},{"en":"a pain that continues for a long time but is not very sharp","cn":""},{"en":"a continuous pain in a part of your body","cn":""}]},"vocab":{"pos":"1 n 2 n","senses":[{"en":"A spasm is a sudden constriction of a muscle or blood vessel. This idea can be generalized to anything that occurs suddenly and lasts a short while. Except for a brief spasm of yard work, you had a perfectly lazy Sunday."}]},"collocations":{"phrases":["ADJ. sudden | muscle, muscular","VERB + SPASM feel He felt a spasm of panic sweeping over him. | go into The muscle goes into spasm, producing the symptom of cramp.","SPASM + VERB pass, subside","PREP. in ~ She could not speak; her throat was in spasm. | ~ of He kicked the chair in a spasm of impatience.","PHRASES a spasm of coughing/pain"]},"media":{"uk":"media/ldoce/hwd/bre/e/spasm0205.mp3","us":"media/ldoce/hwd/ame/3/spasm.mp3"},"examples":[{"en":"a spasm of anxiety/anger/coughing/pain, etc.","cn":"突然一阵焦虑、愤怒、咳嗽、疼痛等"},{"en":"The injection sent his leg into spasm.","cn":"一针打下去，他的腿就痉挛了。"}],"oxford":{"phon":"ˈspæzəm","pos":"noun","senses":[{"en":"a sudden and often painful contracting of a muscle, which you cannot control","cn":"痉挛；抽搐","g":"[countable, uncountable]","ex":{"en":"Cholera reduces heartbeat and causes muscle spasms.","cn":"霍乱会使心跳变慢并引起肌肉痉挛。"}},{"en":"a sudden strong feeling or reaction that lasts for a short time","cn":"（感情或反应）一阵阵发作，阵发","g":"[countable]","ex":{"en":"a spasm of anxiety/anger/coughing/pain, etc.","cn":"突然一阵焦虑、愤怒、咳嗽、疼痛等"}}]}},"spangled":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"装饰着小亮片的","en":"Something that is spangled is covered with small shiny objects.","ex":{"en":"...spangled, backless dresses.","cn":"亮片闪闪的露背裙"}}]},"vocab":{"pos":"adj","senses":[{"en":"To be spangled is to be decorated with beads, jewels, sequins, or others adornments. The American flag is called star- spangled , because it is full of stars."}]}},"spectator":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(尤指体育比赛的)观众","en":"A spectator is someone who watches something, especially a sporting event.","ex":{"en":"Thirty thousand spectators watched the final game.","cn":"3 万名观众观看了决赛。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone who goes to a game and watches people playing a sport","cn":""},{"en":"someone who likes a particular sport, or a particular team, and often goes to watch a game or watch a team play","cn":""},{"en":"someone who likes a particular sport or team and often goes to watch a game or watch a team play - use this especially about football","cn":""}]},"vocab":{"pos":"1 n 2 n","senses":[{"en":"If you're watching something, you're a spectator. Football stadiums and circus tents are full of spectators ."}]},"collocations":{"phrases":["ADJ. mere, passive | interested | paying | cricket, football, sports, etc.","QUANT. crowd","SPECTATOR + VERB gather, turn up | line sth Spectators lined the route of the president's walkabout. | applaud (sb/sth), boo (sb/sth), cheer","SPECTATOR + NOUN event, sport"]},"media":{"uk":"media/ldoce/hwd/bre/f/spectator0205.mp3","us":"media/ldoce/hwd/ame/d/spectator1.mp3"},"examples":[{"en":"The match attracted over 40,000 spectators.","cn":"这场比赛吸引了四万多名观众。"}],"oxford":{"phon":"spekˈteɪtə(r)","pos":"noun","senses":[{"en":"a person who is watching an event, especially a sports event","cn":"（尤指体育比赛的）观看者，观众","ex":{"en":"The new football stadium will hold 75 000 spectators.","cn":"新足球场可以容纳 7.5 万观众。"}}]}},"spermicidal":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"含有杀精剂的","en":"A spermicidal cream or jelly contains spermicide."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a cream or liquid that kills sperm , used while having sex to prevent the woman from becoming pregnant","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/4/ld41spermicide.mp3","us":"media/ldoce/hwd/ame/6/spermicide.mp3"},"oxford":{"phon":"ˌspɜːmɪˈsaɪdl","pos":"adjective","senses":[{"en":"able to kill sperm","cn":"杀精的","ex":{"en":"spermicidal cream","cn":"杀精膏"}}]}},"sponsorship":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"资助(金);赞助(金);资金支持","en":"Sponsorship is financial support given by a sponsor.","ex":{"en":"Campbell is one of an ever-growing number of skiers in need of sponsorship","cn":"坎贝尔是越来越多需要得到资助的滑雪运动员之一。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"赞助行为;资助行为","en":"Sponsorship of something is the act of sponsoring it.","ex":{"en":"When it is done properly, arts sponsorship can be more effective than advertising.","cn":"如果方式得当的话，艺术赞助可能比做广告更有效。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"money that you borrow or receive in order to pay for something important and expensive, for example for starting a business","cn":""},{"en":"a large amount of money that you can use to start a business or to pay for something that will later produce more money","cn":""},{"en":"money that a government provides to pay for education, theatre, music etc, not for business activities","cn":""}]},"collocations":{"phrases":["ADJ. generous, major | direct | arts, sports | business, commercial, corporate, government, industrial, private | tobacco","VERB + SPONSORSHIP attract, find, get, obtain, raise, receive, win | look for, seek | withdraw (from) The company has decided to withdraw fr","SPONSORSHIP + NOUN deal, package, programme, scheme | money","PREP. through ~ Two million pounds were raised through sponsorship. | under (the) ~ under commercial sponsorship | with/without ~ Without ge"]},"media":{"uk":"media/ldoce/hwd/bre/f/sponsorship0205.mp3","us":"media/ldoce/hwd/ame/c/sponsorship.mp3"},"examples":[{"en":"The project needs to raise £8 million in sponsorship.","cn":"这个项目需要筹集 800 万英镑的资助。"},{"en":"the senator's sponsorship of the job training legislation","cn":"那位参议员对制订职业培训法规的倡议"}],"oxford":{"phon":"ˈspɒnsəʃɪp","pos":"noun","senses":[{"en":"financial support from a sponsor","cn":"资助；赞助款","g":"[uncountable, countable]","ex":{"en":"a $50 million sponsorship deal","cn":"5 000 万美元的赞助协议"}},{"en":"the act of supporting a person, organization or activity, especially financially","cn":"资助；主办","g":"[uncountable]","ex":{"en":"Two million pounds were raised through sponsorship.","cn":"通过赞助募集了两百万英镑。"}},{"en":"the act of introducing a proposal for a new law","cn":"（法案的）倡议，推行","g":"[uncountable]","ex":{"en":"the senator’s sponsorship of the job training legislation","cn":"那位参议员对制定职业培训法规的倡议"}}]}},"spoilsport":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"叫人扫兴的人;败兴者","en":"If you say that someone is a spoilsport, you mean that they are behaving in a way that ruins other people's pleasure or enjoyment."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone who spoils a happy event for other people, especially by refusing to join in with everyone else","cn":""},{"en":"someone who deliberately spoils someone else's enjoyment, happiness, or plans","cn":""},{"en":"someone who spoils other people's enjoyment, especially by trying to prevent them from doing something","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"A spoilsport is a person who ruins other people's fun. You know: the girl shushing everyone at a sleepover party, the kid who refuses to play when it comes their turn to be \"it.\""}]},"media":{"uk":"media/ldoce/hwd/bre/a/spoilsport0205.mp3","us":"media/ldoce/hwd/ame/b/spoilsport.mp3"},"examples":[{"en":"Don't be such a spoilsport!","cn":"别让人扫兴！"},{"en":"Don’t be such a spoilsport.","cn":"别这么让人扫兴。"}],"oxford":{"phon":"ˈspɔɪlspɔːt","pos":"noun","senses":[{"en":"a person who stops other people from having fun, for example by not taking part in an activity or by trying to prevent other people from doing it","cn":"扫兴的人","ex":{"en":"Don't be such a spoilsport!","cn":"别让人扫兴！"}}]}},"sponger":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"靠他人养活的人;寄生虫","en":"If you describe someone as a sponger, you mean that they sponge off other people or organizations."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone who gets money, free meals etc from other people and does nothing for them – used to show disapproval","cn":"吃白食的人﹐揩油者〔含贬义〕"}]},"media":{"uk":"media/ldoce/hwd/bre/9/ld41sponger.mp3","us":"media/ldoce/hwd/ame/6/sponger.mp3"},"oxford":{"phon":"ˈspʌndʒə(r)","pos":"noun","senses":[{"en":"a person who gets money, food, etc. from other people without doing anything for them or offering to pay","cn":"吃白食的人；揩油者"}]}},"spidery":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"(字迹等)由黑色细线条构成的","en":"If you describe something such as handwriting as spidery, you mean that it consists of thin, dark, pointed lines.","ex":{"en":"He saw her spidery writing on the envelope.","cn":"他在信封上看到了她那细长的笔迹。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"covered with or made of lots of long thin uneven lines 〔","cn":"线条〕细长而不整齐的"}]},"media":{"uk":"media/ldoce/hwd/bre/d/spidery0205.mp3","us":"media/ldoce/hwd/ame/3/spidery.mp3"},"examples":[{"en":"spidery writing (= consisting of thin lines that are not very clear)","cn":"细长而不易辨认的笔画"},{"en":"spidery fingers","cn":"修长的手指"}],"oxford":{"phon":"ˈspaɪdəri","pos":"adjective","senses":[{"en":"long and thin, like the legs of a spider","cn":"（像蜘蛛腿一样）细长的","ex":{"en":"spidery fingers","cn":"修长的手指"}}]}},"spermicide":{"collins":{"senses":[{"pos":"N-MASS 物质名词","cn":"杀精剂","en":"Spermicide is a substance that kills sperm.","ex":{"en":"Although most condoms contain spermicide, there are some manufactured without.","cn":"虽然多数避孕套含有杀精剂，但也有一些是不含的。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a cream or liquid that kills sperm , used while having sex to prevent the woman from becoming pregnant 〔","cn":"用于避孕的〕杀精子剂"}]},"media":{"uk":"media/ldoce/hwd/bre/4/ld41spermicide.mp3","us":"media/ldoce/hwd/ame/6/spermicide.mp3"},"oxford":{"phon":"ˈspɜːmɪsaɪd","pos":"noun","senses":[{"en":"a substance that kills sperm, used during sex to prevent the woman from becoming pregnant","cn":"杀精子剂"}]}},"sportswoman":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"女运动员","en":"A sportswoman is a woman who takes part in sports."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a woman who plays many different sports","cn":"女运动员﹔参加体育运动的女子"}]},"media":{"uk":"media/ldoce/hwd/bre/0/sportswoman0205.mp3","us":"media/ldoce/hwd/ame/d/laadsportswoman.mp3"},"examples":[{"en":"a great all-round sportswoman","cn":"杰出的全能女运动员"}],"oxford":{"phon":"ˈspɔːtswʊmən","pos":"noun","senses":[{"en":"a woman who plays a lot of sport, especially as a professional","cn":"运动员；体育运动爱好者；（尤指）职业运动员","lab":"British English","ex":{"en":"a keen sportswoman","cn":"热衷体育运动的女子"}}]}},"speedway":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"(在特殊跑道上举行的)摩托车赛","en":"Speedway is the sport of racing motorcycles on special tracks."},{"pos":"N-COUNT 可数名词","cn":"(汽车或摩托车的)赛车跑道","en":"A speedway is a special track for car or motorcycle racing."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the sport of racing motorcycle s or cars on a special track 〔","cn":"摩托车或汽车的〕场地赛车运动"},{"en":"a special track for the sport of speedway","cn":"赛车场，赛道"}]},"media":{"uk":"media/ldoce/hwd/bre/4/ld41speedway.mp3","us":"media/ldoce/hwd/ame/8/speedway.mp3"},"oxford":{"phon":"ˈspiːdweɪ","pos":"noun","senses":[{"en":"the sport of racing motorcycles on a special track","cn":"（摩托车）赛车运动","g":"[uncountable]","lab":"British English"},{"en":"a special track for racing cars or motorcycles on","cn":"（汽车或摩托车的）赛车跑道","g":"[countable]","lab":"North American English"}]}},"sportscaster":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(电台或电视台)体育节目主持人,体育比赛解说员","en":"A sportscaster is a radio or television broadcaster who describes or comments on sporting events."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone who describes a sports game as it is being broadcast on television 〔","cn":"电视上的〕体育比赛解说员"}]},"media":{"uk":"media/ldoce/hwd/bre/6/ld41sportscaster.mp3","us":"media/ldoce/hwd/ame/6/ld41sportscaster.mp3"},"oxford":{"phon":"ˈspɔːtskɑːstə(r)","pos":"noun","senses":[{"en":"a person who introduces and presents a sportscast","cn":"（电视台或广播电台的）体育节目播音员，体育比赛解说员"}]}},"spiked":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"有尖顶的；装有尖钉的","en":"Something that is spiked has one or more spikes on it.","ex":{"en":"...spiked railings.","cn":"带尖顶的栅栏"}},{"pos":"ADJ 形容词","cn":"(头发)短而竖立的","en":"If someone has spiked hair, their hair is short and sticks up all over their head."}]},"examples":[{"en":"spiked running shoes","cn":"带钉的跑鞋"},{"en":"short spiked hair","cn":"刺猬头"}],"oxford":{"phon":"spaɪkt","pos":"adjective","senses":[{"en":"with one or more spikes","cn":"有尖刺的；带钉的","ex":{"en":"spiked running shoes","cn":"带钉的跑鞋"}}]}},"spliff":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"大麻烟卷","en":"A spliff is a cigarette which contains cannabis or marijuana."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a cigarette containing cannabis","cn":"大麻香烟"}]},"media":{"uk":"media/ldoce/hwd/bre/4/ld41spliff.mp3","us":"media/ldoce/hwd/ame/4/ld41spliff.mp3"},"oxford":{"phon":"splɪf","pos":"noun","senses":[{"en":"a cigarette containing cannabis","cn":"大麻烟卷"}]}},"spacey":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（尤指音乐）缥缈虚幻的，荒诞无稽的","en":"You can use spacey to describe things, especially music, which seem strange, especially because they are very modern or like things in a dream.","ex":{"en":"...brilliant, spacey guitar sounds.","cn":"华丽而缥缈的吉他声"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"behaving as though you are not fully conscious of what is happening around you","cn":"头脑不清醒的﹐迷迷糊糊的"}]},"media":{"uk":"media/ldoce/hwd/bre/3/spacey0205.mp3","us":"media/ldoce/hwd/ame/1/spacey.mp3"},"examples":[{"en":"I felt tired and kind of spacey.","cn":"我感到很累﹐有点迷迷糊糊的。"}],"oxford":{"phon":"ˈspeɪsi","pos":"adjective","senses":[{"en":"not completely conscious of what is happening around you, often because of taking drugs","cn":"精神恍惚的，神志迷糊的（常指因吸食毒品）"}]}},"spanking":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(作为惩罚的)打屁股","en":"If someone gives a child a spanking, they punish them by hitting them on the bottom several times with their hand.","ex":{"en":"Andrea gave her son a sound spanking.","cn":"安德烈娅给了儿子结结实实一顿痛打。"}},{"pos":"ADV 副词","cn":"非常；极其","en":"If you describe something as spanking new, spanking clean, or spanking white, you mean that it is very new, very clean, or very white.","ex":{"en":"...a spanking new Mercedes","cn":"崭新的梅赛德斯车"}},{"pos":"ADJ 形容词","cn":"飞快的;疾行的","en":"If something moves at a spanking pace, it moves quickly.","ex":{"en":"The film moves along at a spanking pace","cn":"影片节奏紧凑。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the act of hitting a child on their bottom with your open hand, as a punishment","cn":"打屁股〔对小孩的惩罚〕"},{"en":"very new and impressive","cn":"崭新的﹐簇新的"},{"en":"very clean","cn":"非常干净"}]},"media":{"uk":"media/ldoce/hwd/bre/3/ld41spanking.mp3","us":"media/ldoce/hwd/ame/b/spanking1.mp3"},"examples":[{"en":"The horse set off at a spanking pace.","cn":"那匹马一溜烟飞奔而去。"},{"en":"I don't agree with spanking.","cn":"我不赞成打屁股。"}],"oxford":{"phon":"ˈspæŋkɪŋ","pos":"noun","senses":[{"en":"a series of hits on the bottom, given to somebody, especially a child, as a punishment","cn":"打屁股（尤指打小孩）","ex":{"en":"to give somebody a spanking","cn":"打某人屁股"}},{"en":"when you say that something is spanking new, etc. you are emphasizing that it is very new, etc.","cn":"非常；十足","ex":{"en":"a brand spanking new Rolls-Royce","cn":"一辆全新的劳斯莱斯"},"pos":"adverb"},{"en":"very fast, good or impressive","cn":"飞快的；了不起的；令人赞叹的","ex":{"en":"The horse set off at a spanking pace.","cn":"那匹马一溜烟飞奔而去。"},"pos":"adjective"}]}},"spectre":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"萦绕心头的恐惧","en":"If you refer to the spectre of something unpleasant, you are referring to something that you are frightened might occur.","ex":{"en":"Failure to arrive at a consensus over the issue raised the spectre of legal action","cn":"无法就此事达成共识引起了人们对可能会诉诸法律手段的担忧。"}},{"pos":"N-COUNT 可数名词","cn":"鬼魂;幽灵;亡灵","en":"A spectre is a ghost ."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the spirit of a dead person that some people think they can feel or see in a place","cn":""},{"en":"a creature without a physical body, such as an angel or ghost","cn":""},{"en":"an image of a dead person that someone sees suddenly for a short time","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"A spectre is a ghost or spirit. If you see a spectre of the previous owners in your new house, get out quick! A spectre can also be a thought that haunts you."}]},"collocations":{"phrases":["ADJ. terrible | old | constant","VERB + SPECTRE evoke, raise Wall Street's collapse raised spectres of the 1987 stock market crash. | banish","SPECTRE + VERB hang over sb/sth, haunt sb/sth, hover over sb/sth, loom (over sb/sth)","PREP. ~ of The terrible spectre of civil war hung over the country once again."]},"media":{"uk":"media/ldoce/hwd/bre/2/specter0205.mp3","us":"media/ldoce/hwd/ame/d/specter.mp3"},"examples":[{"en":"These weeks of drought have once again raised the spectre of widespread famine.","cn":"几星期来的干旱再次引起了群众对大饥荒的恐慌。"},{"en":"The country is haunted by the spectre of civil war.","cn":"内战彷佛一触即发，举国上下一片恐慌。"}],"oxford":{"phon":"ˈspektə(r)","pos":"noun","senses":[{"en":"something unpleasant that people are afraid might happen in the future","cn":"恐惧；恐慌；忧虑","ex":{"en":"The country is haunted by the spectre of civil war.","cn":"内战仿佛一触即发，举国上下一片恐慌。"}},{"en":"a ghost","cn":"鬼；鬼魂；幽灵","lab":"literary","ex":{"en":"Was he a spectre returning to haunt her?","cn":"是不是他的幽灵回来找她了？"}}]}},"specialize":{"collins":{"senses":[{"pos":"VERB 动词","cn":"专门从事;专门经营;专门研究;专攻","en":"If you specialize in a thing, you know a lot about it and concentrate a great deal of your time and energy on it, especially in your work or when you are studying or training. You also use specialize to talk about a restaurant which concentrates on a particular type of food.","ex":{"en":"...a University professor who specializes in the history of the Russian empire.","cn":"专门研究俄罗斯帝国历史的大学教授"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"knowing a lot of facts about a particular subject, especially about something that not many people know about","cn":""},{"en":"to know a lot about a particular subject because you have had a lot of experience of it","cn":""},{"en":"to know a particular subject very thoroughly","cn":""}]},"vocab":{"pos":"v","senses":[{"en":"To specialize is to narrow down your focus, in your studies or profession, to a specific field. If you love playing the accordion, perhaps you should specialize in polka music."}]},"media":{"uk":"media/ldoce/hwd/bre/2/specialize0205.mp3","us":"media/ldoce/hwd/ame/e/specialize.mp3"},"examples":[{"en":"The shop specializes in hand-made chocolates.","cn":"这家商店专营手工制作的巧克力。"},{"en":"Many students prefer not to specialize too soon.","cn":"很多学生不愿过早地确定专业。"}],"oxford":{"phon":"ˈspeʃəlaɪz","pos":"verb","senses":[{"en":"to become an expert in a particular area of work, study or business; to spend more time on one area of work, etc. than on others","cn":"专门研究（或从事）；专攻","ex":{"en":"Many students prefer not to specialize too soon.","cn":"很多学生不愿过早地确定专业。"}}]}},"splinter":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(木头、玻璃等硬物的)尖细碎片，破片，裂片","en":"A splinter is a very thin, sharp piece of wood, glass, or other hard substance, which has broken off from a larger piece.","ex":{"en":"...splinters of glass.","cn":"玻璃碎片"}},{"pos":"V-ERG 及物/不及物动词","cn":"(使)裂成碎片","en":"If something splinters or is splintered, it breaks into thin, sharp pieces.","ex":{"en":"The ruler cracked and splintered into pieces","cn":"尺子裂开了，碎成了小片。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a small piece of something bigger, such as cloth, dishes, or building materials. that has been broken or torn","cn":""},{"en":"a very small piece of something such as paper, cloth, or food that is no longer useful or needed","cn":""},{"en":"an extremely small, thin, and sharp piece of something such as wood, glass, or metal that was formed when the wood, glass, or metal was broken","cn":""}]},"collocations":{"phrases":["ADJ. tiny | glass, metal, wooden","VERB + SPLINTER get, have | pull out, remove","SPLINTER + VERB lodge","PREP. ~ of A small splinter of metal had lodged in his thumb."]},"media":{"uk":"media/ldoce/hwd/bre/3/splinter_n0205.mp3","us":"media/ldoce/hwd/ame/b/splinter1.mp3"},"examples":[{"en":"Several firms have splintered off from the original company.","cn":"从原公司分离出好几个企业。"},{"en":"The mirror cracked but did not splinter.","cn":"镜子裂了，但没碎。"}],"oxford":{"phon":"ˈsplɪntə(r)","pos":"noun","senses":[{"en":"a small, thin, sharp piece of wood, metal, glass, etc. that has broken off a larger piece","cn":"（木头、金属、玻璃等的）尖碎片，尖细条","ex":{"en":"splinters of glass","cn":"玻璃碎片"}},{"en":"to break, or to make something break, into small, thin, sharp pieces","cn":"（使）裂成碎片","g":"[intransitive, transitive]","ex":{"en":"The mirror cracked but did not splinter.","cn":"镜子裂了，但没碎。"},"pos":"verb"},{"en":"to divide into smaller groups that are no longer connected; to separate from a larger group","cn":"分裂；分离出来","g":"[intransitive]","ex":{"en":"The party began to splinter.","cn":"那个党开始分裂。"},"pos":"verb"}]}},"spate":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"大批，一连串，一阵(尤指令人不快之物)","en":"A spate of things, especially unpleasant things, is a large number of them that happen or appear within a short period of time.","ex":{"en":"...the recent spate of attacks on horses.","cn":"最近发生的一连串袭马事件"}},{"pos":"PHRASE 短语","cn":"(河水)猛涨，泛滥","en":"When a river is in spate it contains a lot more water than usual and is flowing very fast.","ex":{"en":"The Thames was in spate, with flocks of Canada geese speeding downriver.","cn":"泰晤士河河水暴涨，成群的加拿大雁迅速游向下游。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a lot of unpleasant activity of one particular kind which spreads quickly during a short period of time and which seems to be difficult to stop or control","cn":""},{"en":"a large number of unpleasant events or a particular kind that happen in a short period of time in many different places","cn":""},{"en":"a lot of unpleasant activity or actions suddenly becoming worse and increasing in a short period of time","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"A spate is a large number. If a spate of new coffee shops open in your neighborhood, it’ll be easy for you to stay wide awake. You’ll have easy access to plenty of caffeine."}]},"media":{"uk":"media/ldoce/hwd/bre/1/spate0205.mp3","us":"media/ldoce/hwd/ame/c/spate.mp3"},"examples":[{"en":"The bombing was the latest in a spate of terrorist attacks.","cn":"这次炸弹爆炸事件是一连串恐怖主义袭击中最近的一起。"},{"en":"( figurative ) Celia was in full spate (= completely involved in talking and not likely to stop or able to be interrupted).","cn":"西莉亚口若悬河，滔滔不绝。"}],"oxford":{"phon":"speɪt","pos":"noun","senses":[{"en":"a large number of things, which are usually unpleasant, that happen suddenly within a short period of time","cn":"一连串，接二连三（通常指不愉快的事物）","ex":{"en":"The bombing was the latest in a spate of terrorist attacks.","cn":"这次炸弹爆炸事件是一连串恐怖主义袭击中最近的一起。"}}]}},"spry":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(尤指老人)精力充沛的,活跃的，充满活力的","en":"Someone, especially an old person, who is spry, is lively and active.","ex":{"en":"The old gentleman was as spry as ever.","cn":"这位老先生依然健旺。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"a spry old person has energy and is active 〔","cn":"老人〕充满活力的﹐活跃的"}]},"vocab":{"pos":"adj","senses":[{"en":"If you are an old lady, remaining spry is something you aspire to. It means \"nimble.\" You might also use it to describe a goat that jumps easily along from mountain crag to mountain crag."}]},"media":{"uk":"media/ldoce/hwd/bre/1/spry0205.mp3","us":"media/ldoce/hwd/ame/f/spry.mp3"},"examples":[{"en":"He’s still remarkably spry.","cn":"他依然充满了活力。"}],"oxford":{"phon":"spraɪ","pos":"adjective","senses":[{"en":"full of life and energy","cn":"充满生机的；生气勃勃的；精力充沛的"}]}},"spew":{"collins":{"senses":[{"pos":"V-ERG 及物/不及物动词","cn":"(使)喷出;(使)放出;(使)涌出","en":"When something spews out a substance or when a substance spews from something, the substance flows out quickly in large quantities.","ex":{"en":"The volcano spewed out more scorching volcanic ashes, gases and rocks","cn":"火山喷出更多灼热的火山灰、气体和岩块。"}},{"pos":"VERB 动词","cn":"呕吐","en":"If someone spews or spews up, they vomit.","ex":{"en":"He's pissed. Let's get out of his way before he starts spewing.","cn":"他很恼火。趁他还没有发作，我们赶快离他远点儿。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to flow out of something quickly in large quantities, or to make something flow out in this way （","cn":"使）喷出﹐（使）涌出"},{"en":"to say a lot of bad or negative things very quickly","cn":"发泄﹔破口大骂"},{"en":"to vomit","cn":"呕吐"}]},"media":{"uk":"media/ldoce/hwd/bre/e/spew0205.mp3","us":"media/ldoce/hwd/ame/9/spew.mp3"},"examples":[{"en":"Massive chimneys were spewing out smoke.","cn":"一座座高大的烟囱冒着烟。"},{"en":"She spewed up the entire meal.","cn":"她把吃的饭全吐出来了。"}],"oxford":{"phon":"spjuː","pos":"verb","senses":[{"en":"to flow out quickly, or to make something flow out quickly, in large amounts","cn":"（使）喷出，涌出","g":"[intransitive, transitive]","ex":{"en":"Flames spewed from the aircraft's engine.","cn":"飞机发动机喷出火焰。"}},{"en":"to vomit (= bring food from the stomach back out through the mouth)","cn":"呕吐","g":"[intransitive, transitive]","lab":"British English, informal，，","ex":{"en":"He spewed up on the pavement.","cn":"他在人行道上吐了。"}}]}},"spearhead":{"collins":{"senses":[{"pos":"VERB 动词","cn":"领导;倡导;当…的先锋","en":"If someone spearheads a campaign or an attack, they lead it.","ex":{"en":"...Esther Rantzen, who is spearheading a national campaign against bullying","cn":"埃丝特·兰森，一场全国性的反抗暴力运动的领导者"}},{"pos":"N-COUNT 可数名词","cn":"前锋;先头部队","en":"The spearhead of a campaign is the person or group that leads it.","ex":{"en":"The marines went ashore as a spearhead this morning to capture key targets.","cn":"今天早晨，海军陆战队作为先头部队率先登陆以占领主要目标。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to lead an attack or organized action","cn":"当…的先锋﹐带头〔做某事〕"},{"en":"a person or group of people who lead an attack or organized action","cn":"先锋﹐前导﹐先头部队"}]},"media":{"uk":"media/ldoce/hwd/bre/f/spearhead_v0205.mp3","us":"media/ldoce/hwd/ame/0/spearhead1.mp3"},"examples":[{"en":"He is spearheading a campaign for a new stadium in the town.","cn":"他正发起一项运动，呼吁在城里新建一座体育场。"},{"en":"the troops who spearheaded the rescue mission","cn":"在救援任务中充当先锋的部队"}],"oxford":{"phon":"ˈspɪəhed","pos":"noun","senses":[{"en":"a person or group that begins an activity or leads an attack against somebody/something","cn":"先锋；前锋；先头部队"},{"en":"to begin an activity or lead an attack against somebody/something","cn":"做…的先锋；带头做；领先突击","ex":{"en":"He is spearheading a campaign for a new stadium in the town.","cn":"他正发起一项运动，呼吁在城里新建一座体育场。"},"pos":"verb"}]}},"splendour":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"壮丽辉煌;光彩夺目","en":"The splendour of something is its beautiful and impressive appearance.","ex":{"en":"The foreign ministers are meeting in the splendour of Oktyabrskaya Hotel in central Moscow.","cn":"外长们正在莫斯科市中心富丽堂皇的十月酒店里开会。"}},{"pos":"N-PLURAL 复数名词","cn":"华丽;豪华;奢华","en":"The splendours of a place or way of life are its beautiful and impressive features.","ex":{"en":"Montagu was extremely impressed by the splendours of the French court.","cn":"法国宫廷的豪华给蒙塔古留下了很深的印象。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"impressive beauty, especially of a large building or large place","cn":"壮丽﹐华丽﹐壮观"},{"en":"impressive beautiful features, especially of a large building or place 〔","cn":"尤指大建筑物或地方的〕壮丽景色﹐恢宏气势"}]},"collocations":{"phrases":["ADJ. full A butterfly emerged in its full splendour a week later. | glorious, great, regal | former, original | faded, fading | scenic","VERB + SPLENDOUR have The hotel has the splendour of a nineteenth-century mansion. | lose | recapture, regain It will take a lot of repair w","PREP. in ~ They dined in a special suite in glorious splendour. | in sb's/sth's ~ There below lay Paris in all its splendour. | of ~ a castl","PHRASES in solitary splendour The castle rises in solitary splendour on the fringe of the desert."]},"media":{"uk":"media/ldoce/hwd/bre/c/brelasdesplendour.mp3","us":"media/ldoce/hwd/ame/f/splendor.mp3"},"examples":[{"en":"The palace has been restored to its former splendour.","cn":"宫殿经过修葺，重现出昔日的富丽堂皇。"},{"en":"a view of Rheims Cathedral, in all its splendour","cn":"尽显其宏伟壮观的兰斯大教堂"}],"oxford":{"phon":"ˈsplendə(r)","pos":"noun","senses":[{"en":"grand and impressive beauty","cn":"壮丽；雄伟；豪华；华丽","g":"[uncountable]","ex":{"en":"The room has a view of Rheims Cathedral, in all its splendour.","cn":"从这个房间可以饱览兰斯大教堂的壮观景色。"}},{"en":"the beautiful and impressive features or qualities of something, especially a place","cn":"（尤指某地的）壮丽景色，恢弘气势","g":"[plural]","ex":{"en":"the splendours of Rome (= its fine buildings, etc.)","cn":"罗马的壮丽景色"}}]}},"spellbinding":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"使人入迷的;迷人的","en":"A spellbinding image or sound is one that is so fascinating that you can think about nothing else.","ex":{"en":"Gray describes in dramatic and spellbinding detail the lives of these five ladies.","cn":"格雷以富于戏剧性和令人着迷的细腻笔触描写了这 5 位女性的生活。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"keeping your attention and making you want to know more","cn":""},{"en":"very interesting","cn":""},{"en":"giving you new ideas or experiences in a way that is interesting and enjoyable","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/3/spellbinding0205.mp3","us":"media/ldoce/hwd/ame/9/laadspellbinding.mp3"},"examples":[{"en":"a spellbinding performance","cn":"使人入迷的演出"},{"en":"a spellbinding tale","cn":"引人入胜的故事"}],"oxford":{"phon":"ˈspelbaɪndɪŋ","pos":"adjective","senses":[{"en":"holding your attention completely","cn":"让人着魔的；迷人的","ex":{"en":"a spellbinding performance","cn":"使人入迷的演出"}}]}},"sprinkler":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(浇花草的)洒水器;喷水灭火装置","en":"A sprinkler is a device used to spray water. Sprinklers are used to water plants or grass, or to put out fires in buildings."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a piece of equipment used for scattering water on grass or soil 〔","cn":"浇草地等的〕洒水器"},{"en":"a piece of equipment on a ceiling that scatters water if there is a fire 〔","cn":"天花板上的〕自动喷水灭火装置"}]},"media":{"img":["media/ldoce/img/sprinkler.jpg","media/thumb/sprinkler.jpg"],"uk":"media/ldoce/hwd/bre/a/sprinkler0205.mp3","us":"media/ldoce/hwd/ame/7/sprinkler.mp3"},"oxford":{"phon":"ˈsprɪŋklə(r)","pos":"noun","senses":[{"en":"a device with holes in that is used to spray water in drops onto plants, soil or grass","cn":"喷洒器；喷头"},{"en":"a device inside a building that sprays out water if it detects a rise in temperature because of a fire","cn":"（建筑物内的）喷洒装置，消防喷淋，自动喷水灭火装置"}]}},"spigot":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"龙头;开关","en":"A spigot is a faucet or tap."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a tap in a large container that controls the flow of liquid from it 〔","cn":"大容器的〕塞子﹐栓"},{"en":"an outdoor tap","cn":"室外水龙头"}]},"media":{"uk":"media/ldoce/hwd/bre/1/ld41spigot.mp3","us":"media/ldoce/hwd/ame/a/spigot.mp3"},"oxford":{"phon":"ˈspɪɡət","pos":"noun","senses":[{"en":"a device in a tap that controls the flow of liquid from a container","cn":"（龙头中的）塞，栓","lab":"specialist"},{"en":"any tap, especially one outdoors","cn":"（尤指户外的）龙头","lab":"US English"}]}},"spartan":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(生活方式)简朴的，清苦的","en":"A spartan lifestyle or existence is very simple or strict, with no luxuries.","ex":{"en":"Their spartan lifestyle prohibits a fridge or a phone","cn":"他们不使用冰箱和电话，过着简朴的生活。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"without anything added, or without decoration","cn":""},{"en":"not having a lot of decoration or unnecessary things, but attractive","cn":""},{"en":"very plain and with very little decoration, or very little in it – used about a room or place that does not make you feel welcome","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"A spartan existence is kind of like being a monk. Your room is bare, you live simply and eat sparingly, and your sheets are probably scratchy."}]},"media":{"uk":"media/ldoce/hwd/bre/f/spartan0205.mp3","us":"media/ldoce/hwd/ame/d/spartan.mp3"},"examples":[{"en":"spartan accommodation","cn":"简朴的住处"},{"en":"a spartan existence","cn":"清苦的生活"}],"oxford":{"phon":"ˈspɑːtn","pos":"adjective","senses":[{"en":"simple or severe; without anything that makes life easier or more pleasant","cn":"斯巴达式的；简朴的；清苦的","ex":{"en":"the spartan life of the training camp","cn":"训练营的斯巴达生活"}}]}},"speechwriter":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"演讲稿撰写人","en":"A speechwriter is a person who writes speeches for important people such as politicians."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone whose job is to write speeches for other people","cn":"演讲稿撰写人"}]},"media":{"uk":"media/ldoce/hwd/bre/7/ld41speechwriter.mp3","us":"media/ldoce/hwd/ame/6/laadspeechwriter.mp3"}},"splitting":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"(头痛)欲裂的","en":"A splitting headache is a very severe and painful one."}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"a very bad headache","cn":"极度头疼"}]},"media":{"uk":"media/ldoce/hwd/bre/6/ld44splitting.mp3","us":"media/ldoce/hwd/ame/6/ld44splitting.mp3"},"oxford":{"phon":"ˈsplɪtɪŋ","pos":"adjective","senses":[{"en":"if you have a splitting headache, you have a very bad pain in your head","cn":"（头痛）欲裂的"}]}},"sparkle":{"collins":{"senses":[{"pos":"VERB 动词","cn":"闪闪发光;闪耀","en":"If something sparkles, it is clear and bright and shines with a lot of very small points of light.","ex":{"en":"The jewels on her fingers sparkled","cn":"她手指上戴的首饰闪闪发光。"}},{"pos":"N-COUNT 可数名词","cn":"闪光点;亮点","en":"Sparkles are small points of light caused by light reflecting off a clear bright surface.","ex":{"en":"...sparkles of light","cn":"光亮点"}},{"pos":"VERB 动词","cn":"聪明活泼；机智诙谐;才华横溢","en":"Someone who sparkles is lively, intelligent, and witty.","ex":{"en":"She sparkles, and has as much zest as a person half her age","cn":"她才华横溢，而且像只有她一半岁数的年轻人一样充满热情。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"if something sparkles, it shines with many small bright points when light is on it","cn":""},{"en":"to shine by reflecting the light – used especially about smooth clean surfaces, or about someone’s eyes or teeth","cn":""},{"en":"to shine with quick flashes of light","cn":""}]},"vocab":{"pos":"v n","senses":[{"en":"Fairy dust, stars, Christmas lights, Hanukkah candles, freshly fallen snow, a lake when the sun hits it just right — all of these things sparkle . That means they shine with a bright, glistening, shimmering light."}]},"collocations":{"phrases":["ADJ. extra | old She has lost none of her old sparkle as a jazz singer.","VERB + SPARKLE have | lack | lose | add, put (back) A live band added extra sparkle to the occasion.","PHRASES a sparkle in your eyes"]},"media":{"uk":"media/ldoce/hwd/bre/d/sparkle_v0205.mp3","us":"media/ldoce/hwd/ame/2/sparkle1.mp3"},"examples":[{"en":"He always sparkles at parties.","cn":"在各种聚会上，他总是光芒四射。"},{"en":"Her jewellery sparkled in the candlelight.","cn":"烛光下，她的首饰光彩熠熠。"}],"oxford":{"phon":"ˈspɑːkl","pos":"verb","senses":[{"en":"to shine brightly with small flashes of light","cn":"闪烁；闪耀","g":"[intransitive]","ex":{"en":"sparkling eyes","cn":"炯炯有神的眼睛"}},{"en":"to be full of life, enthusiasm or humour","cn":"生气勃勃；热情奔放；神采飞扬","g":"[intransitive]","ex":{"en":"He always sparkles at parties.","cn":"在各种聚会上，他总是光芒四射。"}},{"en":"a series of flashes of light produced by light hitting a shiny surface","cn":"闪烁（或闪耀）的光","lab":"figurative","ex":{"en":"the sparkle of glass","cn":"玻璃闪耀的亮光"},"pos":"noun"},{"en":"the quality of being lively and original","cn":"生动新颖；亮点","ex":{"en":"The performance lacked sparkle.","cn":"这场演出缺少亮点。"},"pos":"noun"}]}},"sportsmanship":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"运动员风范;体育精神","en":"Sportsmanship is behaviour and attitudes that show respect for the rules of a game and for the other players.","ex":{"en":"The team also won praise for sportsmanship and fair play.","cn":"该队还因其良好的体育精神及公平竞争精神而受到了表扬。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"behaviour that is fair, honest, and polite in a game or sports competition","cn":"运动家风度[品格]﹐体育精神"}]},"vocab":{"pos":"n","senses":[{"en":"Sportsmanship is a type of fairness expected of athletes. If you never cheat or act rude while playing a game, you are modeling good sportsmanship ."}]},"media":{"uk":"media/ldoce/hwd/bre/2/brelasdesportsmanship.mp3","us":"media/ldoce/hwd/ame/c/sportsmanship.mp3"},"examples":[{"en":"His sportsmanship and style of play are refreshing.","cn":"他的体育精神和比赛风格令人耳目一新。"},{"en":"We try to teach the kids good sportsmanship.","cn":"我们尽量教给孩子们良好的体育精神。"}],"oxford":{"phon":"ˈspɔːtsmənʃɪp","pos":"noun","senses":[{"en":"fair, generous and polite behaviour, especially when playing a sport or game","cn":"运动员风范，体育精神（多指体育比赛中光明磊落、有气度）","ex":{"en":"He has a reputation for fair play and good sportsmanship.","cn":"他以公平竞争和良好的体育精神而闻名。"}}]}},"spider":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"蜘蛛","en":"A spider is a small creature with eight legs. Most types of spider make structures called webs in which they catch insects for food."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a small creature with eight legs, which catches insects using a fine network of sticky threads","cn":"蜘蛛"},{"en":"a computer program that searches the Internet for the best websites with the information you want, so that you can find it quickly 〔","cn":"搜索引擎的〕蜘蛛程序"}]},"collocations":{"phrases":["ADJ. hairy | poisonous","SPIDER + VERB make/spin/weave a web | crawl, run, scuttle | hunt sth | catch sth | bite sth | lurk","SPIDER + NOUN silk | web","PHRASES a spider's web"]},"media":{"img":["media/ldoce/img/spider.jpg","media/thumb/spider.jpg"],"uk":"media/ldoce/hwd/bre/9/brelasdespider.mp3","us":"media/ldoce/hwd/ame/5/spider.mp3"},"oxford":{"phon":"ˈspaɪdə(r)","pos":"noun","senses":[{"en":"a small creature with eight thin legs. Many spiders spin webs to catch insects for food.","cn":"蜘蛛","ex":{"en":"a poisonous spider","cn":"毒蜘蛛"}}]}},"sporran":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(苏格兰男子穿褶裥短裙时系于腰带上的)毛皮袋","en":"A sporran is a flat bag made out of leather or fur, which a Scotsman wears on a belt around his waist when he is wearing a skirt called a kilt."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a special bag made of leather or fur, that a Scotsman wears in front of a kilt 〔","cn":"苏格兰男子佩戴于短裙前面的〕毛皮袋"}]},"media":{"uk":"media/ldoce/hwd/bre/9/ld41sporran.mp3","us":"media/ldoce/hwd/ame/9/ld41sporran.mp3"},"oxford":{"phon":"ˈspɒrən","pos":"noun","senses":[{"en":"a flat bag, usually made of leather or fur, that is worn by men in front of the kilt as part of the Scottish national dress","cn":"毛皮袋（苏格兰男子民族服装的一部分，系在褶裥短裙前）"}]}},"spastic":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"患痉挛性麻痹症的(可能具冒犯意味)","en":"Someone who is spastic is born with a disability which makes it difficult for them to control their muscles, especially in their arms and legs. This word could cause offence, and most people now refer to someone with this disability as having cerebral palsy ."}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"having cerebral palsy , a disease that prevents control of the muscles","cn":"患痉挛性麻痹的"},{"en":"an insulting way of describing someone who drops things, falls easily, and is stupid – used especially by children","cn":"愚笨的﹐拙劣的〔尤为儿语〕"}]},"vocab":{"pos":"adj n","senses":[{"en":"A spastic motion is jerky and convulsive. This word also applies to people suffering from spastic paralysis."}]},"media":{"uk":"media/ldoce/hwd/bre/5/spastic0205.mp3","us":"media/ldoce/hwd/ame/a/spastic.mp3"},"examples":[{"en":"spastic children","cn":"痉挛性麻痹症患儿"},{"en":"spastic reactions","cn":"痉挛性麻痹症反应"}],"oxford":{"phon":"ˈspæstɪk","pos":"noun","senses":[{"en":"a word for a person who is affected by cerebral palsy that is now considered offensive","cn":"大脑性麻痹;脑瘫","lab":"medical, old-fashioned, offensive，，，，"},{"en":"an offensive word used by children to mean ‘a stupid person’","cn":"愚蠢的人;笨手笨脚者","lab":"informal, offensive, becoming old-fashioned，，，，"},{"en":"relating to or caused by a muscle spasm (= a sudden contracting movement that cannot be controlled) or weakness, such as that caused by cerebral palsy","cn":"患痉挛性瘫痪的;痉挛性的","lab":"medical","ex":{"en":"spastic movements","cn":"痉挛运动"},"pos":"adjective"},{"en":"a word to describe somebody who is affected by cerebral palsy that is now considered offensive","cn":"患痉挛性瘫痪的人","lab":"medical, old-fashioned, offensive，，，，","pos":"adjective"},{"en":"an offensive word used by children to mean ‘stupid’","cn":"（有时儿童用以骂人愚蠢）笨拙的，无能的","lab":"informal, offensive, becoming old-fashioned，，，，","pos":"adjective"}]}},"spunk":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"勇气;胆量","en":"Spunk is courage.","ex":{"en":"I admired her independence and her spunk.","cn":"我敬佩她的独立精神和勇气。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"courage","cn":"胆量"},{"en":"semen","cn":"精液"}]},"media":{"uk":"media/ldoce/hwd/bre/a/ld41spunk.mp3","us":"media/ldoce/hwd/ame/8/spunk.mp3"},"examples":[{"en":"She had a lot of spunk.","cn":"她很有胆量。"}],"oxford":{"phon":"spʌŋk","pos":"noun","senses":[{"en":"courage; determination","cn":"勇气；胆量；决心","g":"[uncountable]","lab":"informal"},{"en":"semen (= the white liquid containing sperm that is produced by the sex organs of men and male animals)","cn":"精液","g":"[uncountable]","lab":"British English, taboo, slang，，，，"},{"en":"a sexually attractive person","cn":"性感的人","g":"[countable]","lab":"Australian English, informal，，"}]}},"specialization":{"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"an activity or subject that you know a lot about","cn":"专业"},{"en":"the practice of limiting your interests or activities to one particular subject","cn":"专门化﹐专业化"}]},"vocab":{"pos":"n","senses":[{"en":"If you have a specialization , that means you focus on a specific aspect of a larger topic. If you’re a nurse, your specialization might be pediatric care, which means you focus on providing care to infants and children."}]},"collocations":{"phrases":["ADJ. increased, increasing | narrow His specialization is too narrow to be of interest to more than a handful of students. | professional | ","QUANT. degree The production line involves a high degree of specialization of labour.","PREP. ~ in Her degree is in French, with specialization in seventeenth-century literature.","PHRASES an area of specialization The company has gradually focused on its current areas of specialization."]},"media":{"uk":"media/ldoce/hwd/bre/5/ld41specialization.mp3","us":"media/ldoce/hwd/ame/5/ld41specialization.mp3"},"examples":[{"en":"industrial specialization","cn":"工业的专门化"}],"oxford":{"phon":"ˌspeʃəlaɪˈzeɪʃn","pos":"noun","senses":[{"en":"the process of becoming an expert in a particular area of work, study or business; the fact of spending more time on one area of work, etc. than on others","cn":"专门研究（或从事）；专攻","g":"[uncountable]","ex":{"en":"Increasing specialization has reduced the number of doctors who are good at managing medical emergencies.","cn":"专业化程度的提高导致擅长处理医疗紧急情况的医生数量减少。"}},{"en":"a particular area of work, study or business which somebody spends more time on than on other areas","cn":"专门研究（或从事）；专攻","g":"[countable]","ex":{"en":"After completing the course, they select a specialization in specific fields such as metal, woodworking or textiles.","cn":"完成课程后，他们选择金属、木工或纺织等特定领域的专业。"}}]}},"speculative":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(信息)推测性的，猜测性的","en":"A piece of information that is speculative is based on guesses rather than knowledge.","ex":{"en":"The papers ran speculative stories about the mysterious disappearance of Eddie Donagan","cn":"各家报纸都刊登了有关埃迪·多纳根神秘失踪的猜测性报道。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(表情)带着疑问的，好奇的","en":"Someone who has a speculative expression seems to be trying to guess something about a person or thing.","ex":{"en":"His mother regarded him with a speculative eye.","cn":"他的母亲用好奇的目光看着他。"}},{"pos":"ADJ 形容词","cn":"投机性的","en":"Speculative is used to describe activities which involve buying goods or shares, or buildings and properties, in the hope of being able to sell them again at a higher price and make a profit.","ex":{"en":"Thousands of pensioners were persuaded to mortgage their homes to invest in speculative bonds","cn":"几千名领取养老金的人被劝说用自己的住房作抵押去投资投机性债券。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"an attempt to guess something","cn":""},{"en":"an opinion about the value, size, speed etc of something that is formed partly by calculating and partly by guessing","cn":""},{"en":"when you try to understand something or find the answer to something by guessing, because you do not have all the information you need","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"Speculative describes very risky and unproven ideas or chances. You might have great ideas about starting your own business but your plans are speculative until you earn money from them."}]},"media":{"uk":"media/ldoce/hwd/bre/0/ld41speculative.mp3","us":"media/ldoce/hwd/ame/c/speculative.mp3"},"examples":[{"en":"She cast a speculative look at Kate.","cn":"她带着疑问的眼神看了凯特一眼。"},{"en":"a purely speculative theory about life on other planets","cn":"关于其他行星上存在生命的纯属猜测的理论"}],"oxford":{"phon":"ˈspekjələtɪv","pos":"adjective","senses":[{"en":"based on guessing or on opinions that have been formed without knowing all the facts","cn":"推测的；猜测的；推断的","ex":{"en":"The report is highly speculative and should be ignored.","cn":"这个报道推测的成分很大，应该不予理会。"}},{"en":"showing that you are trying to guess something","cn":"揣摩的；忖度的；试探的","ex":{"en":"She cast a speculative look at Kate.","cn":"她带着疑问的眼神看了凯特一眼。"}},{"en":"done in the hope of making a profit but involving the risk of losing money","cn":"投机性的；风险性的","ex":{"en":"speculative investment","cn":"有风险的投资"}}]}},"spoiler":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"捣乱的人(或事物);搞破坏的人(或事物)","en":"If you describe someone or something as a spoiler, you mean that they try to spoil the performance of other people or things.","ex":{"en":"I was a talentless spoiler. If I couldn't be good, why should they?","cn":"我是个无能的捣乱分子。如果我做不好，他们有什么理由表现好呢？"}},{"pos":"N-COUNT 可数名词","cn":"(飞机的)扰流器;(汽车的)气流偏导器","en":"A spoiler is an object which forms part of an aircraft's wings or part of the body of a car. It changes the flow of air around the vehicle, allowing an aircraft to change direction or making a car's forward movement more efficient."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone who spoils a happy event for other people, especially by refusing to join in with everyone else","cn":""},{"en":"someone who deliberately spoils someone else's enjoyment, happiness, or plans","cn":""},{"en":"someone who spoils other people's enjoyment, especially by trying to prevent them from doing something","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/8/ld41spoiler.mp3","us":"media/ldoce/hwd/ame/2/spoiler.mp3"},"oxford":{"phon":"ˈspɔɪlə(r)","pos":"noun","senses":[{"en":"a part of an aircraft’s wing that can be raised in order to interrupt the flow of air over it and so slow the aircraft’s speed","cn":"（机翼的）扰流片"},{"en":"a raised part on a fast car that prevents it from being lifted off the road when travelling very fast","cn":"（汽车的）气流偏导器"},{"en":"a candidate for a political office who is unlikely to win but who may get enough votes to prevent one of the main candidates from winning","cn":"选举中的搅局者（无望获胜但所得选票可能使某主要候选人无法当选）","lab":"especially North American English"},{"en":"a person or thing that intends or is intended to stop somebody/something being successful","cn":"阻碍…成功的人（或事物）；搞砸…的人（或事物）"},{"en":"information that you are given about what is going to happen in a film, television series, etc. before it is shown to the public","cn":"剧透；（在电影、电视剧等公映前的）剧情透露","ex":{"en":"Warning: this review contains spoilers.","cn":"警告：本影评包含剧透。"}},{"en":"a news story, book, etc. that is produced very quickly in order to take attention away from one produced by a competitor that appears at the same time","cn":"（为竞争而迅速发表的）抵消影响的报道（或书籍等）","ex":{"en":"The paper ran a spoiler.","cn":"该报剧透了。"}}]}},"speedometer":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(汽车的)速率计，速度计","en":"A speedometer is the instrument in a vehicle which shows how fast the vehicle is moving."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"an instrument in a vehicle that shows how fast it is going 〔","cn":"车辆上的〕速度计"}]},"media":{"uk":"media/ldoce/hwd/bre/b/speedometer0205.mp3","us":"media/ldoce/hwd/ame/e/speedometer.mp3"},"oxford":{"phon":"spiːˈdɒmɪtə(r)","pos":"noun","senses":[{"en":"an instrument in a vehicle which shows how fast the vehicle is going","cn":"（车辆的）车速里程表"}]}},"spotter":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"以观看(火车或飞机等)为癖好的人","en":"A spotter of something such as trains or aeroplanes is someone whose hobby is watching and finding out about them.","ex":{"en":"I was a devoted train spotter.","cn":"我是个酷爱看火车的人。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone who spends time watching birds, trains etc for pleasure and writes down the things that they see","cn":"鸟类/火车等观察者"},{"en":"someone whose job is to look for or notice a particular type of thing 〔","cn":"以专门搜寻或注意某类事物为职业的〕探子"}]},"media":{"uk":"media/ldoce/hwd/bre/4/ld41spotter.mp3","us":"media/ldoce/hwd/ame/3/spotter1.mp3"},"examples":[{"en":"a talent spotter (= sb who visits clubs and theatres looking for new performers)","cn":"星探"},{"en":"Football clubs send spotters to look for young talent.","cn":"足球俱乐部派出星探去寻找年轻的足球人才。"}],"oxford":{"phon":"ˈspɒtə(r)","pos":"noun","senses":[{"en":"a person who looks for a particular type of thing or person, as a hobby or job","cn":"探子（爱好或专门搜寻物品或人才）","ex":{"en":"a talent spotter (= somebody who visits clubs and theatres looking for new performers)","cn":"星探"}},{"en":"a plane used for finding out what an enemy is doing","cn":"侦察机"}]}},"spire":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(教堂等建筑物顶部的)尖塔，尖顶","en":"The spire of a building such as a church is the tall pointed structure on the top."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a roof that rises steeply to a point on top of a tower, especially on a church 〔","cn":"尤指教堂的〕塔尖﹐尖顶"}]},"vocab":{"pos":"n","senses":[{"en":"A pointed cone shape on top of a building is called a spire , especially when it rises from the roof of a church."}]},"media":{"uk":"media/ldoce/hwd/bre/2/spire0205.mp3","us":"media/ldoce/hwd/ame/9/spire.mp3"},"oxford":{"phon":"ˈspaɪə(r)","pos":"noun","senses":[{"en":"a tall pointed structure on the top of a building, especially a church","cn":"（教堂等顶部的）尖塔，尖顶","ex":{"en":"a magnificent view of the spires of the city","cn":"全城建筑物尖顶尽收眼底的美景。"}}]}},"spangle":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"闪闪发光的饰片（或亮片）","en":"Spangles are small pieces of shiny metal or plastic which are used to decorate clothing or hair.","ex":{"en":"...robes that glittered with spangles.","cn":"缀满闪闪发光的饰片的袍子"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to cover something with shiny points of light","cn":"用闪亮的斑点覆盖﹐使闪闪发亮"},{"en":"a small piece of shiny metal or plastic sewn onto clothes to give them a shining effect 〔","cn":"装饰衣服的〕闪光金属片﹐闪光塑料片﹐闪光饰片"}]},"vocab":{"pos":"n v","senses":[{"en":"Do you like your outfits to have flair? A little sparkle? Then you're probably a fan of spangles , or small, shiny decorative things like sequins."}]},"media":{"uk":"media/ldoce/hwd/bre/c/ld41spangle2.mp3","us":"media/ldoce/hwd/ame/e/ld41spangle.mp3"},"examples":[{"en":"The city skyline was spangled with lights.","cn":"城市的天际线灯光闪耀。"}],"oxford":{"phon":"ˈspæŋɡl","pos":"verb","senses":[{"en":"to cover or to decorate something with small pieces of something shiny","cn":"用闪光片布满（或装饰）"},{"en":"a small piece of shiny metal or plastic used to decorate clothes","cn":"（装饰服装的）闪光金属片，闪光塑料片","ex":{"en":"a dress covered with red spangles","cn":"一件布满红色亮片的连衣裙"},"pos":"noun"}]}},"spinster":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(老)处女;未婚中年(或老年)女子","en":"A spinster is a woman who has never been married; used especially when talking about an old or middle-aged woman."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a man who has never been married","cn":""},{"en":"a woman who has never been married and is no longer young","cn":""},{"en":"someone who is single is not married or is not in a permanent romantic relationship with anyone","cn":""}]},"vocab":{"pos":"1 n 2 n","senses":[{"en":"A spinster , or an older, unmarried woman. Even if you're in awe of your Aunt Sally's glamorous, single life, your grandmother might dismiss her as a spinster ."}]},"media":{"uk":"media/ldoce/hwd/bre/8/spinster0205.mp3","us":"media/ldoce/hwd/ame/c/spinster.mp3"},"examples":[{"en":"For most women, marriage used to bring a higher status than spinsterhood.","cn":"从前，就多数妇女而言，结婚的比独身的更有地位。"}],"oxford":{"phon":"ˈspɪnstə(r)","pos":"noun","senses":[{"en":"a word for a woman who is not married and is no longer young that is now considered offensive","cn":"老处女；老姑娘","ex":{"en":"The sisters were to remain spinsters for the rest of their lives.","cn":"姐妹俩将终生保持老处女的状态。"}}]}},"sphincter":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"括约肌","en":"A sphincter is a ring of muscle that surrounds an opening to the body and that can tighten to close this opening.","ex":{"en":"...the anal sphincter.","cn":"肛门括约肌"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a muscle that surrounds an opening in your body, and can become tight in order to close the opening","cn":"括约肌"}]},"media":{"uk":"media/ldoce/hwd/bre/d/ld41sphincter.mp3","us":"media/ldoce/hwd/ame/6/sphincter.mp3"},"examples":[{"en":"the anal sphincter","cn":"肛门括约肌"}],"oxford":{"phon":"ˈsfɪŋktə(r)","pos":"noun","senses":[{"en":"a ring of muscle that surrounds an opening in the body and can become tight to close it","cn":"括约肌","ex":{"en":"the anal sphincter","cn":"肛门括约肌"}}]}},"splat":{"collins":{"senses":[{"pos":"N-SING; SOUND 单数名词；声音词","cn":"(湿物落在平面上发出的)啪嗒声，溅泼声","en":"Splat is used to describe the sound of something wet hitting a surface with a lot of force.","ex":{"en":"The egg landed on my cheek with a splat.","cn":"鸡蛋啪嚓一声打在我脸颊上。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a noise like something wet hitting a surface hard 〔","cn":"湿物击打表面时发出的〕啪嗒声"},{"en":"to make a noise like something wet hitting a surface, or to make something make this noise （","cn":"使）发出啪嗒声"}]},"media":{"uk":"media/ldoce/hwd/bre/c/ld41splat.mp3","us":"media/ldoce/hwd/ame/d/splat1.mp3"},"examples":[{"en":"The omelette fell splat onto the floor.","cn":"煎蛋饼吧唧一下掉到了地上。"},{"en":"The tomato hit the wall with a splat.","cn":"西红柿啪的一声打在墙上。"}],"oxford":{"phon":"splæt","pos":"noun","senses":[{"en":"the sound made by something wet hitting a surface with force","cn":"（湿物落在平面上的）啪嗒声","ex":{"en":"The tomato hit the wall with a splat.","cn":"西红柿啪的一声打在墙上。"}},{"en":"with the sound made by something wet hitting a surface with force","cn":"（湿物落在平面上的）啪嗒声","ex":{"en":"The omelette fell splat onto the floor.","cn":"蛋饼啪嗒一声掉在地上。"},"pos":"adverb"}]}},"spar":{"collins":{"senses":[{"pos":"V-RECIP 相互动词","cn":"(拳击中为练习或试探对手反应快慢而)轻拳出击","en":"If you spar with someone, you box using fairly gentle blows instead of hitting your opponent hard, either when you are training or when you want to test how quickly your opponent reacts.","ex":{"en":"With protective gear on you can spar with a partner","cn":"戴上护具后可以和对手练习轻拳出击。"}},{"pos":"V-RECIP 相互动词","cn":"争论，争辩，拌嘴(但不动真格的)","en":"If you spar with someone, you argue with them but not in an aggressive or serious way.","ex":{"en":"Over the years he sparred with his friend Jesse Jackson over political tactics","cn":"这些年以来，他一直跟他的朋友杰西·杰克逊为政治手腕的问题争论不休。"}},{"pos":"N-COUNT 可数名词","cn":"粗杆;(帆船的)桅杆","en":"A spar is a strong pole, especially one that a sail is attached to on a sailing ship.","ex":{"en":"The mast, which was a solid spruce spar, bent like a bow, and for a moment I thought we were going to lose it.","cn":"坚固的云杉木做成的桅杆已经弯得像一把弓，那一刻我觉得它马上就要断了。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to practise boxing with someone 〔","cn":"与某人〕练拳击"},{"en":"to argue with someone but not in an unpleasant way 〔","cn":"友好地〕争论﹐争辩"},{"en":"a thick pole, especially one used on a ship to support sails or ropes","cn":"圆材〔尤用作船舶的桅杆〕"}]},"vocab":{"pos":"1 n v 2 n v 3 n","senses":[{"en":"If you spar with someone, you exchange light blows — either literally by punching each other, or figuratively by exchanging verbal blows."}]},"media":{"uk":"media/ldoce/hwd/bre/b/brelasdespar.mp3","us":"media/ldoce/hwd/ame/6/spar1.mp3"},"examples":[{"en":"He broke his nose while sparring with Vega.","cn":"他和维加一起练拳击时给打断了鼻梁骨。"},{"en":"Senators are sparring over the health bill.","cn":"参议员们就医疗保健法案进行辩论。"}],"oxford":{"phon":"spɑː(r)","pos":"verb","senses":[{"en":"to make the movements used in boxing, either in training or to test the speed of your opponent’s reaction","cn":"练习拳击；虚晃一拳","g":"[intransitive]"},{"en":"to argue with somebody, usually in a friendly way","cn":"（多指在友好气氛中）辩论，争论","g":"[intransitive]","ex":{"en":"political sparring","cn":"政治斗争"}},{"en":"a strong pole used to support the sails, etc. on a ship","cn":"（船上用作桅杆等的）圆材","pos":"noun"},{"en":"a structure that supports the wing of an aircraft","cn":"（飞机的）翼梁","pos":"noun"}]}},"spike":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"金属钉状物;尖锥;尖钉","en":"A spike is a long piece of metal with a sharp point.","ex":{"en":"...a 15-foot wall topped with iron spikes","cn":"顶端装有铁刺的 15 英尺高的墙"}},{"pos":"N-COUNT 可数名词","cn":"细长的尖状物","en":"Any long pointed object can be referred to as a spike .","ex":{"en":"Her hair stood out in spikes.","cn":"她的头发一簇簇竖立着。"}},{"pos":"N-COUNT 可数名词","cn":"(价格、数量的)突然上升，剧增","en":"If there is a spike in the price, volume, or amount of something, the price, volume, or amount of it suddenly increases.","ex":{"en":"Although you'd think business would have boomed during the war, there was only a small spike in interest.","cn":"人们会认为战争期间生意会很红火，但实际上利息只有小幅上升。"}},{"pos":"N-PLURAL 复数名词","cn":"(跑步运动员穿的)钉鞋，跑鞋","en":"Spikes are a pair of sports shoes with pointed pieces of metal attached to the soles. They help runners' feet to grip the ground when they are running."},{"pos":"VERB 动词","cn":"偷偷往(饮料中)搀烈性酒(或毒品)","en":"If your drink is spiked, someone has added alcohol or drugs to it without telling you.","ex":{"en":"They wondered whether their drinks had been spiked.","cn":"他们有些疑惑自己的饮料里是否被偷偷搀了烈性酒。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"something long and thin with a sharp point, especially a pointed piece of metal","cn":""},{"en":"a sudden large increase in the number or rate of something","cn":""},{"en":"shoes with metal points on the bottom, worn by people who run races, play golf etc","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/4/spike_v0205.mp3","us":"media/ldoce/hwd/ame/8/spike1.mp3"},"examples":[{"en":"The article was spiked for fear of legal action against the newspaper.","cn":"因担心被提起诉讼，报社未发表那篇文章。"},{"en":"He gave her a drink spiked with tranquillizers.","cn":"他给了她一杯偷偷放了镇静剂的饮料。"}],"oxford":{"phon":"spaɪk","pos":"noun","senses":[{"en":"a thin object with a sharp point, especially a pointed piece of metal, wood, etc.","cn":"尖状物；尖头；尖刺","g":"[countable]","ex":{"en":"a row of iron spikes on a wall","cn":"墙头的一排尖铁"}},{"en":"a metal point attached to the sole of a sports shoe to prevent you from slipping while running","cn":"（防滑）鞋钉","g":"[countable, usually plural]"},{"en":"shoes fitted with these metal spikes, used for running","cn":"（赛跑用的）钉鞋","g":"[plural]","ex":{"en":"a pair of spikes","cn":"一双钉鞋"}},{"en":"a long pointed group of flowers that grow together on a single stem","cn":"穗；穗状花序","g":"[countable]"},{"en":"a sudden large increase in something","cn":"急剧上升；飙升；猛增","g":"[countable, usually singular]","ex":{"en":"a spike in oil prices","cn":"油价的急剧上涨"}},{"en":"to push a sharp piece of metal, wood, etc. into somebody/something; to injure something on a sharp point","cn":"用尖物刺入（或扎破）","g":"[transitive]","pos":"verb"},{"en":"to add alcohol, poison or a drug to somebody’s drink or food without them knowing","cn":"在…中偷偷掺入（烈酒、毒药或毒品）","g":"[transitive]","lab":"figurative","ex":{"en":"He gave her a drink spiked with tranquillizers.","cn":"他给了她一杯偷偷放了镇静剂的饮料。"},"pos":"verb"},{"en":"to reject something that a person has written or said; to prevent something from happening or being made public","cn":"拒绝发表；阻止…传播；阻挠","g":"[transitive]","ex":{"en":"The article was spiked for fear of legal action against the newspaper.","cn":"因担心被提起诉讼，报社未发表那篇文章。"},"pos":"verb"},{"en":"to rise quickly and reach a high value","cn":"迅速升值；急剧增值","g":"[intransitive]","lab":"especially North American English","ex":{"en":"The US dollar spiked to a three-month high.","cn":"美元猛然升值到三个月来的最高价。"},"pos":"verb"}]}},"spinach":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"菠菜","en":"Spinach is a vegetable with large dark green leaves that you chop up and boil in water before eating."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a vegetable with large dark green leaves","cn":"菠菜"}]},"vocab":{"pos":"n","senses":[{"en":"Spinach is a leafy green edible plant. The most famous spinach eater is probably Popeye, the cartoon sailor who grows huge, strong arm muscles after eating it."}]},"media":{"img":["media/ldoce/img/spinach.jpg"],"uk":"media/ldoce/hwd/bre/a/spinach0205.mp3","us":"media/ldoce/hwd/ame/8/spinach.mp3"},"oxford":{"phon":"ˈspɪnɪtʃ","pos":"noun","senses":[{"en":"a vegetable with large, dark-green leaves that are cooked or eaten in salads","cn":"菠菜"}]}},"spaceship":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"宇宙飞船;载人航天器","en":"A spaceship is a spacecraft that carries people through space."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a vehicle for carrying people through space","cn":"宇宙飞船"}]},"media":{"uk":"media/ldoce/hwd/bre/6/spaceship0205.mp3","us":"media/ldoce/hwd/ame/a/spaceship.mp3"},"oxford":{"phon":"ˈspeɪsʃɪp","pos":"noun","senses":[{"en":"a vehicle that travels in space, carrying people","cn":"（航天）飞船"}]}},"spurious":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"形似而实非的;虚假的;伪造的","en":"Something that is spurious seems to be genuine, but is false.","ex":{"en":"He was arrested in 1979 on spurious corruption charges","cn":"他于1979年因被诬告贪污而被捕。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(论点、推理)不正确的，站不住脚的","en":"A spurious argument or way of reasoning is incorrect, and so the conclusion is probably incorrect.","ex":{"en":"...a spurious framework for analysis","cn":"不正确的分析框架"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"not real, but intended to seem real and deceive people","cn":""},{"en":"made to look or seem like something else, especially something worth a lot more money","cn":""},{"en":"a forged official document or bank note has been illegally made to look like a real one","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"Something false or inauthentic is spurious . Don't trust spurious ideas and stories. Spurious statements often are lies, just as a spurious coin is a counterfeit coin — a fake."}]},"media":{"uk":"media/ldoce/hwd/bre/d/spurious0205.mp3","us":"media/ldoce/hwd/ame/f/spurious.mp3"},"examples":[{"en":"He had managed to create the entirely spurious impression that the company was thriving.","cn":"他设法制造出一种彻头彻尾的假象，让人误以为公司一派兴旺。"},{"en":"a spurious argument","cn":"谬误的论据"}],"oxford":{"phon":"ˈspjʊəriəs","pos":"adjective","senses":[{"en":"false, although seeming to be real or true","cn":"虚假的；伪造的","ex":{"en":"He had managed to create the entirely spurious impression that the company was thriving.","cn":"他设法制造出一种彻头彻尾的假象，让人误以为公司一派兴旺。"}},{"en":"based on false ideas or ways of thinking","cn":"建立在错误的观念（或思想方法）之上的；谬误的","ex":{"en":"a spurious argument","cn":"谬误的论据"}}]}},"sprayer":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"喷雾器;喷漆器","en":"A sprayer is a piece of equipment used for spraying liquid somewhere."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a piece of equipment that is used for spraying large amounts of liquid, especially over crops 〔","cn":"尤指农用〕喷雾器"}]},"media":{"uk":"media/ldoce/hwd/bre/7/ld41sprayer.mp3","us":"media/ldoce/hwd/ame/3/sprayer.mp3"},"examples":[{"en":"a paint/crop sprayer","cn":"喷漆器；农用喷雾器"}],"oxford":{"phon":"ˈspreɪə(r)","pos":"noun","senses":[{"en":"a piece of equipment used for spraying liquid, especially paint or a substance used to kill insects that damage crops","cn":"喷漆器；喷雾器；喷枪","ex":{"en":"a paint/crop sprayer","cn":"喷漆器；农用喷雾器"}}]}},"spoor":{"collins":{"senses":[{"pos":"N-SING 单数名词","cn":"(野兽走过时留下的)踪迹","en":"The spoor of an animal is the marks or substances that it leaves behind as it moves along, which hunters can follow."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the track of footmarks or solid waste that a wild animal leaves as it moves along 〔","cn":"野生动物留下的〕脚印﹐足迹﹔臭迹"}]},"media":{"uk":"media/ldoce/hwd/bre/6/ld41spoor.mp3","us":"media/ldoce/hwd/ame/e/spoor.mp3"},"oxford":{"phon":"spʊə(r)","pos":"noun","senses":[{"en":"a track or smell that a wild animal leaves as it travels","cn":"（野兽走过留下的）足迹，嗅迹"}]}},"spindly":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"细长而瘦弱的;瘦长的","en":"Something that is spindly is long and thin and looks very weak.","ex":{"en":"I did have rather spindly legs.","cn":"我的腿的确比较瘦长。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"long and thin in a way that looks weak","cn":"细长而不强壮的﹐纤弱的"}]},"media":{"uk":"media/ldoce/hwd/bre/6/spindly0205.mp3","us":"media/ldoce/hwd/ame/1/spindly.mp3"},"examples":[{"en":"spindly legs","cn":"细长的腿"}],"oxford":{"phon":"ˈspɪndli","pos":"adjective","senses":[{"en":"very long and thin and not strong","cn":"长而纤弱的；细长而瘦弱的","ex":{"en":"spindly legs","cn":"细长的腿"}}]}},"spiritualism":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"招魂论，通灵术(相信死人的灵魂能与活人相沟通)","en":"Spiritualism is the belief that the spirits of people who are dead can communicate with people who are still alive."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the belief that dead people are able to send messages to living people","cn":"招魂说﹐降灵说〔认为死人可以向活人传递信息〕"}]},"media":{"uk":"media/ldoce/hwd/bre/f/spiritualism0205.mp3","us":"media/ldoce/hwd/ame/d/spiritualism.mp3"},"oxford":{"phon":"ˈspɪrɪtʃuəlɪzəm","pos":"noun","senses":[{"en":"the belief that people who have died can send messages to living people, usually through a medium (= a person who has special powers)","cn":"招魂说，招魂术（认为亡灵可通过灵媒或以其他方式向活人传达信息）"}]}},"spontaneity":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"自然行为;自发动作","en":"Spontaneity is spontaneous, natural behaviour.","ex":{"en":"He had the spontaneity of a child.","cn":"他有着孩童般的率性。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"something that is spontaneous is done because you suddenly feel you want to do it, not because you have arranged to do it or been asked to do it","cn":""},{"en":"done or happening without any planning or preparation","cn":""},{"en":"something that is not well thought out has not been planned carefully enough and therefore is unlikely to work well","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"Acting with spontaneity might mean bursting into song on the street, or throwing down your rake and jumping in a pile of leaves — in other words, doing something without thinking it through beforehand."}]},"media":{"uk":"media/ldoce/hwd/bre/3/spontaneous0205.mp3","us":"media/ldoce/hwd/ame/8/spontaneous.mp3"},"examples":[{"en":"The crowd gave a spontaneous cheer.","cn":""},{"en":"My spontaneous reaction was to run away.","cn":""}],"oxford":{"phon":"ˌspɒntəˈneɪəti","pos":"noun","senses":[{"en":"the quality of being spontaneous","cn":"自发性；自然","ex":{"en":"There is a lack of spontaneity in her performance.","cn":"她的表演缺乏自发性。"}}]}},"spherical":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"球状的;球形的","en":"Something that is spherical is round like a ball.","ex":{"en":"...purple and gold spherical earrings.","cn":"紫色和金色的球形耳环"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"shaped like a ball - use this in technical contexts","cn":""},{"en":"having the shape of a sphere","cn":"球形的﹐球状的"}]},"vocab":{"pos":"adj","senses":[{"en":"A ball is spherical; it's shaped like a sphere — a three-dimensional version of the two-dimensional circle."}]},"media":{"uk":"media/ldoce/hwd/bre/4/spherical0205.mp3","us":"media/ldoce/hwd/ame/0/spherical.mp3"},"oxford":{"phon":"ˈsferɪkl","pos":"adjective","senses":[{"en":"like a sphere in shape","cn":"球形的；球状的"}]}},"sponsor":{"collins":{"senses":[{"pos":"VERB 动词","cn":"(常出于广告目的而)赞助，资助","en":"If an organization or an individual sponsors something such as an event or someone's training, they pay some or all of the expenses connected with it, often in order to get publicity for themselves.","ex":{"en":"Mercury, in association with The Independent, is sponsoring Britain's first major Pop Art exhibition for over 20 years","cn":"《信使报》正携手《独立报》一起为 20 多年来英国举办的首届大型通俗艺术展览提供赞助。"}},{"pos":"VERB 动词","cn":"(为慈善事业而)赞助，资助","en":"In Britain, if you sponsor someone who is doing something to raise money for charity, for example trying to walk a certain distance, you agree to give them a sum of money for the charity if they succeed in doing it.","ex":{"en":"Please could you sponsor me for my school's campaign for Help the Aged?","cn":"我在参加我们学校举办的“助老”募捐活动，您能赞助我吗？"}},{"pos":"VERB 动词","cn":"倡议，发起(某项提议或建议)","en":"If you sponsor a proposal or suggestion, you officially put it forward and support it.","ex":{"en":"Eight senators sponsored legislation to stop the military funding.","cn":"8 位参议员支持立法停止军事拨款。"}},{"pos":"VERB 动词","cn":"(国家或组织)发起，组织，主办","en":"When a country or an organization such as the United Nations sponsors negotiations between countries, it suggests holding the negotiations and organizes them.","ex":{"en":"Given the strength of pressure on both sides, the superpowers may well have difficulties sponsoring negotiations","cn":"迫于来自对方的强大压力，两个超级大国想要组织谈判肯定会有困难。"}},{"pos":"VERB 动词","cn":"(一国)坐视(某次袭击事件)而不顾，支持","en":"If one country accuses another of sponsoring attacks on it, they mean that the other country does not do anything to prevent the attacks, and may even encourage them.","ex":{"en":"We have to make the states that sponsor terrorism pay a price.","cn":"我们必须让那些支持恐怖主义的国家付出代价。"}},{"pos":"VERB 动词","cn":"赞助(电视节目);做…的广告赞助商","en":"If a company or organization sponsors a television programme, they pay to have a special advertisement shown at the beginning and end of the programme, and at each commercial break.","ex":{"en":"Companies will now be able to sponsor programmes on ITV and Channel 4.","cn":"现在公司可以在独立电视台和第 4 频道上出资做节目广告了。"}},{"pos":"N-COUNT 可数名词","cn":"赞助人;资助人;倡议者;发起人;主办者","en":"A sponsor is a person or organization that sponsors something or someone.","ex":{"en":"I understand Coca-Cola are to be named as the new sponsors of the League Cup later this week","cn":"我知道可口可乐公司将在本周晚些时候被指定为联赛杯的新赞助商。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a person or company that pays for a show, broadcast, sports event etc, especially in exchange for the right to advertise at that event 〔","cn":"表演﹑广播节目﹑体育赛事等的〕赞助者﹐赞助商"},{"en":"a person or company that supports someone by paying for their training, education, living costs etc 〔","cn":"为某人支付培训费﹑教育费﹑生活费等的〕资助者"},{"en":"someone who agrees to give someone else money for a charity if they walk, run etc a particular distance 〔","cn":"慈善募捐活动的〕捐资者﹐捐款人"}]},"vocab":{"pos":"n v","senses":[{"en":"A sponsor provides support for someone or something, typically by supplying cash. Because your company is a sponsor for a homeless organization, they provide funding for the annual 5K run to raise money for the shelter."}]},"collocations":{"phrases":["ADJ. big, major | main | potential | private | official | commercial, corporate, industrial","VERB + SPONSOR look for, seek | attract, find, get | act as","SPONSOR + VERB back sb/sth, support sb/sth","SPONSOR + NOUN money","PREP. ~ for/of I need to find some more sponsors for my bike ride to Brighton."]},"media":{"uk":"media/ldoce/hwd/bre/1/sponsor_n0205.mp3","us":"media/ldoce/hwd/ame/2/sponsor1.mp3"},"examples":[{"en":"I'm collecting sponsors for next week's charity run.","cn":"我正在为下星期的募款赛跑征集捐款者。"},{"en":"The race organizers are trying to attract sponsors.","cn":"比赛的组织者在想方设法吸引赞助者。"}],"oxford":{"phon":"ˈspɒnsə(r)","pos":"verb","senses":[{"en":"to pay the costs of a particular event, programme, etc. as a way of advertising","cn":"赞助（活动、节目等）","ex":{"en":"Sports events are no longer sponsored by the tobacco industry.","cn":"体育赛事不再由烟草业赞助。"}},{"en":"to agree to give somebody money for a charity if they complete a particular task","cn":"为慈善活动捐资；为义赛捐款","ex":{"en":"They got their granny and aunts and other people to sponsor them.","cn":"他们找了奶奶、婶婶等人为他们捐款。"}},{"en":"to support somebody by paying for their training or education","cn":"资助（某人的培训或教育）","ex":{"en":"The corporation is sponsoring several athletes and teams here in the US.","cn":"该公司在美国这里资助了几名运动员和几支运动队。"}},{"en":"to provide money for a particular activity","cn":"资助（某项活动）","ex":{"en":"The group has been accused of sponsoring terrorism.","cn":"该组织被控资助恐怖活动。"}},{"en":"to arrange for something official to take place","cn":"主办；举办；促成","ex":{"en":"The US is sponsoring negotiations between the two sides.","cn":"美国正在安排双方的谈判。"}},{"en":"to introduce a proposal for a new law, etc.","cn":"倡议，提交（法案等）","ex":{"en":"The bill was sponsored by a Labour MP.","cn":"这项议案是一位工党议员提交的。"}},{"en":"a person or company that pays for a radio or television programme, or for a concert or sporting event, usually in return for advertising","cn":"（广播电视节目、音乐会或体育赛事的）赞助者，赞助商","ex":{"en":"The programme is funded by a number of corporate sponsors.","cn":"这个节目由多家赞助公司资助。"},"pos":"noun"},{"en":"a person who agrees to give somebody money for a charity if that person succeeds in completing a particular activity","cn":"为慈善活动捐资的人；义赛（或义演等）捐款者","ex":{"en":"Even though the race is still ten weeks away, we are already looking for sponsors.","cn":"尽管距离比赛还有十周，我们已经在寻找赞助商了。"},"pos":"noun"},{"en":"a person or company that supports somebody by paying for their training or education","cn":"（培训或教育的）资助者","ex":{"en":"Each student's tuition was paid by an individual sponsor.","cn":"每个学生的学费都由一名资助者支付。"},"pos":"noun"},{"en":"a person, a group, an organization, etc. that provides money for an activity","cn":"（为活动提供资金的）支持者，资助者","ex":{"en":"the list of state sponsors of terrorism","cn":"支持恐怖主义国家名单"},"pos":"noun"},{"en":"a person who introduces and supports a proposal for a new law, etc.","cn":"（法案等的）倡议者，发起人，倡导者","ex":{"en":"the sponsor of the new immigration bill","cn":"新移民法案的倡议者"},"pos":"noun"},{"en":"a person who agrees to be officially responsible for another person","cn":"保人；保证人","pos":"noun"},{"en":"a person who presents a candidate for Christian baptism or confirmation","cn":"代父（或母）；教父（或母）；（洗礼、坚信礼等的）引领人","pos":"noun"}]}},"spittle":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"唾液;唾沫","en":"Spittle is the watery liquid which is produced in your mouth.","ex":{"en":"Spittle oozed down his jaw.","cn":"唾液顺着他的下巴流下来。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the liquid in your mouth","cn":"唾沫﹐口水"}]},"media":{"uk":"media/ldoce/hwd/bre/f/ld41spittle.mp3","us":"media/ldoce/hwd/ame/4/spittle.mp3"},"oxford":{"phon":"ˈspɪtl","pos":"noun","senses":[{"en":"the liquid that forms in the mouth","cn":"唾沫；口水"}]}},"spacy":{"collins":{"senses":[{"pos":"","cn":"","en":"→see: ;"}]}},"spiel":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(常指招徕生意的)叫卖词，推销套话","en":"Someone's spiel is a well-prepared speech that they make, and that they have usually made many times before, often in order to persuade you to buy something."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a quick speech that the speaker has used many times before, especially one that is intended to persuade people to buy something 〔","cn":"推销商品用的〕长串的套话﹐油嘴滑舌的游说"}]},"vocab":{"pos":"n v","senses":[{"en":"A spiel is a lengthy, often glib talk that's intended to persuade or make excuses. Infomercials feature salespeople giving a 30-minute spiel about some product."}]},"media":{"uk":"media/ldoce/hwd/bre/f/spiel0205.mp3","us":"media/ldoce/hwd/ame/3/spiel.mp3"},"examples":[{"en":"A salesman started giving us a spiel about life insurance.","cn":"一名推销员开始夸夸其谈﹐向我们推销人寿保险。"}],"oxford":{"phon":"ʃpiːl","pos":"noun","senses":[{"en":"a speech that somebody has used many times that is intended to persuade you to believe something or buy something","cn":"油嘴滑舌的游说；一长串招徕生意的套话；话术","ex":{"en":"The salesman went into a long spiel about the merits of the new design.","cn":"推销员长篇大论地介绍了新设计的优点。"}}]}},"spite":{"collins":{"senses":[{"pos":"PREP-PHRASE 短语介词","cn":"尽管;不顾;虽然","en":"You use in spite of to introduce a fact which makes the rest of the statement you are making seem surprising.","ex":{"en":"Josef Krips at the State Opera hired her in spite of the fact that she had never sung on stage","cn":"尽管她从未在舞台上演唱过，国家歌剧院的约瑟夫·克里普斯还是聘用了她。"}},{"pos":"PREP-PHRASE 短语介词","cn":"不由自主地;不禁","en":"If you do something in spite of yourself, you do it although you did not really intend to or expect to.","ex":{"en":"The blunt comment made Richard laugh in spite of himself","cn":"这番率直的话让理查德不由自主地大笑起来。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"恶意;怨恨","en":"If you do something cruel out of spite, you do it because you want to hurt or upset someone.","ex":{"en":"I refused her a divorce, out of spite I suppose","cn":"我拒绝和她离婚，就是为了出口恶气。"}},{"pos":"VERB 动词","cn":"(故意做坏事来)伤害，激怒","en":"If you do something cruel to spite someone, you do it in order to hurt or upset them.","ex":{"en":"Pantelaras was giving his art collection away for nothing, to spite Marie and her husband.","cn":"潘特拉拉斯将自己的艺术藏品全都无偿捐了出去，存心要激怒玛丽和她的丈夫。"}},{"pos":"","cn":"","en":"to cut off your nose to spite your face→see: ;"}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"even though something happens or is true, especially something bad","cn":""},{"en":"deliberately cruel and unkind to someone because you really want to upset them and enjoy doing so","cn":""},{"en":"deliberately nasty to someone in order to hurt or upset them, especially because you are jealous of them or are angry with them","cn":""}]},"vocab":{"pos":"n v","senses":[{"en":"When your sister told you that you looked terrible in your new tube top, she may have been saying it out of spite , or in a deliberately mean or offensive way."}]},"collocations":{"phrases":["ADJ. pure | personal","VERB + SPITE be full of, feel She was angry and full of spite. | vent He vented his spite on his grandfather.","PREP. out of ~ She killed her neighbour's cow out of pure spite. | with ~ &lsquo;Your cooking is hard to forget&rsquo;, he said with spite. "]},"media":{"uk":"media/ldoce/hwd/bre/1/spite_n0205.mp3","us":"media/ldoce/hwd/ame/4/spite1.mp3"},"examples":[{"en":"English became the official language for business in spite of the fact that the population was largely Chinese.","cn":"虽然当地居民主要是中国人，英语却成了商业上正式使用的语言。"},{"en":"They went swimming in spite of all the danger signs.","cn":"他们无视所有那些危险水域告示牌，还是去游泳了。"}],"oxford":{"phon":"spaɪt","pos":"noun","senses":[{"en":"a feeling of wanting to hurt or upset somebody","cn":"恶意；怨恨","ex":{"en":"I'm sure he only said it out of spite.","cn":"我相信他只是为了泄愤才那么说的。"}},{"en":"to deliberately annoy or upset somebody","cn":"故意使烦恼；存心使苦恼","ex":{"en":"They're playing the music so loud just to spite us.","cn":"他们把音乐放得这么响就是存心要搅扰我们。"},"pos":"verb"}]}},"spear":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"矛;投枪;梭镖","en":"A spear is a weapon consisting of a long pole with a sharp metal point attached to the end."},{"pos":"VERB 动词","cn":"用矛(投)刺;叉住","en":"If you spear something, you push or throw a pointed object into it.","ex":{"en":"Spear a piece of fish with a carving fork and dip it in the batter","cn":"用切肉叉叉一片鱼肉，在面糊里蘸一下。"}},{"pos":"N-COUNT 可数名词","cn":"(芦笋、花椰菜等的)嫩茎","en":"Asparagus or broccoli spears are individual stalks of asparagus or broccoli."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a pole with a sharp pointed blade at one end, used as a weapon in the past","cn":"矛﹔标枪"},{"en":"a thin pointed stem of a plant","cn":"嫩芽﹐嫩枝﹐嫩茎"},{"en":"to push or throw a spear into something, especially in order to kill it","cn":"用矛刺"}]},"vocab":{"pos":"n v","senses":[{"en":"A spear consists of a long shaft that has a sharp point at one end. You might use one to go spear fishing, but that's about it. Spears are no longer the weapon of choice."}]},"collocations":{"phrases":["ADJ. hunting","VERB + SPEAR be armed with, carry The tribesmen were armed with spears and shields. | lift, raise | brandish | hurl, throw | thrust","PHRASES the point of a spear She had a fish impaled on the point of her spear."]},"media":{"uk":"media/ldoce/hwd/bre/6/spear_v0205.mp3","us":"media/ldoce/hwd/ame/d/spear1.mp3","img":["media/thumb/spear.jpg"]},"examples":[{"en":"She speared an olive with her fork.","cn":"她用叉子叉了一个橄榄。"},{"en":"They were standing in the river spearing fish.","cn":"他们站在河里叉鱼。"}],"oxford":{"phon":"spɪə(r)","pos":"noun","senses":[{"en":"a weapon with a long wooden handle and a sharp metal point used for fighting, hunting and fishing in the past","cn":"矛；标枪","ex":{"en":"She had a fish impaled on the point of her spear.","cn":"她矛尖上叉住了一条鱼。"}},{"en":"the long pointed stem of some plants","cn":"（某些植物的）嫩枝，幼芽"},{"en":"to throw or push a spear or other pointed object through something/somebody","cn":"用矛刺；用尖物刺穿","ex":{"en":"They were standing in the river spearing fish.","cn":"他们站在河里叉鱼。"},"pos":"verb"}]}},"spongy":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"海绵般松软而有弹性的","en":"Something that is spongy is soft and can be pressed in, like a sponge.","ex":{"en":"We liked the bike's spongy handgrip for keeping our hands away from cold metal","cn":"我们喜欢这辆自行车的软把手，有了它，我们的双手就不用再接触冰冷的金属了。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"not hard, firm, or stiff, but easy to press","cn":""},{"en":"used about meat or vegetables that are soft and easy to cut, especially because they have been well cooked","cn":""},{"en":"very wet and too soft, in a way that seems unpleasant – used about bread, vegetables, and the ground","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/c/spongy0205.mp3","us":"media/ldoce/hwd/ame/e/spongy.mp3"},"examples":[{"en":"The ground was soft and spongy.","cn":"土地松软，像海绵似的。"},{"en":"The bread had a spongy texture.","cn":"那种面包很松软。"}],"oxford":{"phon":"ˈspʌndʒi","pos":"adjective","senses":[{"en":"soft and able to hold water easily like a sponge","cn":"海绵似的；柔软吸水的","ex":{"en":"spongy moss","cn":"海绵似的苔藓"}}]}},"speechless":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"(因惊愕)一时语塞的","en":"If you are speechless, you are temporarily unable to speak, usually because something has shocked you.","ex":{"en":"Alex was almost speechless with rage and despair.","cn":"亚历克斯又生气又绝望，几乎说不出话来。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"having the feeling you get when something happens that you did not expect","cn":""},{"en":"extremely surprised, especially by something good or by something that seems hard to believe","cn":""},{"en":"extremely surprised","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"If you’re speechless , you can’t talk, usually because something surprising and crazy happened. You might be rendered speechless if you win the lottery or find a whale on your front lawn."}]},"collocations":{"phrases":["VERBS be, remain, sit, stand Rachel stood speechless. | leave sb, render sb The news left us all speechless.","ADV. completely, totally | almost, practically | for a moment, momentarily, temporarily","PREP. with He was almost speechless with anger."]},"media":{"uk":"media/ldoce/hwd/bre/5/brelasdespeechless.mp3","us":"media/ldoce/hwd/ame/7/speechless.mp3"},"examples":[{"en":"Laura was speechless with rage.","cn":"劳拉气得说不出话来。"},{"en":"His comments left me speechless with rage.","cn":"他的那番话气得我说不出话来。"}],"oxford":{"phon":"ˈspiːtʃləs","pos":"adjective","senses":[{"en":"not able to speak, especially because you are extremely angry or surprised","cn":"（尤指气得或惊讶得）说不出话的","ex":{"en":"Laura was speechless with rage.","cn":"劳拉气得说不出话来。"}}]}},"sphinx":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"斯芬克斯，狮身人面像(古埃及人建造于金字塔旁的巨大雕像，神话中传说它会出谜语来为难人);神秘的人;令人困惑不解的人","en":"The Sphinx is a large ancient statue of a creature with a human head and a lion's body that stands near the pyramids in Egypt. In mythology, sphinxes gave people puzzles to solve, and so a person who is mysterious or puzzling is sometimes referred to as a sphinx .","ex":{"en":"It suited him to play the sphinx.","cn":"让他演神秘莫测的人很合适。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"an ancient Egyptian image of a lion with a human head, lying down 〔","cn":"古埃及的〕狮身人面像﹐斯芬克斯（像）"}]},"media":{"uk":"media/ldoce/hwd/bre/7/sphinx0205.mp3","us":"media/ldoce/hwd/ame/8/sphinx1.mp3"},"oxford":{"phon":"sfɪŋks","pos":"noun","senses":[{"en":"an ancient Egyptian stone statue of a creature with a human head and the body of a lion lying down. In ancient Greek stories the Sphinx spoke in riddles.","cn":"斯芬克斯，狮身人面像（古埃及石像；在希腊神话中，斯芬克斯说话惯用谜语）","ex":{"en":"a sphinx-like enigma/smile","cn":"狮身人面像般的谜/微笑"}}]}},"spyware":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"间谍软件(能秘密记录用户网站浏览信息的计算机软件)","en":"Spyware is computer software that secretly records information about which websites you visit.","ex":{"en":"The publishers promise not to use spyware to grab your personal information or otherwise compromise privacy.","cn":"出版商承诺不会用间谍软件来获取个人信息，或用其他的办法破坏个人隐私。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"computer software that secretly records information about which websites you visit. This information is then used by advertising companies, who try to sell you products.","cn":"间谍软件"}]},"media":{"uk":"media/ldoce/hwd/bre/2/ld42spyware.mp3","us":"media/ldoce/hwd/ame/2/ld42spyware.mp3"},"oxford":{"phon":"ˈspaɪweə(r)","pos":"noun","senses":[{"en":"software that enables somebody to obtain secret information about somebody else and their computer activities without their knowledge or permission","cn":"间谍软件（可窃取他人秘密及其计算机活动情况）","ex":{"en":"Hackers can install spyware to get all your passwords.","cn":"黑客能通过安装间谍软件来获取你的所有密码。"}}]}},"spatula":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(烹调用的)刮刀，刮勺，刮铲","en":"A spatula is an object like a knife with a wide, flat blade. Spatulas are used in cooking.","ex":{"en":"Spoon the batter into the prepared pan, smoothing over the top with a spatula.","cn":"将面糊舀入备好的平底锅中，用刮铲将表面抹平。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a kitchen tool with a wide flat blade, used for spreading, mixing, or lifting soft substances","cn":"抹刀，铲〔厨房用具〕"},{"en":"a small instrument with a flat surface, used by doctors to hold your tongue down so that they can examine your throat 〔","cn":"医生用的〕压舌板"}]},"vocab":{"pos":"n","senses":[{"en":"Don’t even think about making pancakes if you don’t have a spatula . What else would you flip them with?"}]},"media":{"uk":"media/ldoce/hwd/bre/6/ld41spatula.mp3","us":"media/ldoce/hwd/ame/b/spatula.mp3"},"oxford":{"phon":"ˈspætʃələ","pos":"noun","senses":[{"en":"a tool with a broad flat part that is not sharp, used for mixing and spreading things, especially in cooking and painting","cn":"（烹饪、油漆等活动中用以调拌或涂敷的）铲，刮勺，抹刀，刮刀"},{"en":"a kitchen utensil that has a broad flat part with narrow holes in it, attached to a long handle, used for turning and lifting food when cooking","cn":"锅铲，煎鱼铲（铲面有细长孔）","lab":"North American English"},{"en":"a thin flat instrument that doctors use for pressing the tongue down when they are examining somebody’s throat","cn":"压舌板，压舌器（医生诊症用）","lab":"British English"}]}},"spill":{"collins":{"senses":[{"pos":"V-ERG 及物/不及物动词","cn":"(使)溢出;(使)泼出;(使)洒出","en":"If a liquid spills or if you spill it, it accidentally flows over the edge of a container.","ex":{"en":"70,000 tonnes of oil spilled from the tanker","cn":"7 万吨油从油轮中溢了出来。"}},{"pos":"N-COUNT 可数名词","cn":"溢出量;溢出物","en":"A spill is an amount of liquid that has spilled from a container.","ex":{"en":"She wiped a spill of milkshake off the counter","cn":"她把洒出来的奶昔从柜台上擦掉。"}},{"pos":"V-ERG 及物/不及物动词","cn":"(使)(袋子、盒子等中盛放的东西)洒出，涌出","en":"If the contents of a bag, box, or other container spill or are spilled, they come out of the container onto a surface.","ex":{"en":"A number of bags had split and were spilling their contents","cn":"有几只袋子裂开了，里面的东西撒了出来。"}},{"pos":"VERB 动词","cn":"蜂拥而出","en":"If people or things spill out of a place, they come out of it in large numbers.","ex":{"en":"Tears began to spill out of the boy's eyes","cn":"男孩的眼泪开始夺眶而出。"}},{"pos":"V-ERG 及物/不及物动词","cn":"（使）(光线)透进，洒落","en":"If light spills or is spilled into a place, it shines brightly into it, usually through a gap.","ex":{"en":"She noticed the light spilling under Brian's door","cn":"她注意到布莱恩门底下透出的光。"}},{"pos":"PHRASE 短语","cn":"杀死;弄伤","en":"If you spill someone's blood, you kill them or wound them.","ex":{"en":"He is prepared to spill the blood of a million people","cn":"他准备杀掉100万人。"}},{"pos":"","cn":"","en":"to spill the beans→see: ; thrills and spills→see: ;"},{"pos":"","cn":"","en":"相关词组：spill out"}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to make a liquid or other substance flow out of or into a container by holding it at an angle","cn":""},{"en":"to pour a liquid onto food in small drops or in a small stream – often used in cooking instructions","cn":""},{"en":"to pour something out of a container by turning it upside down","cn":""}]},"collocations":{"phrases":["ADV. almost | accidentally | out, over He nodded, his tears spilling over.","VERB + SPILL try not to | let sth He opened the curtains, letting the morning light spill into the room.","PREP. down, from, into, onto, out of, over I accidentally spilled my drink all over him."]},"media":{"img":["media/ldoce/img/spill.jpg"],"uk":"media/ldoce/hwd/bre/b/spill_v0205.mp3","us":"media/ldoce/hwd/ame/1/spill1.mp3"},"examples":[{"en":"Thousands of gallons of crude oil were spilled into the ocean.","cn":"成千上万加仑的原油泄漏，流进了海洋。"},{"en":"She filled the glass so full that the water spilled over.","cn":"她往杯子里倒水倒得太满，都溢出来了。"}],"oxford":{"phon":"spɪl","pos":"verb","senses":[{"en":"to flow over the edge of a container by accident; to make liquid do this","cn":"（使）洒出，泼出，溢出","g":"[intransitive, transitive]","lab":"figurative","ex":{"en":"Water had spilled out of the bucket onto the floor.","cn":"桶里的水洒出来了，洒了一地。"}},{"en":"to come out of a place in large numbers and spread out","cn":"涌出；蜂拥而出","g":"[intransitive]","ex":{"en":"The doors opened and people spilled into the street.","cn":"门开了，人们涌上街道。"}},{"en":"an act of letting a liquid come or fall out of a container; the amount of liquid that comes or falls out","cn":"洒出（量）；泼出（量）；溢出（量）；泄漏（量）","g":"[countable]","lab":"formal","ex":{"en":"Many seabirds died as a result of the oil spill.","cn":"许多海鸟死于这次石油泄漏。"},"pos":"noun"},{"en":"a long match, or a thin piece of twisted paper, used for lighting fires, oil lamps, etc.","cn":"（点火用的）长梗火柴，纸捻","g":"[countable]","pos":"noun"},{"en":"a fall, especially from a bicycle or a boat","cn":"（尤指从自行车或船上）摔下，跌落","g":"[countable, usually singular]","ex":{"en":"to take a spill","cn":"（骑车）摔一跤"},"pos":"noun"}]}},"speakerphone":{"collins":{"senses":[{"pos":"","cn":"免提电话（内置麦克风和扬声器，无需手持）","en":"A speakerphone is a telephone that has a microphone and a loudspeaker, allowing you to talk to someone without putting the phone to your ear, as well as allowing other people to hear the person you are talking to.","ex":{"en":"...a 10-channel cordless speakerphone with 13-number memory.","cn":"可储存13个电话号码的10信道无绳免提电话"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a telephone that contains a microphone and a loudspeaker , so that you can use it without holding it. Speakerphones are especially used in business meetings when groups of people in different places want to talk to each other.","cn":"会议电话，免提通话扬声器〔内置麦克风和扬声器﹐使用时无须手持﹐尤用于商务会议〕"}]},"media":{"uk":"media/ldoce/hwd/bre/1/ld41speakerphone.mp3","us":"media/ldoce/hwd/ame/1/ld41speakerphone.mp3"},"oxford":{"phon":"ˈspiːkəfəʊn","pos":"noun","senses":[{"en":"a phone that can be used without being held, because it contains a microphone and a loudspeaker","cn":"扬声电话（内置麦克风和扬声器，使用时无须拿起听筒）"}]}},"sprightly":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(尤指老人)生气勃勃的，充满活力的，精力充沛的","en":"A sprightly person, especially an old person, is lively and active.","ex":{"en":"...the sprightly 85-year-old President.","cn":"精神矍铄的 85 岁的总统"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"an old person who is sprightly is still active and full of energy – used to show approval 〔","cn":"老人〕活跃的﹐充满活力的〔含褒义〕"}]},"vocab":{"pos":"adj","senses":[{"en":"To be sprightly is to be full of youthful, vibrant energy. You don’t have to be young to be sprightly , though, energetic old people can be sprightly , too. Weeeeeee!"}]},"media":{"uk":"media/ldoce/hwd/bre/a/sprightly0205.mp3","us":"media/ldoce/hwd/ame/c/sprightly.mp3"},"examples":[{"en":"a sprightly 80-year-old","cn":"精神矍铄的 80 岁老人"}],"oxford":{"phon":"ˈspraɪtli","pos":"adjective","senses":[{"en":"full of life and energy","cn":"精力充沛的；精神矍铄的","ex":{"en":"a sprightly 80-year-old","cn":"精神矍铄的 80 岁老人"}}]}},"sprigged":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"(织物或纸张)带有叶片（或花卉）图案的","en":"Sprigged material or paper has a pattern of small leaves or flowers on it.","ex":{"en":"...a sprigged cotton dress","cn":"棉质碎花连衣裙"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"sprigged cloth or a sprigged pattern is decorated with leaves or flowers on stems 〔","cn":"布等〕饰有带叶[花]小枝图案的"}]},"media":{"uk":"media/ldoce/hwd/bre/3/ld41sprigged.mp3","us":"media/ldoce/hwd/ame/3/ld41sprigged.mp3"},"oxford":{"phon":"sprɪɡd","pos":"adjective","senses":[{"en":"decorated with patterns of stems with leaves or flowers on","cn":"枝状的：装饰着带有叶子或花朵的茎状图案"}]}},"speckled":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"布满斑点的","en":"A speckled surface is covered with small marks, spots, or shapes.","ex":{"en":"...a large brown speckled egg","cn":"布满棕色斑点的大个儿鸡蛋"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"covered with many small marks or spots","cn":"带有许多小斑点的﹐布满小斑点的"}]},"media":{"uk":"media/ldoce/hwd/bre/7/brelasdespeckled.mp3","us":"media/ldoce/hwd/ame/3/laadspeckled.mp3"},"examples":[{"en":"speckled eggs","cn":"蛋壳上布满小斑点的鸡蛋"}],"oxford":{"phon":"ˈspekld","pos":"adjective","senses":[{"en":"covered with small marks or spots","cn":"布满斑点的；有色斑的"}]}},"sparkler":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(可点燃后拿在手上的)烟花，花炮","en":"A sparkler is a small firework that you can hold as it burns. It looks like a piece of thick wire and burns with a lot of small bright sparks."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a type of firework that you can hold in your hand, consisting of a thin stick that gives off sparks of fire","cn":"烟花棒"}]},"vocab":{"pos":"n","senses":[{"en":"A sparkler is a firework that glows and sparks as you hold in you hand. A sparkler burns very slowly, giving you time to wave it around and make patterns in the dark before its flame goes out."}]},"media":{"uk":"media/ldoce/hwd/bre/5/sparkler0205.mp3","us":"media/ldoce/hwd/ame/f/sparkler.mp3"},"oxford":{"phon":"ˈspɑːklə(r)","pos":"noun","senses":[{"en":"a type of small firework that you hold in your hand and light. It burns with many bright sparks.","cn":"烟花棒"}]}},"spring-clean":{"collins":{"senses":[{"pos":"VERB 动词","cn":"彻底打扫","en":"When you spring-clean a house, you thoroughly clean everything in it.","ex":{"en":"It's almost as easy these days to give your rooms a new coat of paint as it is to spring-clean them.","cn":"如今，重新粉刷一下房间就像彻底打扫一次房间一样简单。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"to make something clean by removing the dirt, dust etc","cn":""},{"en":"to completely clean a room, cupboard etc, especially by taking everything out and putting it back in neatly","cn":""},{"en":"to clean your whole house very thoroughly, including things that you do not clean very often","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/1/ld41spring-cleanin.mp3","us":"media/ldoce/hwd/ame/6/laadspring-cleaning.mp3"},"examples":[{"en":"( BrE ) The place needed a good spring clean before we could move in.","cn":"那地方得来个大扫除，然后我们才能搬进去。"},{"en":"Fran decided to spring-clean the apartment.","cn":"弗朗决定把房间彻底打扫一下。"}],"oxford":{"phon":"ˌsprɪŋ ˈkliːn","pos":"noun","senses":[{"en":"an occasion when you clean a house, room, etc. carefully and completely, including the parts you do not usually clean","cn":"彻底打扫（房屋等）","ex":{"en":"The place needed a good spring clean before we could move in.","cn":"那地方得来个大扫除，然后我们才能搬进去。"}},{"en":"to clean a house, room, etc. carefully and completely, including the parts you do not usually clean","cn":"彻底打扫（房屋等）；进行大扫除","ex":{"en":"Fran decided to spring-clean the apartment.","cn":"弗朗决定把房间彻底打扫一下。"},"pos":"verb"}]}},"spinney":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"小树林","en":"A spinney is a small area covered with trees."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a small area of trees and bushes","cn":"小树林﹐灌木丛"}]},"media":{"uk":"media/ldoce/hwd/bre/e/ld41spinney.mp3","us":"media/ldoce/hwd/ame/e/ld41spinney.mp3"},"oxford":{"phon":"ˈspɪni","pos":"noun","senses":[{"en":"a small area of trees","cn":"小树林"}]}},"speller":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（拼写能力强或差的）拼写者","en":"If you describe someone as a good or bad speller, you mean that they find it easy or difficult to spell words correctly.","ex":{"en":"I am an absolutely appalling speller.","cn":"我的拼写能力极差。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone who is good or bad at spelling words correctly","cn":"拼写能力好/不好/差等的人"}]},"media":{"uk":"media/ldoce/hwd/bre/3/ld41speller.mp3","us":"media/ldoce/hwd/ame/3/speller.mp3"},"examples":[{"en":"words that confuse even good spellers","cn":"甚至连拼写能力很好的人都弄错的单词"}],"oxford":{"phon":"ˈspelə(r)","pos":"noun","senses":[{"en":"if somebody is a good/bad speller, they find it easy/difficult to spell words correctly","cn":"拼写能力强（或差）的人"}]}},"splashdown":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(宇宙飞船在海洋上的)溅落","en":"A splashdown is the landing of a spacecraft in the sea after a flight."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a landing by a spacecraft in the sea 〔","cn":"航天器在海上的〕溅落"}]},"media":{"uk":"media/ldoce/hwd/bre/4/ld41splashdown.mp3","us":"media/ldoce/hwd/ame/e/splashdown.mp3"},"oxford":{"phon":"ˈsplæʃdaʊn","pos":"noun","senses":[{"en":"a landing of a spacecraft in the sea","cn":"溅落（指航天器坠入海洋）","ex":{"en":"Splashdown is scheduled for 0500 hours.","cn":"Splashdown 预计在 0500 点进行。"}}]}},"sprain":{"collins":{"senses":[{"pos":"VERB 动词","cn":"扭;扭伤","en":"If you sprain a joint such as your ankle or wrist, you accidentally damage it by twisting it or bending it violently.","ex":{"en":"He fell and sprained his ankle.","cn":"他摔了一跤，扭伤了脚踝。"}},{"pos":"N-COUNT 可数名词","cn":"扭伤","en":"A sprain is the injury caused by spraining a joint."}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to damage part of your body, or someone else’s body","cn":""},{"en":"to hurt yourself quite severely, or to be hurt in an accident or fighting","cn":""},{"en":"to deliberately hurt someone using a weapon such as a knife or gun","cn":""}]},"vocab":{"pos":"v n","senses":[{"en":"To sprain one of your joints is to twist it suddenly. The result is a sprain , in which the ligaments have been injured. Don’t go hiking in high heels because you might sprain your ankle."}]},"media":{"uk":"media/ldoce/hwd/bre/f/sprain0205.mp3","us":"media/ldoce/hwd/ame/8/sprain1.mp3"},"examples":[{"en":"I stumbled and sprained my ankle.","cn":"我摔了一跤，把脚脖子扭了。"},{"en":"a bad ankle sprain","cn":"踝关节严重扭伤"}],"oxford":{"phon":"spreɪn","pos":"verb","senses":[{"en":"to injure a joint in your body, especially your wrist or ankle, by suddenly twisting it","cn":"扭伤（关节）","lab":"especially British English","ex":{"en":"I stumbled and sprained my ankle.","cn":"我摔了一跤，把脚脖子扭了。"}},{"en":"an injury to a joint in your body, especially your wrist or ankle, caused by suddenly twisting it","cn":"扭伤（关节）","ex":{"en":"a bad ankle sprain","cn":"踝关节严重扭伤"},"pos":"noun"}]}},"speakeasy":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(1920 年到 1933 年美国禁酒时期)非法经营的酒店","en":"A speakeasy was a place where people could buy alcoholic drinks illegally in the United States between 1920 and 1933, when alcohol was forbidden."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a place in the US in the 1920s and 1930s where you could buy alcohol illegally 〔20","cn":"世纪20﹑30年代美国的〕非法经营的售酒处"}]},"vocab":{"pos":"n","senses":[{"en":"During the time of Prohibition, people who wanted an alcoholic drink had to visit a speakeasy , or an illegal bar."}]},"media":{"uk":"media/ldoce/hwd/bre/4/ld41speakeasy.mp3","us":"media/ldoce/hwd/ame/e/speakeasy.mp3"},"oxford":{"phon":"ˈspiːkiːzi","pos":"noun","senses":[{"en":"a place in the US where people could buy alcohol illegally, at the time in the 1920s and 1930s when it was illegal to make or sell alcohol","cn":"（美国 20 世纪 20、30 年代禁酒期间）非法经营的酒店"}]}},"spritzer":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(用汽水和白葡萄酒调制成的)汽酒","en":"A spritzer is a drink consisting of white wine and soda water."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a drink made with soda water and white wine 〔","cn":"用汽水和白葡萄酒调制的〕汽酒"}]},"media":{"uk":"media/ldoce/hwd/bre/e/ld41spritzer.mp3","us":"media/ldoce/hwd/ame/3/spritzer.mp3"},"examples":[{"en":"a white wine spritzer","cn":"一杯白葡萄汽酒"}],"oxford":{"phon":"ˈsprɪtsə(r)","pos":"noun","senses":[{"en":"a drink made with wine (usually white) mixed with either soda water or sparkling mineral water (= with bubbles in it)","cn":"汽酒","ex":{"en":"a white wine spritzer","cn":"一杯白葡萄汽酒"}}]}},"splice":{"collins":{"senses":[{"pos":"VERB 动词","cn":"绞接(绳子);粘接(胶片、磁带等)","en":"If you splice two pieces of rope, film, or tape together, you join them neatly at the ends so that they make one continuous piece.","ex":{"en":"He taught me to edit and splice film","cn":"他教我剪辑和粘接胶片。"}},{"pos":"V-PASSIVE 被动动词","cn":"结婚","en":"When two people get spliced, they get married.","ex":{"en":"An old friend of mine, newly spliced, recently invited me to dinner in his new marital home.","cn":"我的一位刚结婚不久的老朋友最近邀请我到他的婚房去吃晚饭。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to join the ends of two pieces of rope, film etc so that they form one continuous piece","cn":"连接﹐捻接﹐接合〔两条绳子﹑胶片等的两端〕"},{"en":"to get married","cn":"步入婚姻的殿堂﹐结婚"},{"en":"the act of joining the ends of two things together, or the place where this join has been made","cn":"连接﹐接合﹔连接处﹐接合点"}]},"vocab":{"pos":"v n","senses":[{"en":"As noun and verb, splice refers to the overlapping or interweaving of two ends of something to create the strongest possible attachment."}]},"media":{"uk":"media/ldoce/hwd/bre/1/splice_v0205.mp3","us":"media/ldoce/hwd/ame/1/splice1.mp3"},"oxford":{"phon":"splaɪs","pos":"verb","senses":[{"en":"to join the ends of two pieces of rope by twisting them together","cn":"绞接，捻接（两段绳子）"},{"en":"to join the ends of two pieces of film, tape, etc. by sticking them together","cn":"胶接，黏结（胶片、磁带等）"},{"en":"the place where two pieces of film, tape, rope, etc. have been joined","cn":"胶接处；黏结处；绞接处","pos":"noun"}]}},"spain":{"ldoce":{"phon":"hwd","pos":"","senses":[{"en":"a country in southwest Europe, between France and Portugal, which includes the Balearic and Canary Islands, and is a member of the (EU European Union). Population: 47,370,542 (2014). Capital: Madrid. Some parts of Spain, especially Catalunya and the Basque cou","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/e/p028-000011433.mp3","us":"media/ldoce/hwd/ame/e/p028-000011433.mp3"},"oxford":{"phon":"speɪn","pos":"noun","senses":[{"en":"a country in south-western Europe","cn":"西班牙（西南欧国家）"}]}},"speculate":{"collins":{"senses":[{"pos":"VERB 动词","cn":"推测;猜测;猜想","en":"If you speculate about something, you make guesses about its nature or identity, or about what might happen.","ex":{"en":"Critics of the project speculate about how many hospitals could be built instead","cn":"对该项目持批评态度的人在推测如果改作他用不知可以建多少所医院。"}},{"pos":"VERB 动词","cn":"投机;做投机买卖","en":"If someone speculates financially, they buy property, stocks, or shares, in the hope of being able to sell them again at a higher price and make a profit.","ex":{"en":"Big farmers are moving in, not in order to farm, but in order to speculate with rising land prices","cn":"大农场主正在不断涌进来，不是为了耕作，而是要利用不断上涨的地价进行投机。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to give an answer or decide that something is probably true, when you do not know enough to be definitely sure","cn":""},{"en":"to guess something, especially when you are trying to answer a question or explain how something might have happened","cn":""},{"en":"to guess an answer, amount, or number - use this especially when you are telling someone to do this","cn":""}]},"vocab":{"pos":"v","senses":[{"en":"When you speculate , you use what you know to make a prediction about an outcome, like when you speculate that the injury of two key players will prevent your favorite team from going far in the playoffs this year."}]},"collocations":{"phrases":["VERB + SPECULATE can/could only | decline to, refuse to | be fascinating to, be interesting to, be tempting to | be idle to It is idle to sp","PREP. about There was no point speculating about the possibility of them getting back together. | as to We can only speculate as to this man"]},"media":{"uk":"media/ldoce/hwd/bre/6/speculate0205.mp3","us":"media/ldoce/hwd/ame/a/speculate.mp3"},"examples":[{"en":"We can speculate that the stone circles were used in some sort of pagan ceremony.","cn":"我们可以推测，这些石头排成的圆圈是用于某种异教崇拜仪式的。"},{"en":"It is useless to speculate why he did it.","cn":"对他为什么这么做妄加猜测毫无用处。"}],"oxford":{"phon":"ˈspekjuleɪt","pos":"verb","senses":[{"en":"to form an opinion about something without knowing all the details or facts","cn":"推测；猜测；推断","g":"[intransitive, transitive]","lab":"British English or formal, North American English，，","ex":{"en":"We all speculated about the reasons for her resignation.","cn":"我们大家都推测过她辞职的原因。"}},{"en":"to buy goods, property, shares, etc., hoping to make a profit when you sell them, but with the risk of losing money","cn":"投机；做投机买卖","g":"[intransitive]","ex":{"en":"He likes to speculate on the stock market.","cn":"他喜欢炒股。"}}]}},"speculation":{"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"an attempt to guess something","cn":""},{"en":"an opinion about the value, size, speed etc of something that is formed partly by calculating and partly by guessing","cn":""},{"en":"when you try to understand something or find the answer to something by guessing, because you do not have all the information you need","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"When you guess about how something is going to come out (or how it happened), that's speculation . You're making an educated guess."}]},"collocations":{"phrases":["ADJ. considerable, intense, much, widespread | further, increasing, renewed | continuing, endless | pure | mere Whether or not he will get t","VERB + SPECULATION cause, encourage, fuel, give rise to, increase, intensify, invite, lead to, prompt, raise | dampen, discourage, end, put ","PREP. amid ~ He was dropped from the team amid speculation that he was seriously ill. | ~ among There was wild speculation among the student","PHRASES a matter for speculation, a subject of speculation 2 buying and selling for profit","ADJ. financial | market | currency, land, property, etc.","PREP. ~ against speculation against the euro | ~ in speculation in oil | ~ on speculation on the stock market"]},"media":{"uk":"media/ldoce/hwd/bre/3/ld41speculation.mp3","us":"media/ldoce/hwd/ame/5/speculation.mp3"},"examples":[{"en":"Today's announcement ends months of speculation about the company's future.","cn":"今天的声明使得几个月来关于公司未来的种种猜测就此烟消云散。"},{"en":"She dismissed the newspaper reports as pure speculation.","cn":"她说报纸上的报道毫无根据，纯属臆断。"}],"oxford":{"phon":"ˌspekjuˈleɪʃn","pos":"noun","senses":[{"en":"the act of forming opinions about what has happened or what might happen without knowing all the facts","cn":"推测；猜测；推断","ex":{"en":"His private life is the subject of much speculation.","cn":"他的私生活引起诸多猜测。"}},{"en":"the activity of buying and selling goods or shares in a company in the hope of making a profit, but with the risk of losing money","cn":"投机买卖；炒股","ex":{"en":"speculation in oil","cn":"石油投机"}}]}},"spotless":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"极其干净的;一尘不染的","en":"Something that is spotless is completely clean.","ex":{"en":"Each morning cleaners make sure everything is spotless","cn":"每天早晨，清洁工们会把一切都打扫得干干净净。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"without any dirt or marks","cn":""},{"en":"water or air that is pure does not contain any dirt, pollution, or bacteria","cn":""},{"en":"completely clean, with no bacteria, and therefore safe for medical or scientific use","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/9/spotless0205.mp3","us":"media/ldoce/hwd/ame/f/spotless.mp3"},"examples":[{"en":"( figurative ) He has a spotless record so far.","cn":"他的操行记录至今无任何污点。"},{"en":"She keeps the house spotless.","cn":"她把家里收拾得一尘不染。"}],"oxford":{"phon":"ˈspɒtləs","pos":"adjective","senses":[{"en":"perfectly clean","cn":"极清洁的；非常洁净的","lab":"figurative","ex":{"en":"a spotless white shirt","cn":"洁白的衬衣"}}]}},"splint":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(治疗骨折用的)夹板","en":"A splint is a long piece of wood or metal that is fastened to a broken arm, leg, or back to keep it still."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a flat piece of wood, metal etc used for keeping a broken bone in position while it mends 〔","cn":"用以固定断骨的〕夹板"}]},"media":{"uk":"media/ldoce/hwd/bre/1/splint0205.mp3","us":"media/ldoce/hwd/ame/1/splint.mp3"},"oxford":{"phon":"splɪnt","pos":"noun","senses":[{"en":"a long piece of wood or metal that is tied to a broken arm or leg to keep it still and in the right position","cn":"（固定断肢的）夹板"}]}},"spangly":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"(衣服)装饰着小亮片的","en":"Spangly clothes are decorated with a lot of small shiny objects.","ex":{"en":"He certainly liked spangly jackets.","cn":"他显然喜欢缀着闪闪亮片的夹克。"}}]}},"springtime":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"春天;春季","en":"Springtime is the period of time during which spring lasts."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the time of the year when it is spring","cn":"春天﹐春季"}]},"media":{"uk":"media/ldoce/hwd/bre/d/springtime0205.mp3","us":"media/ldoce/hwd/ame/3/springtime.mp3"},"examples":[{"en":"a visit to Holland in springtime/in the springtime","cn":"春季游览荷兰"},{"en":"when the snow melts in the springtime","cn":"春天积雪消融之际"}],"oxford":{"phon":"ˈsprɪŋtaɪm","pos":"noun","senses":[{"en":"the season of spring","cn":"春季；春天；春令","ex":{"en":"a visit to Holland in (the) springtime","cn":"春季游览荷兰"}}]}},"sporty":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(汽车)速度快的，像跑车似的","en":"You can describe a car as sporty when it performs like a racing car but can be driven on normal roads.","ex":{"en":"The steering and braking are exactly what you want from a sporty car.","cn":"其转向和制动装置都完全符合一辆运动型汽车的标准。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"爱好体育运动的","en":"Someone who is sporty likes playing sports."}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"someone who is sporty likes sport and is good at it","cn":"爱好并擅长体育运动的"},{"en":"sporty clothes are designed to look attractive in a bright informal way 〔","cn":"衣服〕颜色明亮的﹐休闲的"},{"en":"a sporty car is designed to look attractive and go fast 〔","cn":"汽车〕外观优美速度快的"}]},"media":{"uk":"media/ldoce/hwd/bre/e/sporty0205.mp3","us":"media/ldoce/hwd/ame/0/sporty.mp3"},"examples":[{"en":"I'm not very sporty.","cn":"我不擅长体育运动。"},{"en":"a sporty Mercedes","cn":"一辆又快又靓的奔驰汽车"}],"oxford":{"phon":"ˈspɔːti","pos":"adjective","senses":[{"en":"liking or good at sport","cn":"爱好（或擅长）体育运动的","lab":"especially British English","ex":{"en":"I'm not very sporty.","cn":"我不擅长体育运动。"}},{"en":"bright, attractive and informal; looking suitable for wearing for sports","cn":"漂亮帅气的；适合运动时穿着的","ex":{"en":"a sporty cotton top","cn":"漂亮帅气的棉布上衣"}},{"en":"fast and attractive","cn":"外形优美且速度快的","ex":{"en":"a sporty Mercedes","cn":"一辆又快又靓的奔驰汽车"}}]}},"spoonerism":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(说话时的)首音误置(如将long road 说成 wrong load)","en":"A spoonerism is a mistake made by a speaker in which the first sounds of two words are changed over, often with a humorous result, for example when someone says 'wrong load' instead of 'long road'."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a phrase in which the speaker accidentally exchanges the first sounds of two words, with a funny result, for example ‘sew you to a sheet’ instead of ‘show you to a seat’ 〔","cn":"两个词的〕首音误置〔说话时误把两个单词的首音调换﹐造成滑稽效果﹐如把show you to a seat说成sew you to a sheet〕"}]},"vocab":{"pos":"n","senses":[{"en":"Here's the official meaning of spoonerism : \"The transposition of initial consonants in a pair of words.\" Zzzzzzzzz. Okay, pretty dull sounding, but in practice actually pretty funny: \"My lips are zipped\" becomes \"my zips are lipped.\""}]},"media":{"uk":"media/ldoce/hwd/bre/c/ld41spoonerism.mp3","us":"media/ldoce/hwd/ame/e/spoonerism.mp3"},"oxford":{"phon":"ˈspuːnərɪzəm","pos":"noun","senses":[{"en":"a mistake in which you change around the first sounds of two words by mistake when saying them, often with a humorous result, for example well-boiled icicle for well-oiled bicycle","cn":"首音误置（说话时误把两个单词的首音掉换，常造成滑稽效果）"}]}},"speck":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"污点;痕迹;斑点;小块","en":"A speck is a very small stain, mark, or shape.","ex":{"en":"...a speck of blood.","cn":"一点血迹"}},{"pos":"N-COUNT 可数名词","cn":"(粉末状物质的)微粒","en":"A speck is a very small piece of a powdery substance.","ex":{"en":"Billy leaned forward and brushed a speck of dust off his shoes.","cn":"比利俯身擦掉了鞋子上的一丝灰尘。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a small piece that has broken off something, especially something hard","cn":""},{"en":"a very small piece of bread, cake etc","cn":""},{"en":"a piece of something such as dirt or dust which is so small you almost cannot see it","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/6/speck0205.mp3","us":"media/ldoce/hwd/ame/7/speck.mp3"},"examples":[{"en":"The ship was now just a speck in the distance.","cn":"此时，那艘船不过是远处的一个小点。"},{"en":"specks of dust","cn":"尘埃"}],"oxford":{"phon":"spek","pos":"noun","senses":[{"en":"a very small spot; a small piece of dirt, etc.","cn":"小点；污点","ex":{"en":"The ship was now just a speck in the distance.","cn":"此时，那艘船不过是远处的一个小点。"}}]}},"spineless":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"没有骨气的;懦弱的","en":"If you say that someone is spineless, you mean that they are afraid to take action or oppose people when they should.","ex":{"en":"...bureaucrats and spineless politicians.","cn":"官僚和懦弱的政客们"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"not brave","cn":""},{"en":"someone who is not brave enough to do something dangerous or unpleasant that they should do","cn":""},{"en":"someone who is spineless is too weak to say what they really think because they are afraid of what might happen or what other people might say -- use this to show disapproval","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/3/spineless0205.mp3","us":"media/ldoce/hwd/ame/2/spineless.mp3"},"examples":[{"en":"a bunch of spineless politicians","cn":"一群怯弱的政客"}],"oxford":{"phon":"ˈspaɪnləs","pos":"adjective","senses":[{"en":"weak and easily frightened","cn":"没有骨气的；怯懦的","lab":"disapproving"},{"en":"having no spine (= the long bone in the back)","cn":"无脊椎的；无脊柱的"},{"en":"having no spines (= sharp parts like needles)","cn":"无刺的"}]}},"sprocket":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"链轮;(胶片的)输片齿轮;(磁带的)带齿卷盘","en":"A sprocket is a wheel with teeth around the outer edge that fit into the holes in a chain or a length of film or tape in order to move it round."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a wheel with teeth (= parts along the edge ) that fit into and turn a bicycle chain, a photographic film with holes etc 〔","cn":"自行车的〕链轮﹔〔电影放映机的〕带齿卷轴﹐带齿卷盘"},{"en":"one of the teeth on a sprocket wheel","cn":"链轮齿﹐链齿"}]},"media":{"img":["media/ldoce/img/sprocket.jpg","media/pic/sprocket.jpg"],"uk":"media/ldoce/hwd/bre/b/ld41sprocket.mp3","us":"media/ldoce/hwd/ame/a/sprocket.mp3"},"oxford":{"phon":"ˈsprɒkɪt","pos":"noun","senses":[{"en":"a wheel with a row of teeth around the edge that connect with the holes of a bicycle chain or with holes in a film, etc. in order to turn it","cn":"链轮；输片齿轮"},{"en":"one of the teeth on such a wheel","cn":"链轮齿；链齿"}]}},"sphere":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"球(体)；球形","en":"A sphere is an object that is completely round in shape like a ball."},{"pos":"N-COUNT 可数名词","cn":"(活动、兴趣等的)范围，领域","en":"A sphere of activity or interest is a particular area of activity or interest.","ex":{"en":"...the sphere of international politics.","cn":"国际政治领域"}},{"pos":"N-COUNT 可数名词","cn":"(社会地位或兴趣等相同的)人群，阶层，圈子","en":"A sphere of people is a group of them who are similar in social status or who have the same interests.","ex":{"en":"...the realities of life outside the government and academic spheres of society.","cn":"政府和学术界以外社会阶层的生活现状"}},{"pos":"PHRASE 短语","cn":"(国家的)势力范围，影响所及的范围","en":"A country's sphere of influence is an area of the world where it has a lot of influence.","ex":{"en":"They see the region as their natural sphere of influence due to their historical links and a shared language.","cn":"基于历史上的联系和共同的语言，他们把该地区看成是自己天然的势力范围。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a shape with four straight sides that are equal in length and four angles of 90 degrees","cn":""},{"en":"a round shape that is like an O","cn":""},{"en":"half a circle","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"Marbles, oranges, bubbles, and beach balls — all of these objects illustrate the shape of a sphere , or globe (unless the beach balls are under-inflated, in which case they’re sort-of a “squished- sphere ” shape)."}]},"collocations":{"phrases":["ADJ. wider He wanted to spread his ideas to a wider sphere than the school. | academic, cultural, domestic, economic, military, political, s","PREP. in/within sb's/the ~ The region is within the Russian sphere of influence. | outside sb's/the ~ The matter is outside my sphere of res","PHRASES a sphere of activity/influence/life"]},"media":{"uk":"media/ldoce/hwd/bre/b/sphere0205.mp3","us":"media/ldoce/hwd/ame/b/sphere.mp3","img":["media/thumb/sphere.jpg"]},"examples":[{"en":"This area was formerly within the sphere of influence of the US.","cn":"这一地区先前属于美国的势力范围。"},{"en":"He and I moved in totally different social spheres.","cn":"我和他进入了完全不同的社会圈子。"}],"oxford":{"phon":"sfɪə(r)","pos":"noun","senses":[{"en":"a solid figure that is completely round, with every point on its surface at an equal distance from the centre","cn":"球；球体；球形","lab":"geometry","ex":{"en":"The Earth is not a perfect sphere.","cn":"地球并不是完美的球体。"}},{"en":"any object that is completely round, for example a ball","cn":"圆球；球状物"},{"en":"an area of activity, influence or interest; a particular section of society","cn":"范围；领域；阶层；界","ex":{"en":"the political sphere","cn":"政界"}},{"en":"a region that surrounds a planet, especially the earth","cn":"（包围地球等的大气的）层","ex":{"en":"ionosphere","cn":"电离层"}}]}},"spirited":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(行动)坚决有力的，激烈的，猛烈的","en":"A spirited action shows great energy and courage.","ex":{"en":"This television program provoked a spirited debate in the United Kingdom.","cn":"这个电视节目在英国引起了激烈的辩论。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(人)活泼的，生气勃勃的，自信的","en":"A spirited person is very active, lively, and confident.","ex":{"en":"He was by nature a spirited little boy.","cn":"他是个生性活泼的小男孩。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"having energy and determination – used to show approval","cn":"精神饱满的﹐生气勃勃的﹔有决心的〔含褒义〕"},{"en":"having a particular type of character","cn":"性格温顺的/坚强的/叛逆的等"}]},"media":{"uk":"media/ldoce/hwd/bre/5/brelasdespirited.mp3","us":"media/ldoce/hwd/ame/e/spirited.mp3"},"examples":[{"en":"She put up a spirited defence in the final game.","cn":"她在最后一场比赛中进行了顽强的防守。"},{"en":"a spirited young woman","cn":"充满朝气的年轻女子"}],"oxford":{"phon":"ˈspɪrɪtɪd","pos":"adjective","senses":[{"en":"full of energy, courage or determination","cn":"精神饱满的；勇猛的；坚定的","ex":{"en":"a spirited young woman","cn":"充满朝气的年轻女子"}}]}},"speciality":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"专业;专长","en":"Someone's speciality is a particular type of work that they do most or do best, or a subject that they know a lot about.","ex":{"en":"My father was a historian of repute. His speciality was the history of Germany","cn":"我的父亲是一名颇有名气的历史学家，他专门研究德国历史。"}},{"pos":"N-COUNT 可数名词","cn":"特色菜;特产","en":"A speciality of a particular place is a special food or product that is always very good there.","ex":{"en":"Rhineland dishes are a speciality of the restaurant","cn":"莱茵兰菜是这家饭店的特色菜。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"things that people and animals eat","cn":""},{"en":"a type of food that is cooked in a particular way","cn":""},{"en":"a type of food that a restaurant or place is famous for","cn":""}]},"collocations":{"phrases":["ADJ. local, regional","PHRASES a speciality of the house I ordered the speciality of the house?frogs' legs."]},"media":{"uk":"media/ldoce/hwd/bre/7/speciality0205.mp3","us":"media/ldoce/hwd/ame/e/ld41speciality.mp3"},"examples":[{"en":"My speciality is international tax law.","cn":"我的专业是国际税法。"},{"en":"Seafood is a speciality on the island.","cn":"海味是岛上的特产。"}],"oxford":{"phon":"ˌspeʃiˈæləti","pos":"noun","senses":[{"en":"a type of food or product that a restaurant or place is famous for because it is so good","cn":"特产；特色菜","ex":{"en":"Seafood is a speciality on the island.","cn":"海味是岛上的特产。"}},{"en":"an area of work or study that somebody gives most of their attention to and knows a lot about; something that somebody is good at","cn":"专业；专长","ex":{"en":"My speciality is international tax law.","cn":"我的专业是国际税法。"}}]}},"spiny":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"(动植物)带刺的","en":"A spiny plant or animal is covered with long sharp points.","ex":{"en":"...a spiny lobster.","cn":"刺龙虾"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"a spiny animal or plant has lots of stiff sharp points","cn":"多刺的"}]},"media":{"uk":"media/ldoce/hwd/bre/d/ld41spiny.mp3","us":"media/ldoce/hwd/ame/5/spiny.mp3"},"examples":[{"en":"spiny sea urchins","cn":"多刺的海胆"},{"en":"spiny bushes","cn":"多刺的灌木丛"}],"oxford":{"phon":"ˈspaɪni","pos":"adjective","senses":[{"en":"having sharp points like needles","cn":"有刺毛的；带刺的；多刺的","ex":{"en":"spiny sea urchins","cn":"多刺的海胆"}}]}},"specification":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"规格;具体要求","en":"A specification is a requirement which is clearly stated, for example about the necessary features in the design of something.","ex":{"en":"Troll's exclusive, personalized luggage is made to our own exacting specifications in heavy-duty PVC/nylon","cn":"特罗尔专用的、个性化的行李箱是按照我们自己严格的规格要求用耐用聚氯乙烯/尼龙材料定制的。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a detailed instruction about how a car, building, piece of equipment etc should be made 〔","cn":"汽车﹑建筑﹑设备等的〕规格说明﹐明细规范"},{"en":"a clear statement of what is needed or wanted","cn":"具体[明确]说明"}]},"vocab":{"pos":"n","senses":[{"en":"We sometimes call them \"specs,\" but a specification has no relationship to eyeglasses! Instead, it is an explicit detail of a design, presenting the exact way something specific must be constructed. For example, blueprints contain the specifications for a building."}]},"collocations":{"phrases":["ADJ. complete, detailed, full | clear, exact | standard | high The yachts are built to the highest specifications. | strict | original | des","VERB + SPECIFICATION draft, draw up, lay down, write | meet The aircraft have to meet the strict specifications laid down by the FAA.","PREP. (according) to the/your ~s Each vehicle can be equipped according to your specifications."]},"media":{"uk":"media/ldoce/hwd/bre/2/specification0205.mp3","us":"media/ldoce/hwd/ame/1/specification.mp3"},"examples":[{"en":"The house has been built exactly to our specifications.","cn":"房子完全是按照我们的工程设计书建造的。"},{"en":"The office was furnished to a high specification.","cn":"办公室是按高规格装潢的。"}],"oxford":{"phon":"ˌspesɪfɪˈkeɪʃn","pos":"noun","senses":[{"en":"a detailed description of how something is, or should be, designed or made","cn":"规格；规范；明细单；说明书","ex":{"en":"the technical specifications of the new model (= of car)","cn":"新型号的技术规格"}}]}},"spokesperson":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(团体或组织的)发言人","en":"A spokesperson is a person who speaks as the representative of a group or organization.","ex":{"en":"A spokesperson for Amnesty, Norma Johnston, describes some cases.","cn":"大赦国际的一名发言人诺尔马·约翰斯顿讲述了几个案例。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone who has been chosen to represent an organization or country","cn":""},{"en":"a person who officially gives the opinions of an organization, company, government etc","cn":""},{"en":"a word meaning spokesman or spokeswoman , used especially when you do not want to say whether the person is a man or a woman","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/f/brelasdespokesperson.mp3","us":"media/ldoce/hwd/ame/1/spokesperson.mp3"},"oxford":{"phon":"ˈspəʊkspɜːsn","pos":"noun","senses":[{"en":"a person who speaks for a group or an organization","cn":"发言人","ex":{"en":"a council spokesperson","cn":"议会发言人"}}]}},"spur-of-the-moment":{"collins":{"senses":[{"pos":"","cn":"","en":"→see: ;"}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"a spur-of-the-moment decision or action is made or done suddenly without planning","cn":"一时冲动的﹐心血来潮的"}]},"media":{"uk":"media/ldoce/hwd/bre/d/ld41spur-of-the-mo.mp3","us":"media/ldoce/hwd/ame/a/spur-of-the-moment.mp3"}},"splatter":{"collins":{"senses":[{"pos":"V-ERG 及物/不及物动词","cn":"溅泼；洒落","en":"If a thick wet substance splatters on something or is splattered on it, it drops or is thrown over it.","ex":{"en":"The rain splattered against the french windows","cn":"雨溅落在落地窗上。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"if liquid splatters somewhere, or if someone splatters it, it falls or is thrown onto a surface","cn":"飞溅（在）﹔把…溅泼（于）"}]},"vocab":{"pos":"v n","senses":[{"en":"In horror movies, you'll see a lot of blood splattering on walls. Ick. To splatter is to splash liquid. A splatter is also the spot the liquid makes."}]},"media":{"uk":"media/ldoce/hwd/bre/4/splatter0205.mp3","us":"media/ldoce/hwd/ame/6/ld44splatter.mp3"},"examples":[{"en":"Coffee had splattered across the front of his shirt.","cn":"他的衬衣前襟上洒了一大片咖啡。"},{"en":"Heavy rain splattered on the roof.","cn":"大雨劈里啪啦地打在屋顶上。"}],"oxford":{"phon":"ˈsplætə(r)","pos":"verb","senses":[{"en":"to fall or hit something noisily","cn":"啪嗒啪嗒地落下（或击打）","g":"[intransitive]","ex":{"en":"Heavy rain splattered on the roof.","cn":"大雨噼里啪啦地打在屋顶上。"}},{"en":"to drop or throw water, paint, mud, etc. on somebody/something; to make somebody/something wet or dirty by landing on them in large drops","cn":"把（水等）泼洒在…上；淋湿；溅污","g":"[transitive, intransitive]","ex":{"en":"The walls were splattered with blood.","cn":"墙上血迹斑斑。"}}]}},"sprite":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(童话及传说中生活在水边的)小精灵，小仙子","en":"In fairy stories and legends, a sprite is a small, magic creature which lives near water."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a fairy (1)","cn":"仙子﹐小精灵"}]},"media":{"uk":"media/ldoce/hwd/bre/3/ld41sprite.mp3","us":"media/ldoce/hwd/ame/1/sprite1.mp3"},"oxford":{"phon":"spraɪt","pos":"noun","senses":[{"en":"(in stories) a small creature with magic powers, especially one that likes playing tricks","cn":"（传说中的）小仙子，小精灵，小妖精"}]}},"spotty":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"脸上有斑点的;多粉刺的","en":"Someone who is spotty has spots on their face.","ex":{"en":"She was rather fat, and her complexion was muddy and spotty.","cn":"她比较胖，脸色暗淡、多斑。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"时好时坏的","en":"Something that is spotty does not stay the same but is sometimes good and sometimes bad.","ex":{"en":"He quit in 1981—had a spotty political career","cn":"他在1981年辞职了——其政治生涯几经沉浮。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"someone who is spotty has small raised red marks on their skin, especially on their face 〔","cn":"尤指脸上〕有粉刺的"},{"en":"good only in some parts, but not in other parts 〔","cn":"质量〕有好有坏的﹐参差不齐的"}]},"media":{"uk":"media/ldoce/hwd/bre/b/spotty0205.mp3","us":"media/ldoce/hwd/ame/a/spotty.mp3"},"examples":[{"en":"a spotty adolescent","cn":"满脸粉刺的少年"},{"en":"a spotty dress","cn":"带圆点的连衣裙"}],"oxford":{"phon":"ˈspɒti","pos":"adjective","senses":[{"en":"having a lot of spots on the skin","cn":"多丘疹的；多粉刺的","lab":"British English, usually disapproving，，","ex":{"en":"a spotty adolescent","cn":"满脸粉刺的少年"}},{"en":"not complete; good in some parts, but not in others","cn":"不完整的；参差不齐的","lab":"North American English"},{"en":"having a regular pattern of small dots (= small round marks) on it","cn":"有圆点的","ex":{"en":"a spotty dress","cn":"带圆点的连衣裙"}}]}},"spatter":{"collins":{"senses":[{"pos":"V-ERG 及物/不及物动词","cn":"溅;洒","en":"If a liquid spatters a surface or you spatter a liquid over a surface, drops of the liquid fall on an area of the surface.","ex":{"en":"He stared at the rain spattering on the glass","cn":"他凝视着雨点溅落在玻璃上。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"if a liquid spatters, or if something spatters it, drops of it fall or are thrown all over a surface （","cn":"使）洒落﹔（使）飞溅"}]},"collocations":{"phrases":["ADV. liberally","PREP. against Rain spattered against the window. | on Blood was spattered on the walls and doors. | over The water had spattered all over he"]},"media":{"uk":"media/ldoce/hwd/bre/9/spatter0205.mp3","us":"media/ldoce/hwd/ame/a/spatter1.mp3"},"examples":[{"en":"We heard the rain spattering on the roof.","cn":"我们听见雨点劈里啪啦地打在房顶上。"},{"en":"As the bus passed, it spattered us with mud.","cn":"公共汽车开过时溅了我们一身泥。"}],"oxford":{"phon":"ˈspætə(r)","pos":"verb","senses":[{"en":"to cover somebody/something with drops of liquid, dirt, etc., especially by accident","cn":"溅；洒","g":"[transitive, often passive]","ex":{"en":"blood-spattered walls","cn":"血染的墙壁"}},{"en":"to fall on a surface in drops, often noisily","cn":"洒落；滴滴答答地落下","g":"[intransitive]","ex":{"en":"We heard the rain spattering on the roof.","cn":"我们听见雨点噼里啪啦地打在房顶上。"}},{"en":"a number of drops of a liquid or small amounts of something that hit a surface; the noise this makes","cn":"洒；溅；滴答声；飞溅声","lab":"figurative","ex":{"en":"a spatter of rain against the window","cn":"雨点打在窗户上的噼啪声"},"pos":"noun"}]}},"spadework":{"collins":{"senses":[{"pos":"N-SING 单数名词","cn":"(计划、活动等开始之前需要做的)艰苦枯燥的准备工作","en":"The spadework is the uninteresting work that has to be done as preparation before you can start a project or activity.","ex":{"en":"It is now that the spadework has to be done to lay firm foundations for later success.","cn":"现在应该着手做一些准备工作以便为日后的成功打下坚实基础。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"hard work that has to be done in preparation before something can happen","cn":"艰苦的准备工作"}]},"media":{"uk":"media/ldoce/hwd/bre/b/ld41spadework.mp3","us":"media/ldoce/hwd/ame/c/spadework.mp3"},"examples":[{"en":"Most of the spadework had been done by 1981.","cn":"这些艰苦的前期工作到1981年已经大部分完成。"}],"oxford":{"phon":"ˈspeɪdwɜːk","pos":"noun","senses":[{"en":"the hard work that has to be done in order to prepare for something","cn":"艰苦的前期准备工作","ex":{"en":"I have to do all the spadework for the monthly committee meetings.","cn":"我必须为每月的委员会会议做所有的准备工作。"}}]}},"sparrow":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"麻雀","en":"A sparrow is a small brown bird that is very common in Britain."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a small brown bird, very common in many parts of the world","cn":"麻雀"}]},"media":{"uk":"media/ldoce/hwd/bre/d/sparrow0205.mp3","us":"media/ldoce/hwd/ame/a/laadsparrow.mp3"},"oxford":{"phon":"ˈspærəʊ","pos":"noun","senses":[{"en":"a small brown and grey bird, common in many parts of the world","cn":"麻雀"}]}},"sparing":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"节约的;俭省的","en":"Someone who is sparing with something uses it or gives it only in very small quantities.","ex":{"en":"I've not been sparing with the garlic","cn":"我总是用很多大蒜。"}}]},"ldoce":{"phon":"hwd","pos":"adverb","senses":[{"en":"using or doing only a little of something","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/f/sparingly0205.mp3","us":"media/ldoce/hwd/ame/5/laadsparingly.mp3"},"examples":[{"en":"Doctors now advise only sparing use of such creams.","cn":"现在大夫建议，这种乳霜要慎用。"},{"en":"Use the cream very sparingly.","cn":"这种乳霜要尽可能少用。"}],"oxford":{"phon":"ˈspeərɪŋ","pos":"adjective","senses":[{"en":"careful to use or give only a little of something","cn":"慎用；俭省的；吝惜的","ex":{"en":"Doctors now advise only sparing use of such creams.","cn":"现在大夫建议，这种乳霜要慎用。"}}]}},"spleen":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"脾;脾脏","en":"Your spleen is an organ near your stomach that controls the quality of your blood."},{"pos":"N-UNCOUNT 不可数名词","cn":"大发脾气;大怒","en":"Spleen is great and bitter anger.","ex":{"en":"Paul Fussell's latest book vents his spleen against everything he hates about his country","cn":"保罗·富塞尔在新作中发泄了他对国家的所有不满。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a strong emotion that you feel because someone has behaved badly or because a situation seems bad or unfair","cn":""},{"en":"slight anger or impatience","cn":""},{"en":"a feeling of being annoyed and impatient, especially because something keeps happening or someone keeps saying something","cn":""}]},"vocab":{"pos":"1 n 2 n","senses":[{"en":"The spleen is an organ that's about the size of a fist, located on the left side, just below the ribcage. Don't let its small size fool you. This little organ is very important in helping the body fight infection."}]},"media":{"uk":"media/ldoce/hwd/bre/b/ld41spleen.mp3","us":"media/ldoce/hwd/ame/7/spleen.mp3"},"examples":[{"en":"He vented his spleen (= shouted in an angry way) on the assembled crowd.","cn":"他把怒气撒在了聚集的人群身上。"},{"en":"a ruptured spleen","cn":"破裂的脾"}],"oxford":{"phon":"spliːn","pos":"noun","senses":[{"en":"a small organ near the stomach that controls the quality of the blood cells","cn":"脾","g":"[countable]","ex":{"en":"a ruptured spleen","cn":"破裂的脾"}},{"en":"anger","cn":"愤怒；怒气","g":"[uncountable]","lab":"literary","ex":{"en":"He vented his spleen (= shouted in an angry way) on the assembled crowd.","cn":"他把怒气撒在了聚集的人群身上。"}}]}},"splurge":{"collins":{"senses":[{"pos":"VERB 动词","cn":"挥霍","en":"If you splurge on something, you spend a lot of money, usually on things that you do not need.","ex":{"en":"We splurged on Bohemian glass for gifts, and for ourselves.","cn":"我们花了很多钱买波希米亚玻璃制品送人和自用。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to pay money for something so that you can own it","cn":""},{"en":"to buy something, especially something large or expensive, in a business deal or by a legal contract","cn":""},{"en":"to become the owner of something large or expensive such as property, a company, or a valuable object","cn":""}]},"vocab":{"pos":"v n","senses":[{"en":"To splurge is to indulge yourself. You can also go on a splurge if you spend a lot or act extravagantly in another way."}]},"media":{"uk":"media/ldoce/hwd/bre/1/ld41splurge.mp3","us":"media/ldoce/hwd/ame/8/splurge.mp3"},"examples":[{"en":"Within a couple of months, I’d splurged about £2,500 on clothes.","cn":"就在几个月时间里﹐我买衣服花掉了2,500英镑。"}],"oxford":{"phon":"splɜːdʒ","pos":"noun","senses":[{"en":"an act of spending a lot of money on something that you do not really need","cn":"乱花钱；糟蹋钱；挥霍"},{"en":"to spend a lot of money on something that you do not really need","cn":"乱花（钱）；糟蹋（钱）；挥霍","ex":{"en":"He splurged his whole week’s wages on a champagne dinner.","cn":"整整一周的工资，他一顿香槟晚餐就挥霍得一干二净。"},"pos":"verb"}]}},"springboard":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"跳板;推动力","en":"If something is a springboard for something else, it makes it possible for that thing to happen or start.","ex":{"en":"The 1981 budget was the springboard for an economic miracle","cn":"1981 年的预算促成了一场经济奇迹的出现。"}},{"pos":"N-COUNT 可数名词","cn":"(跳水或体操运动用的)跳板","en":"A springboard is a flexible board from which you jump into a swimming pool or onto a piece of gymnastic equipment."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"something that helps you to start doing something 〔","cn":"有助于开始做某事的〕起点﹐起步方法"},{"en":"a strong board for jumping on or off, used when diving ( dive 1 (1) ) or doing gymnastics 〔","cn":"跳水运动的〕跳板﹔〔体操运动的〕踏跳板"}]},"media":{"uk":"media/ldoce/hwd/bre/9/springboard0205.mp3","us":"media/ldoce/hwd/ame/5/springboard.mp3"},"examples":[{"en":"The company expects that this strategic move would allow it to springboard into the US market.","cn":"公司希望这次战略行动会成为公司进入美国市场的跳板。"},{"en":"The document provided a springboard for a lot of useful discussion.","cn":"这份文件引发出许多有益的讨论。"}],"oxford":{"phon":"ˈsprɪŋbɔːd","pos":"noun","senses":[{"en":"a strong board that you jump on and use to help you jump high in diving and gymnastics","cn":"（跳水或体操中的）跳板"},{"en":"something that helps you start an activity, especially by giving you ideas","cn":"（有助于开展某事的）基础，出发点","ex":{"en":"The document provided a springboard for a lot of useful discussion.","cn":"这份文件引发了许多有益的讨论。"}},{"en":"to help somebody/something start an activity quickly and strongly; to start an activity in this way","cn":"（有助于开展某事的）基础，出发点","ex":{"en":"The company expects that this strategic move would allow it to springboard into the US market.","cn":"公司期望这一战略行动能成为其进入美国市场的跳板。"},"pos":"verb"}]}},"spud":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"马铃薯;土豆","en":"Spuds are potatoes."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a potato","cn":"马铃薯﹐土豆"}]},"media":{"uk":"media/ldoce/hwd/bre/c/spud0205.mp3","us":"media/ldoce/hwd/ame/9/spud.mp3"},"oxford":{"phon":"spʌd","pos":"noun","senses":[{"en":"a potato","cn":"土豆"}]}},"spaniel":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"西班牙猎犬(一种耳朵长且下垂的小犬)","en":"A spaniel is a type of dog with long ears that hang down."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a type of dog with long ears that hang down","cn":"猎鹬犬，枪猎犬〔长耳下垂〕"}]},"media":{"uk":"media/ldoce/hwd/bre/2/spaniel0205.mp3","us":"media/ldoce/hwd/ame/c/spaniel.mp3"},"oxford":{"phon":"ˈspænjəl","pos":"noun","senses":[{"en":"a dog with large soft ears that hang down. There are several types of spaniel.","cn":"西班牙猎犬（大耳下垂，品种甚多）","ex":{"en":"a cocker spaniel","cn":"西班牙猎鸡狗。"}}]}},"spoof":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（关于严肃事件的）玩笑，讽刺性文章(或电视节目等)","en":"A spoof is something such as an article or television programme that seems to be about a serious matter but is actually a joke.","ex":{"en":"...a spoof on Hollywood life.","cn":"拿好莱坞生活开玩笑的作品"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a film, book etc that makes fun of a serious type of film, book etc by copying it in a funny way","cn":""},{"en":"a performance, film, article etc that makes fun of a situation or the behaviour of a group of people by copying it in a funny way","cn":""},{"en":"a piece of writing or music that is amusing because it makes fun of a famous piece of writing or music by clearly copying its style","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/4/spoof0205.mp3","us":"media/ldoce/hwd/ame/c/spoof.mp3"},"examples":[{"en":"Someone has been spoofing my address.","cn":"有人一直在冒充我的电邮地址发送电邮。"},{"en":"It is a movie that spoofs other movies.","cn":"这是一部夸张地模仿其他电影的影片。"}],"oxford":{"phon":"spuːf","pos":"noun","senses":[{"en":"a humorous copy of a film, TV programme, etc. that exaggerates its main features","cn":"（对电影、电视节目等的）滑稽模仿","ex":{"en":"It's a spoof on horror movies.","cn":"这是对恐怖片的滑稽模仿。"}},{"en":"to copy a film, TV programme, etc. in a humorous way by exaggerating its main features","cn":"滑稽地模仿（电影、电视节目等）","ex":{"en":"It is a movie that spoofs other movies.","cn":"这是一部夸张地模仿其他电影的影片。"},"pos":"verb"},{"en":"to send an email that appears to come from somebody else’s email address","cn":"（冒用他人电邮地址）发送电邮；发送仿真电邮；电邮欺骗","ex":{"en":"Someone has been spoofing my address.","cn":"有人一直在冒用我的电邮地址发送电邮。"},"pos":"verb"}]}},"spaced-out":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(因服用毒品或极度劳累)飘飘然的，产生幻觉的","en":"Someone who is spaced-out feels as if nothing around them is real, usually because they have taken drugs or because they are very tired.","ex":{"en":"He's got this spaced-out look.","cn":"他一副吸毒之后的迷幻模样。"}}]},"oxford":{"phon":"ˌspeɪst ˈaʊt","pos":"adjective","senses":[{"en":"not completely conscious of what is happening around you, often because of taking drugs","cn":"精神恍惚的，神志迷糊的（常指因吸食毒品）","ex":{"en":"He sat in the corner looking completely spaced out.","cn":"他坐在角落里，看来完全神志不清。"}}]}},"sprog":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"小孩;婴儿","en":"A sprog is a baby or child."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a child or baby – used humorously","cn":"小孩，婴儿〔幽默用法〕"}]},"media":{"uk":"media/ldoce/hwd/bre/a/ld41sprog.mp3","us":"media/ldoce/hwd/ame/a/ld41sprog.mp3"},"oxford":{"phon":"sprɒɡ","pos":"noun","senses":[{"en":"a child or baby","cn":"小孩；婴儿"}]}},"spillage":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"溢出;溢出物","en":"If there is a spillage, a substance such as oil escapes from its container. Spillage is also used to refer to the substance that escapes.","ex":{"en":"...an oil spillage off the coast of Texas.","cn":"得克萨斯州沿海的溢油事件"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a spill 2 (1)","cn":"洒出（量）﹐溢出（量）"}]},"media":{"uk":"media/ldoce/hwd/bre/c/spillage0205.mp3","us":"media/ldoce/hwd/ame/5/laadspillage.mp3"},"examples":[{"en":"Put the bottle in a plastic bag in case of spillage.","cn":"把瓶子装在塑料袋里，以免洒得到处都是。"}],"oxford":{"phon":"ˈspɪlɪdʒ","pos":"noun","senses":[{"en":"an act of letting a liquid come or fall out of a container; the amount of liquid that comes or falls out","cn":"洒出（量）；泼出（量）；溢出（量）；泄漏（量）","ex":{"en":"Put the bottle in a plastic bag in case of spillage.","cn":"把瓶子装在塑料袋里，以免洒得到处都是。"}}]}},"sprinkle":{"collins":{"senses":[{"pos":"VERB 动词","cn":"洒(水);撒(粉末)","en":"If you sprinkle a thing with something such as a liquid or powder, you scatter the liquid or powder over it.","ex":{"en":"Sprinkle the meat with salt and place in the pan","cn":"在肉上撒上盐，然后放进平底锅。"}},{"pos":"VERB 动词","cn":"使…上零星分布(着…)","en":"If something is sprinkled with particular things, it has a few of them throughout it and they are far apart from each other.","ex":{"en":"Unfortunately, the text is sprinkled with errors","cn":"遗憾的是，文本中零星地有一些错误。"}},{"pos":"VERB 动词","cn":"下毛毛细雨","en":"If it is sprinkling, it is raining very lightly."}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to make liquid or a substance flow steadily out of a container, by making the container lean to one side","cn":""},{"en":"to accidentally make a liquid or substance come out of a container","cn":""},{"en":"to make a container empty by pouring out everything inside it","cn":""}]},"vocab":{"pos":"v n","senses":[{"en":"A sprinkle is a light shower of something, often water. It’s also a verb that means to gently scatter something. A sprinkle of snow won’t cause school to close, but a sprinkle of fairy dust could transport you to a magical land."}]},"collocations":{"phrases":["ADV. lightly | evenly","PREP. on, onto, over Sprinkle sugar evenly over the top of the cake. | with Sprinkle the meat lightly with salt."]},"media":{"img":["media/ldoce/img/ldoce_312.png"],"uk":"media/ldoce/hwd/bre/6/sprinkle_v0205.mp3","us":"media/ldoce/hwd/ame/e/sprinkle1.mp3"},"examples":[{"en":"His poems are sprinkled with quotations from ancient Greek.","cn":"他的诗歌不时穿插有古希腊引文。"},{"en":"We've only had a few sprinkles (of rain) recently.","cn":"近来我们这里只下过几场小雨。"}],"oxford":{"phon":"ˈsprɪŋkl","pos":"verb","senses":[{"en":"to shake small pieces of something or drops of a liquid on something","cn":"撒；洒；把…撒（或洒）在…上","g":"[transitive]","ex":{"en":"Sprinkle chocolate on top of the cake.","cn":"给蛋糕洒上巧克力。"}},{"en":"to include a few of something in something else","cn":"使某物包含少量的另一物；用…点缀","g":"[transitive, usually passive]","ex":{"en":"His poems are sprinkled with quotations from ancient Greek.","cn":"他的诗歌不时穿插有古希腊引文。"}},{"en":"if it sprinkles, it rains lightly","cn":"下小雨","g":"[intransitive]","lab":"North American English","ex":{"en":"It's only sprinkling. We can still go out.","cn":"雨不大，我们还可以出去。"}},{"en":"a small amount of a substance that is dropped somewhere, or a number of things or people that are spread or included somewhere","cn":"少量（落、撒或包含的某种物质）；少数（分散在或包括在某处的人）","g":"[usually singular]","ex":{"en":"Add a sprinkle of cheese and serve.","cn":"再撒点奶酪，然后端上桌。"},"pos":"noun"},{"en":"light rain","cn":"小雨","lab":"especially North American English","ex":{"en":"We’ve only had a few sprinkles (of rain) recently.","cn":"近来我们这里只下过几场小雨。"},"pos":"noun"}]}},"sparkly":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"闪闪发光的","en":"Sparkly things sparkle.","ex":{"en":"...a sparkly toy necklace","cn":"闪闪发光的玩具项链"}}]},"vocab":{"pos":"adj","senses":[{"en":"The adjective sparkly is useful for describing an object that glints with light, like a disco ball, or a person whose personality is equally bright and bubbly."}]}},"spellbound":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"（对…）入迷的;（被…）吸引的","en":"If you are spellbound by something or someone, you are so fascinated that you cannot think about anything else.","ex":{"en":"His audience had listened like children, spellbound by his words","cn":"他的观众像孩子般倾听着，被他的话深深吸引了。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"very interested in something, so that you give it all your attention and do not notice anything else","cn":""},{"en":"very interested, especially in a story you are reading, a film you are watching etc, so that you are eager to find out what happens next","cn":""},{"en":"very interested and enjoying something very much, so that you want to see or hear more","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"To be spellbound is to have your attention captured by something, captured so strongly it feels like witchcraft."}]},"media":{"uk":"media/ldoce/hwd/bre/c/spellbound0205.mp3","us":"media/ldoce/hwd/ame/9/laadspellbound.mp3"},"examples":[{"en":"a storyteller who can hold audiences spellbound","cn":"讲故事能让听众如痴如醉的人"},{"en":"‘King Lear’ still holds audiences spellbound . 《","cn":"李尔王》依然能让听众着迷。"}],"oxford":{"phon":"ˈspelbaʊnd","pos":"adjective","senses":[{"en":"with your attention completely held by what you are listening to or watching","cn":"入迷；出神；着魔","ex":{"en":"a storyteller who can hold audiences spellbound","cn":"讲故事能让听众如痴如醉的人"}}]}},"sprint":{"collins":{"senses":[{"pos":"N-SING 单数名词","cn":"短跑","en":"The sprint is a short, fast running race.","ex":{"en":"Rob Harmeling won the sprint in Bordeaux.","cn":"罗布·哈梅林在波尔多获得短跑冠军。"}},{"pos":"N-COUNT 可数名词","cn":"短程竞速赛","en":"A sprint is a short race in which the competitors run, drive, ride, or swim very fast.","ex":{"en":"Lewis will compete in both sprints in Stuttgart","cn":"刘易斯将参加在斯图加特举行的两个短跑项目的比赛。"}},{"pos":"N-SING 单数名词","cn":"冲刺;快跑","en":"A sprint is a fast run that someone does, either at the end of a race or because they are in a hurry.","ex":{"en":"Gilles Delion, of France, won the Tour of Lombardy in a sprint finish at Monza yesterday","cn":"法国选手吉勒斯·德利翁昨天在蒙扎凭借最后的冲刺获得伦巴第巡回赛冠军。"}},{"pos":"VERB 动词","cn":"全速奔跑;(短距离)冲刺","en":"If you sprint, you run or ride as fast as you can over a short distance.","ex":{"en":"Sergeant Horne sprinted to the car.","cn":"霍恩中士全力冲向那辆汽车。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to move very quickly, by moving your legs more quickly than when you walk","cn":""},{"en":"to run quite slowly for exercise over a long distance","cn":""},{"en":"to run somewhere as quickly as you can, especially because you have to do something urgently","cn":""}]},"collocations":{"phrases":["ADJ. quick, short | 100-metre, etc.","VERB + SPRINT break into, make The runners broke into a sprint a few hundred yards from the finish. It started raining, so we made a sprint ","SPRINT + NOUN relay Jamaica won the gold in the sprint relay. | finish Sato just pipped the Kenyan runner in a sprint finish. | champion Oly","PREP. in a ~ This car could comfortably outpace its rivals in a sprint. | ~ for The Moroccan came out best in a frantic sprint for the line."]},"media":{"uk":"media/ldoce/hwd/bre/c/sprint_n0205.mp3","us":"media/ldoce/hwd/ame/8/sprint1.mp3"},"examples":[{"en":"She won in a sprint finish.","cn":"她在最后的冲刺中取得胜利。"},{"en":"Three runners sprinted past.","cn":"三名运动员飞跑了过去。"}],"oxford":{"phon":"sprɪnt","pos":"verb","senses":[{"en":"to run or swim a short distance very fast","cn":"短距离快速奔跑（或游泳）；冲刺","ex":{"en":"He sprinted for the line.","cn":"他向终点线冲去。"}},{"en":"a race in which the people taking part run, swim, etc. very fast over a short distance","cn":"短跑比赛；短距离速度竞赛","ex":{"en":"a 100-metre sprint","cn":"100 米短跑"},"pos":"noun"},{"en":"a short period of running, swimming, etc. very fast","cn":"短距离快速奔跑（或游泳等）；冲刺","g":"[usually singular]","ex":{"en":"The Moroccan came out best in a frantic sprint for the line.","cn":"在向终点线的疯狂冲刺中摩洛哥运动员胜出。"},"pos":"noun"}]}},"spinnaker":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(帆船前桅上的)大三角帆","en":"A spinnaker is a large, light, triangular sail that is attached to the front mast of a boat."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a sail with three points at the front of a boat, used when the wind is directly behind 〔","cn":"帆船的〕大三角帆"}]},"media":{"uk":"media/ldoce/hwd/bre/0/ld41spinnaker.mp3","us":"media/ldoce/hwd/ame/c/spinnaker.mp3"},"oxford":{"phon":"ˈspɪnəkə(r)","pos":"noun","senses":[{"en":"a large extra sail on a racing yacht that you use when the wind is coming from behind","cn":"（赛艇的）大三角帆（顺风时用）"}]}},"spree":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"毫无节制;纵情","en":"If you spend a period of time doing something in an excessive way, you can say that you are going on a particular kind of spree .","ex":{"en":"Some Americans went on a spending spree in December to beat the new tax.","cn":"一些美国人在 12 月疯狂花钱，以避开新税。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a short period of time when you do a lot of one activity, especially spending money or drinking alcohol","cn":"作乐﹐狂欢〔尤指花钱或喝酒〕"}]},"vocab":{"pos":"n v","senses":[{"en":"If you go on a spree , you go a little wild, indulging in some activity in an unrestrained way. You might go on a cupcake spree every year on your birthday, eating as many cupcakes as you can."}]},"collocations":{"phrases":["ADJ. massive a massive buying spree | mad | buying, shopping, spending | drinking, drunken | crime, killing | scoring Uruguay's scoring spre","VERB + SPREE go on He's gone on a drinking spree.","PREP. on a ~ She's out on a mad spending spree."]},"media":{"uk":"media/ldoce/hwd/bre/8/spree0205.mp3","us":"media/ldoce/hwd/ame/2/spree.mp3"},"examples":[{"en":"He's out on a spree.","cn":"他到外面潇洒去了。"},{"en":"to go on a killing spree","cn":"一阵杀戮"}],"oxford":{"phon":"spriː","pos":"noun","senses":[{"en":"a short period of time that you spend doing one particular activity that you enjoy, but often too much of it","cn":"（常指过分）玩乐，作乐；纵乐","ex":{"en":"a shopping/spending spree","cn":"疯狂购物；大肆花钱"}},{"en":"a period of activity, especially criminal activity","cn":"一阵，一通（犯罪活动）","ex":{"en":"to go on a killing spree","cn":"在大杀特杀"}}]}},"spinal":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"脊椎的","en":"Spinal means relating to your spine.","ex":{"en":"...spinal fluid.","cn":"脊椎液"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"belonging to or affecting your spine","cn":"脊柱的﹔脊椎的"}]},"media":{"uk":"media/ldoce/hwd/bre/4/spinal0205.mp3","us":"media/ldoce/hwd/ame/0/spinal1.mp3"},"examples":[{"en":"spinal injuries","cn":"脊椎损伤"}],"oxford":{"phon":"ˈspaɪnl","pos":"adjective","senses":[{"en":"connected with the spine (= the long bone in the back)","cn":"脊的；脊椎的；脊髓的","ex":{"en":"spinal injuries","cn":"脊椎损伤"}}]}},"spacecraft":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"宇宙飞船;航天器","en":"A spacecraft is a rocket or other vehicle that can travel in space."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a vehicle that is able to travel in space","cn":"航天器﹐宇宙飞船"}]},"collocations":{"phrases":["VERB + SPACECRAFT launch","SPACECRAFT + VERB orbit sth a spacecraft orbiting the earth","PREP. in/on a/the ~"]},"media":{"img":["media/ldoce/img/space_shuttle.jpg"],"uk":"media/ldoce/hwd/bre/2/ld41spacecraft.mp3","us":"media/ldoce/hwd/ame/a/spacecraft.mp3"},"oxford":{"phon":"ˈspeɪskrɑːft","pos":"noun","senses":[{"en":"a vehicle that travels in space","cn":"航天（飞行）器；宇宙飞船；太空船","ex":{"en":"An unmanned Chinese spacecraft has returned safely to Earth.","cn":"中国一架无人驾驶航天器已安全返回地面。"}}]}},"span":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"间隔;期间","en":"A span is the period of time between two dates or events during which something exists, functions, or happens.","ex":{"en":"The batteries had a life span of six hours","cn":"这些电池的寿命为 6 小时。"}},{"pos":"N-COUNT 可数名词","cn":"(注意力的)持续时间","en":"Your concentration span or your attention span is the length of time you are able to concentrate on something or be interested in it.","ex":{"en":"His ability to absorb information was astonishing, but his concentration span was short","cn":"他吸收信息的能力令人吃惊，但是他的注意力持续时间很短。"}},{"pos":"VERB 动词","cn":"持续;跨越;贯穿","en":"If something spans a long period of time, it lasts throughout that period of time or relates to that whole period of time.","ex":{"en":"His professional career spanned 16 years","cn":"他的职业生涯持续了 16 年。"}},{"pos":"VERB 动词","cn":"包括;遍及","en":"If something spans a range of things, all those things are included in it.","ex":{"en":"Bernstein's compositions spanned all aspects of music, from symphonies to musicals.","cn":"伯恩斯坦创作的乐曲涉及了从交响乐到音乐剧等音乐的各个方面。"}},{"pos":"N-COUNT 可数名词","cn":"宽度;宽幅","en":"The span of something that extends or is spread out sideways is the total width of it from one end to the other.","ex":{"en":"It is a very pretty butterfly, with a 2 inch wing span","cn":"这是一只非常美丽的蝴蝶，翼展 2 英寸。"}},{"pos":"VERB 动词","cn":"(桥等建筑物)横跨，跨越","en":"A bridge or other structure that spans something such as a river or a valley stretches right across it.","ex":{"en":"Travellers get from one side to the other by walking across a footbridge that spans a little stream.","cn":"游客通过一座横跨小溪的步行桥从一边来到另一边。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a past tense of spin 1","cn":""},{"en":"a period of time between two dates or events 〔","cn":"两个日期或事件之间的〕时距﹐期间"},{"en":"the length of time over which someone’s life, ability to pay attention to something etc continues 〔","cn":"生命﹑注意力等的〕持续时间"}]},"vocab":{"pos":"1 n v 2 n","senses":[{"en":"Any distance between two things is called a span . These end points can be physical, like the span of a rope between two trees, or they can be more abstract, such as the span of time between five and six o'clock."}]},"collocations":{"phrases":["ADJ. full | broad, wide a broad span of interests | clear The bridge has a clear span of 36 metres. | 12-foot, 500-metre, etc. | wing (also ","ADJ. long | short | 10-day, 2-week, etc. | entire | allotted The speech continued well beyond its allotted span. | time | life (also lifespa","VERB + SPAN cover The book covers the entire span of Arab history.","PREP. over a/the ~ Developments were monitored over a span of two years.","PHRASES a span of time/years"]},"media":{"uk":"media/ldoce/hwd/bre/6/span0205.mp3","us":"media/ldoce/hwd/ame/1/span1.mp3"},"examples":[{"en":"The operation, which spanned nine countries, resulted in 200 arrests.","cn":"这次行动涉及九个国家，逮捕了 200 人。"},{"en":"The project must be completed within a specific time span.","cn":"这项工程必须在规定期限内完成。"}],"oxford":{"phon":"spæn","pos":"verb","senses":[{"en":"to last all through a period of time or to cover the whole of it","cn":"持续；贯穿","ex":{"en":"His acting career spanned 55 years.","cn":"他的演艺生涯长达 55 年。"}},{"en":"to include a large area or a lot of things","cn":"包括（广大地区）；涵盖（多项内容）","ex":{"en":"The operation, which spanned nine countries, resulted in 200 arrests.","cn":"这次行动涉及九个国家，逮捕了 200 人。"}},{"en":"to stretch right across something, from one side to the other","cn":"横跨；跨越","ex":{"en":"a series of bridges spanning the river","cn":"架在河上的一系列桥梁"}},{"en":"the length of time that something lasts or is able to continue","cn":"持续时间","ex":{"en":"I worked with him over a span of six years.","cn":"我和他共事达六年之久。"},"pos":"noun"},{"en":"a range or variety of something","cn":"范围；包括的种类","ex":{"en":"Managers have a wide span of control.","cn":"经理的职权范围很大。"},"pos":"noun"},{"en":"the part of a bridge or an arch between one support and another","cn":"（桥或拱的）跨径，跨度，跨距","ex":{"en":"The bridge crosses the river in a single span.","cn":"河上的桥为单跨桥。"},"pos":"noun"},{"en":"the measurement of something from one side to the other","cn":"宽度；翼展","ex":{"en":"The kite has a span of 1.5 metres.","cn":"风筝宽 1.5 米。"},"pos":"noun"}]}},"sprat":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"西鲱，黍鲱(产于欧洲的一种小海鱼，可食用)","en":"Sprats are very small European sea fish which can be eaten."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a small fish that is cooked and eaten whole","cn":"黍鲱〔可食用的小鱼〕"}]},"media":{"uk":"media/ldoce/hwd/bre/0/ld41sprat.mp3","us":"media/ldoce/hwd/ame/5/sprat.mp3"},"oxford":{"phon":"spræt","pos":"noun","senses":[{"en":"a very small European sea fish that is used for food","cn":"黍鲱（欧洲小海鱼，可食用）"}]}},"sportscast":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（电台或电视台的)赛事播报,体育比赛转播","en":"A sportscast is a radio or television broadcast of a sporting event."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a television broadcast of a sports game 〔","cn":"电视的〕体育比赛节目"}]},"media":{"uk":"media/ldoce/hwd/bre/f/sportscast0205.mp3","us":"media/ldoce/hwd/ame/c/sportscast.mp3"},"oxford":{"phon":"ˈspɔːtskɑːst","pos":"noun","senses":[{"en":"a television or radio broadcast of sports news or a sports event","cn":"（电视台或广播电台的）体育节目"}]}},"spore":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"孢子;胚种","en":"Spores are cells produced by bacteria and fungi which can develop into new bacteria or fungi."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a cell like a seed that is produced by some plants such as mushroom s and can develop into a new plant","cn":"孢子﹔芽孢"}]},"media":{"uk":"media/ldoce/hwd/bre/c/ld41spore.mp3","us":"media/ldoce/hwd/ame/5/spore.mp3"},"examples":[{"en":"Ferns, mosses and fungi spread by means of spores.","cn":"蕨类植物、苔藓和真菌通过孢子传播蔓生。"}],"oxford":{"phon":"spɔː(r)","pos":"noun","senses":[{"en":"one of the very small cells that are produced by some plants and that develop into new plants","cn":"孢子","ex":{"en":"Ferns, mosses and fungi spread by means of spores.","cn":"蕨类植物、苔藓和真菌通过孢子传播蔓生。"}}]}},"splodge":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(尤指某种液体的)大块污渍,大斑块","en":"A splodge is a large uneven mark or stain, especially one that has been caused by a liquid."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a large mark of mud, paint etc with an irregular shape 〔","cn":"污泥﹑油漆等大面积的〕斑块﹐污渍"}]},"media":{"uk":"media/ldoce/hwd/bre/a/ld41splodge.mp3","us":"media/ldoce/hwd/ame/a/ld41splodge.mp3"},"examples":[{"en":"splodges of colour","cn":"色块"}],"oxford":{"phon":"splɒdʒ","pos":"noun","senses":[{"en":"a large mark or spot of ink, paint, mud, etc.; a small area of colour or light","cn":"一块污渍；一片污迹；色块；光斑","ex":{"en":"He had a splodge of oil on his cheek.","cn":"他脸颊上有一块油渍。"}}]}},"specialise":{"collins":{"senses":[{"pos":"","cn":"","en":"→see: ;"}]}},"spark":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"火花;火星","en":"A spark is a tiny bright piece of burning material that flies up from something that is burning.","ex":{"en":"The fire gradually got bigger and bigger. Sparks flew off in all directions.","cn":"火越燃越烈，火星四溅。"}},{"pos":"N-COUNT 可数名词","cn":"电火花;火花放电","en":"A spark is a flash of light caused by electricity. It often makes a loud sound.","ex":{"en":"He passed an electric spark through a mixture of gases.","cn":"他让一束电火花穿过了一团混合气体。"}},{"pos":"VERB 动词","cn":"发出火花;闪光","en":"If something sparks, sparks of fire or light come from it.","ex":{"en":"The wires were sparking above me","cn":"电线在我头顶上方冒着火花。"}},{"pos":"VERB 动词","cn":"引起(大火)","en":"If a burning object or electricity sparks a fire, it causes a fire.","ex":{"en":"A dropped cigarette may have sparked the fire.","cn":"可能是丢弃的烟头导致了这场大火。"}},{"pos":"N-COUNT 可数名词","cn":"微量;一点点","en":"A spark of a quality or feeling, especially a desirable one, is a small but noticeable amount of it.","ex":{"en":"His music lacked that vital spark of imagination","cn":"他的音乐缺少非常关键的那一点灵感。"}},{"pos":"VERB 动词","cn":"触发;引发","en":"If one thing sparks another, the first thing causes the second thing to start happening.","ex":{"en":"What was it that sparked your interest in motoring?","cn":"是什么让你对开车产生了兴趣？"}},{"pos":"PHRASE 短语","cn":"激烈争论;热烈讨论","en":"If sparks fly between people, they discuss something in an excited or angry way.","ex":{"en":"They are not afraid to tackle the issues or let the sparks fly when necessary.","cn":"他们不怕应对这些问题，也不怕必要时来一番激烈的争论。"}},{"pos":"","cn":"","en":"相关词组：spark off"}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a very small piece of burning material produced by a fire or by hitting or rubbing two hard objects together","cn":"火花﹐火星"},{"en":"a flash of light caused by electricity passing across a space","cn":"电火花"},{"en":"a small amount of a feeling or quality","cn":"一点点兴趣/激动/怒气等"}]},"vocab":{"pos":"n v","senses":[{"en":"A spark is a small, glowing particle that's either thrown off of a fire or that starts a fire. Your dad might tell everyone to stand back from the bonfire so they don't get burned by a spark ."}]},"collocations":{"phrases":["ADJ. tiny | flying | electric","VERB + SPARK emit, produce, send (out), shower, strike The firework showered sparks all over the lawn. His iron-tipped stick struck sparks f","SPARK + VERB fly | ignite sth, set fire to sth Flying sparks set fire to the dry grass. | die (out)","PHRASES a shower of sparks The grinding wheel sent a shower of sparks across the workbench. | a spark of light 2 small amount of a quality/f","ADJ. little, tiny A tiny spark of rebellion flared within her. | creative, divine, vital","VERB + SPARK have | lack His performances lack creative spark. | feel She felt a little spark of anger. | kindle","SPARK + VERB flare, kindle","PREP. ~ of He had kindled a spark of interest within her."]},"media":{"uk":"media/ldoce/hwd/bre/8/brelasdespark.mp3","us":"media/ldoce/hwd/ame/f/spark1.mp3"},"examples":[{"en":"The riots were sparked off by the arrest of a local leader.","cn":"骚乱是因逮捕一名当地领导人而触发的。"},{"en":"The proposal would spark a storm of protest around the country.","cn":"这一提案将引发全国性的抗议浪潮。"}],"oxford":{"phon":"spɑːk","pos":"verb","senses":[{"en":"to cause something to start or develop, especially suddenly","cn":"引发；触发","g":"[transitive]","ex":{"en":"The proposal would spark a storm of protest around the country.","cn":"这一提案将引发全国性的抗议浪潮。"}},{"en":"to produce small flashes of fire or electricity","cn":"冒火花；飞火星；产生电火花","g":"[intransitive]","lab":"figurative","ex":{"en":"a sparking, crackling fire","cn":"噼啪直响、火星飞迸的火"}},{"en":"a very small burning piece of material that is produced by something that is burning or by hitting two hard substances together","cn":"火花；火星","g":"[countable]","ex":{"en":"A shower of sparks flew up the chimney.","cn":"烟囱里飞出无数火星。"},"pos":"noun"},{"en":"a small flash of light produced by an electric current","cn":"电火花","g":"[countable]","ex":{"en":"sparks from a faulty light switch","cn":"漏电的电灯开关发出的火花"},"pos":"noun"},{"en":"a small amount of a particular quality or feeling","cn":"（指品质或感情）一星，丝毫，一丁点","g":"[countable, usually singular]","ex":{"en":"a spark of hope","cn":"一线希望"},"pos":"noun"},{"en":"a special quality of energy, intelligence or enthusiasm that makes somebody very clever, funny, etc.","cn":"生气；活力；才华；热情","g":"[uncountable, singular]","ex":{"en":"As a writer he seemed to lack creative spark.","cn":"作为作家，他似乎缺少创作激情。"},"pos":"noun"},{"en":"an action or event that causes something important to develop, especially trouble or violence","cn":"诱因；导火线","g":"[countable]","ex":{"en":"These were the sparks of revolution.","cn":"这些都是革命的火花。"},"pos":"noun"},{"en":"feelings of anger or excitement between people","cn":"愤怒的情感；激烈的情绪","g":"[countable, usually plural]","ex":{"en":"Sparks flew at the meeting (= there was a lot of argument).","cn":"会上争论激烈，火星四溅。"},"pos":"noun"}]}},"specialism":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"专业(研究);专长;特长","en":"Someone's specialism is a particular subject or skill which they study and know a lot about.","ex":{"en":"...a teacher with a specialism in mathematics.","cn":"一位数学专业的老师"}},{"pos":"N-UNCOUNT 不可数名词","cn":"专业化;专门化;专科化","en":"Specialism is the act of specializing in a particular subject.","ex":{"en":"The needs of children may not be best met by an overemphasis on subject specialism.","cn":"过分强调学科的专业化也许并不能最好地满足儿童的需要。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a particular activity or subject that you know a lot about","cn":"特长﹐专长﹐专业"},{"en":"the practice of limiting your interests or activities to particular subjects","cn":"专门化﹐专业化"}]},"media":{"uk":"media/ldoce/hwd/bre/0/ld41specialism.mp3","us":"media/ldoce/hwd/ame/0/ld41specialism.mp3"},"examples":[{"en":"Dr Crane's specialism is tropical diseases.","cn":"克莱恩博士的研究领域是热带病。"},{"en":"a business degree with a specialism in computing","cn":"专修计算机技术的商业学位"}],"oxford":{"phon":"ˈspeʃəlɪzəm","pos":"noun","senses":[{"en":"an area of study or work that somebody specializes in","cn":"专业；专长","g":"[countable]","ex":{"en":"a business degree with a specialism in computing","cn":"专修计算机技术的商业学位"}},{"en":"the fact of specializing in a particular subject","cn":"专业化","g":"[uncountable]"}]}},"splutter":{"collins":{"senses":[{"pos":"VERB 动词","cn":"(因窘迫或生气而)结结巴巴地说，语无伦次地说，气急败坏地说","en":"If someone splutters, they make short sounds and have difficulty speaking clearly, for example because they are embarrassed or angry.","ex":{"en":"'But it cannot be,' he spluttered","cn":"“但这不可能，”他气急败坏地说道。"}},{"pos":"VERB 动词","cn":"发出噼啪声","en":"If something splutters, it makes a series of short, sharp sounds.","ex":{"en":"Suddenly the engine coughed, spluttered and died.","cn":"突然发动机噗噗响起来，噼啪几下就熄火了。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to talk quickly in short confused phrases, especially because you are angry or surprised","cn":"气急败坏地说；急促而慌乱地说〔尤因生气或吃惊〕"},{"en":"to make a series of short sharp noises","cn":"发出噼啪声﹐发噗噗声"}]},"media":{"uk":"media/ldoce/hwd/bre/c/ld41splutter.mp3","us":"media/ldoce/hwd/ame/b/splutter1.mp3"},"examples":[{"en":"‘But, but … you can't!’ she spluttered. “","cn":"可是，可是 … 你不能啊！”她急促而慌乱地说。"},{"en":"She fled from the blaze, coughing and spluttering.","cn":"她从大火中逃出来，一边咳嗽，一边噗噗地吐气。"}],"oxford":{"phon":"ˈsplʌtə(r)","pos":"verb","senses":[{"en":"to speak quickly and with difficulty, making soft spitting sounds, because you are angry or embarrassed","cn":"气急败坏地说；慌张地说","g":"[transitive, intransitive]","ex":{"en":"‘But, but…you can’t!’ she spluttered.","cn":"“可是，可是…你不能啊！”她急促而慌乱地说。"}},{"en":"to make a series of short explosive sounds","cn":"发噗噗声；发噼啪声","g":"[intransitive]","ex":{"en":"The firework spluttered and went out.","cn":"花炮噼里啪啦地喷完后灭了。"}},{"en":"a short explosive sound","cn":"噗的一声；啪的一声","ex":{"en":"The car started with a loud splutter.","cn":"汽车突的一声发动了。"},"pos":"noun"}]}},"specious":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"似是而非的;貌似真实的","en":"Something that is specious seems to exist or be true, but is not real or true.","ex":{"en":"It is unlikely that the Duke was convinced by such specious arguments.","cn":"公爵不太可能相信这种似是而非的论点。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"seeming to be true or correct, but actually false","cn":"似是而非的﹐貌似正确的"}]},"vocab":{"pos":"adj","senses":[{"en":"Use specious to describe an argument that seems to be good, correct, or logical, but is not so. We live on the earth, therefore the earth must be the center of the universe has been proven to be a specious theory of the solar system."}]},"media":{"uk":"media/ldoce/hwd/bre/0/ld41specious.mp3","us":"media/ldoce/hwd/ame/6/specious.mp3"},"examples":[{"en":"a specious argument","cn":"似是而非的论点"}],"oxford":{"phon":"ˈspiːʃəs","pos":"adjective","senses":[{"en":"seeming right or true but actually wrong or false","cn":"似是而非的；貌似有理的","ex":{"en":"a specious argument","cn":"似是而非的论点"}}]}},"sputum":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"痰","en":"Sputum is the wet substance which is coughed up from someone's lungs."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"liquid in your mouth which you have coughed up from your lungs","cn":"痰"}]},"media":{"uk":"media/ldoce/hwd/bre/5/ld41sputum.mp3","us":"media/ldoce/hwd/ame/3/sputum.mp3"},"examples":[{"en":"blood in the sputum","cn":"痰中的血丝"}],"oxford":{"phon":"ˈspjuːtəm","pos":"noun","senses":[{"en":"liquid from the throat or lungs, especially when it is coughed up (= forced up from the lungs, etc.) because of disease","cn":"（尤指因疾病而咳出的）痰","ex":{"en":"blood in the sputum","cn":"痰中的血丝"}}]}},"spanner":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"扳手;扳钳","en":"A spanner is a metal tool whose end fits round a nut so that you can turn it to loosen or tighten it."},{"pos":"PHRASE 短语","cn":"从中捣乱;横加阻拦;搅局","en":"If someone throws a spanner in the works, they prevent something happening smoothly in the way that it was planned, by causing a problem or difficulty.","ex":{"en":"A bad result is sure to throw a spanner in the works.","cn":"糟糕的成绩肯定会坏事的。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"to completely spoil what someone has been trying to do","cn":""},{"en":"to spoil something important or something that has been carefully planned","cn":""},{"en":"to spoil something that has taken a long time to develop","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"A spanner is a type of wrench. It's adjustable and used to tighten or loosen nuts and bolts."}]},"media":{"uk":"media/ldoce/hwd/bre/4/spanner0205.mp3","us":"media/ldoce/hwd/ame/7/ld41spanner.mp3","img":["media/thumb/spanner.jpg"]},"oxford":{"phon":"ˈspænə(r)","pos":"noun","senses":[{"en":"a metal tool with an end with a special shape for holding and turning nuts and bolts (= small metal rings and pins that hold things together)","cn":"扳手；扳子；扳钳","ex":{"en":"I’ll need a spanner to change the back wheel.","cn":"我需要一把扳手来换后轮。"}}]}},"spook":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"鬼魂;幽灵","en":"A spook is a ghost."},{"pos":"N-COUNT 可数名词","cn":"间谍","en":"A spook is a spy.","ex":{"en":"...as a US intelligence spook said yesterday.","cn":"据昨天一位美国情报员所说…"}},{"pos":"VERB 动词","cn":"使受到惊吓;使神经紧张","en":"If people are spooked, something has scared them or made them nervous.","ex":{"en":"But was it the wind that spooked her?","cn":"但会是风吓到她了吗？"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the spirit of a dead person that some people think they can feel or see in a place","cn":""},{"en":"a creature without a physical body, such as an angel or ghost","cn":""},{"en":"an image of a dead person that someone sees suddenly for a short time","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/a/ld41spook.mp3","us":"media/ldoce/hwd/ame/4/spook1.mp3"},"examples":[{"en":"We were spooked by the strange noises and lights.","cn":"那奇怪的声音和亮光把我们吓坏了。"},{"en":"The horse spooked at the siren.","cn":"警报器一响，马受惊了。"}],"oxford":{"phon":"spuːk","pos":"noun","senses":[{"en":"a ghost","cn":"鬼","ex":{"en":"a castle haunted by spooks","cn":"闹鬼的城堡"}},{"en":"a spy","cn":"间谍；特工","lab":"especially North American English","ex":{"en":"a CIA spook","cn":"中央情报局特工"}},{"en":"to frighten a person or an animal; to become frightened","cn":"吓；惊吓；受惊","ex":{"en":"We were spooked by the strange noises and lights.","cn":"那奇怪的声音和亮光把我们吓坏了。"},"pos":"verb"}]}},"sportswear":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"运动服;便装","en":"Sportswear is the special clothing worn for playing sports or for informal leisure activities."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"clothes that you wear to play sports or when you are relaxing","cn":"运动服装﹔休闲服装"},{"en":"clothes that are suitable for informal occasions","cn":"便服﹐便装"}]},"media":{"uk":"media/ldoce/hwd/bre/0/ld41sportswear.mp3","us":"media/ldoce/hwd/ame/0/laadsportswear.mp3"},"oxford":{"phon":"ˈspɔːtsweə(r)","pos":"noun","senses":[{"en":"clothes that are worn for playing sports, or in informal situations","cn":"运动服装","lab":"especially British English"},{"en":"clothes that are worn in informal situations","cn":"便装","lab":"especially North American English"}]}},"spay":{"collins":{"senses":[{"pos":"VERB 动词","cn":"切除(雌畜)的卵巢","en":"When a female animal is spayed, it has its ovaries removed so that it cannot become pregnant.","ex":{"en":"All bitches should be spayed unless being used for breeding.","cn":"除非是用作种犬，所有的母犬都应摘除卵巢。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to remove part of the sex organs of a female animal so that it is not able to have babies","cn":"切除〔雌性动物〕的卵巢﹔阉割〔雌性动物〕"}]},"media":{"uk":"media/ldoce/hwd/bre/1/ld41spay.mp3","us":"media/ldoce/hwd/ame/e/spay.mp3"},"examples":[{"en":"Have you had your cat spayed?","cn":"你的母猫劁了没有？"}],"oxford":{"phon":"speɪ","pos":"verb","senses":[{"en":"to remove the ovaries of a female animal, to prevent it from producing young","cn":"切除雌兽的卵巢；劁（雌兽）","ex":{"en":"Have you had your cat spayed?","cn":"你的母猫劁了没有？"}}]}},"spaniard":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"西班牙人；西班牙裔人","en":"A Spaniard is a Spanish citizen, or a person of Spanish origin."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone from Spain","cn":"西班牙人"}]},"media":{"uk":"media/ldoce/hwd/bre/5/ld41spaniard.mp3","us":"media/ldoce/hwd/ame/9/spaniard.mp3"},"oxford":{"phon":"ˈspænjəd","pos":"noun","senses":[{"en":"a person from Spain","cn":"西班牙人"}]}},"spurn":{"collins":{"senses":[{"pos":"VERB 动词","cn":"拒绝;摈弃","en":"If you spurn someone or something, you reject them.","ex":{"en":"He spurned the advice of management consultants","cn":"他拒绝了管理顾问们的建议。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to refuse to accept something or someone, especially because you are too proud","cn":"轻蔑地拒绝﹐对…不屑一顾"}]},"vocab":{"pos":"v","senses":[{"en":"If you reject your mother's offer to buy you a pair of lederhosen with a snort and eye roll, you are spurning her generosity. To spurn means to reject with disdain."}]},"media":{"uk":"media/ldoce/hwd/bre/6/spurn0205.mp3","us":"media/ldoce/hwd/ame/e/spurn.mp3"},"examples":[{"en":"Eve spurned Mark's invitation.","cn":"伊夫一口回绝了马克的邀请。"},{"en":"a spurned lover","cn":"遭到轻蔑拒绝的痴心爱慕者"}],"oxford":{"phon":"spɜːn","pos":"verb","senses":[{"en":"to reject or refuse somebody/something, especially in a proud way","cn":"（尤指傲慢地）拒绝","ex":{"en":"Eve spurned Mark's invitation.","cn":"伊夫一口回绝了马克的邀请。"}}]}},"spiritless":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"没精打采的;垂头丧气的","en":"If someone is spiritless, they lack energy, courage, and liveliness.","ex":{"en":"They were too spiritless even to resist.","cn":"他们无精打采的，甚至都没有抵抗。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"having no energy or determination","cn":"没精打采的﹐无朝气的﹔没有决心的"},{"en":"not cheerful","cn":"情绪低落的﹐垂头丧气的"}]},"media":{"uk":"media/ldoce/hwd/bre/9/spiritless0205.mp3","us":"media/ldoce/hwd/ame/1/spiritless.mp3"},"oxford":{"phon":"ˈspɪrɪtləs","pos":"adjective","senses":[{"en":"without energy or enthusiasm","cn":"没有生气的；无精打采的；意志薄弱的","ex":{"en":"a pale, spiritless child","cn":"一个苍白、无精打采的孩子"}}]}},"spawn":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"(鱼、蛙等产下的)卵，子，卵块","en":"Spawn is a soft, jelly-like substance containing the eggs of fish, or of animals such as frogs.","ex":{"en":"...her passion for collecting frog spawn.","cn":"她对采集蛙卵的热爱"}},{"pos":"VERB 动词","cn":"(鱼、蛙等)产卵","en":"When fish or animals such as frogs spawn, they lay their eggs.","ex":{"en":"...fish species like salmon and trout which go upstream, spawn and then die","cn":"诸如鲑鱼和鳟鱼这样洄游产卵后死去的鱼类"}},{"pos":"VERB 动词","cn":"产生;造成;引起","en":"If something spawns something else, it causes it to happen or to be created.","ex":{"en":"Tyndall's inspired work spawned a whole new branch of science","cn":"由廷德尔富有创见的著作发展出了一个崭新的科学分支。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to make a series of things happen or start to exist","cn":"使大量出现﹐使大量产生﹔酿成"},{"en":"if a fish or frog spawns, it produces eggs in large quantities at the same time 〔","cn":"鱼或蛙〕大量产卵"},{"en":"the eggs of a fish or frog laid together in a soft mass 〔","cn":"鱼或蛙的〕成团的卵"}]},"vocab":{"pos":"n v","senses":[{"en":"Technically, the mass of small eggs laid by animals like fish, frogs, mollusks is called spawn . But the word has been borrowed to mean offspring, or the act of making them in general."}]},"media":{"uk":"media/ldoce/hwd/bre/b/spawn_v0205.mp3","us":"media/ldoce/hwd/ame/5/spawn1.mp3"},"examples":[{"en":"The band's album spawned a string of hit singles.","cn":"这支乐队的专辑繁衍出一连串走红的单曲唱片。"},{"en":"New technology has spawned new business opportunities.","cn":"新技术创造了大量新的商机。"}],"oxford":{"phon":"spɔːn","pos":"verb","senses":[{"en":"to lay eggs","cn":"产卵","g":"[intransitive, transitive]"},{"en":"to cause something to develop or be produced","cn":"引发；引起；导致；造成","g":"[transitive]","lab":"often disapproving","ex":{"en":"The band's album spawned a string of hit singles.","cn":"这支乐队的专辑带出一连串走红的单曲。"}},{"en":"a soft substance containing the eggs of fish, frogs etc.","cn":"（鱼、蛙等的）卵","pos":"noun"}]}},"spendthrift":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"挥霍者;浪费金钱的人","en":"If you call someone a spendthrift, you mean that they spend too much money.","ex":{"en":"...his father's spendthrift ways.","cn":"他父亲挥金如土"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"spending more money than you can afford on expensive things that you do not really need","cn":""},{"en":"someone who spends money carelessly even when they know that they do cannot afford to","cn":""},{"en":"a rich person who spends a lot of money, especially in order to impress other people","cn":""}]},"vocab":{"pos":"n adj","senses":[{"en":"A spendthrift person is reckless and wasteful with his money. Spendthrifts who like to take you out to nice lunches are good people to be friends with, but it's generally a bad way to handle your own bank account."}]},"media":{"uk":"media/ldoce/hwd/bre/0/spendthrift0205.mp3","us":"media/ldoce/hwd/ame/1/spendthrift.mp3"},"oxford":{"phon":"ˈspendθrɪft","pos":"noun","senses":[{"en":"a person who spends too much money or who wastes money","cn":"花钱无度的人；挥霍者"},{"en":"spending too much money, or wasting money","cn":"花钱无度的人；挥霍者","ex":{"en":"spendthrift governments","cn":"挥霍无度的政府"},"pos":"adjective"}]}}});
